(window.LESE_DATA=window.LESE_DATA||{})["B1"]=[{"id":"b1-01","level":"B1","no":1,"title":"Ein Dorf rettet seinen Laden","titleKo":"가게를 지켜 낸 마을","type":"Zeitungsbericht","typeKo":"신문 보도 기사","intro":"오덴발트의 작은 마을 주민들이 문 닫은 슈퍼마켓 대신 직접 가게를 운영하는 이야기예요.","focus":["수동태와 행위자","주어 없는 수동태","관계절의 선행사","문장 첫 자리"],"paragraphs":[{"de":"Lindenau im Odenwald hat wieder einen Lebensmittelladen. Zwei Jahre nach der Schließung des letzten Supermarkts werden seit dem Frühjahr im selben Gebäude wieder Brot, Milch und Gemüse verkauft. Der Dorfladen gehört aber keiner Handelskette, sondern den Bürgerinnen und Bürgern selbst. Möglich wurde das durch die Gründung einer Genossenschaft, die heute rund 300 Mitglieder hat.","ko":"오덴발트의 린데나우에 다시 식료품 가게가 생겼습니다. 마을의 마지막 슈퍼마켓이 문을 닫은 지 2년 만에, 올봄부터 같은 건물에서 다시 빵과 우유, 채소를 팔고 있습니다. 하지만 이 마을 가게의 주인은 유통 체인이 아니라 주민들 자신입니다. 이 일은 협동조합을 세운 덕분에 가능해졌는데, 이 협동조합의 조합원은 현재 약 300명입니다."},{"de":"Die Schließung des Supermarkts war für viele ein Schock. Vor allem ältere Dorfbewohner ohne Auto mussten plötzlich für jeden Einkauf in die Kreisstadt fahren, die zwölf Kilometer entfernt liegt. „Innerhalb weniger Wochen war uns klar, dass wir selbst etwas tun mussten“, erinnert sich Karin Vogel, heute Vorsitzende der Genossenschaft. Auf einer Bürgerversammlung wurde die Idee vorgestellt, und noch am selben Abend wurden über 100 Anteile zu je 250 Euro verkauft.","ko":"슈퍼마켓이 문을 닫은 일은 많은 사람에게 충격이었습니다. 특히 차가 없는 나이 든 주민들은 갑자기 장을 볼 때마다 12킬로미터 떨어진 군청 소재지까지 가야 했습니다. “몇 주 지나지 않아 우리가 직접 무언가를 해야 한다는 게 분명해졌어요.” 지금 협동조합 대표를 맡고 있는 카린 포겔 씨는 이렇게 회상합니다. 주민 총회에서 이 아이디어를 소개했고, 바로 그날 저녁에 한 구좌에 250유로인 지분이 100구좌 넘게 팔렸습니다."},{"de":"Geführt wird der Dorfladen heute von zwei Angestellten und rund 40 Ehrenamtlichen. Während die Angestellten für Kasse, Bestellungen und Buchhaltung zuständig sind, räumen die Ehrenamtlichen Regale ein oder übernehmen samstags den Verkauf. Gemüse, Eier und Fleisch werden von Höfen aus der Umgebung geliefert. „Hier weiß man, woher die Kartoffeln kommen“, sagt Erich Sommer (78), der fast täglich vorbeischaut.","ko":"현재 이 마을 가게는 직원 두 명과 약 40명의 자원봉사자가 운영합니다. 직원들이 계산대와 주문, 회계를 맡는 반면, 자원봉사자들은 진열대에 물건을 채우거나 토요일마다 판매를 맡습니다. 채소와 달걀, 고기는 근처 농장들이 공급합니다. “여기서는 감자가 어디서 오는지 알 수 있어요.” 거의 매일 들르는 에리히 조머 씨(78)의 말입니다."},{"de":"Beim Umbau, den die Mitglieder größtenteils selbst durchführten, entstand im Dorfladen auch ein kleines Café. Obwohl es nur aus vier Tischen und einer alten Kaffeemaschine besteht, ist es mittlerweile zum Treffpunkt des Dorfes geworden. Vormittags sitzen hier Rentner beim Kaffee, nachmittags machen Schulkinder ihre Hausaufgaben.","ko":"개축 공사는 대부분 조합원들이 직접 했는데, 그때 가게 안에 작은 카페도 생겼습니다. 탁자 네 개와 오래된 커피 머신이 전부인데도, 이 카페는 어느새 마을의 만남의 장소가 되었습니다. 오전에는 은퇴한 어르신들이 이곳에서 커피를 마시고, 오후에는 학교에 다니는 아이들이 숙제를 합니다."},{"de":"Trotz dieses Erfolgs ist die Zukunft des Dorfladens nicht gesichert. Wegen der gestiegenen Energiepreise fiel die Stromrechnung im letzten Jahr wesentlich höher aus. Auch die Löhne der Angestellten mussten erhöht werden. Hinzu kommt die Miete für das Gebäude, die jeden Monat bezahlt werden muss. Mit großen Gewinnen hat von Anfang an niemand gerechnet. Verluste kann sich die Genossenschaft aber nicht lange leisten. Deshalb wird derzeit über eine Verlängerung der Öffnungszeiten diskutiert.","ko":"이런 성공에도 이 마을 가게의 앞날이 보장된 것은 아닙니다. 에너지 가격이 올라서 지난해 전기 요금이 훨씬 많이 나왔습니다. 직원들의 임금도 올려야 했습니다. 여기에 매달 내야 하는 건물 임대료도 있습니다. 처음부터 큰 이익을 기대한 사람은 아무도 없었습니다. 하지만 협동조합은 손실을 오래 감당할 수는 없습니다. 그래서 지금은 영업시간을 늘리는 방안을 논의하고 있습니다."},{"de":"Karin Vogel bleibt trotz aller Schwierigkeiten zuversichtlich. „Der Dorfladen wird nicht nur zum Einkaufen gebraucht“, sagt die Vorsitzende. „Hier trifft man Nachbarn, hier bekommt man Hilfe, hier wird geredet. Das kann kein Supermarkt in der Kreisstadt ersetzen.“ Noch in diesem Jahr soll auch ein Lieferdienst für Dorfbewohner entstehen, die nicht mehr selbst in den Dorfladen kommen können.","ko":"카린 포겔 씨는 여러 어려움에도 앞날을 밝게 보고 있습니다. “이 마을 가게는 장을 보는 데만 필요한 곳이 아니에요.” 포겔 대표는 이렇게 말합니다. “여기서는 이웃을 만나고, 도움을 받고, 이야기를 나눠요. 군청 소재지에 있는 슈퍼마켓은 그걸 대신할 수 없어요.” 올해 안에는 더 이상 직접 가게에 올 수 없는 주민들을 위한 배달 서비스도 생길 예정입니다."}],"questions":[{"type":"rf","kind":"inference","q":"Für den neuen Laden musste kein neues Haus gebaut werden.","answer":0,"evidence":"seit dem Frühjahr im selben Gebäude wieder Brot, Milch und Gemüse verkauft","pairs":[["im selben Gebäude","kein neues Haus gebaut"]],"explain":"본문에 따르면 새 가게는 예전 슈퍼마켓이 있던 '같은 건물(im selben Gebäude)'에서 문을 열었어요. 있던 건물을 고쳐 쓴 것이니 새 건물을 지을 필요가 없었어요. 문제는 im selben Gebäude를 kein neues Haus gebaut로 바꿔 말했어요."},{"type":"rf","kind":"detail","q":"Die Dorfbewohner warteten zwei Jahre, bevor sie über einen eigenen Laden nachdachten.","answer":1,"evidence":"Innerhalb weniger Wochen war uns klar, dass wir selbst etwas tun mussten","pairs":[["Innerhalb weniger Wochen","warteten zwei Jahre"]],"explain":"카린 포겔 씨는 '몇 주 안에(Innerhalb weniger Wochen)' 직접 무언가를 해야 한다는 것이 분명해졌다고 말해요. 2년은 슈퍼마켓이 문을 닫은 뒤 새 가게가 문을 열기까지의 기간이에요. 본문의 zwei Jahre를 그대로 가져온 함정이에요."},{"type":"mc","kind":"detail","q":"Wie reagierten viele Einwohner, als die Idee vorgestellt wurde?","options":["Sie kauften die Anteile erst nach dem Umbau des Gebäudes.","Jeder bezahlte 100 Euro für einen einzigen Anteil.","Viele unterstützten das Projekt sofort mit ihrem Geld."],"answer":2,"evidence":"noch am selben Abend wurden über 100 Anteile zu je 250 Euro verkauft","pairs":[["noch am selben Abend","sofort"],["wurden über 100 Anteile zu je 250 Euro verkauft","unterstützten das Projekt sofort mit ihrem Geld"]],"explain":"주민 총회가 열린 바로 그날 저녁에 100구좌가 넘는 지분이 팔렸어요. 많은 주민이 곧바로 돈을 내고 참여했다는 뜻이에요. 지분은 그날 저녁에 이미 팔렸으니 '개축 공사 뒤에야 샀다'는 틀리고, 지분 한 구좌의 값은 100유로가 아니라 250유로예요(zu je 250 Euro). 100은 그날 팔린 지분의 수예요."},{"type":"mc","kind":"detail","q":"Was erfährt man über die beiden Angestellten?","options":["Sie kümmern sich unter anderem um das Geld.","Sie übernehmen nur samstags den Verkauf.","Sie räumen jeden Tag die Regale im Laden ein."],"answer":0,"evidence":"Während die Angestellten für Kasse, Bestellungen und Buchhaltung zuständig sind","pairs":[["für Kasse, Bestellungen und Buchhaltung zuständig","kümmern sich unter anderem um das Geld"]],"explain":"직원들은 계산대(Kasse), 주문(Bestellungen), 회계(Buchhaltung)를 맡아요. 계산대와 회계는 돈을 다루는 일이니 '여러 일 가운데 돈 관리를 맡는다'가 맞아요. 진열대에 물건을 채우는 일과 토요일 판매는 자원봉사자(Ehrenamtliche)가 해요."},{"type":"mc","kind":"meaning","q":"Worauf bezieht sich Erich Sommer mit dem Satz „Hier weiß man, woher die Kartoffeln kommen“?","options":["auf die Lieferungen von Bauernhöfen aus der Nähe","auf den langen Weg der Kunden in die Kreisstadt","auf die Gespräche mit den Angestellten an der Kasse"],"answer":0,"evidence":"Gemüse, Eier und Fleisch werden von Höfen aus der Umgebung geliefert.","pairs":[["von Höfen aus der Umgebung geliefert","Lieferungen von Bauernhöfen aus der Nähe"]],"explain":"바로 앞 문장에서 채소와 달걀, 고기는 근처 농장(Höfe aus der Umgebung)이 공급한다고 해요. 그래서 손님들은 식품이 어디서 오는지 알 수 있어요. 군청 소재지까지 가던 길이나 계산대에서 나누는 대화는 이 말과 관계가 없어요."},{"type":"mc","kind":"inference","q":"Was kann man aus dem Text über das Café schließen?","options":["Es entstand erst, als der Umbau des Ladens ganz fertig war.","Auch mit einfacher Ausstattung ist es bei den Leuten beliebt.","Am Nachmittag trinken dort vor allem die Rentner ihren Kaffee."],"answer":1,"evidence":"Obwohl es nur aus vier Tischen und einer alten Kaffeemaschine besteht, ist es mittlerweile zum Treffpunkt des Dorfes geworden.","pairs":[["nur aus vier Tischen und einer alten Kaffeemaschine","einfacher Ausstattung"],["zum Treffpunkt des Dorfes geworden","bei den Leuten beliebt"]],"explain":"카페에는 탁자 네 개와 오래된 커피 머신뿐인데도(Obwohl …) 이곳이 마을의 만남의 장소가 되었어요. 시설이 소박해도 사람들이 즐겨 찾는다는 뜻이에요. 카페는 개축 공사를 하는 '중에(Beim Umbau)' 생겼고, 오후에는 어르신이 아니라 학생들이 숙제를 해요."},{"type":"rf","kind":"detail","q":"Weil die Stromrechnung höher ausgefallen ist, sollen die Öffnungszeiten kürzer werden.","answer":1,"evidence":"Deshalb wird derzeit über eine Verlängerung der Öffnungszeiten diskutiert.","pairs":[["Verlängerung der Öffnungszeiten","Öffnungszeiten kürzer werden"]],"explain":"본문은 영업시간 '연장(Verlängerung)'을 논의하고 있다고 해요. 손실을 오래 감당할 수 없으니 문을 더 오래 열어 수입을 늘리려는 거예요. 전기 요금이 많이 나온 것은 맞지만, 영업시간을 줄인다는 말은 없어요."},{"type":"mc","kind":"intent","q":"Was will Karin Vogel mit ihren Aussagen am Ende vor allem zeigen?","options":["Der Dorfladen soll bald mehr Waren anbieten als ein Supermarkt.","Die Probleme mit der Miete und dem Strom sind inzwischen gelöst.","Der Laden hat für das Dorf auch eine wichtige soziale Aufgabe."],"answer":2,"evidence":"Hier trifft man Nachbarn, hier bekommt man Hilfe, hier wird geredet.","pairs":[["Hier trifft man Nachbarn, hier bekommt man Hilfe","eine wichtige soziale Aufgabe"]],"explain":"포겔 씨는 이 가게에서 이웃을 만나고, 도움을 받고, 이야기를 나눈다고 말해요. 군청 소재지에 있는 슈퍼마켓은 이런 역할을 대신할 수 없다는 거예요. 즉 이 가게가 장보기 말고도 마을 사람들을 이어 주는 일을 한다는 점을 강조해요. 상품 수나 문제가 해결되었다는 이야기는 하지 않아요."}],"grammar":[{"title":"수동태의 행위자 – von + 3격","term":"Passiv mit Agens (von + Dativ)","explain":"수동태 문장에서 그 일을 하는 사람이나 기관을 밝히고 싶으면 von + 3격을 덧붙여요. 능동문의 주어가 수동문에서 von + 3격이 되고, 능동문의 4격 목적어가 수동문의 주어(1격)가 돼요. 행위자가 중요하지 않거나 누구인지 분명하면 von + 3격을 빼요.","pattern":"주어 + werden + … + von + 3격 + … + 과거분사(문장 끝)","examples":[{"de":"Geführt wird der Dorfladen heute von zwei Angestellten und rund 40 Ehrenamtlichen.","ko":"현재 이 마을 가게는 직원 두 명과 약 40명의 자원봉사자가 운영합니다.","mark":["Geführt","wird","von zwei Angestellten und rund 40 Ehrenamtlichen"],"parts":[["Geführt","동사(끝)"],["wird","동사"],["der Dorfladen","주어"],["heute","부사어(시간)"],["von zwei Angestellten und rund 40 Ehrenamtlichen.","부사어"]]},{"de":"Gemüse, Eier und Fleisch werden von Höfen aus der Umgebung geliefert.","ko":"채소와 달걀, 고기는 근처 농장들이 공급합니다.","mark":["werden","von Höfen aus der Umgebung","geliefert"],"parts":[["Gemüse, Eier und Fleisch","주어"],["werden","동사"],["von Höfen aus der Umgebung","부사어"],["geliefert.","동사(끝)"]]}],"tip":"두 번째 예문을 능동문으로 바꾸면 „Höfe aus der Umgebung liefern Gemüse, Eier und Fleisch.“예요. 첫 번째 예문은 과거분사 Geführt를 문장 맨 앞에 두어 누가 가게를 운영하는지에 눈길이 가게 해요. 수단이나 원인을 말할 때는 von 대신 durch + 4격을 써요."},{"title":"주어 없는 수동태 – hier wird geredet","term":"Unpersönliches Passiv","explain":"4격 목적어를 받지 않는 동사(reden, über etwas diskutieren 등)도 수동태로 쓸 수 있어요. 이런 문장에는 주어가 없어서 werden은 3인칭 단수형 wird(과거형 wurde)를 써요. 누가 하는지보다 그 일이 일어난다는 사실이 중요할 때 써요. 문장 맨 앞자리를 채울 말이 없으면 형식상의 es를 넣어요(Es wird geredet).","pattern":"부사어 + wird + … + 과거분사(문장 끝) / Es wird + … + 과거분사","examples":[{"de":"Hier trifft man Nachbarn, hier bekommt man Hilfe, hier wird geredet.","ko":"여기서는 이웃을 만나고, 도움을 받고, 이야기를 나눠요.","mark":["hier wird geredet"],"parts":[["Hier","부사어(장소)"],["trifft","동사"],["man","주어"],["Nachbarn,","4격 목적어"],["hier","부사어(장소)"],["bekommt","동사"],["man","주어"],["Hilfe,","4격 목적어"],["hier","부사어(장소)"],["wird","동사"],["geredet.","동사(끝)"]]},{"de":"Deshalb wird derzeit über eine Verlängerung der Öffnungszeiten diskutiert.","ko":"그래서 지금은 영업시간을 늘리는 방안을 논의하고 있습니다.","mark":["wird","diskutiert"],"parts":[["Deshalb","접속부사"],["wird","동사"],["derzeit","부사어(시간)"],["über eine Verlängerung der Öffnungszeiten","전치사 목적어"],["diskutiert.","동사(끝)"]]}],"tip":"주어 없는 수동태는 man을 주어로 쓴 능동문과 뜻이 비슷해요: hier wird geredet ≈ hier redet man. 첫 번째 예문은 man을 쓴 문장 두 개 뒤에 주어 없는 수동태를 이어 써요. 세 부분 모두 사람들이 이곳에서 하는 일을 말하지만 형태가 달라요."},{"title":"떨어져 있는 관계절 – 관계대명사로 선행사 찾기","term":"Relativsatz im Nachfeld: Bezugswort finden","explain":"관계절은 보통 꾸며 주는 명사(선행사) 바로 뒤에 와요. 그런데 선행사 뒤에 주문장의 동사(끝)만 남아 있으면, 관계절은 그 동사 뒤로 가서 선행사와 떨어지는 일이 많아요. 이때는 관계대명사의 성과 수, 관계절 동사의 단수·복수를 보고 선행사를 찾아요. 관계대명사의 성과 수는 선행사를 따르고, 격은 관계절 안에서 하는 역할로 정해져요. Beim Umbau, den die Mitglieder … durchführten에서 den은 durchführen의 4격 목적어라서 4격이에요.","pattern":"… + 선행사 + … + 동사(끝), + 관계대명사 + … + 동사(관계절 끝)","examples":[{"de":"Vor allem ältere Dorfbewohner ohne Auto mussten plötzlich für jeden Einkauf in die Kreisstadt fahren, die zwölf Kilometer entfernt liegt.","ko":"특히 차가 없는 나이 든 주민들은 갑자기 장을 볼 때마다 12킬로미터 떨어진 군청 소재지까지 가야 했습니다.","mark":["in die Kreisstadt","die zwölf Kilometer entfernt liegt"],"parts":[["Vor allem ältere Dorfbewohner ohne Auto","주어"],["mussten","동사"],["plötzlich","부사어"],["für jeden Einkauf","부사어"],["in die Kreisstadt","부사어(장소)"],["fahren,","동사(끝)"],["die zwölf Kilometer entfernt liegt.","관계절"]]},{"de":"Noch in diesem Jahr soll auch ein Lieferdienst für Dorfbewohner entstehen, die nicht mehr selbst in den Dorfladen kommen können.","ko":"올해 안에는 더 이상 직접 가게에 올 수 없는 주민들을 위한 배달 서비스도 생길 예정입니다.","mark":["Dorfbewohner","die nicht mehr selbst in den Dorfladen kommen können"],"parts":[["Noch in diesem Jahr","부사어(시간)"],["soll","동사"],["auch","부사어"],["ein Lieferdienst für Dorfbewohner","주어"],["entstehen,","동사(끝)"],["die nicht mehr selbst in den Dorfladen kommen können.","관계절"]]},{"de":"Hinzu kommt die Miete für das Gebäude, die jeden Monat bezahlt werden muss.","ko":"여기에 매달 내야 하는 건물 임대료도 있습니다.","mark":["die Miete","die jeden Monat bezahlt werden muss"]}],"tip":"쉼표 바로 앞의 명사가 늘 선행사인 것은 아니에요. die Miete für das Gebäude, die …에서 die는 여성 단수라서 das Gebäude가 아니라 die Miete를 가리켜요. 두 번째 예문의 die … kommen können은 동사가 복수라서 ein Lieferdienst가 아니라 Dorfbewohner를 가리켜요."},{"title":"주어가 아닌 말로 문장 시작하기","term":"Vorfeld: Objekt oder Prädikativ am Satzanfang","explain":"독일어 평서문에서 인칭 변화한 동사는 두 번째 자리에 와요. 첫 번째 자리에는 주어 말고도 목적어, 전치사구, 형용사가 올 수 있고, 그러면 주어는 동사 뒤로 가요. 신문 기사는 앞 문장과 이어지는 말이나 강조하고 싶은 말을 첫 자리에 두어 문장을 이어 가요.","pattern":"목적어·전치사구·형용사 + 동사 + 주어 + …","examples":[{"de":"Möglich wurde das durch die Gründung einer Genossenschaft, die heute rund 300 Mitglieder hat.","ko":"이 일은 협동조합을 세운 덕분에 가능해졌는데, 이 협동조합의 조합원은 현재 약 300명입니다.","mark":["Möglich","wurde","das"],"parts":[["Möglich","보어"],["wurde","동사"],["das","주어"],["durch die Gründung einer Genossenschaft,","부사어(방법)"],["die heute rund 300 Mitglieder hat.","관계절"]]},{"de":"Verluste kann sich die Genossenschaft aber nicht lange leisten.","ko":"하지만 협동조합은 손실을 오래 감당할 수는 없습니다.","mark":["Verluste","kann","die Genossenschaft"],"parts":[["Verluste","4격 목적어"],["kann","동사"],["sich","재귀대명사"],["die Genossenschaft","주어"],["aber","접속부사"],["nicht","부정어"],["lange","부사어(시간)"],["leisten.","동사(끝)"]]},{"de":"Mit großen Gewinnen hat von Anfang an niemand gerechnet.","ko":"처음부터 큰 이익을 기대한 사람은 아무도 없었습니다.","mark":["Mit großen Gewinnen","hat","niemand"]}],"tip":"첫 자리에 무엇이 오든 인칭 변화한 동사는 두 번째 자리에 있어요. 주어(das, die Genossenschaft, niemand)를 찾을 때는 동사 뒤도 살펴보세요."}],"vocab":[{"de":"der Lebensmittelladen, -¨","ko":"식료품 가게"},{"de":"die Schließung, -en","ko":"폐점, 문을 닫음"},{"de":"die Handelskette, -n","ko":"유통 체인 (여러 지점을 둔 소매 기업)"},{"de":"die Genossenschaft, -en","ko":"협동조합"},{"de":"die Gründung, -en","ko":"설립, 창립"},{"de":"die Kreisstadt, -¨e","ko":"군청 소재지 (군의 중심 도시)"},{"de":"die Bürgerversammlung, -en","ko":"주민 총회"},{"de":"der Anteil, -e","ko":"지분, 출자 구좌"},{"de":"der/die Vorsitzende, -n","ko":"대표, 의장 (단체를 이끄는 사람)"},{"de":"der/die Ehrenamtliche, -n","ko":"자원봉사자 (보수 없이 일하는 사람)"},{"de":"die Buchhaltung (Sg.)","ko":"회계, 장부 관리"},{"de":"der Umbau, -ten","ko":"개축 공사, 리모델링"},{"de":"durch|führen","ko":"(공사·일을) 하다, 실시하다"},{"de":"der Verlust, -e","ko":"손실, 손해"},{"de":"die Verlängerung, -en","ko":"연장, 늘림"},{"de":"zuversichtlich","ko":"앞날을 밝게 보는, 희망을 품은"}],"phrases":[{"de":"für etwas (Akk.) zuständig sein","ko":"~을 맡고 있다, ~을 담당하다","ex":"Während die Angestellten für Kasse, Bestellungen und Buchhaltung zuständig sind, räumen die Ehrenamtlichen Regale ein oder übernehmen samstags den Verkauf.","exko":"직원들이 계산대와 주문, 회계를 맡는 반면, 자원봉사자들은 진열대에 물건을 채우거나 토요일마다 판매를 맡습니다."},{"de":"höher ausfallen (fällt aus, fiel aus, ist ausgefallen)","ko":"(금액·결과가) 더 높게 나오다","ex":"Wegen der gestiegenen Energiepreise fiel die Stromrechnung im letzten Jahr wesentlich höher aus.","exko":"에너지 가격이 올라서 지난해 전기 요금이 훨씬 많이 나왔습니다."},{"de":"hinzu|kommen (kam hinzu, ist hinzugekommen)","ko":"(~이) 더해지다, 거기에 ~도 있다","ex":"Hinzu kommt die Miete für das Gebäude, die jeden Monat bezahlt werden muss.","exko":"여기에 매달 내야 하는 건물 임대료도 있습니다."},{"de":"mit etwas (Dat.) rechnen","ko":"~을 예상하다, ~을 기대하다","ex":"Mit großen Gewinnen hat von Anfang an niemand gerechnet.","exko":"처음부터 큰 이익을 기대한 사람은 아무도 없었습니다."},{"de":"sich (Dat.) etwas leisten können","ko":"~을 감당할 수 있다, ~할 (경제적) 여유가 있다","ex":"Verluste kann sich die Genossenschaft aber nicht lange leisten.","exko":"하지만 협동조합은 손실을 오래 감당할 수는 없습니다."}],"words":355},{"id":"b1-02","level":"B1","no":2,"title":"Die erste Fernfahrt mit dem Auto","titleKo":"자동차로 떠난 최초의 장거리 여행","type":"Sachtext (Kurzbiografie)","typeKo":"설명문 (짧은 전기)","intro":"1888년 베르타 벤츠가 두 아들과 함께 자동차로 만하임에서 포르츠하임까지 달린 이야기예요.","focus":["과거완료","ohne … zu와 zu 부정사","동격","als · für + 보어"],"paragraphs":[{"de":"Bereits im Jahr 1886 hatte der Ingenieur Carl Benz aus Mannheim ein Patent für seinen Motorwagen erhalten. Zwei Jahre später zeigte die Öffentlichkeit jedoch kaum Interesse an der Erfindung. Längere Fahrten hatte bis dahin niemand gewagt, und viele Zeitgenossen hielten das laute Fahrzeug für ein gefährliches Spielzeug. Bertha Benz dagegen, die Geld aus ihrer Mitgift in die Werkstatt ihres Ehemannes gesteckt hatte, glaubte fest an die neue Technik.","ko":"만하임의 기술자 카를 벤츠는 이미 1886년에 자신이 만든 모토르바겐의 특허를 받았습니다. 그러나 2년이 지난 뒤에도 사람들은 이 발명에 거의 관심을 보이지 않았습니다. 그때까지 먼 거리를 달려 볼 엄두를 낸 사람은 아무도 없었고, 당시 많은 사람이 이 시끄러운 탈것을 위험한 장난감으로 여겼습니다. 반면 결혼 지참금으로 받은 돈을 남편의 작업장에 쏟아부었던 베르타 벤츠는 이 새로운 기술을 굳게 믿었습니다."},{"de":"Im August 1888 fasste sie den mutigen Entschluss, mit dem Motorwagen von Mannheim nach Pforzheim zu fahren – eine Strecke von rund 100 Kilometern. Ohne ihrem Mann etwas davon zu erzählen, brach sie frühmorgens in Begleitung ihrer beiden Söhne auf. Die beiden waren damals 15 und 13 Jahre alt. Schon bald nach der Abfahrt wurde deutlich, dass die Reise kein einfacher Ausflug war.","ko":"1888년 8월, 베르타는 모토르바겐을 타고 만하임에서 포르츠하임까지 달리겠다는 용감한 결심을 했습니다. 약 100킬로미터나 되는 거리였습니다. 남편에게 아무 이야기도 하지 않은 채, 그녀는 이른 아침 두 아들과 함께 길을 떠났습니다. 두 아들은 당시 열다섯 살과 열세 살이었습니다. 출발하고 얼마 지나지 않아 이 여행이 가벼운 나들이가 아니라는 것이 분명해졌습니다."},{"de":"Als in Wiesloch der Kraftstoff zu Ende ging, kaufte Bertha Benz in einer Apotheke Ligroin, ein Reinigungsmittel, das damals als Treibstoff diente. Die Apotheke wird deshalb heute als erste Tankstelle der Welt bezeichnet. Eine verstopfte Kraftstoffleitung reinigte sie mit ihrer Hutnadel. Ein beschädigtes Zündkabel isolierte sie mit ihrem Strumpfband. Nachdem sich die Bremsen bergab stark abgenutzt hatten, bat sie einen Schuster, Lederstreifen auf die Bremsklötze zu nageln. Viele sehen darin heute die Erfindung des Bremsbelags. Bergauf reichte die Motorleistung dagegen nicht aus. Dann mussten die Söhne kräftig schieben, während Bertha Benz lenkte.","ko":"비스로흐에서 연료가 떨어지자 베르타 벤츠는 한 약국에서 리그로인을 샀습니다. 당시 연료로 쓰이던 세정제였습니다. 그래서 이 약국은 오늘날 세계 최초의 주유소라고 불립니다. 막힌 연료관은 모자 핀으로 뚫었습니다. 손상된 점화 전선은 자신의 스타킹 고정 밴드로 감아 절연했습니다. 내리막에서 브레이크가 심하게 닳은 뒤에는, 구두 수선공에게 브레이크 블록에 가죽 띠를 못으로 박아 달라고 부탁했습니다. 오늘날 많은 사람은 이것을 브레이크 라이닝의 발명으로 봅니다. 반대로 오르막에서는 엔진의 힘이 모자랐습니다. 그럴 때는 베르타 벤츠가 차를 조종하는 동안 아들들이 힘껏 차를 밀어야 했습니다."},{"de":"Bei Einbruch der Dunkelheit erreichten die drei Reisenden Pforzheim – müde, schmutzig, aber stolz. Noch am selben Abend teilte Bertha Benz ihrem Mann per Telegramm mit, dass alle wohlbehalten angekommen waren.","ko":"날이 어두워질 무렵 세 사람은 포르츠하임에 도착했습니다. 지치고 더러워졌지만 자랑스러웠습니다. 바로 그날 저녁 베르타 벤츠는 모두 무사히 도착했다고 남편에게 전보로 알렸습니다."},{"de":"Die Fahrt blieb nicht ohne Folgen für die Entwicklung des Motorwagens. Unterwegs hatte Bertha Benz genau beobachtet, welche Bauteile noch nicht zuverlässig funktionierten. Nach ihrer Rückkehr schlug sie ihrem Mann deshalb mehrere Verbesserungen vor, darunter einen zusätzlichen Gang für Steigungen. Vor allem aber hatte sie bewiesen, dass der Motorwagen mehr war als ein Spielzeug: Man konnte damit wirklich reisen. Die Nachricht von der Fahrt verbreitete sich schnell und war die beste Werbung für den Motorwagen. Heute gilt Bertha Benz als Pionierin des Automobils und ihre Reise als die erste Fernfahrt der Autogeschichte.","ko":"이 여행은 모토르바겐의 발전에 여러 영향을 끼쳤습니다. 베르타 벤츠는 가는 길에 어떤 부품이 아직 제대로 작동하지 않는지 자세히 살펴보았습니다. 그래서 돌아온 뒤 남편에게 몇 가지 개선점을 제안했는데, 그중에는 오르막길용 기어를 하나 더 다는 것도 있었습니다. 무엇보다도 그녀는 모토르바겐이 장난감 이상이라는 것을 증명했습니다. 이 차로 실제로 여행할 수 있었던 것입니다. 이 여행 소식은 빠르게 퍼졌고, 모토르바겐을 알리는 최고의 광고가 되었습니다. 오늘날 베르타 벤츠는 자동차의 선구자로, 그녀의 여행은 자동차 역사상 최초의 장거리 주행으로 여겨집니다."}],"questions":[{"type":"rf","kind":"inference","q":"Bertha Benz teilte die Meinung vieler Zeitgenossen über den Motorwagen.","answer":1,"evidence":"glaubte fest an die neue Technik","pairs":[["glaubte fest an die neue Technik","teilte die Meinung vieler Zeitgenossen"]],"explain":"본문은 많은 사람이 이 차를 위험한 장난감으로 여겼다고 한 뒤, 베르타는 '반대로(dagegen)' 새 기술을 굳게 믿었다고 해요. 그러니 베르타는 당시 사람들과 생각이 달랐어요. 문제는 Zeitgenossen, Motorwagen 같은 본문 낱말을 썼지만 내용은 반대예요."},{"type":"mc","kind":"detail","q":"Was erfährt man über den Beginn der Fahrt?","options":["Ihr Mann erfuhr erst hinterher von dem Plan.","Bertha Benz brach mit den Söhnen erst abends auf.","Die Söhne planten die Fahrt mit ihrem Vater."],"answer":0,"evidence":"Ohne ihrem Mann etwas davon zu erzählen","pairs":[["Ohne ihrem Mann etwas davon zu erzählen","erfuhr erst hinterher von dem Plan"]],"explain":"베르타는 남편에게 아무 이야기도 하지 않고(Ohne ihrem Mann etwas davon zu erzählen) 떠났어요. 그러니 카를 벤츠는 이 계획을 나중에야 알게 되었어요. 출발은 저녁이 아니라 이른 아침(frühmorgens)이었고, 아들들이 아버지와 함께 계획했다는 말은 없어요."},{"type":"mc","kind":"detail","q":"Wofür brauchte Bertha Benz das Ligroin aus der Apotheke?","options":["um die verstopfte Kraftstoffleitung zu reinigen","damit der Motor wieder genug Brennstoff bekam","um das beschädigte Zündkabel zu isolieren"],"answer":1,"evidence":"ein Reinigungsmittel, das damals als Treibstoff diente","pairs":[["das damals als Treibstoff diente","Brennstoff"],["der Kraftstoff zu Ende ging","damit der Motor wieder genug Brennstoff bekam"]],"explain":"리그로인은 세정제였지만 당시에는 연료(Treibstoff)로 쓰였어요. 연료가 떨어져서 샀으니 차를 계속 몰기 위해서예요. 막힌 연료관은 모자 핀으로, 손상된 전선은 스타킹 밴드로 고쳤어요. 리그로인이 세정제라는 점을 이용한 함정에 주의하세요."},{"type":"mc","kind":"meaning","q":"Was bedeutet der Satz „Viele sehen darin heute die Erfindung des Bremsbelags“?","options":["Viele Leute sahen damals zum ersten Mal einen Bremsbelag.","Der Schuster gilt heute als Erfinder des ersten Motorwagens.","Die Lösung mit dem Leder war der Anfang einer neuen Technik."],"answer":2,"evidence":"bat sie einen Schuster, Lederstreifen auf die Bremsklötze zu nageln","pairs":[["Erfindung des Bremsbelags","Anfang einer neuen Technik"],["Lederstreifen auf die Bremsklötze zu nageln","Lösung mit dem Leder"]],"explain":"darin은 바로 앞 문장, 곧 구두 수선공이 브레이크 블록에 가죽 띠를 박은 일을 가리켜요. 여기서 sehen은 눈으로 본다는 뜻이 아니라 in etwas etwas sehen(~을 ~로 여기다)으로 쓰였어요. 오늘날 많은 사람이 이 임시 수리를 브레이크 라이닝의 발명, 곧 새로운 기술의 시작으로 여겨요. 당시 사람들이 브레이크 라이닝을 처음 보았다는 뜻도, 구두 수선공이 자동차를 발명했다는 뜻도 아니에요."},{"type":"rf","kind":"detail","q":"An Steigungen kam der Wagen nur mit Hilfe der Söhne voran.","answer":0,"evidence":"Dann mussten die Söhne kräftig schieben","pairs":[["Bergauf","An Steigungen"],["mussten die Söhne kräftig schieben","nur mit Hilfe der Söhne"]],"explain":"오르막에서는(Bergauf) 엔진의 힘이 모자라서 아들들이 힘껏 차를 밀어야 했어요. 문제는 Bergauf를 An Steigungen으로, '아들들이 밀어야 했다'를 '아들들의 도움으로만 나아갔다'로 바꿔 말했어요."},{"type":"mc","kind":"meaning","q":"Was zeigt die Beschreibung „müde, schmutzig, aber stolz“?","options":["Der Tag war anstrengend, aber die drei waren zufrieden.","Die drei schämten sich für ihr schmutziges Aussehen.","Die Söhne waren müde und wollten nicht mehr weiterfahren."],"answer":0,"evidence":"müde, schmutzig, aber stolz","pairs":[["müde, schmutzig","anstrengend"],["aber stolz","aber die drei waren zufrieden"]],"explain":"müde(지친)와 schmutzig(더러운)는 여행이 힘들었다는 것을, aber stolz(하지만 자랑스러운)는 그래도 해냈다는 만족감을 보여 줘요. 세 사람이 부끄러워했다거나 아들들이 더 가고 싶어 하지 않았다는 말은 없어요."},{"type":"rf","kind":"detail","q":"Den zusätzlichen Gang für Steigungen schlug Carl Benz seiner Frau vor.","answer":1,"evidence":"Nach ihrer Rückkehr schlug sie ihrem Mann deshalb mehrere Verbesserungen vor","pairs":[["schlug sie ihrem Mann deshalb mehrere Verbesserungen vor","schlug Carl Benz seiner Frau vor"]],"explain":"오르막길용 기어를 제안한 사람은 베르타 벤츠예요. 그녀가 돌아온 뒤 남편에게 제안했어요(schlug sie ihrem Mann … vor). 문제는 제안한 사람과 제안을 받은 사람을 바꿔 놓은 함정이에요."},{"type":"mc","kind":"gist","q":"Was ist das Hauptthema des Textes?","options":["die Entwicklung des Motorwagens bis zum Patent","die Geschichte der ersten Tankstelle in Wiesloch","ein Abenteuer, das den Nutzen des Autos bewies"],"answer":2,"evidence":"Vor allem aber hatte sie bewiesen, dass der Motorwagen mehr war als ein Spielzeug","pairs":[["hatte sie bewiesen, dass der Motorwagen mehr war als ein Spielzeug","den Nutzen des Autos bewies"]],"explain":"글 전체는 베르타 벤츠의 장거리 주행과 그 결과를 다뤄요. 마지막 단락에서 이 여행이 모토르바겐이 장난감 이상이라는 것, 곧 실제로 쓸모 있다는 것을 증명했다고 정리해요. 특허와 약국 이야기는 글의 일부일 뿐이에요."}],"grammar":[{"title":"과거완료 – 이야기보다 앞선 일","term":"Plusquamperfekt","explain":"과거완료는 과거의 어떤 때보다 더 먼저 일어난 일을 나타내요. hatte/war를 동사 자리에 두고 과거분사를 문장 끝에 둬요. 부문장에서는 hatte/war가 과거분사 뒤 맨 끝에 와요. 이 글의 중심 시점은 1888년의 여행이에요. 그보다 앞선 1886년의 특허, 여행 전의 사정, 결과를 말하는 시점보다 앞서 여행 중에 관찰한 일은 과거완료로 써요. 현재완료에서 sein을 쓰는 동사는 과거완료에서도 war를 써요.","pattern":"주어 + hatte/war + … + 과거분사(문장 끝)","examples":[{"de":"Bereits im Jahr 1886 hatte der Ingenieur Carl Benz aus Mannheim ein Patent für seinen Motorwagen erhalten.","ko":"만하임의 기술자 카를 벤츠는 이미 1886년에 자신이 만든 모토르바겐의 특허를 받았습니다.","mark":["hatte","erhalten"],"parts":[["Bereits im Jahr 1886","부사어(시간)"],["hatte","동사"],["der Ingenieur Carl Benz aus Mannheim","주어"],["ein Patent für seinen Motorwagen","4격 목적어"],["erhalten.","동사(끝)"]]},{"de":"Unterwegs hatte Bertha Benz genau beobachtet, welche Bauteile noch nicht zuverlässig funktionierten.","ko":"베르타 벤츠는 가는 길에 어떤 부품이 아직 제대로 작동하지 않는지 자세히 살펴보았습니다.","mark":["hatte","beobachtet"]},{"de":"Bertha Benz dagegen, die Geld aus ihrer Mitgift in die Werkstatt ihres Ehemannes gesteckt hatte, glaubte fest an die neue Technik.","ko":"반면 결혼 지참금으로 받은 돈을 남편의 작업장에 쏟아부었던 베르타 벤츠는 이 새로운 기술을 굳게 믿었습니다.","mark":["gesteckt hatte"]}],"tip":"과거완료는 주로 과거형 문장과 함께 나와요. 과거의 두 일 가운데 더 먼저 일어난 쪽이 과거완료예요. 세 번째 예문에서 지참금으로 받은 돈을 작업장에 넣은 일은 베르타가 새 기술을 믿었다는 이야기보다 먼저 일어났어요."},{"title":"zu 부정사구 – ohne … zu, bitten … zu","term":"Infinitivgruppen mit ohne … zu und nach bitten","explain":"ohne … zu는 '~하지 않고, ~하지 않은 채'라는 뜻이에요. 부정사구에는 주어가 따로 없고, 주절의 주어가 그 행동도 해요. zu + 동사원형은 부정사구 끝에 와요. bitten, versuchen, beschließen 같은 동사 뒤에도 zu 부정사구가 와요. bitten 문장에서는 부탁을 받은 사람(einen Schuster)이 부정사구의 행동을 해요. 부정사구는 쉼표로 주절과 나눠요.","pattern":"Ohne + … + zu + 동사원형, 동사 + 주어 … / 주어 + bitten + 4격, … zu + 동사원형","examples":[{"de":"Ohne ihrem Mann etwas davon zu erzählen, brach sie frühmorgens in Begleitung ihrer beiden Söhne auf.","ko":"남편에게 아무 이야기도 하지 않은 채, 그녀는 이른 아침 두 아들과 함께 길을 떠났습니다.","mark":["Ohne","zu erzählen"],"parts":[["Ohne ihrem Mann etwas davon zu erzählen,","zu 부정사구"],["brach","동사"],["sie","주어"],["frühmorgens","부사어(시간)"],["in Begleitung ihrer beiden Söhne","부사어(방법)"],["auf.","동사(끝)"]]},{"de":"Nachdem sich die Bremsen bergab stark abgenutzt hatten, bat sie einen Schuster, Lederstreifen auf die Bremsklötze zu nageln.","ko":"내리막에서 브레이크가 심하게 닳은 뒤에는, 구두 수선공에게 브레이크 블록에 가죽 띠를 못으로 박아 달라고 부탁했습니다.","mark":["bat","einen Schuster","zu nageln"],"parts":[["Nachdem sich die Bremsen bergab stark abgenutzt hatten,","종속절"],["bat","동사"],["sie","주어"],["einen Schuster,","4격 목적어"],["Lederstreifen auf die Bremsklötze zu nageln.","zu 부정사구"]]}],"tip":"분리동사는 zu가 앞부분과 어간 사이에 들어가요(aufbrechen → aufzubrechen). ohne … zu는 두 행동의 주어가 같을 때 쓰고, 주어가 다르면 ohne dass + 부문장을 써요."},{"title":"동격 – 명사 뒤에 붙이는 설명","term":"Apposition","explain":"명사 뒤에 그 명사를 설명하는 명사구를 쉼표로 붙일 수 있어요. 이것을 동격이라고 해요. 동격 명사구는 보통 앞 명사와 같은 격을 써요. 낯선 낱말이나 숫자를 짧게 설명할 수 있어서 설명문과 기사에 자주 나와요.","pattern":"명사, + 관사 + (형용사) + 명사 (+ 관계절),","examples":[{"de":"Als in Wiesloch der Kraftstoff zu Ende ging, kaufte Bertha Benz in einer Apotheke Ligroin, ein Reinigungsmittel, das damals als Treibstoff diente.","ko":"비스로흐에서 연료가 떨어지자 베르타 벤츠는 한 약국에서 리그로인을 샀습니다. 당시 연료로 쓰이던 세정제였습니다.","mark":["Ligroin, ein Reinigungsmittel"],"parts":[["Als in Wiesloch der Kraftstoff zu Ende ging,","종속절"],["kaufte","동사"],["Bertha Benz","주어"],["in einer Apotheke","부사어(장소)"],["Ligroin, ein Reinigungsmittel,","4격 목적어"],["das damals als Treibstoff diente.","관계절"]]},{"de":"Im August 1888 fasste sie den mutigen Entschluss, mit dem Motorwagen von Mannheim nach Pforzheim zu fahren – eine Strecke von rund 100 Kilometern.","ko":"1888년 8월, 베르타는 모토르바겐을 타고 만하임에서 포르츠하임까지 달리겠다는 용감한 결심을 했습니다. 약 100킬로미터나 되는 거리였습니다.","mark":["eine Strecke von rund 100 Kilometern"]}],"tip":"첫 번째 예문의 ein Reinigungsmittel은 Ligroin과 같은 4격이고, 관계절 das … diente는 다시 Reinigungsmittel을 설명해요. 두 번째 예문에서는 eine Strecke von rund 100 Kilometern을 쉼표 대신 줄표(–) 뒤에 붙였어요. 이 동격은 명사 하나가 아니라 앞에 나온 구간 전체(von Mannheim nach Pforzheim)를 설명해요. „der Ingenieur Carl Benz“처럼 쉼표 없이 이름 앞에 붙는 동격도 있어요."},{"title":"als · für와 함께 쓰는 동사 – halten für, bezeichnen als, gelten als","term":"Verben mit als / für + Prädikativ","explain":"어떤 대상을 무엇으로 여기거나 부르는 동사 가운데에는 als나 für와 함께 쓰는 것이 많아요. etwas für etwas halten(~을 ~로 여기다), etwas als etwas bezeichnen(~을 ~라고 부르다), als etwas gelten(~로 여겨지다)이 대표적이에요. für 뒤에는 4격이 오고, als 뒤에는 그 말이 설명하는 명사와 같은 격이 와요.","pattern":"4격 + für + 4격 halten / 4격 + als + … bezeichnen / 주어 + gilt als + 1격","examples":[{"de":"Längere Fahrten hatte bis dahin niemand gewagt, und viele Zeitgenossen hielten das laute Fahrzeug für ein gefährliches Spielzeug.","ko":"그때까지 먼 거리를 달려 볼 엄두를 낸 사람은 아무도 없었고, 당시 많은 사람이 이 시끄러운 탈것을 위험한 장난감으로 여겼습니다.","mark":["hielten","für ein gefährliches Spielzeug"]},{"de":"Die Apotheke wird deshalb heute als erste Tankstelle der Welt bezeichnet.","ko":"그래서 이 약국은 오늘날 세계 최초의 주유소라고 불립니다.","mark":["als erste Tankstelle der Welt","bezeichnet"],"parts":[["Die Apotheke","주어"],["wird","동사"],["deshalb","접속부사"],["heute","부사어(시간)"],["als erste Tankstelle der Welt","보어"],["bezeichnet.","동사(끝)"]]},{"de":"Heute gilt Bertha Benz als Pionierin des Automobils und ihre Reise als die erste Fernfahrt der Autogeschichte.","ko":"오늘날 베르타 벤츠는 자동차의 선구자로, 그녀의 여행은 자동차 역사상 최초의 장거리 주행으로 여겨집니다.","mark":["gilt","als Pionierin des Automobils","als die erste Fernfahrt der Autogeschichte"]}],"tip":"수동태 문장(wird … als … bezeichnet)에서는 als 뒤의 명사가 주어와 같은 1격이에요. 본문의 „Viele sehen darin heute die Erfindung …“처럼 in etwas etwas sehen(~을 ~로 보다)도 비슷한 뜻으로 써요."}],"vocab":[{"de":"das Patent, -e","ko":"특허"},{"de":"die Erfindung, -en","ko":"발명, 발명품"},{"de":"die Öffentlichkeit (Sg.)","ko":"대중, 세상 사람들"},{"de":"wagen","ko":"감히 ~하다, 엄두를 내다"},{"de":"der Zeitgenosse, -n","ko":"같은 시대의 사람"},{"de":"die Mitgift, -en","ko":"결혼 지참금"},{"de":"auf|brechen (bricht auf, brach auf, ist aufgebrochen)","ko":"길을 떠나다, 출발하다"},{"de":"der Kraftstoff, -e","ko":"연료"},{"de":"das Reinigungsmittel, -","ko":"세정제, 세제"},{"de":"verstopft","ko":"막힌"},{"de":"sich ab|nutzen","ko":"닳다, 마모되다"},{"de":"der Schuster, -","ko":"구두 수선공, 제화공"},{"de":"der Bremsbelag, -¨e","ko":"브레이크 라이닝 (브레이크에 붙이는 마찰재)"},{"de":"die Motorleistung, -en","ko":"엔진 출력, 엔진의 힘"},{"de":"wohlbehalten","ko":"무사히, 탈 없이"},{"de":"beweisen (bewies, hat bewiesen)","ko":"증명하다"}],"phrases":[{"de":"den Entschluss fassen, etwas zu tun","ko":"~하기로 결심하다","ex":"Im August 1888 fasste sie den mutigen Entschluss, mit dem Motorwagen von Mannheim nach Pforzheim zu fahren – eine Strecke von rund 100 Kilometern.","exko":"1888년 8월, 베르타는 모토르바겐을 타고 만하임에서 포르츠하임까지 달리겠다는 용감한 결심을 했습니다. 약 100킬로미터나 되는 거리였습니다."},{"de":"Interesse an etwas (Dat.) zeigen","ko":"~에 관심을 보이다","ex":"Zwei Jahre später zeigte die Öffentlichkeit jedoch kaum Interesse an der Erfindung.","exko":"그러나 2년이 지난 뒤에도 사람들은 이 발명에 거의 관심을 보이지 않았습니다."},{"de":"zu Ende gehen (ging zu Ende, ist zu Ende gegangen)","ko":"떨어지다, 바닥나다, 끝나다","ex":"Als in Wiesloch der Kraftstoff zu Ende ging, kaufte Bertha Benz in einer Apotheke Ligroin, ein Reinigungsmittel, das damals als Treibstoff diente.","exko":"비스로흐에서 연료가 떨어지자 베르타 벤츠는 한 약국에서 리그로인을 샀습니다. 당시 연료로 쓰이던 세정제였습니다."},{"de":"bei Einbruch der Dunkelheit","ko":"날이 어두워질 무렵에","ex":"Bei Einbruch der Dunkelheit erreichten die drei Reisenden Pforzheim – müde, schmutzig, aber stolz.","exko":"날이 어두워질 무렵 세 사람은 포르츠하임에 도착했습니다. 지치고 더러워졌지만 자랑스러웠습니다."},{"de":"jemandem etwas mit|teilen","ko":"~에게 ~을 알리다","ex":"Noch am selben Abend teilte Bertha Benz ihrem Mann per Telegramm mit, dass alle wohlbehalten angekommen waren.","exko":"바로 그날 저녁 베르타 벤츠는 모두 무사히 도착했다고 남편에게 전보로 알렸습니다."}],"words":344},{"id":"b1-03","level":"B1","no":3,"title":"Hunde im Büro?","titleKo":"사무실에 개를 데려와도 될까요?","type":"Leserbriefe","typeKo":"독자 편지","intro":"사무실에 개를 데려오는 문제를 두고 독자 세 명이 신문에 보낸 의견이에요.","focus":["접속법 2식 조건문","es + zu 부정사","의견 말하기","접속부사"],"paragraphs":[{"style":"meta","de":"Zum Artikel „Immer mehr Firmen erlauben Hunde am Arbeitsplatz“ vom 12. März","ko":"3월 12일 자 기사 「직장에 개를 허용하는 회사가 늘고 있다」에 대하여"},{"label":"A · Andrea Schulte, Grafikdesignerin","de":"Seit drei Jahren arbeite ich in einer Werbeagentur, in der Hunde ausdrücklich erlaubt sind. Einen Arbeitsplatz ohne Bürohund kann ich mir kaum vorstellen. Meine Hündin Lotte liegt tagsüber unter dem Schreibtisch, und wenn sie durch das Großraumbüro läuft, schmunzeln selbst gestresste Kollegen. Ich bin der Meinung, dass ein Bürohund das Arbeitsklima verbessert. Außerdem tut Lotte meiner Gesundheit gut, denn sie sorgt für regelmäßige Pausen: Zur Erholung gehe ich mittags eine halbe Stunde mit ihr spazieren, statt am Schreibtisch zu essen. Ohne Lotte würde ich wahrscheinlich bis zum Feierabend am Schreibtisch sitzen. Wären alle Arbeitgeber so offen wie meiner, gäbe es weniger gestresste Beschäftigte.","ko":"저는 3년째 개를 데려와도 된다고 분명히 허용하는 광고 회사에서 일하고 있어요. 사무실 개가 없는 직장은 거의 상상할 수 없어요. 제 개 로테는 낮에는 책상 밑에 누워 있고, 로테가 넓은 개방형 사무실을 지나가면 스트레스에 시달리던 동료들조차 빙그레 웃어요. 저는 사무실 개가 직장 분위기를 좋게 만든다고 생각해요. 게다가 로테는 제 건강에도 좋아요. 로테 덕분에 규칙적으로 쉬거든요. 점심때는 책상에서 밥을 먹는 대신 쉴 겸 로테와 30분 동안 산책해요. 로테가 없다면 아마 퇴근할 때까지 책상 앞에 앉아 있을 거예요. 모든 회사가 우리 회사처럼 열려 있다면 스트레스에 시달리는 직장인이 더 적을 거예요."},{"style":"meta","de":"Andrea Schulte, Wiesbaden","ko":"안드레아 슐테, 비스바덴"},{"label":"B · Tim Albers, Buchhalter","de":"Ich bin ein großer Tierfreund. Trotzdem halte ich es für falsch, Hunde im Büro zu erlauben, und ich war erleichtert, dass Ihr Artikel wenigstens kurz die Allergiker erwähnt. Ich bin selbst Allergiker und bekomme trotz täglicher Allergietabletten nach einer Stunde neben einem Hund tränende Augen und Atemprobleme. Als vor zwei Jahren ein Kollege seinen Hund mitbrachte, musste ich schließlich in ein Einzelbüro umziehen, und niemand hatte mich vorab gefragt. Meiner Meinung nach wird in der Diskussion zu oft vergessen, dass Allergiker keine Wahl haben. Hätte ich keine Allergie, würde ich mich über einen Bürohund wahrscheinlich sogar freuen. So aber müsste ich den Arbeitgeber wechseln, wenn noch mehr Kollegen ihre Hunde mitbringen würden.","ko":"저는 동물을 무척 좋아해요. 그런데도 사무실에 개를 허용하는 것은 잘못이라고 생각하고, 귀 신문의 기사가 적어도 짧게나마 알레르기가 있는 사람들을 언급해서 마음이 놓였어요. 저도 알레르기가 있는데, 매일 알레르기약을 먹어도 개 옆에 한 시간만 있으면 눈물이 나고 숨쉬기가 힘들어져요. 2년 전 한 동료가 자기 개를 데려왔을 때 저는 결국 1인 사무실로 옮겨야 했는데, 아무도 제게 미리 묻지 않았어요. 제 생각에 이 논의에서는 알레르기가 있는 사람들에게 선택권이 없다는 점이 너무 자주 잊혀요. 알레르기가 없다면 저도 사무실 개를 아마 반길 거예요. 하지만 실제로는 알레르기가 있으니, 개를 데려오는 동료가 더 늘어난다면 직장을 옮겨야 할 거예요."},{"style":"meta","de":"Tim Albers, Darmstadt","ko":"팀 알버스, 다름슈타트"},{"label":"C · Petra Lang, Geschäftsführerin","de":"Als Geschäftsführerin einer kleinen Firma mit 20 Beschäftigten kenne ich beide Seiten. Bei uns dürfen Hunde seit einem Jahr ins Büro, allerdings nur unter klaren Bedingungen. Jeder Hund muss zunächst einen Probetag bestehen. Die Küche und der Besprechungsraum bleiben hundefreie Zonen, und wer einen Hund mitbringen will, braucht die Zustimmung der Kollegen im selben Büro. Obwohl wir anfangs Bedenken hatten, haben wir bisher überwiegend gute Erfahrungen gemacht. Ich halte es deshalb für einen Fehler, Hunde grundsätzlich zu verbieten. Genauso falsch wäre es aber, alles zu erlauben. Ohne Regeln gäbe es schnell Konflikte, und am Ende würden alle verlieren – die Hundebesitzer, die Allergiker und die Firma. Ein Kompromiss kostet Mühe, aber er lohnt sich.","ko":"직원 20명의 작은 회사를 운영하는 대표로서 저는 양쪽 입장을 다 알고 있어요. 우리 회사에서는 1년 전부터 개를 사무실에 데려올 수 있어요. 다만 분명한 조건이 있어요. 모든 개는 먼저 시험 출근일을 통과해야 해요. 주방과 회의실은 개가 들어갈 수 없는 구역으로 남겨 두고, 개를 데려오려는 사람은 같은 사무실을 쓰는 동료들의 동의를 받아야 해요. 처음에는 걱정이 있었지만 지금까지 대체로 좋은 경험을 했어요. 그래서 저는 개를 무조건 금지하는 것은 잘못이라고 생각해요. 하지만 모든 것을 허용하는 것도 똑같이 잘못일 거예요. 규칙이 없다면 금방 갈등이 생기고, 결국에는 개 주인도, 알레르기가 있는 사람도, 회사도 모두 손해를 볼 거예요. 타협에는 수고가 들지만 그만한 가치가 있어요."},{"style":"meta","de":"Petra Lang, Mainz","ko":"페트라 랑, 마인츠"}],"questions":[{"type":"mc","kind":"match","q":"Wer hat wegen eines Tieres im Büro einen anderen Arbeitsraum bekommen?","options":["Andrea Schulte","Tim Albers","Petra Lang"],"answer":1,"evidence":"musste ich schließlich in ein Einzelbüro umziehen","pairs":[["in ein Einzelbüro umziehen","einen anderen Arbeitsraum bekommen"]],"explain":"팀 알버스 씨는 동료가 개를 데려온 뒤 결국 1인 사무실로 옮겨야 했어요. in ein Einzelbüro umziehen을 '다른 업무 공간을 얻었다'로 바꿔 말했어요. 회사(Arbeitgeber)를 옮겨야 할 거라는 말은 개를 데려오는 동료가 더 늘어날 경우를 가정한 것일 뿐이에요."},{"type":"mc","kind":"match","q":"Für wen ist das eigene Tier ein Grund, die Arbeit regelmäßig zu unterbrechen?","options":["Andrea Schulte","Tim Albers","Petra Lang"],"answer":0,"evidence":"denn sie sorgt für regelmäßige Pausen","pairs":[["sorgt für regelmäßige Pausen","die Arbeit regelmäßig zu unterbrechen"]],"explain":"안드레아 슐테 씨의 개 로테는 규칙적으로 쉬게 해 줘요(sorgt für regelmäßige Pausen). 그래서 점심때는 책상에서 먹지 않고 로테와 산책해요. Pausen machen을 die Arbeit unterbrechen으로 바꿔 말했어요."},{"type":"mc","kind":"match","q":"Wer beschreibt, unter welchen Voraussetzungen Hunde in einer Firma erlaubt sind?","options":["Andrea Schulte","Tim Albers","Petra Lang"],"answer":2,"evidence":"allerdings nur unter klaren Bedingungen","pairs":[["unter klaren Bedingungen","unter welchen Voraussetzungen"]],"explain":"페트라 랑 씨는 개를 허용하는 조건(시험 출근일, 개 금지 구역, 동료의 동의)을 하나씩 설명해요. Bedingungen을 Voraussetzungen으로 바꿔 말했어요. 안드레아 슐테 씨의 회사도 개를 허용하지만, 조건에 관한 이야기는 없어요."},{"type":"mc","kind":"match","q":"Wer würde einen Hund am Arbeitsplatz begrüßen, wenn es gesundheitlich möglich wäre?","options":["Andrea Schulte","Tim Albers","Petra Lang"],"answer":1,"evidence":"Hätte ich keine Allergie, würde ich mich über einen Bürohund wahrscheinlich sogar freuen.","pairs":[["Hätte ich keine Allergie","wenn es gesundheitlich möglich wäre"],["würde ich mich über einen Bürohund wahrscheinlich sogar freuen","würde einen Hund am Arbeitsplatz begrüßen"]],"explain":"팀 알버스 씨는 알레르기가 없다면 사무실 개를 반길 거라고 해요. 알레르기라는 건강 사정을 '건강상 가능하다면'으로 바꿔 말했어요. 안드레아 슐테 씨는 이미 개를 데려오고 있으니 조건이 필요 없어요."},{"type":"mc","kind":"detail","q":"Was gilt in der Firma von Petra Lang für Beschäftigte, die einen Hund mitbringen möchten?","options":["Sie dürfen den Hund dann auch in die Küche mitnehmen.","Sie müssen vorher ihre Bürokollegen um Erlaubnis fragen.","Sie müssen den Hund an einem Probetag noch zu Hause lassen."],"answer":1,"evidence":"wer einen Hund mitbringen will, braucht die Zustimmung der Kollegen im selben Büro","pairs":[["braucht die Zustimmung","um Erlaubnis fragen"],["der Kollegen im selben Büro","ihre Bürokollegen"]],"explain":"개를 데려오려면 같은 사무실을 쓰는 동료들의 동의(Zustimmung)가 필요해요. 이것을 '사무실 동료들에게 허락을 구해야 한다'로 바꿔 말했어요. 주방은 개가 들어갈 수 없는 구역이고, 시험 출근일(Probetag)은 개가 회사에 와서 통과해야 하는 날이에요."},{"type":"mc","kind":"paraphrase","q":"Was meint Tim Albers mit der Aussage, „dass Allergiker keine Wahl haben“?","options":["Allergiker dürfen bei der Diskussion gar nicht mitreden.","Sie können nicht entscheiden, ob ein Hund ihnen schadet.","Allergiker finden nur schwer einen neuen Arbeitgeber."],"answer":1,"evidence":"trotz täglicher Allergietabletten nach einer Stunde neben einem Hund tränende Augen und Atemprobleme","pairs":[["keine Wahl haben","können nicht entscheiden"],["tränende Augen und Atemprobleme","ob ein Hund ihnen schadet"]],"explain":"개를 좋아하는 사람은 개와 함께할지 스스로 정할 수 있지만, 알레르기가 있는 사람은 약을 먹어도 몸이 반응해요. 개가 자기 몸에 해가 될지 말지를 스스로 고를 수 없다는 뜻이에요. 논의에 끼지 못한다거나 새 직장을 찾기 어렵다는 말은 본문에 없어요."},{"type":"mc","kind":"paraphrase","q":"Was meint Petra Lang mit dem Satz „Genauso falsch wäre es aber, alles zu erlauben“?","options":["Auch eine Erlaubnis ohne Grenzen hält sie für schlecht.","Sie findet es falsch, dass Hunde bei ihr erlaubt sind.","Sie würde Hunde im Büro am liebsten grundsätzlich verbieten."],"answer":0,"evidence":"Ich halte es deshalb für einen Fehler, Hunde grundsätzlich zu verbieten.","pairs":[["alles zu erlauben","eine Erlaubnis ohne Grenzen"],["Genauso falsch","hält sie für schlecht"]],"explain":"바로 앞에서 페트라 랑 씨는 개를 무조건 금지하는 것은 잘못이라고 해요. 이어서 '모든 것을 허용하는 것도 똑같이 잘못'이라고 하니, 제한 없는 허용도 좋지 않다는 뜻이에요. 그녀의 회사는 조건을 두고 개를 허용하고, 금지에는 반대해요."},{"type":"mc","kind":"gist","q":"Welche Haltung vertritt Petra Lang?","options":["Hunde sollten im Büro verboten werden, weil es sonst Konflikte gibt.","Mit festen Absprachen können Tiere am Arbeitsplatz gut funktionieren.","Jede Firma sollte Hunde erlauben, weil sie das Arbeitsklima verbessern."],"answer":1,"evidence":"Ohne Regeln gäbe es schnell Konflikte, und am Ende würden alle verlieren","pairs":[["unter klaren Bedingungen","Mit festen Absprachen"],["überwiegend gute Erfahrungen","gut funktionieren"]],"explain":"페트라 랑 씨는 금지에도, 제한 없는 허용에도 반대해요. 분명한 규칙을 두고 개를 허용하자는 것이 그녀의 입장이에요. '금지해야 한다'는 선지는 Konflikte를, '모든 회사가 허용해야 한다'는 선지는 Arbeitsklima를 본문에서 가져왔지만, 각각 금지와 전면 허용을 주장해서 틀려요."}],"grammar":[{"title":"접속법 2식 – wenn 없이 쓰는 조건문","term":"Irreale Bedingungen ohne wenn (Verb am Satzanfang)","explain":"접속법 2식은 사실과 다른 상황을 가정할 때 써요. wenn을 쓰면 wenn 절의 동사가 끝에 오지만, wenn을 빼면 접속법 동사(Hätte, Wäre)가 문장 맨 앞에 와요. 뒤따르는 주절에도 접속법 2식(würde + 동사원형, gäbe, müsste)을 쓰고, 주절은 쉼표 바로 뒤에 동사로 시작해요. wenn 절은 세 번째 예문처럼 주절 뒤에 올 수도 있어요.","pattern":"Hätte/Wäre + 주어 + …, würde/gäbe + 주어 + … / 주절 + …, wenn + … + 동사(끝)","examples":[{"de":"Hätte ich keine Allergie, würde ich mich über einen Bürohund wahrscheinlich sogar freuen.","ko":"알레르기가 없다면 저도 사무실 개를 아마 반길 거예요.","mark":["Hätte","würde","freuen"],"parts":[["Hätte ich keine Allergie,","종속절"],["würde","동사"],["ich","주어"],["mich","재귀대명사"],["über einen Bürohund","전치사 목적어"],["wahrscheinlich","부사어"],["sogar","부사어"],["freuen.","동사(끝)"]]},{"de":"Wären alle Arbeitgeber so offen wie meiner, gäbe es weniger gestresste Beschäftigte.","ko":"모든 회사가 우리 회사처럼 열려 있다면 스트레스에 시달리는 직장인이 더 적을 거예요.","mark":["Wären","gäbe"]},{"de":"So aber müsste ich den Arbeitgeber wechseln, wenn noch mehr Kollegen ihre Hunde mitbringen würden.","ko":"하지만 실제로는 알레르기가 있으니, 개를 데려오는 동료가 더 늘어난다면 직장을 옮겨야 할 거예요.","mark":["müsste","wenn","mitbringen würden"]}],"tip":"wenn을 빼고 동사로 시작하는 조건문은 의문문처럼 보이지만, 쉼표 뒤에 주절이 이어지면 조건문이에요. haben, sein, geben과 화법조동사는 보통 hätte, wäre, gäbe, müsste, könnte 같은 형태를 쓰고, 다른 동사는 대부분 würde + 동사원형을 써요."},{"title":"es + zu 부정사 – Ich halte es für …, … zu …","term":"Korrelat „es“ mit zu-Infinitiv","explain":"„Ich halte es für falsch, … zu …“에서 es는 뒤에 나오는 zu 부정사구를 미리 가리켜요. 진짜 내용은 쉼표 뒤의 zu 부정사구에 있어요. etwas für + 형용사/명사 halten은 '~을 ~라고 여기다'라는 뜻이에요. „Falsch wäre es, … zu …“처럼 es가 주어 자리에 오는 문장도 같은 원리예요.","pattern":"주어 + halten + es + für + 형용사/명사, … zu + 동사원형 / 형용사 + wäre + es, … zu + 동사원형","examples":[{"de":"Ich halte es deshalb für einen Fehler, Hunde grundsätzlich zu verbieten.","ko":"그래서 저는 개를 무조건 금지하는 것은 잘못이라고 생각해요.","mark":["halte es","für einen Fehler","zu verbieten"],"parts":[["Ich","주어"],["halte","동사"],["es","4격 목적어"],["deshalb","접속부사"],["für einen Fehler,","보어"],["Hunde grundsätzlich zu verbieten.","zu 부정사구"]]},{"de":"Genauso falsch wäre es aber, alles zu erlauben.","ko":"하지만 모든 것을 허용하는 것도 똑같이 잘못일 거예요.","mark":["wäre es","alles zu erlauben"],"parts":[["Genauso falsch","보어"],["wäre","동사"],["es","주어"],["aber,","접속부사"],["alles zu erlauben.","zu 부정사구"]]}],"tip":"zu 부정사구 대신 dass 절이 올 수도 있어요: Ich halte es für falsch, dass Hunde erlaubt sind. 부정사구의 행동을 누가 하는지 분명할 때는 zu 부정사가 더 짧고 자연스러워요."},{"title":"의견 말하기 – der Meinung sein / meiner Meinung nach","term":"Meinung äußern","explain":"„Ich bin der Meinung, dass …“는 '~라고 생각해요'라는 뜻이고, dass 절의 동사는 끝에 와요. „Meiner Meinung nach“는 문장 첫 자리를 차지하는 부사어라서 바로 뒤에 동사가 와요. 반대 의견은 „Ich bin nicht der Meinung, dass …“로 말해요. 독자 편지에서는 이런 표현으로 의견과 사실을 나눠요.","pattern":"Ich bin (nicht) der Meinung, dass + … + 동사(끝) / Meiner Meinung nach + 동사 + …","examples":[{"de":"Ich bin der Meinung, dass ein Bürohund das Arbeitsklima verbessert.","ko":"저는 사무실 개가 직장 분위기를 좋게 만든다고 생각해요.","mark":["bin der Meinung, dass","verbessert"],"parts":[["Ich","주어"],["bin","동사"],["der Meinung,","보어"],["dass ein Bürohund das Arbeitsklima verbessert.","종속절"]]},{"de":"Meiner Meinung nach wird in der Diskussion zu oft vergessen, dass Allergiker keine Wahl haben.","ko":"제 생각에 이 논의에서는 알레르기가 있는 사람들에게 선택권이 없다는 점이 너무 자주 잊혀요.","mark":["Meiner Meinung nach"],"parts":[["Meiner Meinung nach","부사어"],["wird","동사"],["in der Diskussion","부사어"],["zu oft","부사어(빈도)"],["vergessen,","동사(끝)"],["dass Allergiker keine Wahl haben.","종속절"]]}],"tip":"„Ich bin der Meinung“의 der Meinung은 2격이고, „meiner Meinung nach“의 meiner는 3격이에요. 두 번째 예문의 wird … vergessen은 수동태로, '사람들이 잊는다'는 뜻이에요."},{"title":"접속부사 – trotzdem, außerdem, deshalb, allerdings","term":"Konjunktionaladverbien","explain":"접속부사는 앞 문장과 어떤 관계인지 알려 줘요: trotzdem(그런데도), außerdem(게다가), deshalb(그래서), allerdings(다만, 하지만). 접속부사가 문장 첫 자리에 오면 바로 뒤에 동사가 오고 주어는 동사 뒤로 가요(Trotzdem halte ich …). 동사 뒤 가운데 자리에 올 수도 있어요(Ich halte es deshalb …). und, aber, denn은 접속사라서 첫 자리를 차지하지 않고, 뒤 문장의 어순도 바뀌지 않아요. 다만 aber는 Genauso falsch wäre es aber …처럼 문장 가운데에 와서 부사처럼 쓰이기도 해요.","pattern":"접속부사 + 동사 + 주어 + … / 주어 + 동사 + … + 접속부사 + …","examples":[{"de":"Trotzdem halte ich es für falsch, Hunde im Büro zu erlauben, und ich war erleichtert, dass Ihr Artikel wenigstens kurz die Allergiker erwähnt.","ko":"그런데도 사무실에 개를 허용하는 것은 잘못이라고 생각하고, 귀 신문의 기사가 적어도 짧게나마 알레르기가 있는 사람들을 언급해서 마음이 놓였어요.","mark":["Trotzdem","halte","ich"],"parts":[["Trotzdem","접속부사"],["halte","동사"],["ich","주어"],["es","4격 목적어"],["für falsch,","보어"],["Hunde im Büro zu erlauben,","zu 부정사구"],["und","접속사"],["ich","주어"],["war","동사"],["erleichtert,","보어"],["dass Ihr Artikel wenigstens kurz die Allergiker erwähnt.","종속절"]]},{"de":"Bei uns dürfen Hunde seit einem Jahr ins Büro, allerdings nur unter klaren Bedingungen.","ko":"우리 회사에서는 1년 전부터 개를 사무실에 데려올 수 있어요. 다만 분명한 조건이 있어요.","mark":["allerdings"]},{"de":"Außerdem tut Lotte meiner Gesundheit gut, denn sie sorgt für regelmäßige Pausen: Zur Erholung gehe ich mittags eine halbe Stunde mit ihr spazieren, statt am Schreibtisch zu essen.","ko":"게다가 로테는 제 건강에도 좋아요. 로테 덕분에 규칙적으로 쉬거든요. 점심때는 책상에서 밥을 먹는 대신 쉴 겸 로테와 30분 동안 산책해요.","mark":["Außerdem tut Lotte","denn sie sorgt"]}],"tip":"세 번째 예문에서 Außerdem 뒤에는 동사 tut가 바로 오지만, denn 뒤에는 주어 sie가 먼저 와요. 이 차이로 접속부사와 접속사를 구별할 수 있어요."}],"vocab":[{"de":"ausdrücklich","ko":"분명히, 명시적으로"},{"de":"die Hündin, -nen","ko":"암캐 (암컷 개)"},{"de":"das Großraumbüro, -s","ko":"개방형 대형 사무실"},{"de":"schmunzeln","ko":"빙그레 웃다"},{"de":"das Arbeitsklima (Sg.)","ko":"직장 분위기"},{"de":"der Feierabend, -e","ko":"퇴근 (뒤의 시간)"},{"de":"der/die Beschäftigte, -n","ko":"직원, 종사자"},{"de":"der Allergiker, -","ko":"알레르기가 있는 사람"},{"de":"erwähnen","ko":"언급하다"},{"de":"um|ziehen (zog um, ist umgezogen)","ko":"(다른 방·집으로) 옮기다, 이사하다"},{"de":"vorab","ko":"미리, 사전에"},{"de":"die Bedingung, -en","ko":"조건"},{"de":"die Zustimmung (Sg.)","ko":"동의, 찬성"},{"de":"die Bedenken (Pl.)","ko":"우려, 걱정"},{"de":"grundsätzlich","ko":"원칙적으로, 예외 없이"},{"de":"der Kompromiss, -e","ko":"타협, 절충"}],"phrases":[{"de":"sich (Dat.) etwas vor|stellen können","ko":"~을 상상할 수 있다","ex":"Einen Arbeitsplatz ohne Bürohund kann ich mir kaum vorstellen.","exko":"사무실 개가 없는 직장은 거의 상상할 수 없어요."},{"de":"jemandem gut|tun (tat gut, hat gutgetan)","ko":"~에게 좋다, ~에게 이롭다","ex":"Außerdem tut Lotte meiner Gesundheit gut, denn sie sorgt für regelmäßige Pausen: Zur Erholung gehe ich mittags eine halbe Stunde mit ihr spazieren, statt am Schreibtisch zu essen.","exko":"게다가 로테는 제 건강에도 좋아요. 로테 덕분에 규칙적으로 쉬거든요. 점심때는 책상에서 밥을 먹는 대신 쉴 겸 로테와 30분 동안 산책해요."},{"de":"keine Wahl haben","ko":"선택권이 없다, 고를 수 없다","ex":"Meiner Meinung nach wird in der Diskussion zu oft vergessen, dass Allergiker keine Wahl haben.","exko":"제 생각에 이 논의에서는 알레르기가 있는 사람들에게 선택권이 없다는 점이 너무 자주 잊혀요."},{"de":"gute Erfahrungen machen","ko":"좋은 경험을 하다, 결과가 좋다","ex":"Obwohl wir anfangs Bedenken hatten, haben wir bisher überwiegend gute Erfahrungen gemacht.","exko":"처음에는 걱정이 있었지만 지금까지 대체로 좋은 경험을 했어요."},{"de":"sich lohnen","ko":"그만한 가치가 있다, 보람이 있다","ex":"Ein Kompromiss kostet Mühe, aber er lohnt sich.","exko":"타협에는 수고가 들지만 그만한 가치가 있어요."}],"words":349},{"id":"b1-04","level":"B1","no":4,"title":"Frische Luft, warme Wohnung","titleKo":"신선한 공기, 따뜻한 집","type":"Ratgeber im Kundenmagazin","typeKo":"고객 잡지의 생활 정보 글","intro":"겨울에 난방비를 아끼면서 곰팡이 없이 환기하는 방법을 알려 주는 글이에요.","focus":["um … zu와 damit","명령형과 sollte","분리동사의 앞말","beim + 동사원형"],"paragraphs":[{"de":"Im Winter stehen viele Mieterinnen und Mieter vor demselben Problem: Die Wohnung soll warm bleiben, doch nach wenigen Stunden wird die Raumluft stickig, und an den Fensterscheiben sammelt sich Kondenswasser. Wer dann einfach die Heizung höher dreht, ohne zu lüften, spart kein Geld, sondern riskiert Schimmel. Mit ein paar einfachen Regeln erreicht man beides: frische Luft und eine warme Wohnung.","ko":"겨울이 되면 많은 세입자가 같은 문제를 겪습니다. 집은 따뜻해야 하는데 몇 시간만 지나면 실내 공기가 탁해지고 유리창에 물방울이 맺힙니다. 이때 환기는 하지 않고 난방만 더 세게 틀면 돈이 절약되기는커녕 곰팡이가 생길 위험이 커집니다. 몇 가지 간단한 규칙만 지키면 신선한 공기와 따뜻한 집, 두 가지를 모두 얻을 수 있습니다."},{"de":"Stoßlüften statt Kippfenster","ko":"창문을 젖혀 두는 대신 활짝 열어 짧게 환기하기","style":"h"},{"de":"Viele Menschen kippen das Fenster und lassen es stundenlang so. Dabei wird die Luft kaum ausgetauscht, während die Wände um das Fenster stark auskühlen. Um die Wohnung richtig zu lüften, sollten Sie die Fenster deshalb mehrmals täglich ganz öffnen; im Winter genügen fünf bis zehn Minuten. Noch wirksamer ist das sogenannte Querlüften, bei dem man Fenster auf zwei Seiten der Wohnung gleichzeitig öffnet. So wird die verbrauchte Luft innerhalb weniger Minuten ersetzt, doch Wände und Möbel kühlen dabei kaum ab.","ko":"많은 사람이 창문을 조금만 젖혀 열고 몇 시간이고 그대로 둡니다. 그러면 공기는 거의 바뀌지 않는데, 창문 주변 벽은 심하게 식습니다. 그래서 집을 제대로 환기하려면 하루에 여러 번 창문을 활짝 여는 것이 좋습니다. 겨울에는 5분에서 10분이면 충분합니다. 집의 양쪽에 있는 창문을 동시에 여는 이른바 맞바람 환기는 효과가 더 좋습니다. 그러면 탁한 공기는 몇 분 안에 바뀌지만, 벽과 가구는 그동안 거의 식지 않습니다."},{"de":"Erst die Heizung herunterdrehen, dann lüften","ko":"먼저 난방을 줄이고 환기하기","style":"h"},{"de":"Drehen Sie die Thermostate der Heizkörper herunter, bevor Sie die Fenster öffnen, damit die Wärme nicht ungenutzt nach draußen entweicht. Anschließend sollte man die Heizung sofort wieder aufdrehen, statt zu warten, bis der Raum völlig ausgekühlt ist. Ein Raum, der nur kurz gelüftet wurde, ist nämlich schnell wieder warm, weil Wände und Möbel ihre Wärme gespeichert haben.","ko":"창문을 열기 전에 라디에이터의 온도 조절기를 낮추세요. 그래야 열이 쓸모없이 밖으로 빠져나가지 않습니다. 환기가 끝나면 방이 완전히 식을 때까지 기다리지 말고 곧바로 난방을 다시 올리는 것이 좋습니다. 잠깐만 환기한 방은 벽과 가구가 열을 간직하고 있어서 금방 다시 따뜻해집니다."},{"de":"Feuchtigkeit sofort nach draußen","ko":"습기는 바로 밖으로","style":"h"},{"de":"Beim Duschen, Kochen und Wäschetrocknen entsteht viel Wasserdampf. Lüften Sie deshalb unmittelbar danach, damit die Feuchtigkeit gar nicht erst in die übrigen Räume gelangt. Schließen Sie beim Kochen die Küchentür, um den Dampf in der Küche zu halten, und öffnen Sie gleichzeitig das Fenster oder schalten Sie die Dunstabzugshaube ein. Wer die Wäsche in einem Zimmer trocknet, sollte dieses Zimmer besonders häufig lüften.","ko":"샤워하고 요리하고 빨래를 말릴 때는 수증기가 많이 생깁니다. 그러니 그 직후에 바로 환기해서 습기가 다른 방으로 아예 퍼지지 않게 하세요. 요리할 때는 수증기를 주방 안에 붙잡아 두도록 주방 문을 닫고, 동시에 창문을 열거나 레인지 후드를 켜세요. 방 안에서 빨래를 말리는 사람은 그 방을 특히 자주 환기하는 것이 좋습니다."},{"de":"Möbel mit Abstand zur Außenwand","ko":"가구는 외벽에서 떨어뜨려","style":"h"},{"de":"Schimmel bildet sich häufig hinter großen Schränken an Außenwänden, weil die Luft dort nicht zirkulieren kann. Stellen Sie Möbel deshalb nicht direkt an eine Außenwand, sondern lassen Sie einige Zentimeter Abstand. Ob die Raumluft zu feucht ist, kann man mit einem einfachen Hygrometer aus dem Baumarkt kontrollieren. Die Luftfeuchtigkeit sollte ungefähr zwischen 40 und 60 Prozent liegen. Liegt sie längere Zeit darüber, muss man häufiger lüften. Wer diese Regeln beachtet, wohnt nicht nur gesünder, sondern senkt auch seine Heizkosten.","ko":"곰팡이는 외벽에 붙어 있는 큰 장롱 뒤에 자주 생깁니다. 그곳에서는 공기가 순환하지 못하기 때문입니다. 그러니 가구를 외벽에 바로 붙이지 말고 몇 센티미터 간격을 두세요. 실내 공기가 너무 습한지는 건축 자재 매장에서 파는 간단한 습도계로 확인할 수 있습니다. 습도는 대략 40에서 60퍼센트 사이가 적당합니다. 습도가 오랫동안 그보다 높으면 더 자주 환기해야 합니다. 이 규칙들을 지키면 더 건강하게 살 수 있을 뿐 아니라 난방비도 줄일 수 있습니다."}],"questions":[{"type":"rf","kind":"detail","q":"Wer mehr heizt, statt zu lüften, schützt die Wohnung vor Schimmel.","answer":1,"evidence":"Wer dann einfach die Heizung höher dreht, ohne zu lüften, spart kein Geld, sondern riskiert Schimmel.","pairs":[["riskiert Schimmel","schützt die Wohnung vor Schimmel"],["die Heizung höher dreht, ohne zu lüften","mehr heizt, statt zu lüften"]],"explain":"본문은 환기하지 않고 난방만 세게 하면 돈도 아끼지 못하고 곰팡이 위험(riskiert Schimmel)만 생긴다고 해요. 문제는 Schimmel, lüften 같은 본문 낱말을 쓰면서 '곰팡이를 막는다'고 반대로 말해요."},{"type":"mc","kind":"inference","q":"Warum ist ein Fenster, das stundenlang gekippt bleibt, im Winter keine gute Lösung?","options":["Durch den ständigen Luftaustausch wird die Raumluft zu trocken.","Weil die Wände stark auskühlen, wird die Luft schneller ausgetauscht.","Viel Wärme geht dabei verloren, doch der Luftwechsel bleibt gering."],"answer":2,"evidence":"Dabei wird die Luft kaum ausgetauscht, während die Wände um das Fenster stark auskühlen.","pairs":[["kaum ausgetauscht","der Luftwechsel bleibt gering"],["die Wände um das Fenster stark auskühlen","Viel Wärme geht dabei verloren"]],"explain":"창문을 젖혀 두면 공기는 거의 바뀌지 않는데(kaum ausgetauscht) 벽은 심하게 식어요(stark auskühlen). 열은 잃고 신선한 공기는 거의 얻지 못하니 좋은 방법이 아니에요. '공기가 계속 바뀌어 너무 건조해진다'는 선지는 본문과 반대이고, '벽이 식어서 공기가 더 빨리 바뀐다'는 선지는 벽이 식는 것을 공기가 빨리 바뀌는 원인으로 잘못 연결했어요."},{"type":"mc","kind":"detail","q":"Welchen Vorteil hat das Querlüften laut Text?","options":["Die Luft wird rasch erneuert, und es geht kaum Heizwärme verloren.","Man muss die Fenster nur fünf bis zehn Minuten am Tag öffnen.","Die Heizung kann während des Lüftens weiter voll aufgedreht bleiben."],"answer":0,"evidence":"So wird die verbrauchte Luft innerhalb weniger Minuten ersetzt, doch Wände und Möbel kühlen dabei kaum ab.","pairs":[["innerhalb weniger Minuten ersetzt","rasch erneuert"],["Wände und Möbel kühlen dabei kaum ab","es geht kaum Heizwärme verloren"]],"explain":"양쪽 창문을 함께 여는 맞바람 환기(Querlüften)를 하면 탁한 공기가 몇 분 안에 바뀌고(innerhalb weniger Minuten ersetzt), 벽과 가구는 거의 식지 않아요(kühlen kaum ab). 그래서 난방으로 데운 열을 별로 잃지 않아요. 5분에서 10분은 창문을 활짝 여는 환기를 한 번 할 때의 시간이고, 하루에 여러 번 해야 해요. 환기할 때는 난방을 먼저 줄여야 하니 난방을 계속 세게 틀어 두어도 된다는 선지도 틀려요."},{"type":"mc","kind":"paraphrase","q":"Was ist mit „damit die Wärme nicht ungenutzt nach draußen entweicht“ gemeint?","options":["Man soll die Fenster erst öffnen, wenn die Heizkörper warm sind.","Sonst geht Heizenergie verloren, die den Raum gar nicht wärmt.","Die warme Luft soll durch das offene Fenster in andere Räume ziehen."],"answer":1,"evidence":"Drehen Sie die Thermostate der Heizkörper herunter, bevor Sie die Fenster öffnen","pairs":[["nicht ungenutzt nach draußen entweicht","Sonst geht Heizenergie verloren, die den Raum gar nicht wärmt"]],"explain":"창문이 열려 있을 때 난방을 세게 하면 데운 열이 방을 데우지 못하고 그대로 밖으로 빠져나가요. ungenutzt(쓰이지 않은 채)와 entweichen(빠져나가다)을 '방을 전혀 데우지 못하는 난방 에너지를 잃는다'로 바꿔 말했어요. 열을 다른 방으로 보낸다거나 라디에이터가 따뜻해진 뒤에 창문을 열라는 말은 없어요."},{"type":"rf","kind":"detail","q":"Ein Raum braucht nach kurzem Lüften lange, bis er wieder warm ist.","answer":1,"evidence":"Ein Raum, der nur kurz gelüftet wurde, ist nämlich schnell wieder warm","pairs":[["schnell wieder warm","braucht nach kurzem Lüften lange"]],"explain":"잠깐 환기한 방은 벽과 가구가 열을 간직하고 있어서 금방(schnell) 다시 따뜻해져요. 문제는 Raum, warm 같은 본문 낱말을 쓰면서 '오래 걸린다'고 반대로 말해요."},{"type":"mc","kind":"detail","q":"Was empfiehlt der Text für das Kochen?","options":["die Küchentür offen zu lassen, damit sich der Dampf verteilt","die Wäsche in der Küche zu trocknen, weil es dort warm ist","die Tür zu schließen und den Dunst rasch ins Freie zu lassen"],"answer":2,"evidence":"Schließen Sie beim Kochen die Küchentür, um den Dampf in der Küche zu halten, und öffnen Sie gleichzeitig das Fenster oder schalten Sie die Dunstabzugshaube ein.","pairs":[["Schließen Sie beim Kochen die Küchentür","die Tür zu schließen"],["öffnen Sie gleichzeitig das Fenster oder schalten Sie die Dunstabzugshaube ein","den Dunst rasch ins Freie zu lassen"]],"explain":"요리할 때는 주방 문을 닫아 수증기를 주방에 가두고, 창문을 열거나 레인지 후드를 켜서 밖으로 내보내라고 해요. '문을 열어 두라'는 선지는 반대 내용이고, 주방에서 빨래를 말리라는 말은 본문에 없어요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet „weil die Luft dort nicht zirkulieren kann“?","options":["weil hinter dem Schrank zu viel kalte Luft hereinkommt","weil zwischen Schrank und Wand kein Luftstrom entsteht","weil die Außenwand an dieser Stelle zu warm und trocken ist"],"answer":1,"evidence":"Schimmel bildet sich häufig hinter großen Schränken an Außenwänden, weil die Luft dort nicht zirkulieren kann.","pairs":[["nicht zirkulieren kann","kein Luftstrom entsteht"],["hinter großen Schränken an Außenwänden","zwischen Schrank und Wand"]],"explain":"zirkulieren은 '순환하다, 돌다'라는 뜻이에요. 장롱과 외벽 사이에서는 공기가 움직이지 않아 습기가 머물고, 그래서 곰팡이가 생겨요. 찬 공기가 들어온다거나 벽이 따뜻하고 건조하다는 말은 본문에 없어요."},{"type":"rf","kind":"gist","q":"Gutes Lüften und eine angenehme Raumtemperatur schließen sich nicht aus.","answer":0,"evidence":"Mit ein paar einfachen Regeln erreicht man beides: frische Luft und eine warme Wohnung.","pairs":[["erreicht man beides: frische Luft und eine warme Wohnung","Gutes Lüften und eine angenehme Raumtemperatur schließen sich nicht aus"]],"explain":"글은 처음부터 끝까지 따뜻한 집과 신선한 공기를 함께 얻는 방법을 알려 줘요. 첫 단락이 '두 가지를 모두 얻을 수 있다(erreicht man beides)'고 정리해요. sich nicht ausschließen은 '서로 배제하지 않는다, 함께 갈 수 있다'는 뜻이에요."}],"grammar":[{"title":"um … zu와 damit – 목적 말하기","term":"Finalsätze: um … zu / damit","explain":"'~하려고, ~하도록'이라는 목적은 um … zu 부정사구나 damit 부문장으로 말해요. 목적 부분의 행동을 하는 사람이 주절의 주어와 같으면 um … zu + 동사원형을 써요. 서로 다르면 damit 부문장을 쓰고, 동사는 부문장 끝에 와요. 생활 정보 글은 이 두 구조로 무엇을 하고 왜 하는지를 함께 알려 줘요.","pattern":"주어가 같을 때: …, um … zu + 동사원형 / 주어가 다를 때: …, damit + 주어 + … + 동사(끝)","examples":[{"de":"Um die Wohnung richtig zu lüften, sollten Sie die Fenster deshalb mehrmals täglich ganz öffnen; im Winter genügen fünf bis zehn Minuten.","ko":"그래서 집을 제대로 환기하려면 하루에 여러 번 창문을 활짝 여는 것이 좋습니다. 겨울에는 5분에서 10분이면 충분합니다.","mark":["Um die Wohnung richtig zu lüften","sollten"],"parts":[["Um die Wohnung richtig zu lüften,","zu 부정사구"],["sollten","동사"],["Sie","주어"],["die Fenster","4격 목적어"],["deshalb","접속부사"],["mehrmals täglich","부사어(빈도)"],["ganz","부사어(방법)"],["öffnen;","동사(끝)"],["im Winter genügen fünf bis zehn Minuten.","기타"]]},{"de":"Lüften Sie deshalb unmittelbar danach, damit die Feuchtigkeit gar nicht erst in die übrigen Räume gelangt.","ko":"그러니 그 직후에 바로 환기해서 습기가 다른 방으로 아예 퍼지지 않게 하세요.","mark":["damit","gelangt"],"parts":[["Lüften","동사"],["Sie","주어"],["deshalb","접속부사"],["unmittelbar danach,","부사어(시간)"],["damit die Feuchtigkeit gar nicht erst in die übrigen Räume gelangt.","종속절"]]},{"de":"Schließen Sie beim Kochen die Küchentür, um den Dampf in der Küche zu halten, und öffnen Sie gleichzeitig das Fenster oder schalten Sie die Dunstabzugshaube ein.","ko":"요리할 때는 수증기를 주방 안에 붙잡아 두도록 주방 문을 닫고, 동시에 창문을 열거나 레인지 후드를 켜세요.","mark":["um den Dampf in der Küche zu halten"]}],"tip":"첫 번째 예문은 환기하는 사람과 창문을 여는 사람이 모두 Sie라서 um … zu를 썼어요. 두 번째 예문은 환기하는 사람(Sie)과 퍼지는 것(die Feuchtigkeit)이 달라서 damit을 썼어요."},{"title":"명령형과 sollte – 부드럽게 권하기","term":"Empfehlungen: Imperativ (Sie) und sollte(n)","explain":"생활 정보 글은 독자에게 직접 말할 때 Sie 명령형을 써요. 동사가 맨 앞에 오고 Sie가 바로 뒤에 와요(Stellen Sie …). sollte/sollten은 sollen의 접속법 2식으로, '~하는 것이 좋다'는 권유를 나타내요. 명령형보다 부드럽고, man이나 wer 문장과 함께 쓰면 모든 사람에게 하는 조언이 돼요.","pattern":"동사 + Sie + … / 주어 + sollte(n) + … + 동사원형(문장 끝)","examples":[{"de":"Stellen Sie Möbel deshalb nicht direkt an eine Außenwand, sondern lassen Sie einige Zentimeter Abstand.","ko":"그러니 가구를 외벽에 바로 붙이지 말고 몇 센티미터 간격을 두세요.","mark":["Stellen Sie","lassen Sie"],"parts":[["Stellen","동사"],["Sie","주어"],["Möbel","4격 목적어"],["deshalb","접속부사"],["nicht","부정어"],["direkt an eine Außenwand,","부사어(장소)"],["sondern","접속사"],["lassen","동사"],["Sie","주어"],["einige Zentimeter Abstand.","4격 목적어"]]},{"de":"Wer die Wäsche in einem Zimmer trocknet, sollte dieses Zimmer besonders häufig lüften.","ko":"방 안에서 빨래를 말리는 사람은 그 방을 특히 자주 환기하는 것이 좋습니다.","mark":["sollte","lüften"],"parts":[["Wer die Wäsche in einem Zimmer trocknet,","관계절"],["sollte","동사"],["dieses Zimmer","4격 목적어"],["besonders häufig","부사어(빈도)"],["lüften.","동사(끝)"]]},{"de":"Die Luftfeuchtigkeit sollte ungefähr zwischen 40 und 60 Prozent liegen.","ko":"습도는 대략 40에서 60퍼센트 사이가 적당합니다.","mark":["sollte","liegen"]}],"tip":"세 번째 예문처럼 sollte는 '알맞은 값, 바람직한 상태'를 말할 때도 써요. 두 번째 예문의 wer는 '~하는 사람은 누구나'라는 뜻이에요."},{"title":"분리동사의 앞말 – auf-, herunter-, aus-","term":"Trennbare Verben: Bedeutung der Vorsilben","explain":"분리동사의 앞말은 동사에 뜻을 더해요. 이 글에서 auf-와 herunter-는 '올리다'와 '내리다'(aufdrehen 난방을 올리다, herunterdrehen 낮추다), aus-는 '완전히'(auskühlen 완전히 식다)나 '바꾸어 내보내다'(austauschen 교환하다)를 나타내요. 주문장에서는 앞말이 문장 끝으로 가고, 부문장과 동사원형에서는 동사와 붙어 있어요. 과거분사에서는 ge가 앞말과 어간 사이에 들어가요(ausgekühlt, ausgetauscht).","pattern":"주문장: 동사 + … + 앞말(끝) / 부문장·동사원형: 앞말 + 동사(붙여 씀)","examples":[{"de":"Drehen Sie die Thermostate der Heizkörper herunter, bevor Sie die Fenster öffnen, damit die Wärme nicht ungenutzt nach draußen entweicht.","ko":"창문을 열기 전에 라디에이터의 온도 조절기를 낮추세요. 그래야 열이 쓸모없이 밖으로 빠져나가지 않습니다.","mark":["Drehen","herunter"],"parts":[["Drehen","동사"],["Sie","주어"],["die Thermostate der Heizkörper","4격 목적어"],["herunter,","동사(끝)"],["bevor Sie die Fenster öffnen,","종속절"],["damit die Wärme nicht ungenutzt nach draußen entweicht.","종속절"]]},{"de":"Dabei wird die Luft kaum ausgetauscht, während die Wände um das Fenster stark auskühlen.","ko":"그러면 공기는 거의 바뀌지 않는데, 창문 주변 벽은 심하게 식습니다.","mark":["ausgetauscht","auskühlen"]},{"de":"Anschließend sollte man die Heizung sofort wieder aufdrehen, statt zu warten, bis der Raum völlig ausgekühlt ist.","ko":"환기가 끝나면 방이 완전히 식을 때까지 기다리지 말고 곧바로 난방을 다시 올리는 것이 좋습니다.","mark":["aufdrehen","ausgekühlt"]}],"tip":"entweichen, gelangen처럼 ent-, ge-, be-, er-, ver-로 시작하는 동사는 분리되지 않아요. 분리동사는 앞말에 강세가 있어요(áufdrehen, áuskühlen)."},{"title":"beim + 명사화된 동사원형 – '~할 때'","term":"beim + nominalisierter Infinitiv","explain":"동사원형을 대문자로 쓰면 중성 명사가 돼요(das Duschen, das Kochen). beim(= bei dem) + 명사화된 동사원형은 '~할 때, ~하는 동안'이라는 뜻이고, wenn이나 während 부문장보다 짧아요. 목적어와 동사로 된 표현은 한 낱말로 붙여 써요(Wäsche trocknen → das Wäschetrocknen).","pattern":"beim + 명사화된 동사원형 (≈ wenn/während + 주어 + … + 동사)","examples":[{"de":"Beim Duschen, Kochen und Wäschetrocknen entsteht viel Wasserdampf.","ko":"샤워하고 요리하고 빨래를 말릴 때는 수증기가 많이 생깁니다.","mark":["Beim Duschen, Kochen und Wäschetrocknen"],"parts":[["Beim Duschen, Kochen und Wäschetrocknen","부사어(시간)"],["entsteht","동사"],["viel Wasserdampf.","주어"]]},{"de":"Schließen Sie beim Kochen die Küchentür, um den Dampf in der Küche zu halten, und öffnen Sie gleichzeitig das Fenster oder schalten Sie die Dunstabzugshaube ein.","ko":"요리할 때는 수증기를 주방 안에 붙잡아 두도록 주방 문을 닫고, 동시에 창문을 열거나 레인지 후드를 켜세요.","mark":["beim Kochen"]}],"tip":"beim Kochen은 wenn Sie kochen과 뜻이 같아요. 여러 개를 나열할 때는 beim을 한 번만 써요(Beim Duschen, Kochen und Wäschetrocknen)."}],"vocab":[{"de":"die Raumluft (Sg.)","ko":"실내 공기"},{"de":"stickig","ko":"(공기가) 탁한, 답답한"},{"de":"das Kondenswasser (Sg.)","ko":"결로로 맺힌 물"},{"de":"der Schimmel (Sg.)","ko":"곰팡이"},{"de":"kippen","ko":"(창문을) 젖혀서 조금 열다"},{"de":"das Stoßlüften (Sg.)","ko":"창문을 활짝 열고 짧게 하는 환기"},{"de":"aus|kühlen (ist ausgekühlt)","ko":"완전히 식다"},{"de":"das Querlüften (Sg.)","ko":"맞바람 환기 (양쪽 창문을 동시에 열어 하는 환기)"},{"de":"der Heizkörper, -","ko":"라디에이터, 난방기"},{"de":"entweichen (entwich, ist entwichen)","ko":"(열·기체가) 빠져나가다"},{"de":"speichern","ko":"저장하다, (열을) 간직하다"},{"de":"der Wasserdampf (Sg.)","ko":"수증기"},{"de":"die Dunstabzugshaube, -n","ko":"레인지 후드 (주방 환풍기)"},{"de":"gelangen (ist gelangt) in + Akk.","ko":"~에 이르다, ~로 들어가다"},{"de":"die Außenwand, -¨e","ko":"외벽, 바깥쪽 벽"},{"de":"zirkulieren","ko":"순환하다, (공기가) 돌다"}],"phrases":[{"de":"vor einem Problem stehen","ko":"문제에 부딪히다, 문제를 안고 있다","ex":"Im Winter stehen viele Mieterinnen und Mieter vor demselben Problem: Die Wohnung soll warm bleiben, doch nach wenigen Stunden wird die Raumluft stickig, und an den Fensterscheiben sammelt sich Kondenswasser.","exko":"겨울이 되면 많은 세입자가 같은 문제를 겪습니다. 집은 따뜻해야 하는데 몇 시간만 지나면 실내 공기가 탁해지고 유리창에 물방울이 맺힙니다."},{"de":"gar nicht erst","ko":"아예 (~하지 않도록), 처음부터 (~하지 않게)","ex":"Lüften Sie deshalb unmittelbar danach, damit die Feuchtigkeit gar nicht erst in die übrigen Räume gelangt.","exko":"그러니 그 직후에 바로 환기해서 습기가 다른 방으로 아예 퍼지지 않게 하세요."},{"de":"sich bilden","ko":"생기다, 형성되다","ex":"Schimmel bildet sich häufig hinter großen Schränken an Außenwänden, weil die Luft dort nicht zirkulieren kann.","exko":"곰팡이는 외벽에 붙어 있는 큰 장롱 뒤에 자주 생깁니다. 그곳에서는 공기가 순환하지 못하기 때문입니다."},{"de":"Abstand lassen","ko":"간격을 두다","ex":"Stellen Sie Möbel deshalb nicht direkt an eine Außenwand, sondern lassen Sie einige Zentimeter Abstand.","exko":"그러니 가구를 외벽에 바로 붙이지 말고 몇 센티미터 간격을 두세요."},{"de":"nicht nur …, sondern auch …","ko":"~뿐만 아니라 ~도","ex":"Wer diese Regeln beachtet, wohnt nicht nur gesünder, sondern senkt auch seine Heizkosten.","exko":"이 규칙들을 지키면 더 건강하게 살 수 있을 뿐 아니라 난방비도 줄일 수 있습니다."}],"words":357},{"id":"b1-05","level":"B1","no":5,"title":"Die Frau aus dem vierten Stock","titleKo":"4층에 사는 여자","type":"Erzählung","typeKo":"짧은 이야기 (1인칭 서술)","intro":"새 집으로 이사한 대학생이 인사를 받아 주지 않는 이웃 여자의 비밀을 알게 되는 이야기예요.","focus":["남성 약변화 명사","지시대명사","3격 지배 동사","직접 화법의 어순"],"paragraphs":[{"de":"Im Oktober zog ich in ein altes Mietshaus in der Nähe der Universität. Meine Wohnung war winzig, aber günstig, und die Nachbarn, denen ich im Treppenhaus begegnete, grüßten mich freundlich. Nur eine ältere Nachbarin, die im vierten Stock unmittelbar über mir wohnte, erwiderte meinen Gruß nie.","ko":"10월에 저는 대학 근처의 오래된 임대 주택으로 이사했어요. 집은 아주 작았지만 쌌고, 계단에서 마주치는 이웃들은 저에게 친절하게 인사했어요. 다만 바로 제 위층인 4층에 사는 나이 든 이웃 여자 한 명만은 한 번도 제 인사를 받아 주지 않았어요."},{"de":"„Das ist Frau Lindner“, sagte der Student, der im Erdgeschoss wohnte. „Mit der redet keiner. Die hält sich für etwas Besseres.“ Auch Herr Kowalczyk, mein Nachbar von gegenüber, schüttelte nur den Kopf, als ich ihn nach ihr fragte. Ich glaubte dem Studenten und meinem Nachbarn und grüßte sie bald ebenfalls nicht mehr. Nachts allerdings hörte ich gelegentlich Klavierspiel, das gedämpft durch die Zimmerdecke drang – klassische Stücke, die ich aus meiner Kindheit kannte.","ko":"“저분은 린트너 씨예요.” 1층에 사는 학생이 말했어요. “저 사람하고는 아무도 말을 안 해요. 자기가 뭐라도 되는 줄 알거든요.” 건너편에 사는 이웃 코발치크 씨도 제가 그녀에 대해 묻자 고개만 저었어요. 저는 그 학생과 이웃의 말을 믿었고, 곧 저도 그녀에게 인사하지 않게 되었어요. 그런데 밤이면 가끔 천장을 뚫고 피아노 소리가 나지막이 들려왔어요. 어릴 때부터 알던 클래식 곡들이었어요."},{"de":"An einem Nachmittag im Dezember klingelte ein Paketbote bei mir. Er brachte eine Sendung für Frau Lindner, doch oben öffnete niemand, also nahm ich sie an. Am Abend stieg ich in den vierten Stock und klopfte mehrmals, aber erst als ich schon aufgeben wollte, öffnete sie die Tür. Vor mir stand eine zierliche Frau mit silbergrauen Haaren, die mich überrascht und etwas misstrauisch ansah. Ich hielt ihr das Paket hin und erklärte, wer ich war, doch sie reagierte nicht. „Sie müssen mich ansehen, wenn Sie sprechen“, sagte sie schließlich und zeigte auf ihr Ohr. „Ich höre fast nichts.“","ko":"12월의 어느 오후, 택배 기사가 우리 집 초인종을 눌렀어요. 린트너 씨에게 온 우편물을 가져왔는데 위층에서 아무도 문을 열지 않아서, 제가 대신 받았어요. 저녁에 저는 4층으로 올라가 여러 번 문을 두드렸지만, 막 포기하려던 참에야 그녀가 문을 열었어요. 제 앞에는 은회색 머리의 자그마한 여자가 서서 놀라면서도 조금 경계하는 눈으로 저를 바라보았어요. 저는 소포를 내밀며 제가 누구인지 설명했지만, 그녀는 반응이 없었어요. “말씀하실 때는 저를 보셔야 해요.” 마침내 그녀가 이렇게 말하며 자기 귀를 가리켰어요. “저는 거의 들리지 않거든요.”"},{"de":"Sie bat mich herein und führte mich in ihr Wohnzimmer, in dem auf einem schwarzen Klavier Notenblätter und Fotografien lagen. Vierzig Jahre lang hatte sie als Klavierlehrerin gearbeitet, erzählte sie. „Aber seit einigen Jahren wird mein Gehör immer schlechter. Die Musik höre ich inzwischen mehr mit den Fingern als mit den Ohren. Deshalb spiele ich nur noch nachts, wenn mir hoffentlich niemand zuhört.“ Ich dachte an den Studenten aus dem Erdgeschoss und an Herrn Kowalczyk, der nur den Kopf geschüttelt hatte, und schämte mich.","ko":"그녀는 저를 안으로 들어오라고 하고, 검은 피아노 위에 악보와 사진이 놓인 거실로 데려갔어요. 자신은 40년 동안 피아노 교사로 일했다고 했어요. “하지만 몇 년 전부터 청력이 점점 나빠지고 있어요. 이제 음악은 귀보다 손가락으로 더 많이 들어요. 그래서 아무도 듣지 않기를 바라면서 이제는 밤에만 피아노를 쳐요.” 저는 1층 학생과 고개만 저었던 코발치크 씨를 떠올렸고, 부끄러웠어요."},{"de":"Frau Lindner hatte unsere Grüße nie gehört und nicht bemerkt, dass jemand sie ansprach – und wir hatten nie gefragt, warum sie schwieg. Wenn ich ihr seitdem im Treppenhaus begegne, hebe ich die Hand und winke, bis sie mich bemerkt und lächelnd zurückwinkt. Und nachts lasse ich manchmal das Fenster offen, damit ich sie spielen hören kann.","ko":"린트너 씨는 우리의 인사를 한 번도 듣지 못했고, 누군가 자기에게 말을 건다는 것도 알아차리지 못했어요. 그리고 우리는 그녀가 왜 말이 없는지 한 번도 묻지 않았어요. 그때부터 저는 계단에서 그녀와 마주치면, 그녀가 저를 알아보고 미소 지으며 손을 흔들어 줄 때까지 손을 들어 흔들어요. 그리고 밤에는 가끔 그녀의 연주를 들을 수 있도록 창문을 열어 두어요."}],"questions":[{"type":"rf","kind":"detail","q":"Bis auf eine Bewohnerin wurde der Erzähler im Haus freundlich aufgenommen.","answer":0,"evidence":"die Nachbarn, denen ich im Treppenhaus begegnete, grüßten mich freundlich","pairs":[["die Nachbarn, denen ich im Treppenhaus begegnete, grüßten mich freundlich","wurde der Erzähler im Haus freundlich aufgenommen"],["Nur eine ältere Nachbarin","Bis auf eine Bewohnerin"]],"explain":"계단에서 마주친 이웃들은 화자에게 친절하게 인사했고, 4층에 사는 나이 든 이웃 여자 한 명만 인사를 받지 않았어요. 문제는 '한 사람을 빼고는(Bis auf eine Bewohnerin)' 친절하게 맞아 주었다고 바꿔 말했어요."},{"type":"mc","kind":"detail","q":"Wie erklären sich die Nachbarn das Verhalten von Frau Lindner?","options":["Sie glauben, dass sie arrogant und eingebildet ist.","Sie vermuten, dass sie seit Jahren schlecht hört.","Sie denken, dass sie erst im Oktober eingezogen ist."],"answer":0,"evidence":"Die hält sich für etwas Besseres.","pairs":[["hält sich für etwas Besseres","arrogant und eingebildet"]],"explain":"1층 학생은 그녀가 '자기가 남보다 낫다고 여긴다(hält sich für etwas Besseres)'고 해요. 이웃들은 그녀를 거만하다고 생각하는 거예요. 청력 문제는 이웃들이 몰랐던 사실이고, 10월에 이사 온 사람은 린트너 씨가 아니라 화자예요."},{"type":"rf","kind":"detail","q":"Der Erzähler glaubte den Nachbarn nicht und grüßte Frau Lindner weiterhin.","answer":1,"evidence":"Ich glaubte dem Studenten und meinem Nachbarn und grüßte sie bald ebenfalls nicht mehr.","pairs":[["grüßte sie bald ebenfalls nicht mehr","grüßte Frau Lindner weiterhin"],["Ich glaubte dem Studenten und meinem Nachbarn","glaubte den Nachbarn nicht"]],"explain":"화자는 학생과 이웃의 말을 믿었고, 곧 자기도 린트너 씨에게 인사하지 않았어요(grüßte sie bald ebenfalls nicht mehr). 문제는 glauben, grüßen 같은 본문 낱말을 쓰면서 내용을 반대로 바꿨어요. 마지막 단락에서 다시 인사하게 되는 것과 헷갈리지 마세요."},{"type":"mc","kind":"detail","q":"Warum hatte der Erzähler am Abend ein Paket für Frau Lindner?","options":["Der Bote hatte die Empfängerin oben nicht angetroffen.","Frau Lindner hatte ihn vorher um diesen Gefallen gebeten.","Der Bote hatte sich im Stock geirrt und bei ihm geklingelt."],"answer":0,"evidence":"doch oben öffnete niemand, also nahm ich sie an","pairs":[["oben öffnete niemand","die Empfängerin oben nicht angetroffen"],["eine Sendung für Frau Lindner","die Empfängerin"]],"explain":"택배 기사가 린트너 씨에게 온 우편물을 가져왔지만 위층에서 아무도 문을 열지 않아서(oben öffnete niemand) 화자가 대신 받았어요. 이것을 '기사가 위층에서 수취인을 만나지 못했다'로 바꿔 말했어요. 린트너 씨가 부탁했다는 말은 없고, 기사는 층을 착각한 것이 아니라 위층에서 먼저 초인종을 눌렀어요."},{"type":"mc","kind":"inference","q":"Warum reagierte Frau Lindner zuerst nicht auf die Worte des Erzählers?","options":["Sie wollte mit den Nachbarn im Haus nicht sprechen.","Sie hatte an diesem Abend mit keiner Sendung gerechnet.","Sie konnte seine Worte akustisch gar nicht verstehen."],"answer":2,"evidence":"Ich höre fast nichts.","pairs":[["Ich höre fast nichts","konnte seine Worte akustisch gar nicht verstehen"]],"explain":"린트너 씨는 곧이어 '말할 때는 저를 보셔야 해요. 저는 거의 들리지 않거든요'라고 해요. 화자의 말을 귀로 알아들을 수 없어서 반응하지 못한 거예요. 이웃과 말하기 싫어한다는 것은 이웃들의 오해이고, 우편물을 예상하지 못했다는 말은 없어요."},{"type":"mc","kind":"paraphrase","q":"Was beschreibt Frau Lindner mit dem Satz „Die Musik höre ich inzwischen mehr mit den Fingern als mit den Ohren“?","options":["Sie zählt beim Klavierspielen den Takt mit den Fingern.","Sie spielt die Stücke inzwischen lieber ohne Notenblätter.","Weil sie schlecht hört, erlebt sie Töne über die Hände."],"answer":2,"evidence":"Aber seit einigen Jahren wird mein Gehör immer schlechter.","pairs":[["mehr mit den Fingern als mit den Ohren","erlebt sie Töne über die Hände"],["wird mein Gehör immer schlechter","Weil sie schlecht hört"]],"explain":"청력이 점점 나빠져서 이제는 소리를 귀보다 피아노를 치는 손가락의 감각으로 느낀다는 뜻이에요. Fingern을 Hände로, 나빠진 청력을 '잘 듣지 못해서'로 바꿔 말했어요. 박자를 손가락으로 센다거나 악보 없이 친다는 말은 없어요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet „wenn mir hoffentlich niemand zuhört“?","options":["Sie möchte beim Spielen lieber keine Zuhörer haben.","Sie hofft, dass die Nachbarn nachts endlich zuhören.","Sie spielt nachts, weil sie tagsüber noch Unterricht gibt."],"answer":0,"evidence":"Deshalb spiele ich nur noch nachts, wenn mir hoffentlich niemand zuhört.","pairs":[["wenn mir hoffentlich niemand zuhört","lieber keine Zuhörer haben"]],"explain":"hoffentlich는 '바라건대'라는 뜻이에요. 그녀는 아무도 듣지 않기를 바라면서 밤에만 피아노를 쳐요. 자기 연주를 듣는 사람이 없기를 원하는 거예요. '이웃들이 밤에 들어 주기를 바란다'는 선지는 반대 내용이고, 피아노 교사로 일한 것은 지나간 일이에요(hatte … gearbeitet)."},{"type":"rf","kind":"gist","q":"Die Geschichte zeigt, dass ein Missverständnis die Nachbarn und Frau Lindner getrennt hatte.","answer":0,"evidence":"Frau Lindner hatte unsere Grüße nie gehört und nicht bemerkt, dass jemand sie ansprach","pairs":[["hatte unsere Grüße nie gehört","ein Missverständnis"],["wir hatten nie gefragt, warum sie schwieg","die Nachbarn und Frau Lindner getrennt hatte"]],"explain":"린트너 씨는 인사를 듣지 못했을 뿐인데 이웃들은 그녀가 거만하다고 생각했고, 아무도 이유를 묻지 않았어요. 서로를 잘못 이해한 것이 이웃들과 그녀 사이를 멀어지게 했다는 것이 이야기의 중심 내용이에요."}],"grammar":[{"title":"남성 약변화 명사 – den Studenten, Herrn, dem Nachbarn","term":"n-Deklination","explain":"일부 남성 명사는 1격 단수를 빼고 모든 격에서 -(e)n이 붙어요: der Student → den/dem/des Studenten, der Nachbar → den/dem Nachbarn, der Herr → den/dem Herrn, der Bote → den/dem Boten. 사람이나 동물을 가리키는 남성 명사가 많고, -e로 끝나는 명사(Kollege, Junge, Bote)와 -ent, -ant, -ist로 끝나는 외래어가 대표적이에요. 복수형도 -(e)n이에요.","pattern":"1격 der Student · 4격 den Studenten · 3격 dem Studenten · 2격 des Studenten","examples":[{"de":"Ich glaubte dem Studenten und meinem Nachbarn und grüßte sie bald ebenfalls nicht mehr.","ko":"저는 그 학생과 이웃의 말을 믿었고, 곧 저도 그녀에게 인사하지 않게 되었어요.","mark":["dem Studenten","meinem Nachbarn"],"parts":[["Ich","주어"],["glaubte","동사"],["dem Studenten und meinem Nachbarn","3격 목적어"],["und","접속사"],["grüßte","동사"],["sie","4격 목적어"],["bald","부사어(시간)"],["ebenfalls","부사어"],["nicht mehr.","부정어"]]},{"de":"Ich dachte an den Studenten aus dem Erdgeschoss und an Herrn Kowalczyk, der nur den Kopf geschüttelt hatte, und schämte mich.","ko":"저는 1층 학생과 고개만 저었던 코발치크 씨를 떠올렸고, 부끄러웠어요.","mark":["den Studenten","Herrn Kowalczyk"],"parts":[["Ich","주어"],["dachte","동사"],["an den Studenten aus dem Erdgeschoss und an Herrn Kowalczyk,","전치사 목적어"],["der nur den Kopf geschüttelt hatte,","관계절"],["und","접속사"],["schämte","동사"],["mich.","재귀대명사"]]},{"de":"Auch Herr Kowalczyk, mein Nachbar von gegenüber, schüttelte nur den Kopf, als ich ihn nach ihr fragte.","ko":"건너편에 사는 이웃 코발치크 씨도 제가 그녀에 대해 묻자 고개만 저었어요.","mark":["Herr Kowalczyk","mein Nachbar"]}],"tip":"1격에서는 어미가 붙지 않아요(der Student, Herr Kowalczyk, mein Nachbar, ein Paketbote). 세 번째 예문의 Herr Kowalczyk와 mein Nachbar는 주어(1격)라서 -n이 없어요. glauben은 말을 믿는 대상인 사람을 3격으로 받아요(jemandem glauben)."},{"title":"지시대명사 der · die – '그 사람'을 가리키는 말","term":"Demonstrativpronomen der, die, das","explain":"der, die, das는 관사와 관계대명사 말고도, 앞에서 말한 사람이나 사물을 가리키는 지시대명사로 쓰여요. 말할 때 er나 sie 대신 쓰면 그 사람을 강하게 가리키고, 거리를 두거나 낮춰 보는 느낌이 날 수 있어요. 형태는 관계대명사와 같아요(3격 복수 denen, 2격 dessen/deren). 다만 지시대명사로 시작하는 문장은 주문장이라서 동사가 두 번째 자리에 와요.","pattern":"지시대명사(1격 der/die/das, 3격 dem/der/dem) + 동사(두 번째 자리) + …","examples":[{"de":"Mit der redet keiner.","ko":"저 사람하고는 아무도 말을 안 해요.","mark":["Mit der"],"parts":[["Mit der","전치사 목적어"],["redet","동사"],["keiner.","주어"]]},{"de":"Die hält sich für etwas Besseres.","ko":"자기가 뭐라도 되는 줄 알거든요.","mark":["Die"],"parts":[["Die","주어"],["hält","동사"],["sich","재귀대명사"],["für etwas Besseres.","보어"]]}],"tip":"„Mit der redet keiner“의 der는 mit 뒤에 왔으니 여성 3격이에요(= mit ihr). „der Student, der im Erdgeschoss wohnte“의 두 번째 der는 관계대명사라서 동사 wohnte가 끝에 가요. 동사의 자리를 보면 둘을 구별할 수 있어요."},{"title":"3격 지배 동사 – begegnen, glauben, zuhören","term":"Verben mit Dativ","explain":"begegnen(~와 마주치다), glauben(~의 말을 믿다), zuhören(~의 말·연주를 듣다)은 사람을 3격으로 받아요. 관계절에서도 같은 규칙이 적용되어서, 사람이 여럿이면 3격 복수 관계대명사 denen을 써요(die Nachbarn, denen ich begegnete). begegnen은 현재완료를 sein으로 만들어요(ich bin ihr begegnet).","pattern":"begegnen / glauben / zuhören + 3격(사람)","examples":[{"de":"Meine Wohnung war winzig, aber günstig, und die Nachbarn, denen ich im Treppenhaus begegnete, grüßten mich freundlich.","ko":"집은 아주 작았지만 쌌고, 계단에서 마주치는 이웃들은 저에게 친절하게 인사했어요.","mark":["denen","begegnete"],"parts":[["Meine Wohnung","주어"],["war","동사"],["winzig, aber günstig,","보어"],["und","접속사"],["die Nachbarn,","주어"],["denen ich im Treppenhaus begegnete,","관계절"],["grüßten","동사"],["mich","4격 목적어"],["freundlich.","부사어(방법)"]]},{"de":"Deshalb spiele ich nur noch nachts, wenn mir hoffentlich niemand zuhört.","ko":"그래서 아무도 듣지 않기를 바라면서 이제는 밤에만 피아노를 쳐요.","mark":["mir","zuhört"]},{"de":"Wenn ich ihr seitdem im Treppenhaus begegne, hebe ich die Hand und winke, bis sie mich bemerkt und lächelnd zurückwinkt.","ko":"그때부터 저는 계단에서 그녀와 마주치면, 그녀가 저를 알아보고 미소 지으며 손을 흔들어 줄 때까지 손을 들어 흔들어요.","mark":["ihr","begegne"]}],"tip":"glauben은 사람을 3격, 믿는 내용을 4격으로 받아요(jemandem etwas glauben). 어떤 존재나 생각을 믿을 때는 an + 4격을 써요(an etwas glauben)."},{"title":"직접 화법 – 인용문 뒤의 어순","term":"Redeeinleitung nach direkter Rede","explain":"인용문(„…“)이 문장 맨 앞에 오면 인용문이 첫 번째 자리를 차지해요. 그래서 바로 뒤에 동사가 오고 주어는 그다음에 와요(„…“, sagte der Student). 인용문 끝의 마침표는 빼고, 닫는 따옴표 뒤에 쉼표를 찍어요. sagen 말고도 erklären, erzählen, fragen, antworten 같은 동사가 이 자리에 와요.","pattern":"„인용문“, + 동사 + 주어 + …","examples":[{"de":"„Das ist Frau Lindner“, sagte der Student, der im Erdgeschoss wohnte.","ko":"“저분은 린트너 씨예요.” 1층에 사는 학생이 말했어요.","mark":["sagte der Student"],"parts":[["„Das ist Frau Lindner“,","기타"],["sagte","동사"],["der Student,","주어"],["der im Erdgeschoss wohnte.","관계절"]]},{"de":"„Sie müssen mich ansehen, wenn Sie sprechen“, sagte sie schließlich und zeigte auf ihr Ohr.","ko":"“말씀하실 때는 저를 보셔야 해요.” 마침내 그녀가 이렇게 말하며 자기 귀를 가리켰어요.","mark":["sagte sie"]},{"de":"Vierzig Jahre lang hatte sie als Klavierlehrerin gearbeitet, erzählte sie.","ko":"자신은 40년 동안 피아노 교사로 일했다고 했어요.","mark":["erzählte sie"]}],"tip":"세 번째 예문은 따옴표 없이 남의 말을 전하지만, 말한 내용이 앞에 와서 똑같이 erzählte sie 순서가 돼요. 인용문이 물음표나 느낌표로 끝나면 그 부호는 그대로 두고 쉼표만 덧붙여요(„Wer sind Sie?“, fragte sie)."}],"vocab":[{"de":"das Mietshaus, -¨er","ko":"임대 주택, 다세대 주택"},{"de":"das Treppenhaus, -¨er","ko":"계단실 (건물 안의 계단 공간)"},{"de":"begegnen (ist begegnet) + Dat.","ko":"~와 마주치다"},{"de":"erwidern","ko":"(인사·말에) 답하다"},{"de":"unmittelbar","ko":"바로, 곧장"},{"de":"das Erdgeschoss, -e","ko":"1층 (지면과 같은 층)"},{"de":"gelegentlich","ko":"가끔, 이따금"},{"de":"gedämpft","ko":"(소리가) 약하게 들리는, 나지막한"},{"de":"dringen (drang, ist gedrungen)","ko":"(소리·빛이) 뚫고 들어오다"},{"de":"der Paketbote, -n","ko":"택배 기사"},{"de":"die Sendung, -en","ko":"우편물, 배송물"},{"de":"zierlich","ko":"자그마하고 가냘픈"},{"de":"misstrauisch","ko":"경계하는, 의심하는"},{"de":"das Gehör (Sg.)","ko":"청력, 청각"},{"de":"sich schämen","ko":"부끄러워하다"},{"de":"zurück|winken","ko":"손을 흔들어 답하다"}],"phrases":[{"de":"sich für etwas Besseres halten","ko":"자기가 남보다 잘났다고 여기다, 거만하다","ex":"Die hält sich für etwas Besseres.","exko":"자기가 뭐라도 되는 줄 알거든요."},{"de":"jemanden nach jemandem/etwas fragen","ko":"~에게 ~에 대해 묻다","ex":"Auch Herr Kowalczyk, mein Nachbar von gegenüber, schüttelte nur den Kopf, als ich ihn nach ihr fragte.","exko":"건너편에 사는 이웃 코발치크 씨도 제가 그녀에 대해 묻자 고개만 저었어요."},{"de":"einen Gruß erwidern","ko":"인사에 답하다, 인사를 받아 주다","ex":"Nur eine ältere Nachbarin, die im vierten Stock unmittelbar über mir wohnte, erwiderte meinen Gruß nie.","exko":"다만 바로 제 위층인 4층에 사는 나이 든 이웃 여자 한 명만은 한 번도 제 인사를 받아 주지 않았어요."},{"de":"jemanden herein|bitten (bat herein, hat hereingebeten)","ko":"~를 안으로 들어오라고 청하다","ex":"Sie bat mich herein und führte mich in ihr Wohnzimmer, in dem auf einem schwarzen Klavier Notenblätter und Fotografien lagen.","exko":"그녀는 저를 안으로 들어오라고 하고, 검은 피아노 위에 악보와 사진이 놓인 거실로 데려갔어요."},{"de":"an jemanden/etwas denken (dachte, hat gedacht)","ko":"~를 떠올리다, ~를 생각하다","ex":"Ich dachte an den Studenten aus dem Erdgeschoss und an Herrn Kowalczyk, der nur den Kopf geschüttelt hatte, und schämte mich.","exko":"저는 1층 학생과 고개만 저었던 코발치크 씨를 떠올렸고, 부끄러웠어요."}],"words":356},{"id":"b1-06","level":"B1","no":6,"title":"Mit 52 in den Hörsaal","titleKo":"52세에 대학 강의실로","type":"Interview","typeKo":"대학 잡지 인터뷰","intro":"52세에 대학생이 된 모니카 하스 씨와 나눈 인터뷰예요.","focus":["seitdem · bis · sobald","als의 세 가지 쓰임","erst als · erst einmal","기능동사 구문"],"paragraphs":[{"de":"Monika Haas ist 52 Jahre alt und studiert im dritten Semester Geschichte. Zuvor hat sie fast dreißig Jahre lang in einer Bankfiliale gearbeitet. Mit unserer Campuszeitung hat sie über ihren späten Neuanfang gesprochen.","ko":"모니카 하스 씨는 52세이고 3학기째 역사학을 공부하고 있어요. 그전에는 거의 30년 동안 은행 지점에서 일했어요. 저희 캠퍼스 신문과 늦은 새 출발에 대해 이야기를 나눴어요."},{"style":"q","de":"Frau Haas, wie kam es zu der Entscheidung, mit über 50 noch zu studieren?","ko":"하스 씨, 50이 넘은 나이에 대학 공부를 하기로 결정하게 된 계기가 뭐였나요?"},{"de":"Der Wunsch begleitet mich seit meiner Schulzeit. Mit zwanzig habe ich eine Ausbildung zur Bankkauffrau gemacht, weil das damals als krisenfester Beruf galt, aber Geschichte hat mich nie losgelassen. Als vor drei Jahren auch unser jüngster Sohn ausgezogen ist, war das Haus plötzlich sehr still. In diesem Moment habe ich die Entscheidung getroffen. Seitdem ich studiere, ist mein Alltag völlig anders.","ko":"그 바람은 학창 시절부터 줄곧 제 마음속에 있었어요. 스무 살에 은행원 직업 교육을 받았는데, 당시에는 그게 위기에도 흔들리지 않는 직업으로 여겨졌기 때문이에요. 하지만 역사에 대한 관심은 한 번도 사라진 적이 없어요. 3년 전에 막내아들까지 집을 나가 독립했을 때, 집이 갑자기 아주 조용해졌어요. 그 순간에 결정을 내렸어요. 공부를 시작한 뒤로 제 일상은 완전히 달라졌어요."},{"style":"q","de":"Haben Sie sich dann sofort eingeschrieben?","ko":"그러면 바로 등록하셨나요?"},{"de":"Nein, so mutig war ich nicht. Ich habe zuerst ein Semester lang als Gasthörerin Vorlesungen besucht, bevor ich mich richtig eingeschrieben habe. Ich wollte herausfinden, ob ich nach Jahrzehnten am Schreibtisch noch neunzig Minuten am Stück zuhören kann. Erst als ich festgestellt habe, dass mir das Lernen trotz der Anstrengung Freude macht, habe ich Kontakt mit der Studienberatung aufgenommen.","ko":"아니요, 그렇게 용감하지는 않았어요. 정식으로 등록하기 전에 먼저 한 학기 동안 청강생으로 강의를 들었어요. 수십 년 동안 책상 앞에서 일한 뒤에도 아직 90분을 쉬지 않고 들을 수 있는지 알아보고 싶었거든요. 힘들어도 공부가 즐겁다는 걸 알게 된 뒤에야 학업 상담실에 연락했어요."},{"style":"q","de":"Wie erleben Sie das Studium unter so vielen Zwanzigjährigen?","ko":"그렇게 많은 스무 살 학생들 사이에서 공부하는 건 어떠세요?"},{"de":"Anfangs war es ungewohnt, weil viele Kommilitonen jünger sind als meine eigenen Kinder. Während die Jüngeren in der Pause aufs Smartphone schauen, lese ich lieber meine Mitschriften. Trotzdem nehmen wir in der Lerngruppe Rücksicht aufeinander. Richtig schwer fiel mir dagegen die Technik. Mit der Lernplattform, auf der alle Skripte hochgeladen werden, bin ich wochenlang nicht zurechtgekommen, bis mir ein Kommilitone alles geduldig erklärt hat.","ko":"처음에는 낯설었어요. 많은 학우가 제 아이들보다도 어리거든요. 젊은 학생들이 쉬는 시간에 스마트폰을 보는 동안 저는 필기 노트를 읽는 편이에요. 그래도 스터디 그룹에서는 서로 배려해요. 반면에 기술은 정말 어려웠어요. 모든 강의 자료가 올라오는 학습 플랫폼은 한 학우가 차근차근 다 설명해 주기 전까지 몇 주 동안 제대로 다루지 못했어요."},{"style":"q","de":"Welches Ziel verfolgen Sie mit dem Studium?","ko":"대학 공부를 하면서 어떤 목표를 갖고 계세요?"},{"de":"Bis ich den Bachelor in der Tasche habe, dauert es noch ungefähr zwei Jahre. Sobald ich fertig bin, möchte ich im Stadtarchiv mitarbeiten, gern auch ehrenamtlich, denn auf ein Gehalt bin ich zum Glück nicht angewiesen. Meine erste Modulprüfung habe ich übrigens schon abgelegt – mit einer Zwei, obwohl ich furchtbar aufgeregt war.","ko":"학사 학위를 손에 넣기까지 아직 2년 정도 걸려요. 공부를 마치자마자 시립 기록 보관소에서 함께 일하고 싶어요. 자원봉사라도 좋아요. 다행히 월급에 기대야 하는 형편은 아니거든요. 참, 첫 모듈 시험은 이미 치렀어요. 무척 긴장했지만 성적은 2(gut)였어요."},{"style":"q","de":"Was raten Sie anderen, die mit 50 noch einmal anfangen möchten?","ko":"50에 다시 시작하려는 사람들에게 어떤 조언을 하시겠어요?"},{"de":"Nicht zu lange zögern. Man muss sich nicht gleich einschreiben, sondern kann erst einmal als Gasthörer ausprobieren, ob das Lernen im Hörsaal zu einem passt. Wer etwas nicht versteht, sollte ruhig nachfragen, denn die Jüngeren helfen gern – das ist jedenfalls meine Erfahrung.","ko":"너무 오래 망설이지 마세요. 바로 등록할 필요는 없고, 우선 청강생으로 강의실에서 배우는 게 자기에게 맞는지 시험해 봐도 돼요. 이해가 안 되는 게 있으면 편하게 물어보세요. 젊은 학생들이 기꺼이 도와주거든요. 적어도 제 경험으로는 그래요."}],"questions":[{"type":"rf","kind":"inference","q":"Frau Haas hat sich als junge Frau für die Bank entschieden, weil Geschichte sie damals noch nicht interessierte.","answer":1,"evidence":"weil das damals als krisenfester Beruf galt, aber Geschichte hat mich nie losgelassen","pairs":[["Geschichte hat mich nie losgelassen","weil Geschichte sie damals noch nicht interessierte"],["weil das damals als krisenfester Beruf galt","für die Bank entschieden"]],"explain":"하스 씨는 그 바람이 학창 시절부터 있었고(Der Wunsch begleitet mich seit meiner Schulzeit), 역사가 한 번도 마음을 떠난 적이 없다(Geschichte hat mich nie losgelassen)고 말해요. 은행원 교육을 받은 이유는 그 직업이 당시 위기에 강한(krisenfest) 직업으로 여겨졌기 때문이에요. 그러니 역사에 관심이 없어서 은행을 골랐다는 진술은 틀려요."},{"type":"rf","kind":"detail","q":"Frau Haas hat sich zum Studium entschlossen, nachdem ihr letztes Kind das Elternhaus verlassen hatte.","answer":0,"evidence":"Als vor drei Jahren auch unser jüngster Sohn ausgezogen ist, war das Haus plötzlich sehr still. In diesem Moment habe ich die Entscheidung getroffen.","pairs":[["unser jüngster Sohn ausgezogen ist","ihr letztes Kind das Elternhaus verlassen hatte"],["die Entscheidung getroffen","hat sich zum Studium entschlossen"]],"explain":"'막내아들까지 집을 나가 독립했을 때(Als … auch unser jüngster Sohn ausgezogen ist)'를 '마지막 자녀가 부모 집을 떠난 뒤'로, 'die Entscheidung treffen'(결정을 내리다)을 'sich entschließen'(결심하다)으로 바꿔 말했어요. 하스 씨는 집이 조용해진 바로 그 순간에 결정했다고 하니 진술은 맞아요."},{"type":"mc","kind":"paraphrase","q":"Was meint Frau Haas mit dem Satz „Nein, so mutig war ich nicht.“?","options":["Sie hatte große Angst vor den vielen Zwanzigjährigen im Hörsaal.","Sie traute sich nicht, sich gleich fest an der Uni anzumelden.","Sie fand die Einschreibung ohne Studienberatung zu schwer."],"answer":1,"evidence":"Nein, so mutig war ich nicht. Ich habe zuerst ein Semester lang als Gasthörerin Vorlesungen besucht, bevor ich mich richtig eingeschrieben habe.","pairs":[["so mutig war ich nicht","traute sich nicht"],["bevor ich mich richtig eingeschrieben habe","sich gleich fest an der Uni anzumelden"]],"explain":"'그렇게 용감하지는 않았다'는 말은 바로 정식으로 등록할 용기가 없었다는 뜻이에요. 그래서 하스 씨는 먼저 한 학기 동안 청강생으로 강의를 들었어요. 젊은 학생들이 무서웠다는 말도, 상담 없이 등록하기가 너무 어려웠다는 말도 본문에 없어요."},{"type":"mc","kind":"detail","q":"Wann hat sich Frau Haas an die Studienberatung gewandt?","options":["erst nachdem sie gemerkt hatte, dass ihr das Studieren Spaß macht","bevor sie zum ersten Mal als Gasthörerin eine Vorlesung besucht hat","nachdem sie ihre erste Modulprüfung mit einer Zwei bestanden hatte"],"answer":0,"evidence":"Erst als ich festgestellt habe, dass mir das Lernen trotz der Anstrengung Freude macht, habe ich Kontakt mit der Studienberatung aufgenommen.","pairs":[["Erst als ich festgestellt habe","erst nachdem sie gemerkt hatte"],["dass mir das Lernen trotz der Anstrengung Freude macht","dass ihr das Studieren Spaß macht"],["Kontakt mit der Studienberatung aufgenommen","an die Studienberatung gewandt"]],"explain":"'Erst als ich festgestellt habe, dass mir das Lernen … Freude macht'를 '공부가 즐겁다는 걸 알아차린 뒤에야'로, 'Kontakt aufnehmen mit'(~와 연락하다)을 'sich wenden an'(~에게 문의하다)으로 바꿔 말했어요. 상담실에 연락한 것은 청강 학기를 보낸 뒤이니 첫 강의 전이라는 말은 틀려요. 또 연락은 정식 등록 전의 일이고 첫 모듈 시험은 등록한 뒤에 치렀으니 시험 뒤라는 말도 틀려요."},{"type":"mc","kind":"detail","q":"Was fiel Frau Haas zu Beginn des Studiums besonders schwer?","options":["das Verhalten der Jüngeren in den kurzen Vorlesungspausen","der Umgang mit den digitalen Angeboten der Universität","die Zusammenarbeit mit den Jüngeren in der Lerngruppe"],"answer":1,"evidence":"Richtig schwer fiel mir dagegen die Technik.","pairs":[["die Technik","der Umgang mit den digitalen Angeboten der Universität"],["Mit der Lernplattform","digitalen Angeboten"]],"explain":"본문의 'die Technik'(기술)과 'die Lernplattform'(학습 플랫폼)을 '대학의 디지털 서비스를 다루는 일'로 바꿔 말했어요. 'dagegen'(반면에)은 앞 내용과 대조해서, 젊은 학생들과 함께하는 것은 낯설었을 뿐이고 정말 어려웠던 것은 기술이었다고 알려 줘요. 쉬는 시간에 스마트폰을 보는 것은 젊은 학생들의 습관일 뿐이고, 스터디 그룹에서는 서로 배려한다고 했으니 나머지 선지는 틀려요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Bis ich den Bachelor in der Tasche habe, dauert es noch ungefähr zwei Jahre.“?","options":["Sie hat den Bachelor schon vor ungefähr zwei Jahren bekommen.","Sie braucht noch zwei Jahre, bis sie sich endlich einschreiben darf.","Sie wird ihr Studium vermutlich in rund zwei Jahren abschließen."],"answer":2,"evidence":"Bis ich den Bachelor in der Tasche habe, dauert es noch ungefähr zwei Jahre.","pairs":[["den Bachelor in der Tasche habe","ihr Studium vermutlich in rund zwei Jahren abschließen"],["dauert es noch ungefähr zwei Jahre","in rund zwei Jahren"]],"explain":"'etwas in der Tasche haben'은 '(학위나 자격을) 확실히 손에 넣다'라는 뜻이에요. 그래서 이 문장은 학사 학위를 받고 공부를 마치기까지 아직 2년쯤 남았다는 뜻이에요. 하스 씨는 이미 3학기째 공부하고 있으니, 학위를 벌써 받았다거나 아직 등록하지 못했다는 뜻이 아니에요."},{"type":"rf","kind":"detail","q":"Frau Haas wäre bereit, nach dem Studium ohne Bezahlung im Archiv zu arbeiten.","answer":0,"evidence":"Sobald ich fertig bin, möchte ich im Stadtarchiv mitarbeiten, gern auch ehrenamtlich, denn auf ein Gehalt bin ich zum Glück nicht angewiesen.","pairs":[["gern auch ehrenamtlich","ohne Bezahlung"],["Sobald ich fertig bin","nach dem Studium"],["im Stadtarchiv mitarbeiten","im Archiv zu arbeiten"]],"explain":"'gern auch ehrenamtlich'는 '자원봉사로 해도 좋다'는 뜻이에요. 보수 없이 일해도 괜찮다고 했으니 진술은 맞아요. 바로 뒤에서 다행히 월급에 기대야 하는 형편이 아니라고 이유도 말해요. 'Sobald ich fertig bin'(마치자마자)은 학업을 마친 뒤를 가리켜요."},{"type":"mc","kind":"gist","q":"Was möchte Frau Haas Älteren mit ihrem Rat vor allem sagen?","options":["Ältere sollten sich sofort einschreiben, damit sie keine Zeit verlieren.","Ältere sollten den Schritt wagen und sich trauen, Fragen zu stellen.","Ältere sollten als Gasthörer zuerst eine Modulprüfung ablegen."],"answer":1,"evidence":"Nicht zu lange zögern.","pairs":[["Nicht zu lange zögern","den Schritt wagen"],["sollte ruhig nachfragen","sich trauen, Fragen zu stellen"],["Man muss sich nicht gleich einschreiben","sofort einschreiben"]],"explain":"하스 씨의 조언은 세 가지예요. 너무 오래 망설이지 말 것(Nicht zu lange zögern), 우선 청강으로 시작해도 된다는 것, 모르면 편하게 물어볼 것이에요. 이것을 '용기를 내어 시작하고 질문하기를 두려워하지 말라'로 요약했어요. 바로 등록하라는 말은 본문과 반대이고, 청강생이 시험을 치러야 한다는 말은 본문에 없어요."}],"grammar":[{"title":"시간 관계를 나타내는 종속접속사: seitdem · bis · sobald","term":"Temporale Nebensätze: seit(dem), bis, sobald","explain":"seitdem(또는 seit)은 '~한 뒤로 지금까지', bis는 '~할 때까지', sobald는 '~하자마자'라는 뜻이에요. 세 접속사 모두 종속절을 이끌기 때문에 종속절의 동사는 끝에 와요. seitdem은 과거에 시작된 일이 지금까지 이어질 때 쓰고, bis는 어떤 일이 끝나는 시점을 나타내요. sobald는 한 일이 끝나면 곧바로 다음 일이 이어진다는 뜻이에요.","pattern":"seitdem / bis / sobald + 주어 … 동사(끝), 동사 + 주어 …","examples":[{"de":"Seitdem ich studiere, ist mein Alltag völlig anders.","ko":"공부를 시작한 뒤로 제 일상은 완전히 달라졌어요.","mark":["Seitdem","studiere"],"parts":[["Seitdem","접속사"],["ich","주어"],["studiere,","동사(끝)"],["ist","동사"],["mein Alltag","주어"],["völlig anders.","보어"]]},{"de":"Bis ich den Bachelor in der Tasche habe, dauert es noch ungefähr zwei Jahre.","ko":"학사 학위를 손에 넣기까지 아직 2년 정도 걸려요.","mark":["Bis","habe"],"parts":[["Bis ich den Bachelor in der Tasche habe,","종속절"],["dauert","동사"],["es","주어"],["noch ungefähr zwei Jahre.","부사어(시간)"]]},{"de":"Sobald ich fertig bin, möchte ich im Stadtarchiv mitarbeiten, gern auch ehrenamtlich, denn auf ein Gehalt bin ich zum Glück nicht angewiesen.","ko":"공부를 마치자마자 시립 기록 보관소에서 함께 일하고 싶어요. 자원봉사라도 좋아요. 다행히 월급에 기대야 하는 형편은 아니거든요.","mark":["Sobald","fertig bin"]}],"tip":"seitdem 문장에서 두 일이 지금까지 이어지면 두 절 모두 현재형을 써요. 한국어로는 '달라졌어요'처럼 과거로 말하지만 독일어로는 'ist … anders'처럼 현재형이에요. bis는 전치사로도 쓰여요(bis morgen). 접속사 bis 뒤에는 주어와 동사가 있는 절이 와요(…, bis mir ein Kommilitone alles geduldig erklärt hat)."},{"title":"als의 세 가지 쓰임: 때 · 자격 · 비교","term":"als: temporale Konjunktion, Funktion, Vergleich","explain":"als는 쓰임에 따라 뜻이 달라요. 첫째, 접속사 als는 과거에 한 번 있었던 일을 말하는 종속절을 이끌어요. 이때 동사는 절 끝에 와요(Als … ausgezogen ist, …). 둘째, 명사 앞의 als는 '~로서'라는 뜻으로 사람이나 사물의 역할·자격을 나타내요(als Gasthörerin). gelten als(~로 여겨지다)처럼 als와 함께 쓰는 동사도 있어요. 셋째, 비교급 뒤의 als는 '~보다'라는 뜻이에요(jünger als).","pattern":"Als + 주어 … 동사(끝), 동사 + 주어 …  ·  als + 명사(역할)  ·  비교급 + als","examples":[{"de":"Als vor drei Jahren auch unser jüngster Sohn ausgezogen ist, war das Haus plötzlich sehr still.","ko":"3년 전에 막내아들까지 집을 나가 독립했을 때, 집이 갑자기 아주 조용해졌어요.","mark":["Als","ausgezogen ist"],"parts":[["Als vor drei Jahren auch unser jüngster Sohn ausgezogen ist,","종속절"],["war","동사"],["das Haus","주어"],["plötzlich","부사어"],["sehr still.","보어"]]},{"de":"Ich habe zuerst ein Semester lang als Gasthörerin Vorlesungen besucht, bevor ich mich richtig eingeschrieben habe.","ko":"정식으로 등록하기 전에 먼저 한 학기 동안 청강생으로 강의를 들었어요.","mark":["als Gasthörerin"],"parts":[["Ich","주어"],["habe","동사"],["zuerst","부사어(시간)"],["ein Semester lang","부사어(시간)"],["als Gasthörerin","부사어"],["Vorlesungen","4격 목적어"],["besucht,","동사(끝)"],["bevor ich mich richtig eingeschrieben habe.","종속절"]]},{"de":"Anfangs war es ungewohnt, weil viele Kommilitonen jünger sind als meine eigenen Kinder.","ko":"처음에는 낯설었어요. 많은 학우가 제 아이들보다도 어리거든요.","mark":["jünger","als meine eigenen Kinder"]},{"de":"Mit zwanzig habe ich eine Ausbildung zur Bankkauffrau gemacht, weil das damals als krisenfester Beruf galt, aber Geschichte hat mich nie losgelassen.","ko":"스무 살에 은행원 직업 교육을 받았는데, 당시에는 그게 위기에도 흔들리지 않는 직업으로 여겨졌기 때문이에요. 하지만 역사에 대한 관심은 한 번도 사라진 적이 없어요.","mark":["als krisenfester Beruf galt"]}],"tip":"als의 뜻은 앞뒤를 보고 정해요. als가 이끄는 절의 끝에 동사가 오면 때를 나타내는 접속사이고, 바로 뒤에 명사만 오면 '~로서'예요. 앞에 비교급(jünger, mehr)이 있으면 '~보다'예요. 과거에 여러 번 되풀이된 일에는 als 대신 wenn을 써요."},{"title":"erst als · erst einmal: '그제야'와 '우선'","term":"Die Partikel erst: erst als …, erst einmal","explain":"erst는 시간과 관련해 두 가지 뜻으로 자주 써요. 첫째, erst als …(현재·미래는 erst wenn …)는 '~하고 나서야 비로소'라는 뜻이에요. 그 일이 있기 전에는 다음 일이 일어나지 않았다는 점을 강조해요. 이 종속절이 문장 맨 앞에 오면 쉼표 바로 뒤에 주절의 동사가 오고 그다음에 주어가 와요. 둘째, erst einmal은 '우선, 일단'이라는 뜻으로, 본격적으로 하기 전에 먼저 해 보는 일을 말해요.","pattern":"Erst als + 주어 … 동사(끝), 동사 + 주어 …  ·  erst einmal + 먼저 하는 일","examples":[{"de":"Erst als ich festgestellt habe, dass mir das Lernen trotz der Anstrengung Freude macht, habe ich Kontakt mit der Studienberatung aufgenommen.","ko":"힘들어도 공부가 즐겁다는 걸 알게 된 뒤에야 학업 상담실에 연락했어요.","mark":["Erst als","habe ich"],"parts":[["Erst als ich festgestellt habe, dass mir das Lernen trotz der Anstrengung Freude macht,","종속절"],["habe","동사"],["ich","주어"],["Kontakt","4격 목적어"],["mit der Studienberatung","전치사 목적어"],["aufgenommen.","동사(끝)"]]},{"de":"Man muss sich nicht gleich einschreiben, sondern kann erst einmal als Gasthörer ausprobieren, ob das Lernen im Hörsaal zu einem passt.","ko":"바로 등록할 필요는 없고, 우선 청강생으로 강의실에서 배우는 게 자기에게 맞는지 시험해 봐도 돼요.","mark":["erst einmal"]}],"tip":"erst와 nur는 뜻이 달라요. 'Ich bin erst im dritten Semester.'는 '아직 3학기째예요(앞으로 더 이어져요)'라는 뜻이고, nur는 '그것뿐'이라는 뜻이에요. erst als 문장은 한국어로 '~하고 나서야'로 옮기면 자연스러워요."},{"title":"기능동사 구문 – 명사와 동사가 짝을 이루는 표현","term":"Nomen-Verb-Verbindungen","explain":"독일어에는 명사와 동사가 짝을 이루어 하나의 뜻을 만드는 표현이 많아요. 이런 표현을 기능동사 구문이라고 해요. 뜻은 주로 명사에 있고, 동사는 원래 뜻이 약해져요(eine Entscheidung treffen의 treffen은 '만나다'가 아니에요). eine Entscheidung treffen은 '결정을 내리다', Kontakt aufnehmen은 '연락하다', Rücksicht nehmen은 '배려하다', ein Ziel verfolgen은 '목표를 추구하다', eine Prüfung ablegen은 '시험을 치르다'예요. 동사를 마음대로 바꿀 수 없으니 짝을 통째로 외워요.","pattern":"(관사) + 명사 + 정해진 동사: eine Entscheidung treffen, Rücksicht nehmen auf + 4격","examples":[{"de":"In diesem Moment habe ich die Entscheidung getroffen.","ko":"그 순간에 결정을 내렸어요.","mark":["die Entscheidung getroffen"],"parts":[["In diesem Moment","부사어(시간)"],["habe","동사"],["ich","주어"],["die Entscheidung","4격 목적어"],["getroffen.","동사(끝)"]]},{"de":"Trotzdem nehmen wir in der Lerngruppe Rücksicht aufeinander.","ko":"그래도 스터디 그룹에서는 서로 배려해요.","mark":["nehmen","Rücksicht aufeinander"],"parts":[["Trotzdem","접속부사"],["nehmen","동사"],["wir","주어"],["in der Lerngruppe","부사어(장소)"],["Rücksicht","4격 목적어"],["aufeinander.","전치사 목적어"]]},{"de":"Welches Ziel verfolgen Sie mit dem Studium?","ko":"대학 공부를 하면서 어떤 목표를 갖고 계세요?","mark":["Ziel verfolgen"]},{"de":"Meine erste Modulprüfung habe ich übrigens schon abgelegt – mit einer Zwei, obwohl ich furchtbar aufgeregt war.","ko":"참, 첫 모듈 시험은 이미 치렀어요. 무척 긴장했지만 성적은 2(gut)였어요.","mark":["Modulprüfung","abgelegt"]}],"tip":"entscheiden 대신 eine Entscheidung treffen처럼 명사 표현을 쓰면 더 격식 있게 들려요. 함께 쓰는 전치사도 같이 외우세요: Rücksicht nehmen auf + 4격, Kontakt aufnehmen mit + 3격. 예문의 aufeinander는 auf + einander(서로)예요."}],"vocab":[{"de":"der Hörsaal, -säle","ko":"(대학의) 대형 강의실"},{"de":"die Bankfiliale, -n","ko":"은행 지점"},{"de":"der Neuanfang, -¨e","ko":"새 출발"},{"de":"krisenfest","ko":"위기에 강한, 경기를 타지 않는"},{"de":"gelten als + Nom. (gilt, galt, hat gegolten)","ko":"~로 여겨지다, ~로 통하다"},{"de":"los|lassen (lässt los, ließ los, hat losgelassen)","ko":"놓아주다; (jemanden nicht loslassen) 마음을 떠나지 않다"},{"de":"aus|ziehen (zieht aus, zog aus, ist ausgezogen)","ko":"이사 나가다, 집을 떠나 독립하다"},{"de":"sich ein|schreiben (schreibt sich ein, schrieb sich ein, hat sich eingeschrieben)","ko":"(대학에) 등록하다"},{"de":"die Gasthörerin, -nen","ko":"청강생(여성)"},{"de":"die Vorlesung, -en","ko":"(대학) 강의"},{"de":"der Kommilitone, -n","ko":"같은 대학에 다니는 학생, 학우"},{"de":"die Mitschrift, -en","ko":"(강의) 필기, 필기 노트"},{"de":"zurecht|kommen mit + Dat. (kommt zurecht, kam zurecht, ist zurechtgekommen)","ko":"~을 잘 다루다, ~에 적응하다"},{"de":"ehrenamtlich","ko":"자원봉사로, 무보수로"},{"de":"angewiesen sein auf + Akk.","ko":"~에 의지해야 하다, ~이 꼭 있어야 하다"},{"de":"zögern","ko":"망설이다, 주저하다"}],"phrases":[{"de":"eine Entscheidung treffen","ko":"결정을 내리다","ex":"In diesem Moment habe ich die Entscheidung getroffen.","exko":"그 순간에 결정을 내렸어요."},{"de":"Kontakt aufnehmen mit + Dat.","ko":"~와 연락하다, 접촉하다","ex":"Erst als ich festgestellt habe, dass mir das Lernen trotz der Anstrengung Freude macht, habe ich Kontakt mit der Studienberatung aufgenommen.","exko":"힘들어도 공부가 즐겁다는 걸 알게 된 뒤에야 학업 상담실에 연락했어요."},{"de":"Rücksicht nehmen auf + Akk.","ko":"~을 배려하다","ex":"Trotzdem nehmen wir in der Lerngruppe Rücksicht aufeinander.","exko":"그래도 스터디 그룹에서는 서로 배려해요."},{"de":"etwas in der Tasche haben","ko":"(자격·학위 등을) 확실히 손에 넣다","ex":"Bis ich den Bachelor in der Tasche habe, dauert es noch ungefähr zwei Jahre.","exko":"학사 학위를 손에 넣기까지 아직 2년 정도 걸려요."},{"de":"am Stück","ko":"쉬지 않고 이어서, 한 번에","ex":"Ich wollte herausfinden, ob ich nach Jahrzehnten am Schreibtisch noch neunzig Minuten am Stück zuhören kann.","exko":"수십 년 동안 책상 앞에서 일한 뒤에도 아직 90분을 쉬지 않고 들을 수 있는지 알아보고 싶었어요."}],"words":358},{"id":"b1-07","level":"B1","no":7,"title":"Carsharing: Fragen und Antworten","titleKo":"카셰어링, 자주 묻는 질문","type":"FAQ-Seite","typeKo":"자주 묻는 질문 페이지","intro":"가상의 카셰어링 업체 KlickCar의 홈페이지에 있는 자주 묻는 질문 페이지예요.","focus":["짝을 이루는 접속사","zwar … aber","bei · nach · vor + 명사","합성명사 읽기"],"paragraphs":[{"de":"Hier finden Sie Antworten auf häufige Fragen zur Registrierung, Abrechnung und Nutzung unserer Fahrzeuge. Falls Ihre Frage nicht dabei ist, hilft Ihnen unser Kundenbüro gern weiter.","ko":"여기에서 가입, 요금 정산, 차량 이용에 관해 자주 묻는 질문의 답을 보실 수 있습니다. 찾으시는 질문이 없으면 저희 고객 사무실에서 기꺼이 도와드립니다."},{"style":"h","de":"Wie läuft die Anmeldung ab?","ko":"가입은 어떻게 하나요?"},{"de":"Die Anmeldung ist kostenlos und sowohl in der KlickCar-App als auch in unserem Kundenbüro am Hauptbahnhof möglich. In der App laden Sie einen Scan nicht nur Ihres Führerscheins, sondern auch Ihres Personalausweises hoch. Nach erfolgreicher Prüfung Ihrer Unterlagen erhalten Sie innerhalb von 24 Stunden eine Bestätigung per E-Mail.","ko":"가입은 무료이며 KlickCar 앱에서도, 중앙역에 있는 저희 고객 사무실에서도 할 수 있습니다. 앱에서는 운전면허증뿐 아니라 신분증도 스캔해서 올립니다. 서류 확인이 문제없이 끝나면 24시간 안에 이메일로 승인 안내를 받게 됩니다."},{"style":"h","de":"Wer darf unsere Fahrzeuge nutzen?","ko":"누가 저희 차량을 이용할 수 있나요?"},{"de":"Fahrberechtigt sind alle Personen ab 21 Jahren, die seit mindestens einem Jahr einen gültigen Führerschein besitzen. Fahranfänger, deren Führerschein noch kein Jahr alt ist, können wir aus Versicherungsgründen leider nicht aufnehmen. Das Fahrzeug darf ausschließlich von der angemeldeten Person gefahren werden, also weder von Freunden noch von Familienmitgliedern.","ko":"유효한 운전면허를 1년 이상 가지고 있는 21세 이상이면 누구나 운전할 수 있습니다. 면허를 딴 지 1년이 안 된 초보 운전자는 보험 문제로 아쉽게도 회원으로 받을 수 없습니다. 차량은 가입한 본인만 운전할 수 있으며, 친구도 가족도 운전할 수 없습니다."},{"style":"h","de":"Wie funktioniert die Abrechnung?","ko":"요금은 어떻게 정산되나요?"},{"de":"Abgerechnet wird entweder pro Minute oder pro Stunde – je nachdem, was für Sie günstiger ist, denn am Fahrtende ermittelt die App automatisch den niedrigeren Betrag. Im Basistarif fallen weder eine monatliche Grundgebühr noch eine Kaution an. Der Vielfahrertarif kostet zwar 9 Euro monatlich, dafür sinkt aber der Minutenpreis deutlich.","ko":"요금은 분 단위나 시간 단위 중 고객님께 더 저렴한 쪽으로 정산됩니다. 운행이 끝나면 앱이 자동으로 더 낮은 금액을 계산하기 때문입니다. 기본 요금제에는 월 기본료도 보증금도 없습니다. 다빈도 요금제는 매달 9유로가 들지만, 대신 분당 요금이 크게 내려갑니다."},{"style":"h","de":"Muss ich Kraftstoff oder Strom extra bezahlen?","ko":"연료비나 전기 요금을 따로 내야 하나요?"},{"de":"Nein, denn Kraftstoff und Strom sind im Fahrpreis inklusive. Bei fast leerem Tank oder Akku nutzen Sie bitte die Tank- und Ladekarte im Handschuhfach – die Kosten übernehmen wir.","ko":"아니요. 연료비와 전기 요금은 이용 요금에 포함되어 있습니다. 연료나 배터리가 거의 비었을 때는 글러브 박스에 있는 주유·충전 카드를 사용해 주십시오. 비용은 저희가 부담합니다."},{"style":"h","de":"Wo gebe ich das Fahrzeug zurück?","ko":"차량은 어디에 반납하나요?"},{"de":"Bei der Rückgabe muss das Fahrzeug in derselben Zone stehen wie bei der Abholung – einzige Ausnahme ist der Flughafen. Die genauen Zonengrenzen werden Ihnen in der App angezeigt. Außerhalb einer Zone können Sie die Fahrt nicht beenden.","ko":"반납할 때 차량은 가져갈 때와 같은 구역 안에 있어야 합니다. 유일한 예외는 공항입니다. 정확한 구역 경계는 앱에 표시됩니다. 구역 밖에서는 운행을 종료할 수 없습니다."},{"style":"h","de":"Was mache ich bei einer Beschädigung?","ko":"차량이 파손되었으면 어떻게 하나요?"},{"de":"Prüfen Sie das Fahrzeug bitte vor jeder Fahrt auf sichtbare Schäden und melden Sie uns jeden Schaden umgehend, entweder über die App oder telefonisch – auch kleine Kratzer. Schäden, die nicht gemeldet werden, müssen wir der Person in Rechnung stellen, die das Fahrzeug zuletzt genutzt hat.","ko":"운행 전에는 매번 눈에 보이는 파손이 없는지 차량을 확인하시고, 파손이 있으면 작은 긁힘이라도 앱이나 전화로 즉시 저희에게 알려 주십시오. 신고되지 않은 파손은 마지막으로 차량을 이용한 사람에게 청구할 수밖에 없습니다."},{"style":"h","de":"Wo finde ich KlickCar-Fahrzeuge?","ko":"KlickCar 차량은 어디에 있나요?"},{"de":"Unsere Fahrzeuge stehen nicht nur in der Innenstadt, sondern auch am Flughafen und an allen S-Bahnhöfen. Fahrten zum Flughafen sind zwar aus allen Zonen möglich, aber dort müssen Sie das Fahrzeug auf dem KlickCar-Stellplatz vor Terminal 2 abstellen.","ko":"저희 차량은 도심뿐 아니라 공항과 모든 S반 역에도 있습니다. 공항까지는 어느 구역에서든 운행할 수 있지만, 공항에서는 2터미널 앞 KlickCar 전용 주차 구역에 차량을 세워야 합니다."}],"questions":[{"type":"rf","kind":"detail","q":"Man muss sich nicht unbedingt per Handy registrieren.","answer":0,"evidence":"Die Anmeldung ist kostenlos und sowohl in der KlickCar-App als auch in unserem Kundenbüro am Hauptbahnhof möglich.","pairs":[["sowohl in der KlickCar-App als auch in unserem Kundenbüro","nicht unbedingt per Handy"],["Die Anmeldung","registrieren"]],"explain":"가입은 앱에서도, 중앙역 고객 사무실에서도 할 수 있다고 해요(sowohl … als auch). 고객 사무실에 직접 가서 가입할 수 있으니 꼭 휴대폰으로 등록할 필요는 없어요. Anmeldung(가입)을 sich registrieren(등록하다)으로 바꿔 말했어요."},{"type":"mc","kind":"detail","q":"Wer darf laut FAQ kein KlickCar-Fahrzeug fahren?","options":["ein Kunde mit 23 Jahren, der seit zwei Jahren einen Führerschein hat","der Bruder einer Kundin, wenn er selbst nicht angemeldet ist","eine Kundin mit 21 Jahren, deren Führerschein schon drei Jahre alt ist"],"answer":1,"evidence":"Das Fahrzeug darf ausschließlich von der angemeldeten Person gefahren werden, also weder von Freunden noch von Familienmitgliedern.","pairs":[["weder von Freunden noch von Familienmitgliedern","der Bruder einer Kundin"],["ausschließlich von der angemeldeten Person","wenn er selbst nicht angemeldet ist"]],"explain":"차량은 가입한 본인만(ausschließlich) 운전할 수 있고, 친구도 가족도 운전할 수 없어요(weder … noch). 그러니 고객의 남자 형제라도 본인이 가입하지 않았다면 운전할 수 없어요. 23세이고 면허를 딴 지 2년이 된 사람은 나이(21세 이상)와 면허 기간(1년 이상) 조건을 모두 채워요. 'ab 21 Jahren'은 21세부터라는 뜻이니, 면허를 딴 지 3년이 된 21세 고객도 운전할 수 있어요."},{"type":"mc","kind":"paraphrase","q":"Was ist mit „Abgerechnet wird entweder pro Minute oder pro Stunde – je nachdem, was für Sie günstiger ist“ gemeint?","options":["Man wählt vor der Fahrt selbst, ob pro Minute oder Stunde bezahlt wird.","Der Minutenpreis ist je nach Tageszeit und Wochentag unterschiedlich hoch.","Bei jeder Fahrt wird die Variante berechnet, die am Ende weniger kostet."],"answer":2,"evidence":"denn am Fahrtende ermittelt die App automatisch den niedrigeren Betrag","pairs":[["je nachdem, was für Sie günstiger ist","die am Ende weniger kostet"],["ermittelt die App automatisch den niedrigeren Betrag","wird die Variante berechnet"]],"explain":"'je nachdem, was für Sie günstiger ist'는 '둘 중 고객에게 더 저렴한 쪽에 따라'라는 뜻이에요. 같은 문장 뒷부분에서 운행이 끝나면 앱이 자동으로 더 낮은 금액을 계산한다고 하니, 고객이 미리 고를 필요가 없어요. 시간대나 요일에 따라 분당 요금이 달라진다는 말은 본문에 없어요."},{"type":"rf","kind":"detail","q":"Im Basistarif zahlt man zwar keine Kaution, aber eine feste Monatsgebühr.","answer":1,"evidence":"Im Basistarif fallen weder eine monatliche Grundgebühr noch eine Kaution an.","pairs":[["weder eine monatliche Grundgebühr noch eine Kaution","zwar keine Kaution, aber eine feste Monatsgebühr"],["Der Vielfahrertarif kostet zwar 9 Euro monatlich","eine feste Monatsgebühr"]],"explain":"weder A noch B는 'A도 B도 아니다'라는 뜻이에요. 기본 요금제에는 보증금도 월 기본료도 없으니 진술은 틀려요. 매달 9유로를 내는 것은 다빈도 요금제(Vielfahrertarif)예요."},{"type":"mc","kind":"inference","q":"Für wen lohnt sich der Vielfahrertarif am ehesten?","options":["für Fahranfänger, die erst seit einigen Monaten fahren dürfen","für Leute, die nur selten eine kurze Fahrt zum Flughafen machen","für Leute, die sehr oft und lange mit dem Auto unterwegs sind"],"answer":2,"evidence":"Der Vielfahrertarif kostet zwar 9 Euro monatlich, dafür sinkt aber der Minutenpreis deutlich.","pairs":[["dafür sinkt aber der Minutenpreis deutlich","sehr oft und lange mit dem Auto unterwegs sind"],["kostet zwar 9 Euro monatlich","nur selten eine kurze Fahrt"]],"explain":"다빈도 요금제는 매달 9유로를 내야 하지만 분당 요금이 크게 내려가요. 9유로를 내고도 이득을 보려면 한 달에 자주, 오래 운전해야 해요. 가끔 짧게 타는 사람에게는 월 9유로가 오히려 손해예요. 면허를 딴 지 1년이 안 된 초보 운전자는 처음부터 KlickCar를 이용할 수 없어요."},{"type":"rf","kind":"detail","q":"Wenn der Akku fast leer ist, muss man die Kosten für das Laden zunächst selbst bezahlen.","answer":1,"evidence":"Bei fast leerem Tank oder Akku nutzen Sie bitte die Tank- und Ladekarte im Handschuhfach – die Kosten übernehmen wir.","pairs":[["die Kosten übernehmen wir","die Kosten für das Laden zunächst selbst bezahlen"],["Bei fast leerem Tank oder Akku","Wenn der Akku fast leer ist"]],"explain":"배터리가 거의 비면 글러브 박스에 있는 충전 카드를 쓰면 되고, 비용은 회사가 부담한다고 해요(die Kosten übernehmen wir). 전기 요금은 처음부터 이용 요금에 포함되어 있으니 고객이 먼저 돈을 낼 필요가 없어요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Außerhalb einer Zone können Sie die Fahrt nicht beenden.“?","options":["Fahrten über die Zonengrenzen hinaus sind grundsätzlich verboten.","Die Kosten laufen weiter, bis der Wagen in einem erlaubten Gebiet steht.","Außerhalb der Zonen schaltet sich der Motor des Fahrzeugs automatisch ab."],"answer":1,"evidence":"Außerhalb einer Zone können Sie die Fahrt nicht beenden.","pairs":[["die Fahrt nicht beenden","Die Kosten laufen weiter"],["Außerhalb einer Zone","bis der Wagen in einem erlaubten Gebiet steht"]],"explain":"구역 밖에서는 운행을 끝낼 수 없다는 말은, 차가 다시 구역 안에 설 때까지 이용이 계속되고 요금도 계속 쌓인다는 뜻이에요. 구역 밖으로 나가는 것 자체가 금지라는 말은 없어요. 오히려 어느 구역에서든 공항까지 갈 수 있다고 했어요. 차가 저절로 꺼진다는 말도 본문에 없어요."},{"type":"mc","kind":"inference","q":"Ein Kunde entdeckt vor der Fahrt einen kleinen Kratzer, meldet ihn aber nicht. Was kann danach passieren?","options":["Der Kunde, der das Fahrzeug vor ihm gefahren ist, muss den Kratzer bezahlen.","Nichts, denn so kleine Kratzer müssen laut FAQ nicht gemeldet werden.","Er muss vielleicht für einen Schaden zahlen, den er nicht verursacht hat."],"answer":2,"evidence":"Schäden, die nicht gemeldet werden, müssen wir der Person in Rechnung stellen, die das Fahrzeug zuletzt genutzt hat.","pairs":[["müssen wir der Person in Rechnung stellen","für einen Schaden zahlen"],["die das Fahrzeug zuletzt genutzt hat","den er nicht verursacht hat"],["auch kleine Kratzer","so kleine Kratzer müssen laut FAQ nicht gemeldet werden"]],"explain":"신고되지 않은 파손은 마지막으로 차를 이용한 사람에게 청구된다고 해요(der Person in Rechnung stellen, die das Fahrzeug zuletzt genutzt hat). 이 고객이 긁힘을 신고하지 않고 운행하면, 운행이 끝난 뒤에는 이 고객이 '마지막 이용자'가 돼요. 그래서 자기가 내지 않은 긁힘 값을 낼 수도 있어요. 작은 긁힘도 신고해야 한다고 했으니(auch kleine Kratzer) 아무 일도 없다는 선지는 틀려요. 앞사람이 돈을 낸다는 선지도 틀려요. 운행이 끝나면 마지막 이용자는 앞사람이 아니라 이 고객이기 때문이에요."}],"grammar":[{"title":"짝을 이루는 접속사: sowohl … als auch · weder … noch · entweder … oder","term":"Zweiteilige Konnektoren: sowohl … als auch, weder … noch, entweder … oder","explain":"두 부분으로 된 접속사는 같은 종류의 문장 성분 두 개를 연결해요. sowohl A als auch B는 'A도 B도 둘 다', weder A noch B는 'A도 B도 아니다', entweder A oder B는 'A 아니면 B, 둘 중 하나'라는 뜻이에요. weder … noch에는 부정의 뜻이 들어 있어서 nicht나 kein을 따로 쓰지 않아요. 연결되는 두 부분은 문장 안에서 같은 역할을 해요.","pattern":"sowohl A als auch B  ·  weder A noch B  ·  entweder A oder B","examples":[{"de":"Die Anmeldung ist kostenlos und sowohl in der KlickCar-App als auch in unserem Kundenbüro am Hauptbahnhof möglich.","ko":"가입은 무료이며 KlickCar 앱에서도, 중앙역에 있는 저희 고객 사무실에서도 할 수 있습니다.","mark":["sowohl","als auch"],"parts":[["Die Anmeldung","주어"],["ist","동사"],["kostenlos","보어"],["und","접속사"],["sowohl in der KlickCar-App als auch in unserem Kundenbüro am Hauptbahnhof","부사어(장소)"],["möglich.","보어"]]},{"de":"Im Basistarif fallen weder eine monatliche Grundgebühr noch eine Kaution an.","ko":"기본 요금제에는 월 기본료도 보증금도 없습니다.","mark":["weder","noch"],"parts":[["Im Basistarif","부사어"],["fallen","동사"],["weder eine monatliche Grundgebühr noch eine Kaution","주어"],["an.","동사(끝)"]]},{"de":"Abgerechnet wird entweder pro Minute oder pro Stunde – je nachdem, was für Sie günstiger ist, denn am Fahrtende ermittelt die App automatisch den niedrigeren Betrag.","ko":"요금은 분 단위나 시간 단위 중 고객님께 더 저렴한 쪽으로 정산됩니다. 운행이 끝나면 앱이 자동으로 더 낮은 금액을 계산하기 때문입니다.","mark":["entweder","oder"]}],"tip":"weder … noch와 함께 nicht나 kein을 또 쓰면 틀려요(× weder keine Grundgebühr noch keine Kaution). 비슷한 짝으로 nicht nur A, sondern auch B('A뿐 아니라 B도')가 있어요. sondern 앞에는 쉼표를 찍어요: Unsere Fahrzeuge stehen nicht nur in der Innenstadt, sondern auch am Flughafen und an allen S-Bahnhöfen."},{"title":"zwar … aber – 먼저 인정하고 더 중요한 내용 말하기","term":"Zweiteilige Konnektoren: zwar … aber","explain":"zwar A, aber B는 'A이기는 하지만 B'라는 뜻이에요. 먼저 zwar로 어떤 사실을 인정하고, 뒤에서 aber로 그와 반대되거나 더 중요한 내용을 말해요. zwar는 첫 문장에서 동사 뒤에 오는 경우가 많아요. aber는 두 번째 문장 맨 앞에 올 수도 있고(aber dort müssen Sie …), 동사 뒤로 들어갈 수도 있어요(dafür sinkt aber …).","pattern":"주어 + 동사 + zwar …, aber + 1번 자리 + 동사 …  ·  …, 1번 자리 + 동사 + aber …","examples":[{"de":"Der Vielfahrertarif kostet zwar 9 Euro monatlich, dafür sinkt aber der Minutenpreis deutlich.","ko":"다빈도 요금제는 매달 9유로가 들지만, 대신 분당 요금이 크게 내려갑니다.","mark":["zwar","aber"],"parts":[["Der Vielfahrertarif","주어"],["kostet","동사"],["zwar","부사어"],["9 Euro","4격 목적어"],["monatlich,","부사어(빈도)"],["dafür","부사어"],["sinkt","동사"],["aber","접속부사"],["der Minutenpreis","주어"],["deutlich.","부사어(방법)"]]},{"de":"Fahrten zum Flughafen sind zwar aus allen Zonen möglich, aber dort müssen Sie das Fahrzeug auf dem KlickCar-Stellplatz vor Terminal 2 abstellen.","ko":"공항까지는 어느 구역에서든 운행할 수 있지만, 공항에서는 2터미널 앞 KlickCar 전용 주차 구역에 차량을 세워야 합니다.","mark":["zwar","aber"],"parts":[["Fahrten zum Flughafen","주어"],["sind","동사"],["zwar","부사어"],["aus allen Zonen","부사어(장소)"],["möglich,","보어"],["aber","접속사"],["dort","부사어(장소)"],["müssen","동사"],["Sie","주어"],["das Fahrzeug","4격 목적어"],["auf dem KlickCar-Stellplatz vor Terminal 2","부사어(장소)"],["abstellen.","동사(끝)"]]}],"tip":"zwar … aber는 obwohl과 뜻이 비슷하지만 어순이 달라요. zwar … aber는 주절 두 개를 연결해서 동사가 2번 자리에 있고, obwohl은 종속절을 이끌어서 동사가 끝에 와요: Obwohl der Vielfahrertarif 9 Euro kostet, lohnt er sich für Vielfahrer. 예문의 dafür는 '그 대신'이라는 뜻이에요."},{"title":"bei · nach · vor + 명사 – 부문장 대신 쓰는 명사 표현","term":"Nominalstil: bei, nach, vor + Nomen statt Nebensatz","explain":"안내문이나 규정에서는 부문장 대신 '전치사 + 명사'로 짧게 말하는 경우가 많아요. bei + 명사는 wenn절처럼 '~할 때, ~하는 경우'(bei der Rückgabe = wenn Sie das Fahrzeug zurückgeben), nach + 명사는 nachdem절처럼 '~한 뒤에'(nach der Prüfung = nachdem wir die Unterlagen geprüft haben), vor + 명사는 bevor절처럼 '~하기 전에'(vor jeder Fahrt = bevor Sie losfahren)라는 뜻이에요. 동사 대신 -ung 같은 명사를 쓰고, 동사의 목적어였던 말은 2격으로 붙여요(die Unterlagen prüfen → die Prüfung Ihrer Unterlagen).","pattern":"bei / nach / vor + (관사) + 명사 (+ 2격) + 동사 + 주어 …","examples":[{"de":"Nach erfolgreicher Prüfung Ihrer Unterlagen erhalten Sie innerhalb von 24 Stunden eine Bestätigung per E-Mail.","ko":"서류 확인이 문제없이 끝나면 24시간 안에 이메일로 승인 안내를 받게 됩니다.","mark":["Nach erfolgreicher Prüfung Ihrer Unterlagen"],"parts":[["Nach erfolgreicher Prüfung Ihrer Unterlagen","부사어(시간)"],["erhalten","동사"],["Sie","주어"],["innerhalb von 24 Stunden","부사어(시간)"],["eine Bestätigung","4격 목적어"],["per E-Mail.","부사어(방법)"]]},{"de":"Bei der Rückgabe muss das Fahrzeug in derselben Zone stehen wie bei der Abholung – einzige Ausnahme ist der Flughafen.","ko":"반납할 때 차량은 가져갈 때와 같은 구역 안에 있어야 합니다. 유일한 예외는 공항입니다.","mark":["Bei der Rückgabe","bei der Abholung"]},{"de":"Prüfen Sie das Fahrzeug bitte vor jeder Fahrt auf sichtbare Schäden und melden Sie uns jeden Schaden umgehend, entweder über die App oder telefonisch – auch kleine Kratzer.","ko":"운행 전에는 매번 눈에 보이는 파손이 없는지 차량을 확인하시고, 파손이 있으면 작은 긁힘이라도 앱이나 전화로 즉시 저희에게 알려 주십시오.","mark":["vor jeder Fahrt"]}],"tip":"명사 표현은 짧고 격식 있게 들리지만, 처음 읽을 때는 부문장으로 바꿔 보면 이해하기 쉬워요: Bei fast leerem Tank = Wenn der Tank fast leer ist. 형용사 어미에도 주의하세요. 관사 없이 형용사가 오면 형용사가 격을 보여 줘요(bei fast leerem Tank, nach erfolgreicher Prüfung: 둘 다 3격)."},{"title":"합성명사 읽기: 연결음 -s- · -n-과 붙임표(-)","term":"Komposita: Fugenelemente und Ergänzungsstrich","explain":"독일어 안내문에는 명사를 이어 붙인 합성명사가 많아요. 합성명사의 성과 기본 뜻은 마지막 명사가 정해요(der Grund + die Gebühr → die Grundgebühr, 기본료). 앞 명사와 뒤 명사 사이에 -s-나 -n- 같은 연결음이 들어가기도 해요(die Versicherung + s + die Gründe → die Versicherungsgründe, die Zone + n + die Grenze → die Zonengrenze). 두 합성명사의 뒷부분이 같으면 앞 단어의 뒷부분을 줄이고 붙임표(-)를 써요(Tankkarte und Ladekarte → Tank- und Ladekarte).","pattern":"앞 명사 (+ s / n) + 마지막 명사(성·뜻 결정)  ·  Tank- und Ladekarte = Tankkarte und Ladekarte","examples":[{"de":"Die genauen Zonengrenzen werden Ihnen in der App angezeigt.","ko":"정확한 구역 경계는 앱에 표시됩니다.","mark":["Zonengrenzen"],"parts":[["Die genauen Zonengrenzen","주어"],["werden","동사"],["Ihnen","3격 목적어"],["in der App","부사어(장소)"],["angezeigt.","동사(끝)"]]},{"de":"Fahranfänger, deren Führerschein noch kein Jahr alt ist, können wir aus Versicherungsgründen leider nicht aufnehmen.","ko":"면허를 딴 지 1년이 안 된 초보 운전자는 보험 문제로 아쉽게도 회원으로 받을 수 없습니다.","mark":["Versicherungsgründen"]},{"de":"Bei fast leerem Tank oder Akku nutzen Sie bitte die Tank- und Ladekarte im Handschuhfach – die Kosten übernehmen wir.","ko":"연료나 배터리가 거의 비었을 때는 글러브 박스에 있는 주유·충전 카드를 사용해 주십시오. 비용은 저희가 부담합니다.","mark":["Tank- und Ladekarte"]}],"tip":"긴 합성명사는 뒤에서부터 나눠 읽으세요: Vielfahrertarif = viel + Fahrer + Tarif(많이 타는 사람을 위한 요금제), Minutenpreis = Minute + n + Preis(분당 요금). -s-와 -n-은 따로 뜻을 더하지 않아요."}],"vocab":[{"de":"die Registrierung, -en","ko":"등록, 가입"},{"de":"die Abrechnung, -en","ko":"(요금) 정산"},{"de":"der Personalausweis, -e","ko":"신분증"},{"de":"hoch|laden (lädt hoch, lud hoch, hat hochgeladen)","ko":"(파일을) 올리다, 업로드하다"},{"de":"die Bestätigung, -en","ko":"확인, 승인 안내"},{"de":"fahrberechtigt","ko":"운전할 자격이 있는"},{"de":"der Fahranfänger, -","ko":"초보 운전자"},{"de":"ausschließlich","ko":"오직, 오로지"},{"de":"die Grundgebühr, -en","ko":"기본료"},{"de":"die Kaution, -en","ko":"보증금"},{"de":"an|fallen (fällt an, fiel an, ist angefallen)","ko":"(비용이) 발생하다, 생기다"},{"de":"der Kraftstoff, -e","ko":"연료"},{"de":"das Handschuhfach, -¨er","ko":"(자동차의) 글러브 박스"},{"de":"die Rückgabe, -n","ko":"반납"},{"de":"umgehend","ko":"즉시, 지체 없이"},{"de":"ab|stellen","ko":"(차를) 세워 두다, 주차하다"}],"phrases":[{"de":"je nachdem, was/wie/ob …","ko":"~에 따라서","ex":"Abgerechnet wird entweder pro Minute oder pro Stunde – je nachdem, was für Sie günstiger ist, denn am Fahrtende ermittelt die App automatisch den niedrigeren Betrag.","exko":"요금은 분 단위나 시간 단위 중 고객님께 더 저렴한 쪽으로 정산됩니다. 운행이 끝나면 앱이 자동으로 더 낮은 금액을 계산하기 때문입니다."},{"de":"im (Fahr-)Preis inklusive sein","ko":"요금에 포함되어 있다","ex":"Nein, denn Kraftstoff und Strom sind im Fahrpreis inklusive.","exko":"아니요. 연료비와 전기 요금은 이용 요금에 포함되어 있습니다."},{"de":"die Kosten übernehmen","ko":"비용을 부담하다","ex":"Bei fast leerem Tank oder Akku nutzen Sie bitte die Tank- und Ladekarte im Handschuhfach – die Kosten übernehmen wir.","exko":"연료나 배터리가 거의 비었을 때는 글러브 박스에 있는 주유·충전 카드를 사용해 주십시오. 비용은 저희가 부담합니다."},{"de":"jemandem etwas in Rechnung stellen","ko":"~에게 ~의 비용을 청구하다","ex":"Schäden, die nicht gemeldet werden, müssen wir der Person in Rechnung stellen, die das Fahrzeug zuletzt genutzt hat.","exko":"신고되지 않은 파손은 마지막으로 차량을 이용한 사람에게 청구할 수밖에 없습니다."},{"de":"jemandem weiterhelfen","ko":"~를 (문제 해결에) 도와주다","ex":"Falls Ihre Frage nicht dabei ist, hilft Ihnen unser Kundenbüro gern weiter.","exko":"찾으시는 질문이 없으면 저희 고객 사무실에서 기꺼이 도와드립니다."}],"words":356},{"id":"b1-08","level":"B1","no":8,"title":"Anfrage: Ferienwohnung am Bodensee","titleKo":"문의: 보덴호 휴가용 숙소","type":"E-Mail-Wechsel","typeKo":"이메일 문의와 답장","intro":"휴가용 숙소를 빌리려는 사람의 문의 메일과 집주인의 답장이에요.","focus":["lassen + 동사원형","sich etwas … lassen","falls","종속절 끝의 동사 순서"],"paragraphs":[{"style":"meta","de":"Betreff: Anfrage Ferienwohnung „Seeblick“ – zwei Wochen im August","ko":"제목: 휴가용 숙소 „Seeblick“ 문의 – 8월 2주"},{"style":"meta","de":"Sehr geehrte Frau Mertens,","ko":"메르텐스 씨께,"},{"de":"auf Ihrer Internetseite habe ich die Ferienwohnung „Seeblick“ entdeckt, und die Fotos vom Balkon mit Blick auf den See haben uns sofort begeistert. Mein Mann und ich würden gern mit unseren beiden Kindern (8 und 11 Jahre) vierzehn Tage am Bodensee verbringen, am liebsten vom 9. bis zum 23. August. Ist die Wohnung in diesem Zeitraum noch frei?","ko":"인터넷 홈페이지에서 휴가용 숙소 „Seeblick“을 발견했는데, 호수가 보이는 발코니 사진을 보고 저희는 바로 반했어요. 남편과 저는 두 아이(8세, 11세)와 함께 보덴호에서 14일 동안 지내고 싶은데, 8월 9일부터 23일까지가 가장 좋아요. 이 기간에 숙소가 아직 비어 있나요?"},{"de":"Da wir einen kleinen, sehr ruhigen Hund haben, wüsste ich gern, ob wir ihn mitbringen dürfen. Für unsere geplanten Radtouren interessiert mich außerdem, ob es in der Nähe einen Fahrradverleih gibt oder ob man bei Ihnen Räder leihen kann. Falls wir mit dem Auto anreisen, bräuchten wir auch einen Parkplatz. Schließlich habe ich in einer Bewertung gelesen, dass man sich morgens frische Brötchen bringen lassen kann – gibt es diesen Service noch?","ko":"저희는 작고 아주 얌전한 개를 키우고 있어서, 개를 데려가도 되는지 알고 싶어요. 자전거 여행도 계획하고 있어서 근처에 자전거 대여점이 있는지, 아니면 댁에서 자전거를 빌릴 수 있는지도 궁금해요. 만약 차로 가게 되면 주차 자리도 필요할 것 같아요. 마지막으로, 아침마다 신선한 빵을 배달시켜 먹을 수 있다는 후기를 읽었는데, 이 서비스가 아직 있나요?"},{"de":"Über eine baldige Antwort würde ich mich sehr freuen.","ko":"빠른 답장 주시면 정말 감사하겠어요."},{"style":"meta","de":"Mit freundlichen Grüßen\nJana Schuster","ko":"안부를 전하며\n야나 슈스터 드림"},{"style":"meta","de":"Betreff: AW: Anfrage Ferienwohnung „Seeblick“ – zwei Wochen im August","ko":"제목: 회신: 휴가용 숙소 „Seeblick“ 문의 – 8월 2주"},{"style":"meta","de":"Liebe Frau Schuster,","ko":"슈스터 씨께,"},{"de":"vielen Dank für Ihre freundliche Anfrage. Sie haben Glück, denn die Wohnung ist ab dem 9. August frei, und ich reserviere sie Ihnen gern bis Freitag. Falls Sie sich bis dahin für die Wohnung entscheiden, schicke ich Ihnen den Mietvertrag per E-Mail, und mit der Anzahlung wird die Buchung verbindlich.","ko":"친절하게 문의해 주셔서 감사해요. 운이 좋으시네요. 숙소는 8월 9일부터 비어 있고, 금요일까지 기꺼이 예약해 둘게요. 그때까지 숙소를 쓰시기로 결정하시면 임대 계약서를 이메일로 보내 드릴게요. 계약금을 보내 주시면 예약이 확정돼요."},{"de":"Ihren Hund dürfen Sie selbstverständlich mitbringen, solange er nicht aufs Sofa und in die Betten darf. Im eingezäunten Garten können Sie ihn sogar frei laufen lassen. Vor jeder Ankunft lassen wir die Wohnung von einer Reinigungsfirma gründlich putzen, damit sich auch Allergiker wohlfühlen. Die Brötchen können Sie sich weiterhin bringen lassen – hängen Sie einfach abends den Bestellzettel an die Tür, dann hängt die Bäckerei die Tüte am nächsten Morgen bis acht Uhr daran.","ko":"개는 소파와 침대에 올라가지만 않으면 당연히 데려오셔도 돼요. 울타리가 쳐진 정원에서는 자유롭게 뛰어다니게 두셔도 돼요. 알레르기가 있는 분들도 편안하게 지내실 수 있도록, 손님이 도착하기 전에는 매번 청소 업체에 맡겨 숙소를 꼼꼼히 청소해요. 빵은 지금도 배달시키실 수 있어요. 저녁에 주문 쪽지를 문에 걸어 두시기만 하면 빵집에서 다음 날 아침 8시까지 거기에 빵 봉지를 걸어 놓아요."},{"de":"Für unsere Feriengäste stehen zwei Fahrräder kostenlos im Schuppen bereit, und Kinderräder bekommen Sie beim Verleih im Ort, der nur fünf Minuten entfernt ist. Einen eigenen Parkplatz direkt am Haus haben Sie natürlich auch. Die Schlüssel übergebe ich Ihnen am Anreisetag persönlich, oder ich lasse sie bei meiner Nachbarin, falls ich nicht zu Hause bin.","ko":"휴가 오신 손님들을 위해 창고에 자전거 두 대가 있고, 무료로 쓰실 수 있어요. 아이들 자전거는 5분 거리에 있는 마을 대여점에서 빌리실 수 있어요. 물론 집 바로 옆에 전용 주차 자리도 있어요. 열쇠는 도착하시는 날에 제가 직접 드릴게요. 혹시 제가 집에 없으면 이웃집 여자분에게 맡겨 둘게요."},{"style":"meta","de":"Herzliche Grüße vom Bodensee\nIhre Ursula Mertens","ko":"보덴호에서 따뜻한 안부를 전하며\n우르줄라 메르텐스 드림"}],"questions":[{"type":"rf","kind":"gist","q":"Frau Schuster möchte vor einer Buchung erst einige Einzelheiten klären.","answer":0,"evidence":"Ist die Wohnung in diesem Zeitraum noch frei?","pairs":[["Ist die Wohnung in diesem Zeitraum noch frei?","vor einer Buchung"],["wüsste ich gern, ob wir ihn mitbringen dürfen","einige Einzelheiten klären"]],"explain":"슈스터 씨는 아직 예약하지 않았어요. 먼저 숙소가 비어 있는지 묻고, 개, 자전거, 주차, 빵 배달에 대해 하나씩 물어봐요. 그러니 '예약하기 전에 몇 가지 세부 사항을 먼저 확인하고 싶어 한다'는 진술은 첫 메일 전체의 내용과 맞아요."},{"type":"mc","kind":"inference","q":"Was kann man aus Frau Schusters Frage nach einem Parkplatz schließen?","options":["Es steht noch nicht fest, ob die Familie mit dem Wagen fährt.","Sie will die eigenen Fahrräder im Auto an den See mitbringen.","Sie hat in einer Bewertung gelesen, dass am Haus kein Parkplatz ist."],"answer":0,"evidence":"Falls wir mit dem Auto anreisen, bräuchten wir auch einen Parkplatz.","pairs":[["Falls wir mit dem Auto anreisen","Es steht noch nicht fest, ob die Familie mit dem Wagen fährt"],["bräuchten wir auch einen Parkplatz","nach einem Parkplatz"]],"explain":"falls는 '만약 ~라면'이라는 뜻으로, 확실하지 않은 조건을 나타내요. '차로 가게 되면'이라고 했으니 아직 차로 갈지 정하지 않았다는 걸 알 수 있어요. 자전거는 빌릴 수 있는지 물었으니 자기 자전거를 가져간다는 말은 맞지 않아요. 후기에서 읽은 것은 빵 배달 이야기이고, 주차 자리가 없다는 말은 본문에 없어요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet die Aussage „ich reserviere sie Ihnen gern bis Freitag“?","options":["Die Familie darf die Wohnung nur bis Freitag nutzen und muss dann abreisen.","Bis Freitag hält die Vermieterin die Unterkunft für Familie Schuster frei.","Frau Mertens hat die Wohnung schon verbindlich an die Familie vermietet."],"answer":1,"evidence":"ich reserviere sie Ihnen gern bis Freitag","pairs":[["ich reserviere sie Ihnen gern bis Freitag","Bis Freitag hält die Vermieterin die Unterkunft für Familie Schuster frei"],["mit der Anzahlung wird die Buchung verbindlich","schon verbindlich an die Familie vermietet"]],"explain":"'금요일까지 예약해 두겠다'는 말은 그때까지 다른 손님에게 주지 않고 비워 두겠다는 뜻이에요. 바로 다음 문장에서 '결정하시면 계약서를 보내고, 계약금을 내면 예약이 확정된다'고 하니 아직 확정된 계약은 아니에요. 금요일은 숙박 기간이 아니라 예약을 잡아 두는 기한이에요."},{"type":"rf","kind":"detail","q":"Der Hund darf mitkommen, wenn er nicht auf Sitz- und Schlafmöbel springt.","answer":0,"evidence":"Ihren Hund dürfen Sie selbstverständlich mitbringen, solange er nicht aufs Sofa und in die Betten darf.","pairs":[["solange er nicht aufs Sofa und in die Betten darf","wenn er nicht auf Sitz- und Schlafmöbel springt"],["dürfen Sie selbstverständlich mitbringen","darf mitkommen"]],"explain":"개는 소파와 침대에 올라가지 않는다는 조건으로 데려와도 돼요. solange는 여기서 '~하는 한'이라는 조건의 뜻이에요. 소파와 침대를 'Sitz- und Schlafmöbel'(앉고 자는 가구)로 바꿔 말했으니 진술은 맞아요."},{"type":"mc","kind":"detail","q":"Was erfährt man über die Reinigung der Wohnung?","options":["Bevor neue Gäste eintreffen, putzt eine Firma die Räume.","Die Gäste putzen die Wohnung vor der Abreise selbst.","Frau Mertens putzt täglich selbst, weil Allergiker kommen."],"answer":0,"evidence":"Vor jeder Ankunft lassen wir die Wohnung von einer Reinigungsfirma gründlich putzen, damit sich auch Allergiker wohlfühlen.","pairs":[["lassen wir die Wohnung von einer Reinigungsfirma gründlich putzen","putzt eine Firma die Räume"],["Vor jeder Ankunft","Bevor neue Gäste eintreffen"]],"explain":"'Wir lassen die Wohnung … putzen'은 직접 청소하는 게 아니라 다른 사람에게 청소를 맡긴다는 뜻이에요. 여기서는 청소 업체(Reinigungsfirma)가 청소해요. 'Vor jeder Ankunft'(도착 전마다)를 '새 손님이 오기 전에'로 바꿔 말했어요. 손님이 직접 청소한다거나 메르텐스 씨가 매일 청소한다는 말은 없어요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Die Brötchen können Sie sich weiterhin bringen lassen“?","options":["Die Gäste müssen die Brötchen morgens selbst in der Bäckerei holen.","Die Gäste bekommen ihr Frühstücksgebäck nach wie vor geliefert.","Frau Mertens hängt den Gästen jeden Morgen eine Tüte an die Tür."],"answer":1,"evidence":"Die Brötchen können Sie sich weiterhin bringen lassen","pairs":[["weiterhin","nach wie vor"],["können Sie sich weiterhin bringen lassen","bekommen ihr Frühstücksgebäck nach wie vor geliefert"]],"explain":"'sich etwas bringen lassen'은 누군가에게 가져다 달라고 해서 받는다는 뜻이에요. 그래서 '아침 빵을 여전히 배달받는다'는 선지가 맞아요. weiterhin(계속해서)을 nach wie vor(여전히)로, Brötchen을 Frühstücksgebäck(아침용 빵)으로 바꿔 말했어요. 빵 봉지를 거는 것은 메르텐스 씨가 아니라 빵집이고, 손님이 직접 가지러 가지도 않아요."},{"type":"rf","kind":"detail","q":"Im Schuppen stehen Fahrräder für alle vier Familienmitglieder bereit.","answer":1,"evidence":"Für unsere Feriengäste stehen zwei Fahrräder kostenlos im Schuppen bereit, und Kinderräder bekommen Sie beim Verleih im Ort, der nur fünf Minuten entfernt ist.","pairs":[["zwei Fahrräder","für alle vier Familienmitglieder"],["Kinderräder bekommen Sie beim Verleih im Ort","Im Schuppen stehen Fahrräder"]],"explain":"창고에 있는 자전거는 두 대뿐이에요. 아이들 자전거는 마을의 대여점에서 빌려야 해요. 그러니 가족 네 명 모두를 위한 자전거가 창고에 있다는 말은 틀려요."},{"type":"mc","kind":"detail","q":"Wo bekommt die Familie die Schlüssel, wenn Frau Mertens bei der Ankunft nicht da ist?","options":["bei der Frau, die gleich im Haus nebenan wohnt","vorher zusammen mit dem Mietvertrag per Post","im Schuppen, wo auch die Fahrräder für Gäste stehen"],"answer":0,"evidence":"oder ich lasse sie bei meiner Nachbarin, falls ich nicht zu Hause bin","pairs":[["bei meiner Nachbarin","bei der Frau, die gleich im Haus nebenan wohnt"],["falls ich nicht zu Hause bin","wenn Frau Mertens bei der Ankunft nicht da ist"]],"explain":"'Nachbarin'(이웃 여자)을 '바로 옆집에 사는 여자'로 바꿔 말했어요. 메르텐스 씨가 집에 없으면 열쇠를 이웃에게 맡겨 둬요(ich lasse sie bei meiner Nachbarin). 계약서는 이메일로 보낸다고 했고, 창고에는 열쇠가 아니라 자전거가 있어요."}],"grammar":[{"title":"lassen + 동사원형 – 시키기와 허락하기","term":"lassen + Infinitiv (veranlassen / erlauben)","explain":"lassen + 동사원형에는 두 가지 뜻이 있어요. 첫째는 '어떤 일을 직접 하지 않고 다른 사람에게 시키다'예요. 'Wir lassen die Wohnung putzen.'은 우리가 청소하는 것이 아니라 다른 사람이 청소하게 한다는 뜻이에요. 그 일을 하는 사람은 von + 3격으로 나타낼 수 있어요(von einer Reinigungsfirma). 둘째는 '~하게 두다, 허락하다'예요. 'Sie können ihn frei laufen lassen.'은 개가 자유롭게 뛰어다니게 둬도 된다는 뜻이에요. lassen은 화법조동사처럼 zu 없는 동사원형과 함께 써요. 인칭에 맞게 변한 lassen은 2번 자리에 오고, 동사원형은 문장 끝에 와요.","pattern":"주어 + lassen + 목적어 … + 동사원형(끝)","examples":[{"de":"Vor jeder Ankunft lassen wir die Wohnung von einer Reinigungsfirma gründlich putzen, damit sich auch Allergiker wohlfühlen.","ko":"알레르기가 있는 분들도 편안하게 지내실 수 있도록, 손님이 도착하기 전에는 매번 청소 업체에 맡겨 숙소를 꼼꼼히 청소해요.","mark":["lassen","putzen"],"parts":[["Vor jeder Ankunft","부사어(시간)"],["lassen","동사"],["wir","주어"],["die Wohnung","4격 목적어"],["von einer Reinigungsfirma","부사어"],["gründlich","부사어(방법)"],["putzen,","동사(끝)"],["damit sich auch Allergiker wohlfühlen.","종속절"]]},{"de":"Im eingezäunten Garten können Sie ihn sogar frei laufen lassen.","ko":"울타리가 쳐진 정원에서는 자유롭게 뛰어다니게 두셔도 돼요.","mark":["laufen lassen"],"parts":[["Im eingezäunten Garten","부사어(장소)"],["können","동사"],["Sie","주어"],["ihn","4격 목적어"],["sogar","부사어"],["frei","부사어(방법)"],["laufen lassen.","동사(끝)"]]}],"tip":"'ich lasse sie bei meiner Nachbarin'처럼 동사원형 없이 쓰이면 '~를 (어디에) 두다, 맡기다'라는 일반 동사예요. 화법조동사와 함께 쓰면 'laufen lassen'처럼 동사원형 두 개가 문장 끝에 나란히 와요."},{"title":"sich etwas … lassen – 해 달라고 해서 받는 표현","term":"sich (Dativ) etwas machen lassen","explain":"sich(3격 재귀대명사) + 4격 목적어 + 동사원형 + lassen은 '자기를 위해 어떤 일을 해 달라고 하다, ~받다'라는 뜻이에요. 'Man lässt sich Brötchen bringen.'은 누군가에게 빵을 가져다 달라고 해서 받는다는 뜻이에요. 화법조동사와 함께 쓰면 동사원형 두 개가 문장 끝에 와요(bringen lassen). dass 절에서는 화법조동사가 그 뒤 맨 끝에 와요(bringen lassen kann).","pattern":"주어 + 화법조동사 + sich(3격) + 4격 목적어 … 동사원형 + lassen(끝)","examples":[{"de":"Die Brötchen können Sie sich weiterhin bringen lassen – hängen Sie einfach abends den Bestellzettel an die Tür, dann hängt die Bäckerei die Tüte am nächsten Morgen bis acht Uhr daran.","ko":"빵은 지금도 배달시키실 수 있어요. 저녁에 주문 쪽지를 문에 걸어 두시기만 하면 빵집에서 다음 날 아침 8시까지 거기에 빵 봉지를 걸어 놓아요.","mark":["sich","bringen lassen"],"parts":[["Die Brötchen","4격 목적어"],["können","동사"],["Sie","주어"],["sich","재귀대명사"],["weiterhin","부사어(시간)"],["bringen lassen","동사(끝)"],["– hängen Sie einfach abends den Bestellzettel an die Tür, dann hängt die Bäckerei die Tüte am nächsten Morgen bis acht Uhr daran.","기타"]]},{"de":"Schließlich habe ich in einer Bewertung gelesen, dass man sich morgens frische Brötchen bringen lassen kann – gibt es diesen Service noch?","ko":"마지막으로, 아침마다 신선한 빵을 배달시켜 먹을 수 있다는 후기를 읽었는데, 이 서비스가 아직 있나요?","mark":["sich","bringen lassen kann"]}],"tip":"자주 쓰는 예로 sich die Haare schneiden lassen(미용실에서 머리를 자르다), sich ein Taxi rufen lassen(택시를 불러 달라고 하다)이 있어요. 4격 목적어(Brötchen, die Haare)가 따로 있어서 재귀대명사는 3격이에요: mir, dir, sich, uns, euch, sich."},{"title":"falls: 확실하지 않은 조건을 말하는 종속접속사","term":"Konditionalsatz mit falls","explain":"falls는 '만약 ~라면, ~할 경우에'라는 뜻이에요. 조건을 말할 때는 wenn도 쓸 수 있지만, falls는 그 일이 일어날지 확실하지 않다는 점을 더 분명히 보여 줘요. 우리말 '혹시 ~하면'과 비슷해요. falls는 종속절을 이끌고, 동사는 종속절 끝에 와요. 종속절은 주절 앞이나 뒤에 올 수 있어요.","pattern":"Falls + 주어 … 동사(끝), 동사 + 주어 …  ·  주절, falls + 주어 … 동사(끝)","examples":[{"de":"Falls wir mit dem Auto anreisen, bräuchten wir auch einen Parkplatz.","ko":"만약 차로 가게 되면 주차 자리도 필요할 것 같아요.","mark":["Falls","anreisen"],"parts":[["Falls wir mit dem Auto anreisen,","종속절"],["bräuchten","동사"],["wir","주어"],["auch","부사어"],["einen Parkplatz.","4격 목적어"]]},{"de":"Falls Sie sich bis dahin für die Wohnung entscheiden, schicke ich Ihnen den Mietvertrag per E-Mail, und mit der Anzahlung wird die Buchung verbindlich.","ko":"그때까지 숙소를 쓰시기로 결정하시면 임대 계약서를 이메일로 보내 드릴게요. 계약금을 보내 주시면 예약이 확정돼요.","mark":["Falls","entscheiden"]},{"de":"Die Schlüssel übergebe ich Ihnen am Anreisetag persönlich, oder ich lasse sie bei meiner Nachbarin, falls ich nicht zu Hause bin.","ko":"열쇠는 도착하시는 날에 제가 직접 드릴게요. 혹시 제가 집에 없으면 이웃집 여자분에게 맡겨 둘게요.","mark":["falls","bin"]}],"tip":"wenn은 조건('~하면')과 시간('~할 때') 두 가지 뜻이 있지만, falls는 조건의 뜻만 있어요. 반복되는 일에는 falls를 쓰지 않아요. 예문의 bräuchten은 brauchen의 접속법 2식으로, 필요한 것을 조심스럽게 말해요. 개 이야기에 나오는 solange는 '~하는 한'이라는 뜻으로, 조건이 지켜지는 동안만 허락된다는 느낌을 줘요."},{"title":"종속절 끝에 동사가 여럿일 때: mitbringen dürfen · bringen lassen kann","term":"Verbstellung im Nebensatz mit Modalverb und lassen","explain":"ob, dass, weil이 이끄는 종속절에서는 인칭에 맞게 변한 동사가 맨 끝에 와요. 화법조동사가 있으면 동사원형이 먼저 오고 화법조동사가 마지막에 와요(ob wir ihn mitbringen dürfen). lassen까지 함께 쓰면 동사 세 개가 '본동사 원형 + lassen + 화법조동사' 순서로 끝에 모여요(dass man sich … bringen lassen kann). 분리동사는 종속절 끝에서 한 단어로 붙어요(mitbringen, anreisen).","pattern":"ob / dass + 주어 … 동사원형 + 화법조동사(끝)  ·  … 동사원형 + lassen + 화법조동사(끝)","examples":[{"de":"Da wir einen kleinen, sehr ruhigen Hund haben, wüsste ich gern, ob wir ihn mitbringen dürfen.","ko":"저희는 작고 아주 얌전한 개를 키우고 있어서, 개를 데려가도 되는지 알고 싶어요.","mark":["mitbringen dürfen"],"parts":[["Da wir einen kleinen, sehr ruhigen Hund haben,","종속절"],["wüsste","동사"],["ich","주어"],["gern,","부사어"],["ob","접속사"],["wir","주어"],["ihn","4격 목적어"],["mitbringen dürfen.","동사(끝)"]]},{"de":"Für unsere geplanten Radtouren interessiert mich außerdem, ob es in der Nähe einen Fahrradverleih gibt oder ob man bei Ihnen Räder leihen kann.","ko":"자전거 여행도 계획하고 있어서 근처에 자전거 대여점이 있는지, 아니면 댁에서 자전거를 빌릴 수 있는지도 궁금해요.","mark":["gibt","leihen kann"]}],"tip":"주절에서는 화법조동사가 2번 자리에 오고 동사원형이 끝에 와요(Wir dürfen ihn mitbringen). 종속절이 되면 화법조동사가 맨 끝으로 가요(…, ob wir ihn mitbringen dürfen). 이유를 나타내는 Da 종속절이 맨 앞에 오면 그 뒤 주절은 동사(wüsste)로 시작해요."}],"vocab":[{"de":"die Anfrage, -n","ko":"문의"},{"de":"die Ferienwohnung, -en","ko":"휴가용 숙소(아파트형)"},{"de":"verbringen (verbrachte, hat verbracht)","ko":"(시간을) 보내다"},{"de":"der Zeitraum, -¨e","ko":"기간"},{"de":"der Fahrradverleih, -e","ko":"자전거 대여점"},{"de":"an|reisen (reiste an, ist angereist)","ko":"(여행지에) 도착하다, 오다"},{"de":"die Bewertung, -en","ko":"(인터넷) 후기, 평가"},{"de":"reservieren","ko":"예약해 두다"},{"de":"sich entscheiden für + Akk. (entschied, hat entschieden)","ko":"~로 결정하다, ~을 선택하다"},{"de":"der Mietvertrag, -¨e","ko":"임대 계약서"},{"de":"die Anzahlung, -en","ko":"계약금, 선금"},{"de":"verbindlich","ko":"확정된, 구속력 있는"},{"de":"eingezäunt","ko":"울타리가 쳐진"},{"de":"die Reinigungsfirma, -firmen","ko":"청소 업체"},{"de":"der Bestellzettel, -","ko":"주문 쪽지"},{"de":"übergeben (übergibt, übergab, hat übergeben)","ko":"건네주다, 전달하다"}],"phrases":[{"de":"Glück haben","ko":"운이 좋다","ex":"Sie haben Glück, denn die Wohnung ist ab dem 9. August frei, und ich reserviere sie Ihnen gern bis Freitag.","exko":"운이 좋으시네요. 숙소는 8월 9일부터 비어 있고, 금요일까지 기꺼이 예약해 둘게요."},{"de":"sich über eine baldige Antwort freuen","ko":"빠른 답장을 기다리다 (편지 맺음말)","ex":"Über eine baldige Antwort würde ich mich sehr freuen.","exko":"빠른 답장 주시면 정말 감사하겠어요."},{"de":"mit Blick auf + Akk.","ko":"~이 보이는, ~ 전망의","ex":"auf Ihrer Internetseite habe ich die Ferienwohnung „Seeblick“ entdeckt, und die Fotos vom Balkon mit Blick auf den See haben uns sofort begeistert.","exko":"인터넷 홈페이지에서 휴가용 숙소 „Seeblick“을 발견했는데, 호수가 보이는 발코니 사진을 보고 저희는 바로 반했어요."},{"de":"jemandem etwas persönlich übergeben","ko":"~에게 ~을 직접 건네주다","ex":"Die Schlüssel übergebe ich Ihnen am Anreisetag persönlich, oder ich lasse sie bei meiner Nachbarin, falls ich nicht zu Hause bin.","exko":"열쇠는 도착하시는 날에 제가 직접 드릴게요. 혹시 제가 집에 없으면 이웃집 여자분에게 맡겨 둘게요."},{"de":"in der Nähe","ko":"근처에","ex":"Für unsere geplanten Radtouren interessiert mich außerdem, ob es in der Nähe einen Fahrradverleih gibt oder ob man bei Ihnen Räder leihen kann.","exko":"자전거 여행도 계획하고 있어서 근처에 자전거 대여점이 있는지, 아니면 댁에서 자전거를 빌릴 수 있는지도 궁금해요."}],"words":352},{"id":"b1-09","level":"B1","no":9,"title":"Warum ist Gähnen ansteckend?","titleKo":"하품은 왜 전염될까요?","type":"Populärwissenschaftlicher Artikel","typeKo":"대중 과학 기사","intro":"사람들이 왜 하품을 하고, 왜 남의 하품이 옮는지 설명하는 과학 기사예요.","focus":["je … desto","so … dass · sodass","추측 표현","비교급 강조"],"paragraphs":[{"de":"Ein Kollege gähnt in der Besprechung, und wenige Sekunden später gähnen wir automatisch mit – obwohl wir keineswegs müde sind. Dieses Phänomen kennt beinahe jeder aus dem eigenen Berufsalltag. Doch warum gähnen Menschen überhaupt, und weshalb wirkt das Gähnen anderer so ansteckend? Die Forschung sucht seit Jahrzehnten nach einer überzeugenden Erklärung.","ko":"회의 중에 동료 한 사람이 하품을 하면, 몇 초 뒤에 우리도 저절로 따라서 하품을 해요. 전혀 피곤하지 않은데도요. 거의 누구나 자기 직장 생활에서 겪어 본 현상이에요. 그런데 사람은 도대체 왜 하품을 하고, 다른 사람의 하품은 왜 이렇게 쉽게 옮을까요? 학계는 수십 년 전부터 설득력 있는 설명을 찾고 있어요."},{"style":"h","de":"Wer gähnt eigentlich?","ko":"누가 하품을 할까요?"},{"de":"Alle Menschen gähnen, sogar Babys im Mutterleib, wie Ultraschallaufnahmen beweisen. Auch bei zahlreichen Tierarten, von Fischen über Vögel bis zu Schimpansen, wurde dieses Verhalten beobachtet. Gähnen ist also ein ganz natürlicher Vorgang und vermutlich viel älter als die Menschheit.","ko":"모든 사람이 하품을 해요. 초음파 사진으로 확인되듯이 엄마 배 속의 아기도 하품을 해요. 물고기와 새부터 침팬지까지 많은 동물에게서도 이런 행동이 관찰되었어요. 그러니까 하품은 아주 자연스러운 현상이고, 아마 인류보다 훨씬 오래되었을 거예요."},{"style":"h","de":"Fehlt dem Gehirn Sauerstoff?","ko":"뇌에 산소가 부족한 걸까요?"},{"de":"Lange Zeit galt die Annahme, dass wir gähnen, weil dem Körper Sauerstoff fehlt, und dass der tiefe Atemzug dem Gehirn zusätzlichen Sauerstoff liefert. Diese Erklärung klingt zwar logisch, doch in Untersuchungen konnte sie nicht bestätigt werden. Heute vermuten Forscherinnen und Forscher unter anderem, dass Gähnen das Gehirn abkühlt, denn wahrscheinlich funktioniert es bei einer etwas niedrigeren Temperatur zuverlässiger. Bewiesen ist diese Theorie jedoch nicht, und vermutlich hat das Gähnen gleich mehrere Funktionen. Je genauer Fachleute hinsehen, desto mehr ungeklärte Fragen tauchen auf.","ko":"오랫동안 사람들은 몸에 산소가 부족해서 하품을 하고, 깊은 숨이 뇌에 산소를 더 공급해 준다고 생각했어요. 이 설명은 논리적으로 들리지만, 연구에서는 확인되지 않았어요. 오늘날 연구자들은 여러 가설 가운데 하나로, 하품이 뇌를 식혀 준다고 추측해요. 뇌는 온도가 조금 낮을 때 더 안정적으로 작동하는 것 같기 때문이에요. 하지만 이 이론은 증명되지 않았고, 아마 하품에는 여러 기능이 함께 있을 거예요. 전문가들이 자세히 들여다볼수록 풀리지 않은 질문이 더 많이 나와요."},{"style":"h","de":"Warum gähnen wir mit?","ko":"우리는 왜 따라서 하품을 할까요?"},{"de":"Noch rätselhafter ist das ansteckende Gähnen. Es genügt bereits, jemanden gähnen zu sehen oder zu hören, und bei manchen Menschen ist die Wirkung so stark, dass sie schon beim Lesen eines Zeitungsartikels über das Thema gähnen müssen. Es könnte sein, dass ansteckendes Gähnen mit Mitgefühl zusammenhängt. Dafür spricht eine Beobachtung aus mehreren Studien – je enger die Beziehung zu einer Person ist, desto eher gähnen wir mit. Bei Familienmitgliedern und engen Freunden geschieht das deutlich häufiger als bei Unbekannten.","ko":"더 수수께끼 같은 것은 전염되는 하품이에요. 누군가 하품하는 것을 보거나 듣기만 해도 충분해요. 어떤 사람들은 그 효과가 아주 강해서, 이 주제를 다룬 신문 기사를 읽기만 해도 하품이 나와요. 전염되는 하품은 공감 능력과 관계가 있을 수도 있어요. 여러 연구에서 나온 한 가지 관찰 결과가 이를 뒷받침해요. 어떤 사람과의 관계가 가까울수록 우리는 더 쉽게 따라서 하품을 해요. 가족이나 친한 친구가 하품할 때는 모르는 사람이 하품할 때보다 훨씬 더 자주 그래요."},{"style":"h","de":"Kleinkinder und Hunde","ko":"어린아이와 개"},{"de":"Kleinkinder werden dagegen kaum angesteckt. Die Fähigkeit entwickelt sich offenbar erst im Laufe der Kindheit, sodass die Kleinsten meistens unbeeindruckt bleiben, wenn jemand neben ihnen gähnt. Je älter die Kinder werden, umso häufiger gähnen sie mit. Bemerkenswert ist außerdem, dass auch Hunde gelegentlich mitgähnen, wenn ihre Besitzerinnen und Besitzer gähnen – ob aus Mitgefühl, weiß bislang niemand genau. Vollständig gelöst ist das Rätsel also noch nicht, doch eines ist ziemlich sicher – je länger Sie diesen Text lesen, desto größer wird die Wahrscheinlichkeit, dass Sie selbst gähnen müssen.","ko":"반면에 어린아이들은 거의 전염되지 않아요. 이 능력은 아무래도 어린 시절을 거치면서 비로소 발달하는 것 같아요. 그래서 가장 어린 아이들은 옆에서 누가 하품을 해도 대부분 아무렇지 않아요. 아이들은 나이가 들수록 더 자주 따라서 하품을 해요. 또 눈여겨볼 점은 개도 주인이 하품을 하면 가끔 따라서 하품을 한다는 거예요. 그것이 공감 때문인지는 아직 아무도 정확히 몰라요. 그러니까 수수께끼가 완전히 풀린 것은 아니지만, 한 가지는 꽤 확실해요. 이 글을 오래 읽을수록 여러분도 하품을 하게 될 가능성이 커져요."}],"questions":[{"type":"rf","kind":"detail","q":"Das Gähnen beginnt schon vor der Geburt.","answer":0,"evidence":"Alle Menschen gähnen, sogar Babys im Mutterleib, wie Ultraschallaufnahmen beweisen.","pairs":[["sogar Babys im Mutterleib","schon vor der Geburt"]],"explain":"'엄마 배 속의 아기도 하품을 한다(sogar Babys im Mutterleib)'를 '하품은 태어나기 전부터 시작된다'로 바꿔 말했어요. 초음파 사진으로 이것이 확인된다고 하니 진술은 맞아요."},{"type":"mc","kind":"detail","q":"Was sagt der Text über die Erklärung mit dem Sauerstoff?","options":["Sie wurde in mehreren Studien schon vor Jahren bestätigt.","Sie gilt heute als die wichtigste Erklärung für das Gähnen.","Wissenschaftliche Tests haben sie bis heute nicht belegt."],"answer":2,"evidence":"Diese Erklärung klingt zwar logisch, doch in Untersuchungen konnte sie nicht bestätigt werden.","pairs":[["in Untersuchungen konnte sie nicht bestätigt werden","Wissenschaftliche Tests haben sie bis heute nicht belegt"],["aus mehreren Studien","in mehreren Studien schon vor Jahren bestätigt"]],"explain":"본문은 산소 설명이 논리적으로 들리지만 연구에서 확인되지 않았다(konnte nicht bestätigt werden)고 해요. 이것을 '과학적인 실험으로 아직 입증되지 않았다'로 바꿔 말했어요. '여러 연구(mehreren Studien)'라는 말은 본문에서 공감과 하품의 관계를 이야기할 때 나와요. 오늘날에는 하품이 뇌를 식힌다는 가설 등이 나와 있으니, 산소 설명이 가장 중요한 설명이라는 말도 틀려요."},{"type":"mc","kind":"paraphrase","q":"Was will der Text mit dem Satz „Bewiesen ist diese Theorie jedoch nicht, und vermutlich hat das Gähnen gleich mehrere Funktionen.“ sagen?","options":["Die Kühlung des Gehirns ist inzwischen bewiesen, doch es gibt weitere Gründe.","Die Kühlung ist nicht gesichert, und Gähnen dient wohl verschiedenen Zwecken.","Niemand weiß, wozu Gähnen dient, deshalb gibt es auch keine einzige Theorie."],"answer":1,"evidence":"Bewiesen ist diese Theorie jedoch nicht, und vermutlich hat das Gähnen gleich mehrere Funktionen.","pairs":[["Bewiesen ist diese Theorie jedoch nicht","Die Kühlung ist nicht gesichert"],["vermutlich hat das Gähnen gleich mehrere Funktionen","Gähnen dient wohl verschiedenen Zwecken"]],"explain":"'diese Theorie'는 바로 앞 문장의 '하품이 뇌를 식힌다'는 가설을 가리켜요. 이 가설은 증명되지 않았으니 아직 추측일 뿐이에요. 'vermutlich … mehrere Funktionen'은 하품에 아마 여러 기능이 있다는 뜻이에요. 뇌 냉각이 이미 증명되었다는 말도, 하품에 관한 이론이 하나도 없다는 말도 본문과 맞지 않아요."},{"type":"rf","kind":"detail","q":"Man muss eine gähnende Person sehen, damit man selbst mitgähnt.","answer":1,"evidence":"Es genügt bereits, jemanden gähnen zu sehen oder zu hören, und bei manchen Menschen ist die Wirkung so stark, dass sie schon beim Lesen eines Zeitungsartikels über das Thema gähnen müssen.","pairs":[["jemanden gähnen zu sehen oder zu hören","Man muss eine gähnende Person sehen"],["schon beim Lesen eines Zeitungsartikels über das Thema","damit man selbst mitgähnt"]],"explain":"본문은 누군가 하품하는 것을 보거나 듣기만 해도(sehen oder hören) 충분하다고 해요. 어떤 사람은 하품에 관한 기사를 읽기만 해도 하품을 해요. 그러니 꼭 하품하는 사람을 봐야 따라 한다는 진술은 틀려요."},{"type":"mc","kind":"detail","q":"Bei wem gähnen wir am ehesten mit?","options":["bei Unbekannten, denen wir zum ersten Mal begegnen","bei Kollegen, die in Besprechungen sehr müde sind","bei Menschen, die uns persönlich nahestehen"],"answer":2,"evidence":"Dafür spricht eine Beobachtung aus mehreren Studien – je enger die Beziehung zu einer Person ist, desto eher gähnen wir mit.","pairs":[["je enger die Beziehung zu einer Person ist","die uns persönlich nahestehen"],["Bei Familienmitgliedern und engen Freunden","bei Menschen, die uns persönlich nahestehen"]],"explain":"어떤 사람과의 관계가 가까울수록 더 쉽게 따라 하품을 해요(je enger …, desto eher …). 가족이나 친한 친구에게서는 모르는 사람보다 훨씬 자주 일어나요. 이것을 '우리와 개인적으로 가까운 사람'으로 바꿔 말했어요. 회의 중에 하품하는 동료는 첫 문단의 예일 뿐이고, 전염되는 하품은 피곤함과 관계가 없어요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Kleinkinder werden dagegen kaum angesteckt.“?","options":["Wer noch sehr klein ist, macht das Gähnen anderer selten nach.","Kleinkinder werden durch das Gähnen anderer besonders schnell müde.","Kleinkinder gähnen seltener, weil sie weniger müde sind."],"answer":0,"evidence":"Kleinkinder werden dagegen kaum angesteckt.","pairs":[["kaum angesteckt","macht das Gähnen anderer selten nach"],["Kleinkinder","Wer noch sehr klein ist"]],"explain":"'angesteckt werden'은 '(다른 사람의 하품이) 옮다'라는 뜻이고, kaum은 '거의 ~하지 않다'라는 뜻이에요. 그래서 어린아이들은 다른 사람이 하품해도 거의 따라 하지 않는다는 뜻이에요. 피곤함은 이 문장과 관계가 없어요. 본문은 첫 문단부터 전염되는 하품이 피곤함과 상관없다고 해요."},{"type":"rf","kind":"inference","q":"Ältere Kinder reagieren stärker auf das Gähnen anderer als jüngere.","answer":0,"evidence":"Je älter die Kinder werden, umso häufiger gähnen sie mit.","pairs":[["Je älter die Kinder werden, umso häufiger gähnen sie mit","Ältere Kinder reagieren stärker auf das Gähnen anderer als jüngere"],["Kleinkinder werden dagegen kaum angesteckt","als jüngere"]],"explain":"'아이들은 나이가 들수록 더 자주 따라 하품을 한다(je älter …, umso häufiger …)'고 했어요. 또 어린아이는 거의 전염되지 않는다고 했어요. 이 두 문장을 합치면, 나이가 많은 아이가 어린아이보다 다른 사람의 하품에 더 강하게 반응한다는 진술은 맞아요."},{"type":"mc","kind":"intent","q":"Warum spricht der Text die Leserinnen und Leser im letzten Satz direkt an?","options":["Er will im Spaß sagen, dass schon dieser Text Gähnen auslösen kann.","Er will zeigen, dass lange Texte die Leserinnen und Leser müde machen.","Er will betonen, dass das Rätsel inzwischen vollständig gelöst ist."],"answer":0,"evidence":"doch eines ist ziemlich sicher – je länger Sie diesen Text lesen, desto größer wird die Wahrscheinlichkeit, dass Sie selbst gähnen müssen","pairs":[["je länger Sie diesen Text lesen, desto größer wird die Wahrscheinlichkeit, dass Sie selbst gähnen müssen","schon dieser Text Gähnen auslösen kann"],["Vollständig gelöst ist das Rätsel also noch nicht","das Rätsel inzwischen vollständig gelöst ist"]],"explain":"마지막 문장은 '이 글을 오래 읽을수록 여러분도 하품을 하게 될 가능성이 커진다'고 독자에게 직접 말해요. 앞에서 하품에 관한 기사를 읽기만 해도 하품하는 사람이 있다고 했으니, 이 말은 '하품에 관한 이 글을 읽기만 해도 하품이 날 수 있다'는 농담이에요(im Spaß sagen). 첫 문단에서 전염되는 하품은 피곤함과 상관없다고 했으니 긴 글이 사람을 피곤하게 만든다는 뜻이 아니에요. 수수께끼는 아직 완전히 풀리지 않았다고 했어요."}],"grammar":[{"title":"je … desto / umso – 비례 관계","term":"Proportionalsatz: je … desto / umso","explain":"je + 비교급 …, desto(umso) + 비교급 …은 '~할수록 더 ~하다'라는 뜻이에요. 앞부분(je)은 종속절이라서 동사가 끝에 와요. 뒷부분(desto/umso)은 주절이에요. desto나 umso 바로 뒤에 비교급이 오고, 그다음에 동사가 와요. desto와 umso는 뜻이 같아요.","pattern":"Je + 비교급 … 동사(끝), desto/umso + 비교급 + 동사 + …","examples":[{"de":"Je genauer Fachleute hinsehen, desto mehr ungeklärte Fragen tauchen auf.","ko":"전문가들이 자세히 들여다볼수록 풀리지 않은 질문이 더 많이 나와요.","mark":["Je genauer","desto mehr"],"parts":[["Je genauer Fachleute hinsehen,","종속절"],["desto mehr ungeklärte Fragen","주어"],["tauchen","동사"],["auf.","동사(끝)"]]},{"de":"Je älter die Kinder werden, umso häufiger gähnen sie mit.","ko":"아이들은 나이가 들수록 더 자주 따라서 하품을 해요.","mark":["Je älter","umso häufiger"],"parts":[["Je älter die Kinder werden,","종속절"],["umso häufiger","부사어(빈도)"],["gähnen","동사"],["sie","주어"],["mit.","동사(끝)"]]},{"de":"Dafür spricht eine Beobachtung aus mehreren Studien – je enger die Beziehung zu einer Person ist, desto eher gähnen wir mit.","ko":"여러 연구에서 나온 한 가지 관찰 결과가 이를 뒷받침해요. 어떤 사람과의 관계가 가까울수록 우리는 더 쉽게 따라서 하품을 해요.","mark":["je enger","desto eher"]}],"tip":"desto 뒤에는 '비교급 + 동사' 순서로 와요(desto eher gähnen wir mit). 'desto wir eher gähnen'처럼 쓰면 틀려요. desto 뒤의 비교급이 명사와 함께 쓰이면 그 명사까지 한 덩어리로 앞에 와요(desto mehr ungeklärte Fragen tauchen auf)."},{"title":"so … dass / sodass – 결과 말하기","term":"Konsekutivsatz: so … dass / sodass","explain":"so + 형용사 …, dass …는 '너무 ~해서 …하다'라는 뜻이에요. so가 정도를 강조하고, dass절이 그 결과를 말해요. sodass는 앞 문장 전체의 결과를 말할 때 써요. 우리말 '그래서, 그 결과'와 비슷해요. 두 경우 모두 dass절과 sodass절의 동사는 끝에 와요.","pattern":"… so + 형용사 …, dass + 주어 … 동사(끝)  ·  …, sodass + 주어 … 동사(끝)","examples":[{"de":"Die Fähigkeit entwickelt sich offenbar erst im Laufe der Kindheit, sodass die Kleinsten meistens unbeeindruckt bleiben, wenn jemand neben ihnen gähnt.","ko":"이 능력은 아무래도 어린 시절을 거치면서 비로소 발달하는 것 같아요. 그래서 가장 어린 아이들은 옆에서 누가 하품을 해도 대부분 아무렇지 않아요.","mark":["sodass","bleiben"],"parts":[["Die Fähigkeit","주어"],["entwickelt","동사"],["sich","재귀대명사"],["offenbar","부사어"],["erst im Laufe der Kindheit,","부사어(시간)"],["sodass die Kleinsten meistens unbeeindruckt bleiben, wenn jemand neben ihnen gähnt.","종속절"]]},{"de":"Es genügt bereits, jemanden gähnen zu sehen oder zu hören, und bei manchen Menschen ist die Wirkung so stark, dass sie schon beim Lesen eines Zeitungsartikels über das Thema gähnen müssen.","ko":"누군가 하품하는 것을 보거나 듣기만 해도 충분해요. 어떤 사람들은 그 효과가 아주 강해서, 이 주제를 다룬 신문 기사를 읽기만 해도 하품이 나와요.","mark":["so stark","dass"]}],"tip":"so … dass에서 so는 형용사 바로 앞에 와요(so stark). 목적을 나타내는 damit(~하도록)과 헷갈리지 마세요. sodass는 이미 생긴 결과를 말하고, damit은 원하는 목적을 말해요."},{"title":"추측 표현 – vermutlich · wahrscheinlich · offenbar · es könnte sein, dass","term":"Vermutungen ausdrücken","explain":"과학 기사에서는 확실하지 않은 내용을 조심스럽게 말할 때가 많아요. vermutlich와 wahrscheinlich는 '아마'라는 뜻으로, 그럴 가능성이 높다고 생각할 때 써요. offenbar는 '보아하니, ~인 것 같다'라는 뜻으로, 관찰한 사실에 근거한 추측이에요. 'Es könnte sein, dass …'는 '~일 수도 있다'라는 뜻으로 가능성을 더 조심스럽게 말해요. 동사 vermuten(추측하다)으로도 추측을 나타낼 수 있어요.","pattern":"vermutlich / wahrscheinlich / offenbar + 평서문  ·  Es könnte sein, dass + 주어 … 동사(끝)","examples":[{"de":"Es könnte sein, dass ansteckendes Gähnen mit Mitgefühl zusammenhängt.","ko":"전염되는 하품은 공감 능력과 관계가 있을 수도 있어요.","mark":["Es könnte sein, dass"],"parts":[["Es","주어"],["könnte","동사"],["sein,","동사(끝)"],["dass ansteckendes Gähnen mit Mitgefühl zusammenhängt.","종속절"]]},{"de":"Bewiesen ist diese Theorie jedoch nicht, und vermutlich hat das Gähnen gleich mehrere Funktionen.","ko":"하지만 이 이론은 증명되지 않았고, 아마 하품에는 여러 기능이 함께 있을 거예요.","mark":["vermutlich"]},{"de":"Heute vermuten Forscherinnen und Forscher unter anderem, dass Gähnen das Gehirn abkühlt, denn wahrscheinlich funktioniert es bei einer etwas niedrigeren Temperatur zuverlässiger.","ko":"오늘날 연구자들은 여러 가설 가운데 하나로, 하품이 뇌를 식혀 준다고 추측해요. 뇌는 온도가 조금 낮을 때 더 안정적으로 작동하는 것 같기 때문이에요.","mark":["vermuten","wahrscheinlich"]}],"tip":"vermutlich나 wahrscheinlich가 문장 맨 앞에 오면 동사가 바로 뒤에 와요(Wahrscheinlich funktioniert es …). denn 뒤에서는 어순이 바뀌지 않아요(denn wahrscheinlich funktioniert es …). 확신의 정도는 대략 'Es könnte sein'(가능성이 있음) < vermutlich, wahrscheinlich(아마) < sicher(확실히) 순서예요."},{"title":"비교급을 강조하는 말: noch · viel · deutlich + 비교급","term":"Verstärkung des Komparativs: noch, viel, deutlich","explain":"비교급 앞에 noch, viel, deutlich를 붙이면 차이를 강조할 수 있어요. viel과 deutlich는 '훨씬'이라는 뜻으로, 차이가 크다는 것을 보여 줘요(viel älter als, deutlich häufiger als). noch는 '더욱, 한층 더'라는 뜻으로, 앞에서 말한 것도 이미 그런데 이것은 그보다 더하다는 느낌을 줘요(Noch rätselhafter ist …). 비교 대상은 als로 나타내요.","pattern":"noch / viel / deutlich + 비교급 (+ als …)","examples":[{"de":"Noch rätselhafter ist das ansteckende Gähnen.","ko":"더 수수께끼 같은 것은 전염되는 하품이에요.","mark":["Noch rätselhafter"],"parts":[["Noch rätselhafter","보어"],["ist","동사"],["das ansteckende Gähnen.","주어"]]},{"de":"Gähnen ist also ein ganz natürlicher Vorgang und vermutlich viel älter als die Menschheit.","ko":"그러니까 하품은 아주 자연스러운 현상이고, 아마 인류보다 훨씬 오래되었을 거예요.","mark":["viel älter als"]},{"de":"Bei Familienmitgliedern und engen Freunden geschieht das deutlich häufiger als bei Unbekannten.","ko":"가족이나 친한 친구가 하품할 때는 모르는 사람이 하품할 때보다 훨씬 더 자주 그래요.","mark":["deutlich häufiger als"]}],"tip":"비교급을 강조할 때는 sehr를 쓰지 않아요(× sehr älter). 'immer + 비교급'은 '점점 더'라는 뜻이에요(immer häufiger). 비교급 앞의 noch는 '아직'이 아니라 '더욱'이라는 뜻이에요."}],"vocab":[{"de":"gähnen","ko":"하품하다"},{"de":"ansteckend","ko":"전염되는, 옮는"},{"de":"an|stecken","ko":"전염시키다, 옮기다 (angesteckt werden: 옮다)"},{"de":"die Besprechung, -en","ko":"회의"},{"de":"das Phänomen, -e","ko":"현상"},{"de":"der Mutterleib (Sg.)","ko":"엄마 배 속, 태내"},{"de":"die Annahme, -n","ko":"가정, 추측"},{"de":"der Sauerstoff (Sg.)","ko":"산소"},{"de":"der Atemzug, -¨e","ko":"숨, 한 번의 호흡"},{"de":"bestätigen","ko":"확인하다, 사실로 입증하다"},{"de":"ab|kühlen","ko":"식히다, 온도를 낮추다"},{"de":"rätselhaft","ko":"수수께끼 같은, 알 수 없는"},{"de":"das Mitgefühl (Sg.)","ko":"공감, 함께 느끼는 마음"},{"de":"zusammen|hängen mit + Dat. (hing zusammen, hat zusammengehangen)","ko":"~와 관계가 있다"},{"de":"die Fähigkeit, -en","ko":"능력"},{"de":"unbeeindruckt","ko":"아무 영향을 받지 않은, 아무렇지 않은"}],"phrases":[{"de":"für etwas sprechen","ko":"~을 뒷받침하다, ~의 근거가 되다","ex":"Dafür spricht eine Beobachtung aus mehreren Studien – je enger die Beziehung zu einer Person ist, desto eher gähnen wir mit.","exko":"여러 연구에서 나온 한 가지 관찰 결과가 이를 뒷받침해요. 어떤 사람과의 관계가 가까울수록 우리는 더 쉽게 따라서 하품을 해요."},{"de":"im Laufe + Gen.","ko":"~하는 동안에, ~을 거치면서","ex":"Die Fähigkeit entwickelt sich offenbar erst im Laufe der Kindheit, sodass die Kleinsten meistens unbeeindruckt bleiben, wenn jemand neben ihnen gähnt.","exko":"이 능력은 아무래도 어린 시절을 거치면서 비로소 발달하는 것 같아요. 그래서 가장 어린 아이들은 옆에서 누가 하품을 해도 대부분 아무렇지 않아요."},{"de":"unter anderem","ko":"그 밖에도, 여러 가지 가운데","ex":"Heute vermuten Forscherinnen und Forscher unter anderem, dass Gähnen das Gehirn abkühlt, denn wahrscheinlich funktioniert es bei einer etwas niedrigeren Temperatur zuverlässiger.","exko":"오늘날 연구자들은 여러 가설 가운데 하나로, 하품이 뇌를 식혀 준다고 추측해요. 뇌는 온도가 조금 낮을 때 더 안정적으로 작동하는 것 같기 때문이에요."},{"de":"ein Rätsel lösen","ko":"수수께끼를 풀다","ex":"Vollständig gelöst ist das Rätsel also noch nicht, doch eines ist ziemlich sicher – je länger Sie diesen Text lesen, desto größer wird die Wahrscheinlichkeit, dass Sie selbst gähnen müssen.","exko":"그러니까 수수께끼가 완전히 풀린 것은 아니지만, 한 가지는 꽤 확실해요. 이 글을 오래 읽을수록 여러분도 하품을 하게 될 가능성이 커져요."},{"de":"es genügt, … zu + Inf.","ko":"~하는 것만으로 충분하다","ex":"Es genügt bereits, jemanden gähnen zu sehen oder zu hören, und bei manchen Menschen ist die Wirkung so stark, dass sie schon beim Lesen eines Zeitungsartikels über das Thema gähnen müssen.","exko":"누군가 하품하는 것을 보거나 듣기만 해도 충분해요. 어떤 사람들은 그 효과가 아주 강해서, 이 주제를 다룬 신문 기사를 읽기만 해도 하품이 나와요."}],"words":349},{"id":"b1-10","level":"B1","no":10,"title":"Sieben Tage ohne Smartphone","titleKo":"스마트폰 없이 7일","type":"Blogbeitrag","typeKo":"블로그 글 (자기 실험)","intro":"일주일 동안 스마트폰 없이 지내 본 사람이 쓴 블로그 글이에요.","focus":["접속법 2식 과거","ohne/mit + 명사","분사의 형용사 용법","irgend-"],"paragraphs":[{"label":"Lea Brandt","de":"Letzten Monat habe ich mein Smartphone für eine Woche in eine Schublade gelegt – nicht ausgeschaltet, sondern weggeschlossen, und den Schlüssel hatte meine Mitbewohnerin. Ich wollte herausfinden, wie abhängig ich wirklich bin.","ko":"지난달에 저는 스마트폰을 일주일 동안 서랍에 넣어 두었어요. 끈 게 아니라 아예 잠가 두었고, 열쇠는 룸메이트가 가지고 있었어요. 제가 정말 얼마나 휴대폰에 의존하고 있는지 알아보고 싶었거든요."},{"style":"h","de":"Tag 1 – Der fehlende Wecker","ko":"1일째 – 알람 없는 아침"},{"de":"Am ersten Morgen bin ich erst um Viertel vor neun aufgewacht, weil mich ohne das klingelnde Handy niemand geweckt hatte. Wenn die S-Bahn pünktlich gewesen wäre, hätte ich meinen Termin um neun verpasst. Zum Glück hatte sie fünf Minuten Verspätung. Noch am selben Abend habe ich mir irgendwo einen altmodischen Wecker gekauft.","ko":"첫날 아침에는 8시 45분에야 잠에서 깼어요. 울리는 휴대폰이 없으니 아무도 저를 깨워 주지 않았거든요. 전철이 제시간에 왔다면 9시 약속을 놓쳤을 거예요. 다행히 전철이 5분 늦게 왔어요. 그날 저녁에 바로 어딘가에서 구식 자명종을 하나 샀어요."},{"style":"h","de":"Tag 2 – Verlaufen mit Papier","ko":"2일째 – 종이 지도로 길 찾기"},{"de":"Eine Freundin hatte mich in ein neues Café eingeladen, irgendwo im Norden der Stadt. Mit einem gefalteten Stadtplan in der Hand stand ich an einer Kreuzung und drehte das Papier dreimal hin und her. Dann lief ich natürlich in die falsche Richtung. Ohne die Hilfe einer älteren Dame hätte ich das Café wahrscheinlich nie gefunden. Ich kam eine halbe Stunde zu spät, aber meine Freundin lachte nur.","ko":"친구가 저를 시내 북쪽 어딘가에 새로 생긴 카페에 초대했어요. 접힌 시내 지도를 손에 들고 사거리에 서서 종이를 세 번이나 이리저리 돌렸어요. 그러고는 당연히 반대 방향으로 걸어갔지요. 어느 나이 지긋한 부인의 도움이 없었다면 아마 그 카페를 끝내 찾지 못했을 거예요. 30분 늦게 도착했지만 친구는 그냥 웃기만 했어요."},{"style":"h","de":"Tag 4 – Die wiederentdeckte Langeweile","ko":"4일째 – 다시 발견한 지루함"},{"de":"Am vierten Tag ist etwas Seltsames passiert: Ich habe mich gelangweilt – an der Bushaltestelle, in der Mittagspause und abends auf dem Sofa. Früher hätte ich in solchen Momenten einfach irgendetwas auf dem Bildschirm gelesen. Stattdessen habe ich einen Krimi angefangen und an einem einzigen Abend hundert Seiten geschafft. Zuletzt hatte ich das irgendwann vor Jahren gemacht, glaube ich.","ko":"4일째에는 이상한 일이 일어났어요. 지루해진 거예요. 버스 정류장에서도, 점심시간에도, 저녁에 소파에서도요. 예전 같으면 그런 순간에 그냥 화면에서 아무거나 읽었을 거예요. 대신 추리 소설을 한 권 시작했고, 단 하루 저녁 만에 100쪽을 읽었어요. 마지막으로 그렇게 한 건 아마 몇 년 전 언젠가였을 거예요."},{"style":"h","de":"Tag 6 – Die verpasste Nachricht","ko":"6일째 – 놓친 메시지"},{"de":"Für Samstagabend war ich mit drei Leuten verabredet, und ohne Gruppenchat musste ich jeden einzeln vom Festnetz aus anrufen. Zwei habe ich erreicht, der dritte ging nicht ans Telefon. Irgendjemand hatte den Treffpunkt kurzfristig geändert, doch die Nachricht lag natürlich auf meinem eingeschlossenen Handy. So wartete ich eine halbe Stunde vor dem falschen Lokal. Mit dem Smartphone wäre das nicht passiert.","ko":"토요일 저녁에 세 사람과 만나기로 되어 있었어요. 단체 채팅방이 없으니 유선 전화로 한 명씩 전화를 걸어야 했어요. 두 명과는 연락이 됐지만 세 번째 사람은 전화를 받지 않았어요. 누군가가 약속 장소를 급하게 바꿨는데, 그 메시지는 당연히 잠가 둔 제 휴대폰에 와 있었어요. 그래서 저는 엉뚱한 식당 앞에서 30분을 기다렸어요. 스마트폰이 있었다면 그런 일은 없었을 거예요."},{"style":"h","de":"Mein Fazit","ko":"결론"},{"de":"Wenn ich den Selbstversuch nicht gemacht hätte, wüsste ich bis heute nicht, wie oft ich aus reiner Gewohnheit zum Handy greife. Ganz ohne Smartphone möchte ich trotzdem nicht leben, dafür ist es zu praktisch. Aber ich habe mir vorgenommen, es bewusster zu nutzen. Der Wecker bleibt, der angefangene Krimi wird zu Ende gelesen, und abends liegt das Handy wieder in der Schublade – diesmal allerdings ohne Schlüssel.","ko":"이 실험을 하지 않았다면 제가 순전히 습관 때문에 얼마나 자주 휴대폰에 손을 뻗는지 지금도 몰랐을 거예요. 그래도 스마트폰 없이 아예 살고 싶지는 않아요. 그러기에는 너무 편리하거든요. 하지만 더 의식적으로 쓰기로 마음먹었어요. 자명종은 계속 쓰고, 읽기 시작한 추리 소설은 끝까지 읽고, 저녁에는 휴대폰을 다시 서랍에 넣어 둬요. 다만 이번에는 열쇠 없이요."}],"questions":[{"type":"rf","kind":"inference","q":"Während des Experiments konnte die Autorin ihr Handy selbst nicht benutzen.","answer":0,"evidence":"nicht ausgeschaltet, sondern weggeschlossen, und den Schlüssel hatte meine Mitbewohnerin","pairs":[["weggeschlossen, und den Schlüssel hatte meine Mitbewohnerin","konnte die Autorin ihr Handy selbst nicht benutzen"],["für eine Woche","Während des Experiments"]],"explain":"필자는 휴대폰을 그냥 끈 것이 아니라 서랍에 잠가 두었고(weggeschlossen), 열쇠는 룸메이트가 가지고 있었어요. 그러니 실험하는 동안 필자는 스스로 휴대폰을 꺼내 쓸 수 없었어요. 6일째에 메시지가 '잠가 둔 휴대폰'에 와 있었다는 내용도 이와 맞아요."},{"type":"mc","kind":"detail","q":"Warum hat die Autorin das Experiment gemacht?","options":["Sie wollte prüfen, wie sehr sie auf ihr Handy angewiesen ist.","Ihre Mitbewohnerin hatte sie zu dem Experiment überredet.","Sie wollte in dieser Woche endlich einen Krimi zu Ende lesen."],"answer":0,"evidence":"Ich wollte herausfinden, wie abhängig ich wirklich bin.","pairs":[["wie abhängig ich wirklich bin","wie sehr sie auf ihr Handy angewiesen ist"],["Ich wollte herausfinden","Sie wollte prüfen"]],"explain":"필자는 자기가 정말 얼마나 휴대폰에 의존하는지(wie abhängig ich wirklich bin) 알고 싶었다고 해요. 'abhängig sein'을 'auf etwas angewiesen sein'(~에 기대다)으로 바꿔 말했어요. 룸메이트는 열쇠를 맡았을 뿐이고, 실험은 필자가 스스로 알아보고 싶어서 한 거예요. 추리 소설은 4일째에 지루해서 읽기 시작한 거예요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Wenn die S-Bahn pünktlich gewesen wäre, hätte ich meinen Termin um neun verpasst.“?","options":["Weil die S-Bahn Verspätung hatte, kam die Autorin zu spät zu ihrem Termin.","Gerade weil sich die S-Bahn verspätet hat, war die Autorin rechtzeitig da.","Die S-Bahn fuhr pünktlich ab, aber die Autorin hat sie gerade noch erreicht."],"answer":1,"evidence":"Wenn die S-Bahn pünktlich gewesen wäre, hätte ich meinen Termin um neun verpasst.","pairs":[["Wenn die S-Bahn pünktlich gewesen wäre","Gerade weil sich die S-Bahn verspätet hat"],["hätte ich meinen Termin um neun verpasst","war die Autorin rechtzeitig da"]],"explain":"접속법 2식 과거는 실제로 일어나지 않은 일을 말해요. '전철이 제시간에 왔다면 약속을 놓쳤을 것이다'는 실제로는 전철이 늦게 왔고, 그 덕분에 약속에 늦지 않았다는 뜻이에요. 다음 문장의 '다행히 전철이 5분 늦었다'도 이것을 보여 줘요. 그러니 약속에 늦었다는 말도, 전철이 제시간에 떠났다는 말도 틀려요."},{"type":"mc","kind":"detail","q":"Wie hat die Autorin am zweiten Tag das Café schließlich gefunden?","options":["Sie hat den Stadtplan schließlich richtig gelesen.","Ihre Freundin hat sie an der Kreuzung abgeholt.","Eine unbekannte Frau hat ihr den Weg gezeigt."],"answer":2,"evidence":"Ohne die Hilfe einer älteren Dame hätte ich das Café wahrscheinlich nie gefunden.","pairs":[["Ohne die Hilfe einer älteren Dame","Eine unbekannte Frau hat ihr den Weg gezeigt"],["drehte das Papier dreimal hin und her","den Stadtplan schließlich richtig gelesen"]],"explain":"'Ohne die Hilfe einer älteren Dame hätte ich das Café nie gefunden'은 실제로는 한 나이 든 부인이 도와줘서 카페를 찾았다는 뜻이에요. 이것을 '모르는 여자가 길을 알려 줬다'로 바꿔 말했어요. 지도는 이리저리 돌리다가 반대 방향으로 갔고, 친구는 카페에서 기다리다가 웃기만 했어요."},{"type":"rf","kind":"detail","q":"Dass sie sich am vierten Tag langweilte, fand die Autorin ganz normal.","answer":1,"evidence":"Am vierten Tag ist etwas Seltsames passiert: Ich habe mich gelangweilt","pairs":[["etwas Seltsames","ganz normal"],["Ich habe mich gelangweilt","Dass sie sich am vierten Tag langweilte"]],"explain":"필자는 4일째에 지루해진 것을 '이상한 일(etwas Seltsames)'이라고 불러요. 예전에는 지루할 틈도 없이 휴대폰을 봤기 때문이에요. 그러니 지루함을 아주 평범하게 느꼈다는 진술은 틀려요."},{"type":"mc","kind":"paraphrase","q":"Was will die Autorin mit dem Satz „Früher hätte ich in solchen Momenten einfach irgendetwas auf dem Bildschirm gelesen.“ sagen?","options":["Früher hat sie auf dem Handy nur wichtige Texte für die Arbeit gelesen.","Sie hätte in dieser Woche gern etwas am Bildschirm gelesen, durfte aber nicht.","Vor ihrem Versuch hat sie sich bei Langeweile meist mit dem Handy beschäftigt."],"answer":2,"evidence":"Früher hätte ich in solchen Momenten einfach irgendetwas auf dem Bildschirm gelesen.","pairs":[["Früher hätte ich in solchen Momenten","Vor ihrem Versuch hat sie sich bei Langeweile"],["einfach irgendetwas auf dem Bildschirm gelesen","meist mit dem Handy beschäftigt"]],"explain":"'Früher hätte ich …'는 실험 전 같으면 그랬을 거라는 뜻이에요. 'in solchen Momenten'은 앞 문장에 나온 지루한 순간들을 가리켜요. 그러니 예전에는 지루하면 대개 휴대폰을 보며 시간을 보냈다는 뜻이에요. irgendetwas(아무거나)는 중요한 업무용 글과 반대되는 말이에요. 또 이 문장은 이번 주에 읽고 싶었다는 소망이 아니에요."},{"type":"mc","kind":"detail","q":"Warum wartete die Autorin am sechsten Tag vor dem falschen Lokal?","options":["Die anderen hatten vergessen, ihr Bescheid zu geben.","Ihre Mitbewohnerin hatte ihr eine falsche Adresse genannt.","Von der Änderung des Treffpunkts wusste sie nichts."],"answer":2,"evidence":"Irgendjemand hatte den Treffpunkt kurzfristig geändert, doch die Nachricht lag natürlich auf meinem eingeschlossenen Handy.","pairs":[["die Nachricht lag natürlich auf meinem eingeschlossenen Handy","Von der Änderung des Treffpunkts wusste sie nichts"],["den Treffpunkt kurzfristig geändert","Änderung des Treffpunkts"]],"explain":"누군가 약속 장소를 급하게 바꿨는데, 그 메시지가 잠가 둔 휴대폰에 와 있어서 필자는 바뀐 장소를 몰랐어요. 그래서 원래 장소에서 기다렸어요(So wartete ich …). 다른 사람들은 메시지를 보냈으니 알려 주는 것을 잊은 게 아니에요. 룸메이트가 주소를 잘못 알려 줬다는 말도 본문에 없어요."},{"type":"rf","kind":"gist","q":"Nach ihrem Selbstversuch will die Autorin ganz ohne Smartphone leben.","answer":1,"evidence":"Ganz ohne Smartphone möchte ich trotzdem nicht leben, dafür ist es zu praktisch.","pairs":[["Ganz ohne Smartphone möchte ich trotzdem nicht leben","will die Autorin ganz ohne Smartphone leben"],["es bewusster zu nutzen","ganz ohne Smartphone"]],"explain":"필자는 스마트폰 없이 아예 살고 싶지는 않다고 해요. 너무 편리하기 때문이에요. 그 대신 더 의식적으로 쓰기로 했어요. 그러니 스마트폰을 완전히 끊겠다는 진술은 결론과 맞지 않아요."}],"grammar":[{"title":"접속법 2식 과거 – 실제와 다른 과거","term":"Konjunktiv II der Vergangenheit","explain":"접속법 2식 과거는 과거에 실제로 일어나지 않은 일을 상상해서 말할 때 써요. hätte 또는 wäre + 과거분사로 만들어요. 현재완료에서 haben을 쓰는 동사는 hätte를, sein을 쓰는 동사는 wäre를 써요(verpasst → hätte verpasst, gewesen → wäre gewesen). wenn 종속절에서는 hätte/wäre가 맨 끝에 와요. 'Wenn die S-Bahn pünktlich gewesen wäre, …'는 실제로는 전철이 늦었다는 뜻이에요.","pattern":"Wenn + 주어 … 과거분사 + hätte/wäre(끝), hätte/wäre + 주어 … 과거분사(끝)","examples":[{"de":"Wenn die S-Bahn pünktlich gewesen wäre, hätte ich meinen Termin um neun verpasst.","ko":"전철이 제시간에 왔다면 9시 약속을 놓쳤을 거예요.","mark":["gewesen wäre","hätte","verpasst"],"parts":[["Wenn die S-Bahn pünktlich gewesen wäre,","종속절"],["hätte","동사"],["ich","주어"],["meinen Termin","4격 목적어"],["um neun","부사어(시간)"],["verpasst.","동사(끝)"]]},{"de":"Früher hätte ich in solchen Momenten einfach irgendetwas auf dem Bildschirm gelesen.","ko":"예전 같으면 그런 순간에 그냥 화면에서 아무거나 읽었을 거예요.","mark":["hätte","gelesen"]},{"de":"Wenn ich den Selbstversuch nicht gemacht hätte, wüsste ich bis heute nicht, wie oft ich aus reiner Gewohnheit zum Handy greife.","ko":"이 실험을 하지 않았다면 제가 순전히 습관 때문에 얼마나 자주 휴대폰에 손을 뻗는지 지금도 몰랐을 거예요.","mark":["gemacht hätte","wüsste"]}],"tip":"조건은 과거, 결과는 현재일 수도 있어요. 'Wenn ich den Selbstversuch nicht gemacht hätte, wüsste ich bis heute nicht …'에서 조건(실험)은 과거의 일이라서 gemacht hätte, 결과는 지금의 상태라서 wüsste(접속법 2식 현재)를 써요."},{"title":"ohne/mit + 명사 + 접속법 2식 – 짧은 가정","term":"Irreale Bedingung mit ohne / mit","explain":"wenn 종속절 대신 ohne + 명사나 mit + 명사로 가정을 짧게 말할 수 있어요. 'Ohne die Hilfe einer älteren Dame hätte ich …'는 'Wenn mir die ältere Dame nicht geholfen hätte, …'와 뜻이 같아요. 'Mit dem Smartphone wäre das nicht passiert.'는 'Wenn ich das Smartphone gehabt hätte, …'라는 뜻이에요. 실제로는 반대예요. 부인이 도와주었고, 스마트폰은 없었어요. ohne/mit 구가 1번 자리에 오면 바로 뒤에 hätte/wäre가 와요.","pattern":"Ohne/Mit + 명사 + hätte/wäre + 주어 … 과거분사(끝)","examples":[{"de":"Ohne die Hilfe einer älteren Dame hätte ich das Café wahrscheinlich nie gefunden.","ko":"어느 나이 지긋한 부인의 도움이 없었다면 아마 그 카페를 끝내 찾지 못했을 거예요.","mark":["Ohne die Hilfe","hätte","gefunden"],"parts":[["Ohne die Hilfe einer älteren Dame","부사어"],["hätte","동사"],["ich","주어"],["das Café","4격 목적어"],["wahrscheinlich","부사어"],["nie","부정어"],["gefunden.","동사(끝)"]]},{"de":"Mit dem Smartphone wäre das nicht passiert.","ko":"스마트폰이 있었다면 그런 일은 없었을 거예요.","mark":["Mit dem Smartphone","wäre","passiert"],"parts":[["Mit dem Smartphone","부사어"],["wäre","동사"],["das","주어"],["nicht","부정어"],["passiert.","동사(끝)"]]}],"tip":"passieren은 현재완료에서 sein을 쓰는 동사라서 wäre … passiert가 돼요. 이런 짧은 가정은 실제 일과 반대되는 내용이에요. 'Mit dem Smartphone wäre das nicht passiert.'라고 하면 실제로는 스마트폰이 없어서 그 일이 일어났다는 뜻이에요."},{"title":"현재분사·과거분사의 형용사 용법","term":"Partizip I und II als Adjektiv","explain":"분사는 형용사처럼 명사 앞에서 쓸 수 있고, 이때 형용사 어미가 붙어요. 현재분사(동사원형 + d)는 '~하고 있는, ~하는'이라는 능동·진행의 뜻이에요(das klingelnde Handy: 울리는 휴대폰). 과거분사는 '~된, ~한'이라는 완료나 수동의 뜻이에요(ein gefalteter Stadtplan: 접힌 지도, der angefangene Krimi: 읽기 시작한 추리 소설). 블로그 소제목에서도 분사를 볼 수 있어요(Der fehlende Wecker, Die verpasste Nachricht).","pattern":"관사 + 현재분사(동사원형 + d) + 어미 + 명사  ·  관사 + 과거분사 + 어미 + 명사","examples":[{"de":"Mit einem gefalteten Stadtplan in der Hand stand ich an einer Kreuzung und drehte das Papier dreimal hin und her.","ko":"접힌 시내 지도를 손에 들고 사거리에 서서 종이를 세 번이나 이리저리 돌렸어요.","mark":["gefalteten"],"parts":[["Mit einem gefalteten Stadtplan in der Hand","부사어(방법)"],["stand","동사"],["ich","주어"],["an einer Kreuzung","부사어(장소)"],["und","접속사"],["drehte","동사"],["das Papier","4격 목적어"],["dreimal","부사어(빈도)"],["hin und her.","부사어(방법)"]]},{"de":"Am ersten Morgen bin ich erst um Viertel vor neun aufgewacht, weil mich ohne das klingelnde Handy niemand geweckt hatte.","ko":"첫날 아침에는 8시 45분에야 잠에서 깼어요. 울리는 휴대폰이 없으니 아무도 저를 깨워 주지 않았거든요.","mark":["klingelnde"]},{"de":"Der Wecker bleibt, der angefangene Krimi wird zu Ende gelesen, und abends liegt das Handy wieder in der Schublade – diesmal allerdings ohne Schlüssel.","ko":"자명종은 계속 쓰고, 읽기 시작한 추리 소설은 끝까지 읽고, 저녁에는 휴대폰을 다시 서랍에 넣어 둬요. 다만 이번에는 열쇠 없이요.","mark":["angefangene"]}],"tip":"분사에 붙는 어미는 보통 형용사와 똑같아요(mit einem gefalteten Stadtplan: 3격, das klingelnde Handy: 4격). 현재분사는 그 일이 진행 중임을, 과거분사는 이미 끝났거나 당한 일을 나타내요."},{"title":"irgend-: 정해지지 않은 사람·사물·장소·시간","term":"Indefinitpronomen und -adverbien mit irgend-","explain":"irgend-는 '누군지·무엇인지·어디인지·언제인지 모르거나 중요하지 않다'는 뜻을 더해요. irgendwo는 '어딘가에서', irgendwann은 '언젠가', irgendjemand는 '누군가', irgendetwas는 '무언가, 아무거나'예요. 말하는 사람이 정확히 모르거나, 정확한 정보가 중요하지 않을 때 써요.","pattern":"irgend + wo / wann / jemand / etwas / wie","examples":[{"de":"Noch am selben Abend habe ich mir irgendwo einen altmodischen Wecker gekauft.","ko":"그날 저녁에 바로 어딘가에서 구식 자명종을 하나 샀어요.","mark":["irgendwo"],"parts":[["Noch am selben Abend","부사어(시간)"],["habe","동사"],["ich","주어"],["mir","재귀대명사"],["irgendwo","부사어(장소)"],["einen altmodischen Wecker","4격 목적어"],["gekauft.","동사(끝)"]]},{"de":"Irgendjemand hatte den Treffpunkt kurzfristig geändert, doch die Nachricht lag natürlich auf meinem eingeschlossenen Handy.","ko":"누군가가 약속 장소를 급하게 바꿨는데, 그 메시지는 당연히 잠가 둔 제 휴대폰에 와 있었어요.","mark":["Irgendjemand"]},{"de":"Zuletzt hatte ich das irgendwann vor Jahren gemacht, glaube ich.","ko":"마지막으로 그렇게 한 건 아마 몇 년 전 언젠가였을 거예요.","mark":["irgendwann"]}],"tip":"irgendetwas는 '아무거나'라는 느낌도 있어요. 'Früher hätte ich einfach irgendetwas auf dem Bildschirm gelesen.'은 무엇을 읽는지는 상관없이 그냥 아무거나 읽었을 거라는 뜻이에요. irgendjemand 대신 jemand만 써도 '누군가'라는 뜻이지만, irgend-를 붙이면 누구인지 모른다는 느낌이 더 강해져요."}],"vocab":[{"de":"die Schublade, -n","ko":"서랍"},{"de":"weg|schließen (schließt weg, schloss weg, hat weggeschlossen)","ko":"(열쇠로) 잠가 두다, 넣고 잠그다"},{"de":"die Mitbewohnerin, -nen","ko":"(여자) 룸메이트, 함께 사는 사람"},{"de":"abhängig von + Dat.","ko":"~에 의존하는"},{"de":"der Selbstversuch, -e","ko":"자기 몸으로 해 보는 실험"},{"de":"der Wecker, -","ko":"자명종, 알람 시계"},{"de":"auf|wachen (wachte auf, ist aufgewacht)","ko":"잠에서 깨다"},{"de":"verpassen","ko":"놓치다"},{"de":"die Verspätung, -en","ko":"지연, 연착"},{"de":"altmodisch","ko":"구식의, 옛날식의"},{"de":"sich verlaufen (verläuft sich, verlief sich, hat sich verlaufen)","ko":"길을 잃다"},{"de":"die Kreuzung, -en","ko":"사거리, 교차로"},{"de":"sich langweilen","ko":"지루해하다"},{"de":"verabredet sein mit + Dat.","ko":"~와 만나기로 되어 있다"},{"de":"kurzfristig","ko":"급하게, 얼마 남기지 않고"},{"de":"die Gewohnheit, -en","ko":"습관"}],"phrases":[{"de":"zum Glück","ko":"다행히","ex":"Zum Glück hatte sie fünf Minuten Verspätung.","exko":"다행히 전철이 5분 늦게 왔어요."},{"de":"in die falsche Richtung laufen","ko":"반대 방향(잘못된 방향)으로 가다","ex":"Dann lief ich natürlich in die falsche Richtung.","exko":"그러고는 당연히 반대 방향으로 걸어갔지요."},{"de":"ans Telefon gehen","ko":"전화를 받다","ex":"Zwei habe ich erreicht, der dritte ging nicht ans Telefon.","exko":"두 명과는 연락이 됐지만 세 번째 사람은 전화를 받지 않았어요."},{"de":"aus reiner Gewohnheit","ko":"순전히 습관 때문에","ex":"Wenn ich den Selbstversuch nicht gemacht hätte, wüsste ich bis heute nicht, wie oft ich aus reiner Gewohnheit zum Handy greife.","exko":"이 실험을 하지 않았다면 제가 순전히 습관 때문에 얼마나 자주 휴대폰에 손을 뻗는지 지금도 몰랐을 거예요."},{"de":"sich etwas vornehmen","ko":"~하기로 마음먹다","ex":"Aber ich habe mir vorgenommen, es bewusster zu nutzen.","exko":"하지만 더 의식적으로 쓰기로 마음먹었어요."}],"words":357},{"id":"b1-11","level":"B1","no":11,"title":"Zwei Tage im Kajak auf der Müritz","titleKo":"뮈리츠호에서 카약으로 보낸 이틀","type":"Erlebnisbericht (Reiseblog)","typeKo":"여행 블로그 체험기","intro":"남매가 이틀 동안 카약을 타고 호수를 건넌 경험을 쓴 블로그 글이에요.","focus":["강조하는 부정","이유를 나타내는 전치사","문장을 받는 was · wo(r)-","합성 형용사"],"paragraphs":[{"label":"Hanna Lorenz","de":"Mein jüngerer Bruder Felix und ich haben uns Anfang September einen alten Traum erfüllt: zwei Tage im Kajak auf der Müritz, dem größten See innerhalb Deutschlands, und einigen kleineren Seen. Viel Erfahrung mit dem Kajak hatten wir allerdings nicht.","ko":"제 남동생 펠릭스와 저는 9월 초에 오랜 꿈을 이뤘어요. 전체가 독일 안에 있는 호수 가운데 가장 큰 뮈리츠호와 그보다 작은 호수 몇 곳에서 카약을 타며 이틀을 보낸 거예요. 다만 카약을 타 본 경험은 많지 않았어요."},{"style":"h","de":"Chaos am Bootssteg","ko":"선착장에서 벌어진 소동"},{"de":"Am Samstagmorgen versuchten wir beim Bootsverleih in Waren vergeblich, unsere Ausrüstung – zwei große Rucksäcke, ein Zelt und eine Kühltasche – in den engen Gepäckfächern des Kajaks zu verstauen. Zum Glück bot uns der Mitarbeiter zwei wasserdichte Packsäcke an, und weil wir vermutlich ziemlich verzweifelt aussahen, verlangte er dafür nicht einmal Geld. Nur die Kühltasche mussten wir im Auto zurücklassen, was Felix gar nicht gefiel.","ko":"토요일 아침에 저희는 바렌의 보트 대여소에서 저희 짐, 그러니까 큰 배낭 두 개와 텐트 하나, 보냉 가방 하나를 카약의 좁은 짐칸에 넣어 보려고 애썼지만 소용이 없었어요. 다행히 직원이 방수 짐 자루 두 개를 권해 주었어요. 저희가 아마 꽤 난감해 보였는지 자루 값조차 받지 않았어요. 보냉 가방만은 차에 두고 가야 했는데, 펠릭스는 그게 전혀 마음에 들지 않았어요."},{"style":"h","de":"Gegen den Wind","ko":"바람을 거슬러"},{"de":"Auf dem offenen See hat uns dann der Westwind erwischt. Wegen des Gegenwinds kamen wir den ganzen Vormittag nur mühsam voran, obwohl wir dicht am Ufer blieben. Schon nach zwei Stunden schlug Felix vor, umzukehren, worüber wir heute beide lachen. Aufgegeben haben wir natürlich nicht, aber gegen 13 Uhr legten wir aus Erschöpfung an einer kleinen Badestelle eine Pause ein.","ko":"탁 트인 호수로 나가자 서풍이 저희를 덮쳤어요. 저희는 호숫가에 바짝 붙어 갔는데도 맞바람 때문에 오전 내내 힘겹게 조금씩밖에 나아가지 못했어요. 벌써 두 시간 만에 펠릭스가 돌아가자고 했는데, 지금은 그 일을 떠올리며 둘 다 웃어요. 물론 포기하지는 않았지만, 오후 1시쯤에는 너무 지쳐서 작은 물놀이 장소에서 쉬었어요."},{"style":"h","de":"Eine Nacht am Wasser","ko":"물가에서 보낸 하룻밤"},{"de":"Den Campingplatz, den wir im Internet herausgesucht hatten, erreichten wir erst kurz vor Sonnenuntergang. Dort hatten wir Glück, denn der Platzwart gab uns den letzten freien Stellplatz am Wasser. Wer braucht schon ein Hotel, wenn er so einen Abend am See erleben kann? Schlecht geschlafen habe ich trotzdem, denn meine Isomatte war hauchdünn.","ko":"인터넷에서 찾아 둔 캠핑장에는 해가 지기 직전에야 도착했어요. 그곳에서 저희는 운이 좋았어요. 관리인이 물가에 있는 마지막 빈자리를 저희에게 내주었거든요. 호숫가에서 이런 저녁을 보낼 수 있는데 호텔이 왜 필요하겠어요? 그래도 저는 잠을 잘 못 잤어요. 제 매트가 종잇장처럼 얇았거든요."},{"style":"h","de":"Die Überraschung am Morgen","ko":"아침에 찾아온 뜻밖의 손님"},{"de":"Am Sonntagmorgen ist dann etwas passiert, womit wir nicht gerechnet hatten. Als wir gegen sieben Uhr über einen schmalen See paddelten, flog direkt vor uns ein riesiger Vogel aus einer Baumkrone auf. Vor Schreck ließ ich beinahe mein Paddel fallen. Zuerst hielten wir ihn für einen Reiher, doch eine Rangerin, der wir den Vogel später beschrieben, meinte, dass es vermutlich ein Seeadler war. Ein Beweisfoto konnten wir leider nicht schießen, denn das Smartphone lag gut verpackt im Packsack.","ko":"일요일 아침에는 저희가 예상하지 못한 일이 일어났어요. 아침 7시쯤 좁은 호수 위를 노 저어 가고 있을 때, 바로 앞 나무 꼭대기에서 아주 큰 새 한 마리가 날아올랐어요. 저는 깜짝 놀라 하마터면 노를 떨어뜨릴 뻔했어요. 처음에 저희는 그 새를 왜가리라고 생각했어요. 하지만 나중에 저희가 그 새의 모습을 설명해 드린 레인저는 아마 흰꼬리수리였을 거라고 했어요. 안타깝게도 증거 사진은 찍지 못했어요. 스마트폰이 짐 자루 안에 잘 싸여 있었거든요."},{"style":"h","de":"Mein Fazit","ko":"마무리"},{"de":"Wer die Tour nachmachen möchte, sollte nur das Nötigste mitnehmen, am besten in weichen Taschen statt in festen Rucksäcken. Bei Wind ist es klug, früh loszufahren, denn am Sonntag um sieben Uhr war der See noch spiegelglatt. Wir haben vor, nächstes Jahr wiederzukommen – dann allerdings mit einer dickeren Isomatte.","ko":"이 코스를 따라 해 보고 싶은 분은 꼭 필요한 것만 챙기는 게 좋아요. 단단한 배낭보다는 부드러운 가방에 담는 게 가장 좋고요. 바람이 불 때는 일찍 출발하는 게 현명해요. 일요일 아침 7시에는 호수가 아직 거울처럼 잔잔했거든요. 저희는 내년에 다시 올 생각이에요. 다만 그때는 더 두꺼운 매트를 가지고요."}],"questions":[{"type":"rf","kind":"detail","q":"Felix und Hanna hatten vor dieser Tour schon viel Erfahrung mit dem Kajak gesammelt.","answer":1,"evidence":"Viel Erfahrung mit dem Kajak hatten wir allerdings nicht.","pairs":[["Viel Erfahrung mit dem Kajak hatten wir allerdings nicht","schon viel Erfahrung mit dem Kajak gesammelt"]],"explain":"글쓴이는 'Viel Erfahrung mit dem Kajak hatten wir allerdings nicht'라고 해요. 두 사람은 카약 경험이 많지 않았으니 이 진술은 틀려요. 'viel Erfahrung'과 'Kajak'은 본문에 나오는 낱말이지만, 본문은 경험이 많지 '않았다'고 말해요."},{"type":"mc","kind":"detail","q":"Wie wurde das Problem mit dem Gepäck am Ende gelöst?","options":["Sie mussten beim Verleih für zwei zusätzliche Säcke bezahlen.","Zwei kostenlose Säcke lösten das Problem bis auf die Kühltasche.","Sie mussten das Zelt und auch die Kühltasche im Auto zurücklassen."],"answer":1,"evidence":"Zum Glück bot uns der Mitarbeiter zwei wasserdichte Packsäcke an","pairs":[["verlangte er dafür nicht einmal Geld","kostenlose Säcke"],["Nur die Kühltasche mussten wir im Auto zurücklassen","bis auf die Kühltasche"]],"explain":"직원이 방수 짐 자루 두 개를 권했고 돈도 받지 않았어요. 그 덕분에 짐이 거의 다 들어갔고, 차에 남긴 것은 보냉 가방뿐이었어요. 'nicht einmal Geld verlangen'을 'kostenlos'로, 'Nur die Kühltasche … zurücklassen'을 'bis auf die Kühltasche'로 바꿔 말했어요. 돈을 냈다는 말은 본문과 반대이고, 텐트는 차에 남기지 않았어요."},{"type":"mc","kind":"meaning","q":"Was bedeutet „hat uns dann der Westwind erwischt“ im Text?","options":["Der Wind kam von hinten und machte ihnen das Paddeln leichter.","Draußen auf dem See bekamen sie plötzlich sehr starken Gegenwind.","Wegen des Westwinds mussten sie sofort wieder zurück zum Ufer paddeln."],"answer":1,"evidence":"Auf dem offenen See hat uns dann der Westwind erwischt.","pairs":[["erwischt","bekamen sie plötzlich sehr starken Gegenwind"],["Auf dem offenen See","Draußen auf dem See"]],"explain":"여기서 erwischen은 '바람이 갑자기 들이닥쳐 두 사람을 괴롭혔다'는 뜻이에요. 바로 다음 문장에서 맞바람(Gegenwind) 때문에 오전 내내 힘겹게 나아갔다고 해요. 바람이 도와준 것이 아니고, 두 사람은 호숫가로 돌아간 것이 아니라 호숫가 가까이에서 계속 노를 저었어요."},{"type":"rf","kind":"detail","q":"Felix hatte schon vor der Mittagspause genug vom Paddeln.","answer":0,"evidence":"Schon nach zwei Stunden schlug Felix vor, umzukehren","pairs":[["Schon nach zwei Stunden","schon vor der Mittagspause"],["schlug Felix vor, umzukehren","genug vom Paddeln"]],"explain":"두 사람은 오전 내내 맞바람을 맞으며 노를 저었고, 두 시간 만에 펠릭스는 벌써 돌아가자고 했어요. 쉬는 시간은 오후 1시쯤이었으니 펠릭스는 점심 휴식 전에 이미 지쳐 있었어요. 'vorschlagen, umzukehren'을 'genug vom Paddeln haben'으로 바꿔 말했어요."},{"type":"mc","kind":"paraphrase","q":"Was will die Autorin mit dem Satz „Wer braucht schon ein Hotel, wenn er so einen Abend am See erleben kann?“ sagen?","options":["Nach dem mühsamen Tag hätte sie lieber in einem Hotel geschlafen.","Ein Hotel direkt am Wasser hätte ihnen einen schöneren Abend geboten.","So ein Abend unter freiem Himmel war ihr lieber als jedes Hotel."],"answer":2,"evidence":"Wer braucht schon ein Hotel, wenn er so einen Abend am See erleben kann?","pairs":[["Wer braucht schon ein Hotel","lieber als jedes Hotel"],["so einen Abend am See","So ein Abend unter freiem Himmel"]],"explain":"'호텔이 왜 필요하겠어요?'는 대답을 바라는 질문이 아니라 '호텔은 필요 없다'는 뜻의 수사 의문문이에요. 호숫가의 저녁이 어떤 호텔 방보다 좋았다는 말이에요. 잠을 잘 못 잤다는 내용은 있지만 호텔에서 자고 싶었다는 말은 없고, 호텔이 더 좋은 저녁을 주었을 거라는 생각은 글쓴이의 말과 반대예요."},{"type":"mc","kind":"inference","q":"Was kann man über die Ankunft auf dem Campingplatz schließen?","options":["Sie hatten im Internet einen Stellplatz am Wasser reserviert.","Etwas später hätte es für sie wohl keinen Platz am See mehr gegeben.","Kurz vor Sonnenuntergang waren alle Stellplätze am Wasser schon belegt."],"answer":1,"evidence":"denn der Platzwart gab uns den letzten freien Stellplatz am Wasser","pairs":[["den letzten freien Stellplatz am Wasser","hätte es für sie wohl keinen Platz am See mehr gegeben"],["erst kurz vor Sonnenuntergang","Etwas später"]],"explain":"두 사람이 해 지기 직전에 받은 자리가 물가의 마지막 빈자리였어요. 그러니 조금만 늦게 왔다면 물가 자리는 얻지 못했을 거라고 추론할 수 있어요. 'am Wasser'를 'am See'로 바꿔 말했어요. 인터넷으로는 캠핑장을 찾아 두기만 했고 '운이 좋았다'고 했으니 자리를 예약한 것이 아니에요. 또 물가 자리가 모두 차 있었다면 두 사람도 그 자리를 받지 못했을 거예요."},{"type":"mc","kind":"detail","q":"Woher wissen die Geschwister, dass der Vogel wohl ein Seeadler war?","options":["Eine Rangerin hielt es für wahrscheinlich, als sie ihr davon erzählten.","Eine Rangerin hat den Vogel am Sonntagmorgen selbst auf dem See gesehen.","Ein Beweisfoto vom Smartphone gab ihnen später die richtige Antwort."],"answer":0,"evidence":"eine Rangerin, der wir den Vogel später beschrieben, meinte, dass es vermutlich ein Seeadler war","pairs":[["der wir den Vogel später beschrieben","als sie ihr davon erzählten"],["meinte, dass es vermutlich ein Seeadler war","hielt es für wahrscheinlich"]],"explain":"두 사람은 나중에 레인저에게 새의 모습을 설명했고, 레인저가 그 설명을 듣고 아마 흰꼬리수리였을 거라고 했어요. 'der wir den Vogel später beschrieben'을 'als sie ihr davon erzählten'으로, 'meinte, dass es vermutlich … war'를 'hielt es für wahrscheinlich'로 바꿔 말했어요. 레인저가 그 새를 직접 보았다는 말은 없고, 스마트폰이 짐 자루 안에 있어서 사진도 찍지 못했어요."},{"type":"mc","kind":"intent","q":"Was möchte die Autorin mit ihrem Fazit vor allem erreichen?","options":["Sie warnt davor, bei starkem Wind überhaupt mit dem Kajak loszufahren.","Sie rät, das Nötigste lieber in festen Rucksäcken mitzunehmen.","Sie will Lesern, die diese Tour nachmachen wollen, Tipps mitgeben."],"answer":2,"evidence":"Wer die Tour nachmachen möchte, sollte nur das Nötigste mitnehmen","pairs":[["Wer die Tour nachmachen möchte","Lesern, die diese Tour nachmachen wollen"]],"explain":"마무리 부분에서 글쓴이는 같은 코스를 따라 하려는 사람에게 짐과 출발 시간에 관한 조언을 해요. 바람이 불면 아예 나가지 말라는 것이 아니라 일찍 출발하라고 했고, 단단한 배낭이 아니라 부드러운 가방을 권했어요."}],"grammar":[{"title":"강조하는 부정: gar nicht · nicht einmal","term":"Verstärkte Negation: gar nicht, nicht einmal","explain":"nicht에 다른 말을 붙이면 부정의 뜻이 더 강해지거나 새 뜻이 더해져요. gar nicht는 überhaupt nicht와 같은 뜻으로 '전혀 ~않다'예요. nicht einmal은 '~조차 ~않다'라는 뜻이에요. 보통이라면 있을 만한 최소한의 일도 일어나지 않았다는 것을 강조해요. 두 표현 모두 부정하는 말 바로 앞에 와요(gar nicht gefiel, nicht einmal Geld).","pattern":"gar nicht / überhaupt nicht = 전혀 ~않다  ·  nicht einmal + 부정하는 말 = ~조차 ~않다","examples":[{"de":"Zum Glück bot uns der Mitarbeiter zwei wasserdichte Packsäcke an, und weil wir vermutlich ziemlich verzweifelt aussahen, verlangte er dafür nicht einmal Geld.","ko":"다행히 직원이 방수 짐 자루 두 개를 권해 주었는데, 저희가 아마 꽤 난감해 보였는지 자루 값조차 받지 않았어요.","mark":["nicht einmal Geld"],"parts":[["Zum Glück","부사어"],["bot","동사"],["uns","3격 목적어"],["der Mitarbeiter","주어"],["zwei wasserdichte Packsäcke","4격 목적어"],["an,","동사(끝)"],["und","접속사"],["weil wir vermutlich ziemlich verzweifelt aussahen,","종속절"],["verlangte","동사"],["er","주어"],["dafür","기타"],["nicht einmal","부정어"],["Geld.","4격 목적어"]]},{"de":"Nur die Kühltasche mussten wir im Auto zurücklassen, was Felix gar nicht gefiel.","ko":"보냉 가방만은 차에 두고 가야 했는데, 펠릭스는 그게 전혀 마음에 들지 않았어요.","mark":["gar nicht"]}],"tip":"'kein Geld verlangen'은 돈을 받지 않았다는 사실만 말해요. 'nicht einmal Geld verlangen'은 돈을 받는 것이 보통인데 그것조차 받지 않았다는 뜻이라서, 직원이 얼마나 친절했는지가 더 잘 드러나요."},{"title":"이유를 나타내는 전치사 wegen · aus · vor","term":"Kausale Präpositionen: wegen (+ Gen.), aus und vor (+ Dat.)","explain":"이유는 weil 절 말고 전치사구로도 짧게 말할 수 있어요. wegen은 2격과 함께 쓰고, 날씨나 상황 같은 바깥의 원인을 말할 때 자주 써요. aus와 vor는 3격과 함께 쓰는데, 감정이나 몸 상태를 나타내는 명사 앞에서는 보통 관사 없이 써요. aus는 그 감정이나 상태 때문에 어떤 행동을 하기로 정할 때(aus Erschöpfung eine Pause einlegen), vor는 몸이 저절로 반응할 때(vor Schreck etwas fallen lassen) 써요.","pattern":"wegen + 2격  ·  aus + 관사 없는 명사 (스스로 정한 행동)  ·  vor + 관사 없는 명사 (저절로 일어나는 반응)","examples":[{"de":"Wegen des Gegenwinds kamen wir den ganzen Vormittag nur mühsam voran, obwohl wir dicht am Ufer blieben.","ko":"저희는 호숫가에 바짝 붙어 갔는데도 맞바람 때문에 오전 내내 힘겹게 조금씩밖에 나아가지 못했어요.","mark":["Wegen des Gegenwinds"],"parts":[["Wegen des Gegenwinds","부사어(이유)"],["kamen","동사"],["wir","주어"],["den ganzen Vormittag","부사어(시간)"],["nur mühsam","부사어(방법)"],["voran,","동사(끝)"],["obwohl wir dicht am Ufer blieben.","종속절"]]},{"de":"Aufgegeben haben wir natürlich nicht, aber gegen 13 Uhr legten wir aus Erschöpfung an einer kleinen Badestelle eine Pause ein.","ko":"물론 포기하지는 않았지만, 오후 1시쯤에는 너무 지쳐서 작은 물놀이 장소에서 쉬었어요.","mark":["aus Erschöpfung"]},{"de":"Vor Schreck ließ ich beinahe mein Paddel fallen.","ko":"저는 깜짝 놀라 하마터면 노를 떨어뜨릴 뻔했어요.","mark":["Vor Schreck"],"parts":[["Vor Schreck","부사어(이유)"],["ließ","동사"],["ich","주어"],["beinahe","부사어"],["mein Paddel","4격 목적어"],["fallen.","동사(끝)"]]}],"tip":"말할 때는 wegen 뒤에 3격을 쓰는 사람도 많아요(wegen dem Wind). 글에서는 2격이 표준이에요(wegen des Windes, wegen des Gegenwinds)."},{"title":"앞 문장 전체를 받는 was · wo(r)-","term":"Weiterführende Relativsätze mit was und wo(r)- + Präposition","explain":"관계절이 명사 하나가 아니라 앞 문장이 말한 일 전체를 받을 때는 der·die·das가 아니라 was를 써요. 관계절의 동사가 전치사와 함께 쓰이면 was 대신 wo + 전치사를 써요. über etwas lachen이면 worüber, mit etwas rechnen이면 womit이 돼요. 전치사가 모음으로 시작하면 사이에 r를 넣어요. 이런 관계절은 앞 문장 뒤에 쉼표를 찍고 붙이며, 동사는 끝에 와요.","pattern":"앞 문장, was + … + 동사(끝)  ·  앞 문장, wo(r) + 전치사 + … + 동사(끝)","examples":[{"de":"Nur die Kühltasche mussten wir im Auto zurücklassen, was Felix gar nicht gefiel.","ko":"보냉 가방만은 차에 두고 가야 했는데, 펠릭스는 그게 전혀 마음에 들지 않았어요.","mark":["was Felix gar nicht gefiel"],"parts":[["Nur die Kühltasche","4격 목적어"],["mussten","동사"],["wir","주어"],["im Auto","부사어(장소)"],["zurücklassen,","동사(끝)"],["was Felix gar nicht gefiel.","관계절"]]},{"de":"Schon nach zwei Stunden schlug Felix vor, umzukehren, worüber wir heute beide lachen.","ko":"벌써 두 시간 만에 펠릭스가 돌아가자고 했는데, 지금은 그 일을 떠올리며 둘 다 웃어요.","mark":["worüber wir heute beide lachen"],"parts":[["Schon nach zwei Stunden","부사어(시간)"],["schlug","동사"],["Felix","주어"],["vor,","동사(끝)"],["umzukehren,","zu 부정사구"],["worüber wir heute beide lachen.","관계절"]]}],"tip":"첫 번째 예문에서 was가 받는 것은 '보냉 가방을 차에 두고 가야 했다'는 일 전체예요. 여기에 das를 쓰면 중성 명사 하나를 받는 것처럼 들려요. etwas, nichts, alles 뒤에서도 같은 형태를 써요(… etwas passiert, womit wir nicht gerechnet hatten)."},{"title":"명사 + 형용사로 된 합성 형용사","term":"Zusammengesetzte Adjektive (Nomen + Adjektiv: wasserdicht, spiegelglatt, hauchdünn)","explain":"독일어에서는 명사와 형용사를 붙여 새 형용사를 자주 만들어요. 뜻의 중심은 뒤의 형용사이고, 앞의 명사가 그 뜻을 좁히거나 강하게 해요. wasserdicht는 '물에 대해 dicht하다', 곧 물이 새지 않는다는 뜻이에요. spiegelglatt(거울처럼 매끈하다), hauchdünn(입김처럼 얇다)처럼 '~처럼'이라는 비교의 뜻이 들어 있는 것도 있는데, 이런 말은 정도가 아주 높다는 것을 나타내요. 명사 앞에 오면 보통 형용사처럼 어미가 붙어요(zwei wasserdichte Packsäcke).","pattern":"명사 + 형용사 → 형용사  ·  wasser|dicht, spiegel|glatt, hauch|dünn","examples":[{"de":"Bei Wind ist es klug, früh loszufahren, denn am Sonntag um sieben Uhr war der See noch spiegelglatt.","ko":"바람이 불 때는 일찍 출발하는 게 현명해요. 일요일 아침 7시에는 호수가 아직 거울처럼 잔잔했거든요.","mark":["spiegelglatt"],"parts":[["Bei Wind","부사어"],["ist","동사"],["es","주어"],["klug,","보어"],["früh loszufahren,","zu 부정사구"],["denn","접속사"],["am Sonntag um sieben Uhr","부사어(시간)"],["war","동사"],["der See","주어"],["noch","부사어"],["spiegelglatt.","보어"]]},{"de":"Schlecht geschlafen habe ich trotzdem, denn meine Isomatte war hauchdünn.","ko":"그래도 저는 잠을 잘 못 잤어요. 제 매트가 종잇장처럼 얇았거든요.","mark":["hauchdünn"]},{"de":"Zum Glück bot uns der Mitarbeiter zwei wasserdichte Packsäcke an, und weil wir vermutlich ziemlich verzweifelt aussahen, verlangte er dafür nicht einmal Geld.","ko":"다행히 직원이 방수 짐 자루 두 개를 권해 주었는데, 저희가 아마 꽤 난감해 보였는지 자루 값조차 받지 않았어요.","mark":["wasserdichte"]}],"tip":"모르는 합성 형용사를 만나면 뒤의 형용사부터 뜻을 잡고, 앞의 명사가 '무엇에 대해'인지 '무엇처럼'인지 생각해 보세요."}],"vocab":[{"de":"der Bootsverleih, -e","ko":"보트 대여소"},{"de":"die Ausrüstung, -en","ko":"장비, 챙겨 간 짐"},{"de":"vergeblich","ko":"헛된, 소용없이"},{"de":"verstauen","ko":"(짐을 좁은 곳에) 챙겨 넣다"},{"de":"wasserdicht","ko":"방수의"},{"de":"verzweifelt","ko":"어쩔 줄 모르는, 절망한"},{"de":"zurück|lassen (lässt zurück, ließ zurück, hat zurückgelassen)","ko":"두고 가다"},{"de":"erwischen","ko":"(비·바람 등이 갑자기) 덮치다, 붙잡다"},{"de":"der Gegenwind (Sg.)","ko":"맞바람"},{"de":"mühsam","ko":"힘겨운, 애써서"},{"de":"um|kehren (ist umgekehrt)","ko":"되돌아가다"},{"de":"die Erschöpfung (Sg.)","ko":"탈진, 심한 피로"},{"de":"der Stellplatz, -¨e","ko":"(캠핑장의) 자리, 구획"},{"de":"hauchdünn","ko":"아주 얇은, 종잇장처럼 얇은"},{"de":"der Schreck (Sg.)","ko":"깜짝 놀람"},{"de":"spiegelglatt","ko":"거울처럼 잔잔한"}],"phrases":[{"de":"sich (Dat.) einen Traum erfüllen","ko":"꿈을 이루다","ex":"Mein jüngerer Bruder Felix und ich haben uns Anfang September einen alten Traum erfüllt","exko":"제 남동생 펠릭스와 저는 9월 초에 오랜 꿈을 이뤘어요"},{"de":"eine Pause einlegen","ko":"잠시 쉬다, 휴식을 갖다","ex":"Aufgegeben haben wir natürlich nicht, aber gegen 13 Uhr legten wir aus Erschöpfung an einer kleinen Badestelle eine Pause ein.","exko":"물론 포기하지는 않았지만, 오후 1시쯤에는 너무 지쳐서 작은 물놀이 장소에서 쉬었어요."},{"de":"Glück haben","ko":"운이 좋다","ex":"Dort hatten wir Glück, denn der Platzwart gab uns den letzten freien Stellplatz am Wasser.","exko":"그곳에서 저희는 운이 좋았어요. 관리인이 물가에 있는 마지막 빈자리를 저희에게 내주었거든요."},{"de":"mit etwas (Dat.) rechnen","ko":"~을 예상하다","ex":"Am Sonntagmorgen ist dann etwas passiert, womit wir nicht gerechnet hatten.","exko":"일요일 아침에는 저희가 예상하지 못한 일이 일어났어요."},{"de":"jemanden/etwas für etwas halten","ko":"~을 ~로 여기다, ~라고 생각하다","ex":"Zuerst hielten wir ihn für einen Reiher","exko":"처음에 저희는 그 새를 왜가리라고 생각했어요"}],"words":358},{"id":"b1-12","level":"B1","no":12,"title":"Bewerbung als Kinderpfleger","titleKo":"보육 보조 교사 지원","type":"Stellenanzeige und Anschreiben","typeKo":"구인 광고와 지원서","intro":"어린이집의 구인 광고와, 이 자리에 지원하는 사람이 쓴 편지예요.","focus":["전치사와 쓰는 명사","statt … zu","공손한 접속법 2식","전치사 + 관계대명사"],"paragraphs":[{"style":"h","de":"Stellenanzeige","ko":"구인 광고"},{"label":"Wer wir sind","de":"Die Kita „Sonnenhof“ wurde 2009 von einem Elternverein gegründet und wird bis heute von ihm getragen. In unserem Altbau, der vor zwei Jahren aufwendig saniert wurde, betreuen wir 55 Kinder im Alter von einem bis sechs Jahren.","ko":"어린이집 „존넨호프“는 2009년에 학부모회가 세웠으며, 지금까지도 학부모회가 운영하고 있습니다. 저희는 2년 전에 공들여 보수한 오래된 건물에서 1세부터 6세까지의 아이 55명을 돌보고 있습니다."},{"label":"Ihre Aufgaben","de":"Im Mittelpunkt stehen die Begleitung der Kinder durch den Kita-Alltag, etwa beim Essen, beim Spielen und beim Anziehen, sowie die Beobachtung ihrer Entwicklung. Die Planung und Durchführung von Ausflügen und Festen erfolgt gemeinsam im Team.","ko":"가장 중요한 일은 식사, 놀이, 옷 입기 등 어린이집의 하루 일과에서 아이들 곁을 지키며 돕는 일과 아이들의 발달 과정을 관찰하는 일입니다. 소풍과 행사의 계획과 진행은 팀이 함께합니다."},{"label":"Das erwarten wir","de":"Eine abgeschlossene Ausbildung als Kinderpflegerin oder Kinderpfleger, Erfahrung in der Betreuung von Kleinkindern, Freude an kreativen Angeboten und die Bereitschaft zum Schichtdienst.","ko":"보육 보조 교사 과정을 마친 분, 어린아이를 돌본 경험이 있는 분, 창의적인 활동을 즐기시는 분, 교대 근무를 기꺼이 하실 분을 찾습니다."},{"label":"Das bieten wir","de":"Eine unbefristete Teilzeitstelle mit 30 Wochenstunden, eine Vergütung nach Tarif, eine gründliche Einarbeitung sowie regelmäßige Fortbildungen, deren Kosten wir übernehmen. Ihre Bewerbungsunterlagen senden Sie bitte bis zum 15. Oktober an unsere Leiterin, Frau Lindner, die Ihnen bei Rückfragen gern zur Verfügung steht.","ko":"주 30시간 근무의 무기한 시간제 일자리, 단체 협약에 따른 급여, 꼼꼼한 업무 적응 교육, 그리고 저희가 비용을 부담하는 정기 연수를 제공합니다. 지원 서류는 10월 15일까지 원장인 린트너 씨에게 보내 주시기 바랍니다. 문의할 점이 있으면 린트너 씨가 기꺼이 답해 드립니다."},{"style":"h","de":"Anschreiben","ko":"지원서"},{"style":"meta","de":"Betreff: Bewerbung als Kinderpfleger in der Kita „Sonnenhof“","ko":"제목: 어린이집 „존넨호프“ 보육 보조 교사 지원"},{"style":"meta","de":"Sehr geehrte Frau Lindner,","ko":"린트너 씨께,"},{"de":"in der Wochenendausgabe der Stadtzeitung bin ich auf Ihre Anzeige aufmerksam geworden, auf die ich mich hiermit als Kinderpfleger bewerbe. Die Kita „Sonnenhof“, über die ich bereits viel Gutes gehört habe, ist genau die Einrichtung, in der ich mich beruflich weiterentwickeln möchte.","ko":"지역 신문 주말판에서 귀 어린이집의 공고를 보았고, 이렇게 보육 보조 교사로 지원합니다. 이미 좋은 이야기를 많이 들은 „존넨호프“ 어린이집은 제가 직업적으로 더 성장하고 싶은 바로 그런 곳입니다."},{"de":"Seit drei Jahren arbeite ich in der Kita „Kleine Entdecker“, wo ich mit einer Erzieherin eine Gruppe von zwölf Kindern zwischen zwei und vier Jahren betreue. Statt die Kinder nur zu beaufsichtigen, versuche ich, ihre eigenen Ideen aufzugreifen und gemeinsam mit ihnen umzusetzen. So haben wir im Sommer auf Wunsch der Kinder ein Beet angelegt, auf dem sie selbst Tomaten und Kräuter gepflanzt haben.","ko":"저는 3년 전부터 어린이집 „클라이네 엔트데커“에서 일하며, 유아 교사 한 명과 함께 두 살에서 네 살 사이의 아이 열두 명으로 이루어진 반을 맡고 있습니다. 저는 아이들을 그저 지켜보기만 하지 않고, 아이들의 생각을 받아들여 아이들과 함께 실현해 보려고 합니다. 예를 들어 지난여름에는 아이들이 원해서 화단을 만들었고, 아이들이 직접 그곳에 토마토와 허브를 심었습니다."},{"de":"Meine jetzige Stelle möchte ich wechseln, um mehr Verantwortung zu übernehmen. Darüber hinaus wohne ich seit unserem Umzug im Frühjahr nur zehn Minuten von Ihrer Kita entfernt. Statt täglich fast zwei Stunden zu pendeln, hätte ich somit mehr Zeit für meine Tochter, die im Herbst eingeschult wird.","ko":"저는 더 많은 책임을 맡고 싶어서 지금 직장을 옮기려고 합니다. 그 밖에도 봄에 이사한 뒤로는 귀 어린이집에서 불과 10분 거리에 살고 있습니다. 그러면 날마다 거의 두 시간씩 통근하는 대신, 가을에 초등학교에 입학하는 딸과 더 많은 시간을 보낼 수 있을 것입니다."},{"de":"Ich würde mich sehr freuen, wenn ich Ihr Team bei einem Probearbeitstag kennenlernen könnte. Mit Rücksicht auf meine Tochter hätte ich zudem eine Bitte: Könnten wir auch über flexible Arbeitszeiten sprechen?","ko":"체험 근무일에 귀 팀을 만나 볼 수 있다면 정말 기쁘겠습니다. 또 딸을 생각해서 한 가지 부탁을 드리고 싶습니다. 유연한 근무 시간에 대해서도 이야기를 나눌 수 있을까요?"},{"de":"Für eine Einladung zu einem persönlichen Vorstellungsgespräch wäre ich Ihnen sehr dankbar.","ko":"대면 면접에 초대해 주시면 대단히 감사하겠습니다."},{"style":"meta","de":"Mit freundlichen Grüßen\nTobias Wendt","ko":"안부를 전하며\n토비아스 벤트 드림"}],"questions":[{"type":"rf","kind":"detail","q":"Die Kita wird seit ihrer Gründung von einem Zusammenschluss von Eltern geführt.","answer":0,"evidence":"Die Kita „Sonnenhof“ wurde 2009 von einem Elternverein gegründet und wird bis heute von ihm getragen.","pairs":[["von einem Elternverein gegründet","von einem Zusammenschluss von Eltern"],["bis heute","seit ihrer Gründung"]],"explain":"어린이집은 2009년에 학부모회(Elternverein)가 세웠고 지금도 학부모회가 운영해요(getragen). 문제는 Elternverein을 'Zusammenschluss von Eltern'으로, 'bis heute'를 'seit ihrer Gründung'으로, 'tragen'을 'führen'으로 바꿔 말했어요."},{"type":"mc","kind":"detail","q":"Was gehört laut Anzeige zu den Aufgaben der neuen Kraft?","options":["Sie kocht jeden Tag selbst das Mittagessen für alle Kinder im ganzen Haus.","Sie hilft den Kindern im Tagesablauf und verfolgt ihre Fortschritte.","Sie plant die Ausflüge und Feste allein, ohne Hilfe aus dem Team."],"answer":1,"evidence":"Im Mittelpunkt stehen die Begleitung der Kinder durch den Kita-Alltag, etwa beim Essen, beim Spielen und beim Anziehen, sowie die Beobachtung ihrer Entwicklung.","pairs":[["die Begleitung der Kinder durch den Kita-Alltag","hilft den Kindern im Tagesablauf"],["die Beobachtung ihrer Entwicklung","verfolgt ihre Fortschritte"]],"explain":"광고의 'Begleitung der Kinder durch den Kita-Alltag'를 'hilft den Kindern im Tagesablauf'로, 'Beobachtung ihrer Entwicklung'을 'verfolgt ihre Fortschritte'로 바꿔 말했어요. 'beim Essen'은 아이들이 먹을 때 곁에서 돕는다는 뜻이지 점심을 직접 만든다는 뜻이 아니에요. 소풍과 행사는 혼자가 아니라 팀이 함께 계획해요."},{"type":"rf","kind":"detail","q":"Der Bewerber arbeitet zurzeit schon in der Kita, die die Stelle ausgeschrieben hat.","answer":1,"evidence":"Seit drei Jahren arbeite ich in der Kita „Kleine Entdecker“","pairs":[["in der Kita „Kleine Entdecker“","in der Kita, die die Stelle ausgeschrieben hat"]],"explain":"지원자는 3년 전부터 다른 어린이집인 „Kleine Entdecker“에서 일하고 있어요. 구인 광고를 낸 곳은 „Sonnenhof“이니까 같은 곳이라는 말은 틀려요. 'arbeiten'과 'Kita'라는 낱말은 본문과 같지만 가리키는 어린이집이 달라요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Statt die Kinder nur zu beaufsichtigen, versuche ich, ihre eigenen Ideen aufzugreifen und gemeinsam mit ihnen umzusetzen.“?","options":["Er passt nicht nur auf die Kinder auf, sondern verwirklicht auch ihre Einfälle.","Er muss die Kinder ständig beaufsichtigen und hat deshalb keine Zeit für eigene Ideen.","Er setzt vor allem seine eigenen Ideen um und lässt die Kinder dabei nur zusehen."],"answer":0,"evidence":"Statt die Kinder nur zu beaufsichtigen, versuche ich, ihre eigenen Ideen aufzugreifen und gemeinsam mit ihnen umzusetzen.","pairs":[["Statt die Kinder nur zu beaufsichtigen","nicht nur auf die Kinder auf"],["ihre eigenen Ideen aufzugreifen und gemeinsam mit ihnen umzusetzen","verwirklicht auch ihre Einfälle"]],"explain":"'statt … zu'는 '~하는 대신'이라는 뜻이에요. 지원자는 아이들을 지켜보기만 하지 않고, 아이들의 생각을 받아들여 함께 실현해요. 'ihre eigenen Ideen'의 ihre는 아이들을 가리켜요. 그래서 자기 생각만 실현한다는 선지는 틀리고, 아이들의 생각을 다룰 시간이 없다는 선지도 본문과 반대예요."},{"type":"mc","kind":"intent","q":"Was will der Bewerber mit dem Beispiel vom Beet zeigen?","options":["Er hat in seiner Ausbildung gelernt, mit kleinen Kindern Gemüse anzubauen.","Er will damit begründen, warum er seine jetzige Stelle wechseln möchte.","Er will belegen, dass er Wünsche der Kinder wirklich in die Tat umsetzt."],"answer":2,"evidence":"So haben wir im Sommer auf Wunsch der Kinder ein Beet angelegt, auf dem sie selbst Tomaten und Kräuter gepflanzt haben.","pairs":[["auf Wunsch der Kinder","Wünsche der Kinder"],["So haben wir","Er will belegen"]],"explain":"'So haben wir …'로 시작하는 화단 이야기는 바로 앞 문장, 곧 아이들의 생각을 받아들여 실현한다는 말을 보여 주는 사례예요. 아이들이 원해서(auf Wunsch der Kinder) 화단을 만들었다는 점이 핵심이에요. 직업 교육에서 배운 일이라는 말은 없고, 이직 이유는 다음 단락에서 따로 말해요."},{"type":"mc","kind":"detail","q":"Welchen praktischen Vorteil hätte die neue Stelle für den Bewerber?","options":["Die Gruppen wären dort deutlich kleiner als in seiner jetzigen Kita.","Seine Tochter könnte ab dem Herbst in dieselbe Kita gehen wie er.","Er würde täglich viel weniger Zeit unterwegs verbringen als jetzt."],"answer":2,"evidence":"Darüber hinaus wohne ich seit unserem Umzug im Frühjahr nur zehn Minuten von Ihrer Kita entfernt.","pairs":[["nur zehn Minuten von Ihrer Kita entfernt","viel weniger Zeit unterwegs verbringen"],["Statt täglich fast zwei Stunden zu pendeln","als jetzt"]],"explain":"지원자는 이사한 뒤 새 어린이집에서 불과 10분 거리에 살고, 지금은 날마다 거의 두 시간을 길에서 보내요. 그러니 새 직장에서는 오가는 데 드는 시간이 훨씬 줄어요. 'nur zehn Minuten … entfernt'와 'statt täglich fast zwei Stunden'을 'viel weniger Zeit unterwegs verbringen'으로 바꿔 말했어요. 새 어린이집의 반 크기는 나오지 않고, 딸은 가을에 어린이집이 아니라 초등학교에 들어가요."},{"type":"mc","kind":"meaning","q":"Was bedeutet „pendeln“ im Text?","options":["regelmäßig zwischen Wohnung und Arbeitsplatz hin- und herfahren","mehrmals am Tag zwischen zwei Kindergruppen hin- und herwechseln","täglich die Tochter zur Schule bringen und dort wieder abholen"],"answer":0,"evidence":"Statt täglich fast zwei Stunden zu pendeln","pairs":[["täglich fast zwei Stunden zu pendeln","regelmäßig zwischen Wohnung und Arbeitsplatz hin- und herfahren"]],"explain":"pendeln은 집과 직장 사이를 정기적으로 오가는 것, 곧 통근이에요. 이사한 뒤 새 어린이집까지 10분이라는 말과 '날마다 거의 두 시간'이라는 말에서 지금의 출퇴근 길이 멀다는 것을 알 수 있어요. 반을 옮겨 다니는 일도, 딸을 학교에 데려다주는 일도 아니에요. 딸은 가을에야 학교에 들어가요."},{"type":"mc","kind":"inference","q":"Warum bittet der Bewerber wahrscheinlich um ein Gespräch über flexible Arbeitszeiten?","options":["Er hält 30 Wochenstunden für zu wenig und möchte deutlich mehr Stunden arbeiten.","Wechselnde Dienstzeiten passen schlecht zu seinem Alltag mit der Tochter.","Er möchte am Probearbeitstag früher gehen, um seine Tochter abzuholen."],"answer":1,"evidence":"Mit Rücksicht auf meine Tochter hätte ich zudem eine Bitte","pairs":[["die Bereitschaft zum Schichtdienst","Wechselnde Dienstzeiten"],["Mit Rücksicht auf meine Tochter","zu seinem Alltag mit der Tochter"]],"explain":"광고는 교대 근무(Schichtdienst)를 할 수 있는 사람을 찾고, 지원자는 딸을 생각해서(Mit Rücksicht auf meine Tochter) 유연한 근무 시간을 부탁해요. 그래서 바뀌는 근무 시간이 딸을 돌보는 일과 잘 맞지 않을 수 있다고 추론할 수 있어요. 근무 시간을 늘리고 싶다거나 체험 근무일에 일찍 가겠다는 말은 없어요."}],"grammar":[{"title":"전치사와 함께 쓰는 명사","term":"Nomen mit festen Präpositionen (Erfahrung in, Freude an, Bereitschaft zu, Rücksicht auf)","explain":"Erfahrung, Freude, Bereitschaft, Rücksicht 같은 명사는 정해진 전치사와 함께 써요. 격은 그 전치사가 정해요. Erfahrung in + 3격, Freude an + 3격, Bereitschaft zu + 3격, Rücksicht auf + 4격이에요. 형용사나 동사에서 온 명사는 원래 말의 전치사를 그대로 쓰는 경우가 많아요(bereit zu → die Bereitschaft zu). zum은 zu + dem이에요.","pattern":"명사 + 정해진 전치사 + 명사(격은 전치사가 정함)","examples":[{"de":"Eine abgeschlossene Ausbildung als Kinderpflegerin oder Kinderpfleger, Erfahrung in der Betreuung von Kleinkindern, Freude an kreativen Angeboten und die Bereitschaft zum Schichtdienst.","ko":"보육 보조 교사 과정을 마친 분, 어린아이를 돌본 경험이 있는 분, 창의적인 활동을 즐기시는 분, 교대 근무를 기꺼이 하실 분을 찾습니다.","mark":["Erfahrung in der Betreuung","Freude an kreativen Angeboten","Bereitschaft zum Schichtdienst"]},{"de":"Mit Rücksicht auf meine Tochter hätte ich zudem eine Bitte: Könnten wir auch über flexible Arbeitszeiten sprechen?","ko":"또 딸을 생각해서 한 가지 부탁을 드리고 싶습니다. 유연한 근무 시간에 대해서도 이야기를 나눌 수 있을까요?","mark":["Mit Rücksicht auf meine Tochter"],"parts":[["Mit Rücksicht auf meine Tochter","부사어(이유)"],["hätte","동사"],["ich","주어"],["zudem","접속부사"],["eine Bitte:","4격 목적어"],["Könnten","동사"],["wir","주어"],["auch","기타"],["über flexible Arbeitszeiten","전치사 목적어"],["sprechen?","동사(끝)"]]}],"tip":"전치사까지 한 덩어리로 외우세요. 'Freude an der Arbeit'를 'Freude für die Arbeit'처럼 쓰면 틀려요. mit Rücksicht auf + 4격은 '~을 생각해서, ~을 고려해서'라는 뜻이에요."},{"title":"statt … zu: ~하는 대신","term":"Infinitivgruppe mit statt … zu","explain":"statt … zu는 '~하는 대신'이라는 뜻으로, 보통 하거나 기대되는 일 대신 다른 일을 한다는 것을 나타내요. zu + 동사원형은 부정사구의 끝에 오고, 분리동사는 zu가 앞말과 동사 사이에 들어가요(aufzugreifen). 부정사구가 문장 맨 앞에 오면 쉼표 바로 뒤에 주문장의 동사가 와요(Statt …, versuche ich …). 부정사구에는 주어가 없고, 주문장의 주어가 그 행동도 해요.","pattern":"Statt + … + zu + 동사원형, + 동사 + 주어 …  ·  주어 + 동사 …, statt … zu + 동사원형","examples":[{"de":"Statt die Kinder nur zu beaufsichtigen, versuche ich, ihre eigenen Ideen aufzugreifen und gemeinsam mit ihnen umzusetzen.","ko":"저는 아이들을 그저 지켜보기만 하지 않고, 아이들의 생각을 받아들여 아이들과 함께 실현해 보려고 합니다.","mark":["Statt","zu beaufsichtigen"],"parts":[["Statt die Kinder nur zu beaufsichtigen,","zu 부정사구"],["versuche","동사"],["ich,","주어"],["ihre eigenen Ideen aufzugreifen und gemeinsam mit ihnen umzusetzen.","zu 부정사구"]]},{"de":"Statt täglich fast zwei Stunden zu pendeln, hätte ich somit mehr Zeit für meine Tochter, die im Herbst eingeschult wird.","ko":"그러면 날마다 거의 두 시간씩 통근하는 대신, 가을에 초등학교에 입학하는 딸과 더 많은 시간을 보낼 수 있을 것입니다.","mark":["Statt","zu pendeln","hätte"],"parts":[["Statt täglich fast zwei Stunden zu pendeln,","zu 부정사구"],["hätte","동사"],["ich","주어"],["somit","접속부사"],["mehr Zeit","4격 목적어"],["für meine Tochter,","부사어"],["die im Herbst eingeschult wird.","관계절"]]}],"tip":"두 번째 예문처럼 주문장에 접속법 2식(hätte)이 오면, 지금은 그렇지 않지만 새 직장으로 옮기면 그렇게 될 것이라는 가정의 뜻이 돼요. statt … zu pendeln과 함께 읽으면 지금은 날마다 거의 두 시간을 통근하고 있다는 것도 알 수 있어요."},{"title":"공손한 부탁과 소망: 접속법 2식","term":"Konjunktiv II für höfliche Bitten und Wünsche (würde, könnte, hätte, wäre)","explain":"지원서 같은 공식 편지에서는 부탁과 소망을 접속법 2식으로 말하면 더 정중하게 들려요. Könnten wir …?는 Können wir …?보다 부드러운 질문이고, Ich würde mich freuen, wenn … könnte는 '~할 수 있다면 기쁘겠어요'라는 소망이에요. 이때 wenn 절에도 접속법 2식(könnte)을 써요. haben과 sein은 보통 würde + 동사원형 대신 hätte와 wäre를 써요. 그래서 '부탁이 하나 있어요'는 Ich hätte eine Bitte, '감사하겠어요'는 Ich wäre Ihnen dankbar가 돼요.","pattern":"Ich würde mich freuen, wenn … könnte  ·  Ich hätte eine Bitte  ·  Könnten wir … + 동사원형?  ·  Für + 4격 + wäre ich Ihnen dankbar","examples":[{"de":"Ich würde mich sehr freuen, wenn ich Ihr Team bei einem Probearbeitstag kennenlernen könnte.","ko":"체험 근무일에 귀 팀을 만나 볼 수 있다면 정말 기쁘겠습니다.","mark":["würde","freuen","könnte"],"parts":[["Ich","주어"],["würde","동사"],["mich","재귀대명사"],["sehr","부사어(방법)"],["freuen,","동사(끝)"],["wenn ich Ihr Team bei einem Probearbeitstag kennenlernen könnte.","종속절"]]},{"de":"Mit Rücksicht auf meine Tochter hätte ich zudem eine Bitte: Könnten wir auch über flexible Arbeitszeiten sprechen?","ko":"또 딸을 생각해서 한 가지 부탁을 드리고 싶습니다. 유연한 근무 시간에 대해서도 이야기를 나눌 수 있을까요?","mark":["hätte","Könnten"]},{"de":"Für eine Einladung zu einem persönlichen Vorstellungsgespräch wäre ich Ihnen sehr dankbar.","ko":"대면 면접에 초대해 주시면 대단히 감사하겠습니다.","mark":["wäre","dankbar"],"parts":[["Für eine Einladung zu einem persönlichen Vorstellungsgespräch","전치사 목적어"],["wäre","동사"],["ich","주어"],["Ihnen","3격 목적어"],["sehr dankbar.","보어"]]}],"tip":"'Ich habe eine Bitte'나 'Können wir …?'도 틀린 말은 아니에요. 다만 지원서에서는 접속법 2식이 더 정중하게 들려요. 'Ich würde mich freuen, wenn …' 뒤의 wenn 절에서도 könnte, hätte, wäre 같은 접속법 2식을 쓰는 것이 자연스러워요."},{"title":"전치사가 붙는 관계절","term":"Relativsatz mit Präposition","explain":"관계절 안의 동사나 표현이 전치사를 필요로 하면, 그 전치사가 관계대명사 바로 앞에 와요. 관계대명사의 성과 수는 앞의 명사에 맞추고, 격은 전치사가 정해요. über etwas hören은 4격(über die), in + 장소는 3격(in der), 화단 위처럼 auf + 장소도 3격(auf dem), sich auf etwas bewerben은 4격(auf die)이에요. 관계절의 동사는 끝에 와요.","pattern":"선행사, + 전치사 + 관계대명사 + … + 동사(끝),","examples":[{"de":"Die Kita „Sonnenhof“, über die ich bereits viel Gutes gehört habe, ist genau die Einrichtung, in der ich mich beruflich weiterentwickeln möchte.","ko":"이미 좋은 이야기를 많이 들은 „존넨호프“ 어린이집은 제가 직업적으로 더 성장하고 싶은 바로 그런 곳입니다.","mark":["über die","in der"],"parts":[["Die Kita „Sonnenhof“,","주어"],["über die ich bereits viel Gutes gehört habe,","관계절"],["ist","동사"],["genau die Einrichtung,","보어"],["in der ich mich beruflich weiterentwickeln möchte.","관계절"]]},{"de":"in der Wochenendausgabe der Stadtzeitung bin ich auf Ihre Anzeige aufmerksam geworden, auf die ich mich hiermit als Kinderpfleger bewerbe.","ko":"지역 신문 주말판에서 귀 어린이집의 공고를 보았고, 이렇게 보육 보조 교사로 지원합니다.","mark":["auf die"]},{"de":"So haben wir im Sommer auf Wunsch der Kinder ein Beet angelegt, auf dem sie selbst Tomaten und Kräuter gepflanzt haben.","ko":"예를 들어 지난여름에는 아이들이 원해서 화단을 만들었고, 아이들이 직접 그곳에 토마토와 허브를 심었습니다.","mark":["auf dem"]}],"tip":"관계대명사 앞의 전치사는 빼면 안 돼요. 'die Einrichtung, die ich arbeiten möchte'는 틀린 문장이고, 'die Einrichtung, in der ich arbeiten möchte'라고 써야 해요."}],"vocab":[{"de":"die Kita, -s","ko":"어린이집(Kindertagesstätte의 줄임말)"},{"de":"der Elternverein, -e","ko":"학부모회"},{"de":"sanieren","ko":"(건물을) 보수하다, 새로 고치다"},{"de":"die Begleitung (Sg.)","ko":"곁에서 도와줌, 동행"},{"de":"die Durchführung, -en","ko":"실행, 진행"},{"de":"erfolgen (ist erfolgt)","ko":"이루어지다, 행해지다"},{"de":"die Bereitschaft (Sg.)","ko":"(기꺼이 하려는) 마음가짐"},{"de":"der Schichtdienst, -e","ko":"교대 근무"},{"de":"unbefristet","ko":"기한이 없는, 무기한의"},{"de":"die Vergütung, -en","ko":"보수, 급여"},{"de":"die Einarbeitung, -en","ko":"업무 적응 교육"},{"de":"sich bewerben (bewirbt sich, bewarb sich, hat sich beworben) + auf/um + Akk.","ko":"지원하다"},{"de":"beaufsichtigen","ko":"감독하다, 지켜보다"},{"de":"auf|greifen (greift auf, griff auf, hat aufgegriffen)","ko":"(생각을) 받아들여 다루다"},{"de":"pendeln (ist gependelt)","ko":"통근하다"},{"de":"ein|schulen (schult ein, schulte ein, hat eingeschult)","ko":"학교에 입학시키다"}],"phrases":[{"de":"auf etwas (Akk.) aufmerksam werden","ko":"~을 알게 되다, ~이 눈에 띄다","ex":"in der Wochenendausgabe der Stadtzeitung bin ich auf Ihre Anzeige aufmerksam geworden, auf die ich mich hiermit als Kinderpfleger bewerbe.","exko":"지역 신문 주말판에서 귀 어린이집의 공고를 보았고, 이렇게 보육 보조 교사로 지원합니다."},{"de":"jemandem zur Verfügung stehen","ko":"~에게 도움을 줄 수 있다, (문의 등에) 응하다","ex":"Ihre Bewerbungsunterlagen senden Sie bitte bis zum 15. Oktober an unsere Leiterin, Frau Lindner, die Ihnen bei Rückfragen gern zur Verfügung steht.","exko":"지원 서류는 10월 15일까지 원장인 린트너 씨에게 보내 주시기 바랍니다. 문의할 점이 있으면 린트너 씨가 기꺼이 답해 드립니다."},{"de":"auf Wunsch (+ Gen.)","ko":"~의 요청으로, ~가 원해서","ex":"So haben wir im Sommer auf Wunsch der Kinder ein Beet angelegt, auf dem sie selbst Tomaten und Kräuter gepflanzt haben.","exko":"예를 들어 지난여름에는 아이들이 원해서 화단을 만들었고, 아이들이 직접 그곳에 토마토와 허브를 심었습니다."},{"de":"Verantwortung übernehmen","ko":"책임을 맡다","ex":"Meine jetzige Stelle möchte ich wechseln, um mehr Verantwortung zu übernehmen.","exko":"저는 더 많은 책임을 맡고 싶어서 지금 직장을 옮기려고 합니다."},{"de":"mit Rücksicht auf (+ Akk.)","ko":"~을 생각해서, ~을 고려해서","ex":"Mit Rücksicht auf meine Tochter hätte ich zudem eine Bitte","exko":"또 딸을 생각해서 한 가지 부탁을 드리고 싶습니다"}],"words":351},{"id":"b1-13","level":"B1","no":13,"title":"Protokoll der Mieterversammlung","titleKo":"세입자 총회 회의록","type":"Ergebnisprotokoll","typeKo":"회의록(결과 중심)","intro":"한 주택 단지 세입자들이 모여 건물 문제를 논의한 회의를 기록한 글이에요.","focus":["화법조동사 + 수동태","dass 절로 말 전하기","obwohl","명사 뒤의 2격"],"paragraphs":[{"style":"meta","de":"Mieterversammlung der Wohnanlage Ahornweg 3–7","ko":"아호른베크 3–7번지 주택 단지 세입자 총회"},{"style":"meta","de":"12. März 2026, 19.00 bis 20.40 Uhr, Gemeinschaftsraum in Haus 5","ko":"2026년 3월 12일, 19시~20시 40분, 5동 공용실"},{"style":"meta","de":"Anwesend sind 24 Mieter sowie Herr Kaya von der Hausverwaltung; die Versammlung leitet Renate Vogt vom Mieterbeirat, das Protokoll führt Jan Petersen.","ko":"참석자는 세입자 24명과 관리사무소의 카야 씨입니다. 진행은 세입자 대표회의 레나테 포크트 씨가 맡고, 기록은 얀 페테르센 씨가 맡습니다."},{"style":"h","de":"TOP 1 – Reparatur des Aufzugs in Haus 5","ko":"안건 1 – 5동 엘리베이터 수리"},{"de":"Der Aufzug ist seit dem 20. Februar wegen eines defekten Motors außer Betrieb, und obwohl er erst im Oktober gewartet wurde, muss der Motor nun ausgetauscht werden. Herr Kaya berichtet, dass die Herstellerfirma das Ersatzteil erst Mitte März liefern kann; eingebaut werden soll es in der letzten Märzwoche. Frau Demir weist darauf hin, dass mehrere ältere Mieter ihre Wohnungen seit Wochen kaum verlassen, und drei Mieter erklären sich bereit, bis zur Reparatur für sie einzukaufen.","ko":"엘리베이터는 모터 고장으로 2월 20일부터 운행이 멈춘 상태이며, 지난 10월에 점검을 받은 지 얼마 되지 않았는데도 이제 모터를 교체해야 합니다. 카야 씨는 제조사가 부품을 3월 중순에야 납품할 수 있다고 보고합니다. 부품은 3월 마지막 주에 설치할 예정입니다. 데미르 씨는 나이 든 세입자 여러 명이 몇 주째 거의 집 밖에 나가지 않는다고 지적하고, 세입자 세 명이 수리가 끝날 때까지 이분들 대신 장을 보겠다고 나섭니다."},{"de":"Ergebnis: Die Hausverwaltung gibt den Einbautermin per Aushang bekannt.","ko":"결과: 관리사무소가 설치 날짜를 게시판에 공지합니다."},{"style":"h","de":"TOP 2 – Feuchtigkeit im Keller von Haus 3","ko":"안건 2 – 3동 지하실 습기"},{"de":"Seit dem Winter riecht es im Keller stark nach Schimmel, obwohl die Mieter der Hausverwaltung den Schaden bereits im Dezember gemeldet haben. Herr Kaya bittet um Verständnis, weil lange kein Fachbetrieb verfügbar war. Herr Brenner kritisiert die Wartezeit trotzdem deutlich. Laut Herrn Kaya muss zunächst die Ursache der Feuchtigkeit geklärt werden; deshalb soll der Keller am 2. April von einem Gutachter untersucht werden.","ko":"세입자들이 이미 12월에 관리사무소에 신고했는데도 겨울부터 지하실에서 곰팡이 냄새가 심하게 납니다. 카야 씨는 오랫동안 일을 맡을 수 있는 전문 업체가 없었다며 양해를 구합니다. 그런데도 브레너 씨는 오래 기다리게 한 점을 분명하게 비판합니다. 카야 씨에 따르면 먼저 습기의 원인을 밝혀야 하며, 그래서 4월 2일에 감정인이 지하실을 조사할 예정입니다."},{"de":"Ergebnis: Bis zur Untersuchung dürfen im Keller keine Kartons, Bücher oder Kleidungsstücke gelagert werden. Außerdem muss der Keller täglich gelüftet werden; diese Aufgabe übernimmt der Hausmeister.","ko":"결과: 조사 전까지 지하실에 상자, 책, 옷가지를 보관하면 안 됩니다. 또 지하실은 날마다 환기해야 하며, 이 일은 관리인이 맡습니다."},{"style":"h","de":"TOP 3 – Fahrräder im Innenhof","ko":"안건 3 – 안뜰의 자전거"},{"de":"Im Innenhof stehen mehr Fahrräder, als Stellplätze vorhanden sind, und manche davon werden offenbar seit Jahren nicht mehr benutzt. Frau Vogt schlägt deshalb vor, dass im April alle Fahrräder mit einem roten Band markiert werden. Wer sein Fahrrad noch benutzt, nimmt das Band ab; Fahrräder, die nach vier Wochen noch markiert sind, dürfen vom Hausmeister entfernt werden. Einige Anwesende finden den Vorschlag umständlich, stimmen aber trotzdem zu.","ko":"안뜰에는 주차 공간보다 자전거가 더 많고, 그중 일부는 몇 년째 아무도 타지 않는 것으로 보입니다. 그래서 포크트 씨는 4월에 모든 자전거에 빨간 띠를 달아 표시하자고 제안합니다. 자기 자전거를 아직 타는 사람은 그 띠를 떼고, 4주가 지나도 띠가 그대로 달려 있는 자전거는 관리인이 치워도 됩니다. 몇몇 참석자는 이 제안이 번거롭다고 생각하지만, 그래도 찬성합니다."},{"de":"Ergebnis: Der Vorschlag wird mit 21 Ja-Stimmen bei drei Enthaltungen angenommen; Herr Kaya sagt zu, dass die Hausverwaltung die Kosten eines zweiten Fahrradständers prüft.","ko":"결과: 찬성 21표, 기권 3표로 제안이 가결됩니다. 카야 씨는 관리사무소가 두 번째 자전거 거치대의 비용을 검토하겠다고 약속합니다."},{"style":"h","de":"TOP 4 – Verschiedenes","ko":"안건 4 – 기타"},{"de":"Das Sommerfest der Hausgemeinschaft findet am 27. Juni im Innenhof statt; die nächste Versammlung soll am 18. Juni um 19 Uhr stattfinden.","ko":"단지 주민 여름 축제는 6월 27일 안뜰에서 열리고, 다음 총회는 6월 18일 19시에 열릴 예정입니다."},{"style":"meta","de":"Jan Petersen, Protokollführer, 13. März 2026","ko":"얀 페테르센(기록 담당), 2026년 3월 13일"}],"questions":[{"type":"rf","kind":"detail","q":"Der Motor des Aufzugs ist kaputt, obwohl man die Anlage vor wenigen Monaten kontrolliert hat.","answer":0,"evidence":"und obwohl er erst im Oktober gewartet wurde, muss der Motor nun ausgetauscht werden","pairs":[["gewartet wurde","kontrolliert hat"],["erst im Oktober","vor wenigen Monaten"],["wegen eines defekten Motors","Der Motor des Aufzugs ist kaputt"]],"explain":"엘리베이터는 지난 10월에 점검을 받았는데(gewartet), 3월에 열린 이 회의 때 모터가 고장 나 있어요. 그래서 '몇 달 전에 점검했는데도 모터가 고장 났다'는 진술은 맞아요. 'warten'을 'kontrollieren'으로, 'defekter Motor'를 'kaputt'로, 'erst im Oktober'를 'vor wenigen Monaten'으로 바꿔 말했어요."},{"type":"mc","kind":"detail","q":"Wie werden die älteren Bewohner versorgt, bis das Ersatzteil eingebaut ist?","options":["Frau Demir übernimmt bis Ende März allein alle Einkäufe für sie.","Drei Mitbewohner gehen bis dahin an ihrer Stelle einkaufen.","Die Herstellerfirma liefert ihnen bis Mitte März ihr Essen."],"answer":1,"evidence":"drei Mieter erklären sich bereit, bis zur Reparatur für sie einzukaufen","pairs":[["drei Mieter","Drei Mitbewohner"],["bis zur Reparatur","bis dahin"],["für sie einzukaufen","an ihrer Stelle einkaufen"]],"explain":"세입자 세 명이 수리가 끝날 때까지 나이 든 세입자들 대신 장을 보겠다고 나서요. 'drei Mieter'를 'drei Mitbewohner'로, 'für sie einzukaufen'을 'an ihrer Stelle einkaufen'으로 바꿔 말했어요. 데미르 씨는 문제를 알렸을 뿐 혼자 장을 보지 않고, 제조사가 3월 중순에 보내는 것은 음식이 아니라 부품이에요."},{"type":"rf","kind":"detail","q":"Der Geruch im Keller ist der Hausverwaltung erst seit ein paar Tagen bekannt.","answer":1,"evidence":"obwohl die Mieter der Hausverwaltung den Schaden bereits im Dezember gemeldet haben","pairs":[["bereits im Dezember gemeldet","erst seit ein paar Tagen bekannt"]],"explain":"세입자들은 이미 12월에 관리사무소에 문제를 신고했어요. 회의는 3월이니 관리사무소는 이미 몇 달 전부터 이 문제를 알고 있었어요. 'Hausverwaltung'과 'erst'는 본문에 나오는 낱말이지만, '며칠 전부터'라는 말은 본문과 맞지 않아요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Herr Brenner kritisiert die Wartezeit trotzdem deutlich.“?","options":["Herr Brenner findet die Erklärung überzeugend und ist zufrieden.","Herr Brenner ärgert sich, weil Herr Kaya den Schaden zu spät gemeldet hat.","Herrn Kayas Begründung ändert nichts an Herrn Brenners Unzufriedenheit."],"answer":2,"evidence":"Herr Brenner kritisiert die Wartezeit trotzdem deutlich.","pairs":[["trotzdem","ändert nichts an"],["kritisiert","Unzufriedenheit"],["weil lange kein Fachbetrieb verfügbar war","Herrn Kayas Begründung"]],"explain":"trotzdem은 앞 문장, 곧 카야 씨가 전문 업체가 없었다며 양해를 구한 일과 반대되는 결과를 말해요. 그 설명을 들었는데도 브레너 씨는 오래 기다린 것을 비판해요. 그래서 '설명이 브레너 씨의 불만을 바꾸지 못했다'가 맞아요. 브레너 씨는 만족하지 않았어요. 또 피해를 신고한 사람은 카야 씨가 아니라 세입자들이에요."},{"type":"mc","kind":"detail","q":"Was gilt bis zur Untersuchung für den Keller?","options":["Vorerst darf man dort nicht alles lagern, und der Hausmeister lüftet täglich.","Jeder Mieter muss ab sofort jeden Tag selbst sein Kellerabteil lüften.","Der Hausmeister darf den Keller bis zur Untersuchung gar nicht mehr betreten."],"answer":0,"evidence":"Bis zur Untersuchung dürfen im Keller keine Kartons, Bücher oder Kleidungsstücke gelagert werden.","pairs":[["dürfen im Keller keine Kartons, Bücher oder Kleidungsstücke gelagert werden","darf man dort nicht alles lagern"],["muss der Keller täglich gelüftet werden; diese Aufgabe übernimmt der Hausmeister","der Hausmeister lüftet täglich"]],"explain":"조사 전까지 지하실에 상자, 책, 옷가지는 보관하면 안 되고, 날마다 환기를 하는데 그 일은 관리인이 맡아요. 몇 가지 물건을 금지한 'keine Kartons, Bücher oder Kleidungsstücke gelagert werden'을 'nicht alles lagern'으로, 수동태 'täglich gelüftet werden'을 능동태 'der Hausmeister lüftet täglich'로 바꿔 말했어요. 세입자가 직접 환기하는 것이 아니고, 관리인은 오히려 날마다 지하실에 들어가야 해요."},{"type":"mc","kind":"meaning","q":"Was bedeutet „umständlich“ im Text?","options":["für die Hausgemeinschaft viel zu teuer","ungerecht gegenüber allen Radfahrern","kompliziert und mit Aufwand verbunden"],"answer":2,"evidence":"Einige Anwesende finden den Vorschlag umständlich, stimmen aber trotzdem zu.","pairs":[["umständlich","kompliziert und mit Aufwand verbunden"]],"explain":"umständlich는 '번거롭다, 복잡하고 손이 많이 간다'는 뜻이에요. 모든 자전거에 띠를 달고, 타는 사람이 다시 떼고, 4주를 기다려야 하니 절차가 번거로워요. 비용이나 공정성에 관한 말은 이 문장에 없어요."},{"type":"mc","kind":"inference","q":"Was kann man aus dem Ergebnis der Abstimmung schließen?","options":["Keiner der Anwesenden hat gegen den Plan von Frau Vogt gestimmt.","Alle Anwesenden finden den Vorschlag einfach und praktisch.","Die Hausverwaltung muss jetzt sofort einen zweiten Ständer kaufen."],"answer":0,"evidence":"Der Vorschlag wird mit 21 Ja-Stimmen bei drei Enthaltungen angenommen","pairs":[["21 Ja-Stimmen bei drei Enthaltungen","Keiner der Anwesenden hat gegen den Plan von Frau Vogt gestimmt"],["Anwesend sind 24 Mieter","Keiner der Anwesenden"]],"explain":"참석한 세입자는 24명이고, 찬성 21표에 기권 3표예요. 21 + 3 = 24이니 반대한 사람은 없어요. 몇몇 참석자는 이 제안이 번거롭다고 했으니 모두가 쉽다고 생각한 것은 아니에요. 관리사무소는 두 번째 거치대의 비용을 검토하겠다고 했을 뿐 당장 사야 하는 것은 아니에요."},{"type":"mc","kind":"gist","q":"Welche Aufgabe hat dieser Text vor allem?","options":["Er lädt alle Hausbewohner zum Sommerfest Ende Juni in den Innenhof ein.","Er hält fest, was beim Treffen besprochen und beschlossen wurde.","Er beschwert sich bei der Hausverwaltung über den Zustand des Kellers."],"answer":1,"evidence":"Mieterversammlung der Wohnanlage Ahornweg 3–7","pairs":[["Ergebnis","beschlossen wurde"],["Mieterversammlung","beim Treffen"]],"explain":"이 글은 회의록(Protokoll)이에요. 안건마다 논의한 내용과 결과(Ergebnis)를 적어 두어요. 여름 축제는 '기타' 안건의 한 가지 알림일 뿐이고, 지하실 문제에 대한 불만도 회의에서 나온 의견 가운데 하나로 기록되어 있을 뿐이에요."}],"grammar":[{"title":"화법조동사 + 수동태","term":"Passiv mit Modalverb","explain":"누가 하는지보다 무엇을 해야 하는지, 해도 되는지가 중요할 때 화법조동사와 수동태를 함께 써요. 형태는 화법조동사 + 과거분사 + werden이에요. 주문장에서는 화법조동사가 2번째 자리에 오고, 과거분사와 werden은 문장 끝에 와요. 회의록에서는 결정된 일과 규칙을 이렇게 객관적으로 적는 경우가 많아요. 행위자를 말할 때는 von + 3격을 써요(von einem Gutachter).","pattern":"주어 + 화법조동사 + … + 과거분사 + werden(끝)","examples":[{"de":"Bis zur Untersuchung dürfen im Keller keine Kartons, Bücher oder Kleidungsstücke gelagert werden.","ko":"조사 전까지 지하실에 상자, 책, 옷가지를 보관하면 안 됩니다.","mark":["dürfen","gelagert werden"],"parts":[["Bis zur Untersuchung","부사어(시간)"],["dürfen","동사"],["im Keller","부사어(장소)"],["keine Kartons, Bücher oder Kleidungsstücke","주어"],["gelagert werden.","동사(끝)"]]},{"de":"Laut Herrn Kaya muss zunächst die Ursache der Feuchtigkeit geklärt werden; deshalb soll der Keller am 2. April von einem Gutachter untersucht werden.","ko":"카야 씨에 따르면 먼저 습기의 원인을 밝혀야 하며, 그래서 4월 2일에 감정인이 지하실을 조사할 예정입니다.","mark":["muss","geklärt werden","soll","untersucht werden"]},{"de":"Herr Kaya berichtet, dass die Herstellerfirma das Ersatzteil erst Mitte März liefern kann; eingebaut werden soll es in der letzten Märzwoche.","ko":"카야 씨는 제조사가 부품을 3월 중순에야 납품할 수 있다고 보고합니다. 부품은 3월 마지막 주에 설치할 예정입니다.","mark":["eingebaut werden soll"]}],"tip":"세 번째 예문처럼 과거분사와 werden을 문장 맨 앞으로 보내 강조할 수도 있어요(Eingebaut werden soll es …). 이때도 화법조동사는 2번째 자리에 있어요."},{"title":"dass 절로 남의 말 전하기","term":"Redewiedergabe mit dass-Sätzen (berichten, hinweisen, vorschlagen, zusagen)","explain":"회의록에서는 참석자가 한 말을 berichten, darauf hinweisen, vorschlagen, zusagen 같은 동사 + dass 절로 전해요. dass 절에서는 동사가 끝에 오고, 화법조동사가 있으면 그것이 맨 끝에 와요(liefern kann). 이 회의록에서는 dass 절의 동사를 직설법 현재로 썼어요(liefern kann, verlassen). 어떤 동사를 쓰는지에 따라 그 말이 보고인지, 주의를 주는 말인지, 제안인지, 약속인지가 드러나요.","pattern":"주어 + berichtet / weist darauf hin / schlägt vor / sagt zu, + dass + … + 동사(끝)","examples":[{"de":"Frau Vogt schlägt deshalb vor, dass im April alle Fahrräder mit einem roten Band markiert werden.","ko":"그래서 포크트 씨는 4월에 모든 자전거에 빨간 띠를 달아 표시하자고 제안합니다.","mark":["schlägt","vor, dass"],"parts":[["Frau Vogt","주어"],["schlägt","동사"],["deshalb","접속부사"],["vor,","동사(끝)"],["dass im April alle Fahrräder mit einem roten Band markiert werden.","종속절"]]},{"de":"Frau Demir weist darauf hin, dass mehrere ältere Mieter ihre Wohnungen seit Wochen kaum verlassen, und drei Mieter erklären sich bereit, bis zur Reparatur für sie einzukaufen.","ko":"데미르 씨는 나이 든 세입자 여러 명이 몇 주째 거의 집 밖에 나가지 않는다고 지적하고, 세입자 세 명이 수리가 끝날 때까지 이분들 대신 장을 보겠다고 나섭니다.","mark":["weist darauf hin, dass"]},{"de":"Ergebnis: Der Vorschlag wird mit 21 Ja-Stimmen bei drei Enthaltungen angenommen; Herr Kaya sagt zu, dass die Hausverwaltung die Kosten eines zweiten Fahrradständers prüft.","ko":"결과: 찬성 21표, 기권 3표로 제안이 가결됩니다. 카야 씨는 관리사무소가 두 번째 자전거 거치대의 비용을 검토하겠다고 약속합니다.","mark":["sagt zu, dass"]}],"tip":"darauf hinweisen에서 darauf는 뒤에 오는 dass 절을 미리 가리키는 말이에요. berichten은 사실을 알리고, hinweisen은 주의를 끌고, zusagen은 앞으로 하겠다고 약속하는 말이에요."},{"title":"obwohl: 기대와 다른 사실","term":"Konzessivsatz mit obwohl","explain":"obwohl은 '~인데도'라는 뜻의 종속접속사예요. obwohl 절에는 어떤 결과를 예상하게 하는 사실이 오고, 주문장에는 그 예상과 다른 결과가 와요. obwohl 절에서는 동사가 끝에 와요. obwohl 절이 문장 앞에 오면 쉼표 바로 뒤에 주문장의 동사가 와요(obwohl er …, muss der Motor …).","pattern":"obwohl + … + 동사(끝), + 동사 + 주어 …  ·  주문장, obwohl + … + 동사(끝)","examples":[{"de":"Der Aufzug ist seit dem 20. Februar wegen eines defekten Motors außer Betrieb, und obwohl er erst im Oktober gewartet wurde, muss der Motor nun ausgetauscht werden.","ko":"엘리베이터는 모터 고장으로 2월 20일부터 운행이 멈춘 상태이며, 지난 10월에 점검을 받은 지 얼마 되지 않았는데도 이제 모터를 교체해야 합니다.","mark":["obwohl","gewartet wurde","muss"],"parts":[["Der Aufzug","주어"],["ist","동사"],["seit dem 20. Februar","부사어(시간)"],["wegen eines defekten Motors","부사어(이유)"],["außer Betrieb,","보어"],["und","접속사"],["obwohl er erst im Oktober gewartet wurde,","종속절"],["muss","동사"],["der Motor","주어"],["nun","부사어(시간)"],["ausgetauscht werden.","동사(끝)"]]},{"de":"Seit dem Winter riecht es im Keller stark nach Schimmel, obwohl die Mieter der Hausverwaltung den Schaden bereits im Dezember gemeldet haben.","ko":"세입자들이 이미 12월에 관리사무소에 신고했는데도 겨울부터 지하실에서 곰팡이 냄새가 심하게 납니다.","mark":["obwohl","gemeldet haben"]}],"tip":"같은 관계를 주문장 두 개로 말할 수도 있어요. 그때는 두 번째 문장에 trotzdem을 써요(Einige Anwesende finden den Vorschlag umständlich, stimmen aber trotzdem zu)."},{"title":"명사 뒤의 2격","term":"Genitivattribut","explain":"명사 뒤에 2격 명사를 붙이면 '~의'라는 뜻이 돼요. 남성·중성 명사는 des/eines + 명사-(e)s(des Aufzugs, eines zweiten Fahrradständers), 여성 명사와 복수는 der(der Feuchtigkeit, der Hausgemeinschaft)를 써요. 회의록 제목이나 결과처럼 짧고 정확하게 써야 하는 글에서 자주 나와요. 2격에서 관사 뒤에 오는 형용사는 -en으로 끝나요(eines zweiten Fahrradständers).","pattern":"명사 + des/eines … -(e)s  ·  명사 + der/einer … (여성·복수)","examples":[{"de":"Das Sommerfest der Hausgemeinschaft findet am 27. Juni im Innenhof statt; die nächste Versammlung soll am 18. Juni um 19 Uhr stattfinden.","ko":"단지 주민 여름 축제는 6월 27일 안뜰에서 열리고, 다음 총회는 6월 18일 19시에 열릴 예정입니다.","mark":["Das Sommerfest der Hausgemeinschaft"],"parts":[["Das Sommerfest der Hausgemeinschaft","주어"],["findet","동사"],["am 27. Juni","부사어(시간)"],["im Innenhof","부사어(장소)"],["statt;","동사(끝)"],["die nächste Versammlung","주어"],["soll","동사"],["am 18. Juni um 19 Uhr","부사어(시간)"],["stattfinden.","동사(끝)"]]},{"de":"TOP 1 – Reparatur des Aufzugs in Haus 5","ko":"안건 1 – 5동 엘리베이터 수리","mark":["Reparatur des Aufzugs"]},{"de":"Laut Herrn Kaya muss zunächst die Ursache der Feuchtigkeit geklärt werden; deshalb soll der Keller am 2. April von einem Gutachter untersucht werden.","ko":"카야 씨에 따르면 먼저 습기의 원인을 밝혀야 하며, 그래서 4월 2일에 감정인이 지하실을 조사할 예정입니다.","mark":["die Ursache der Feuchtigkeit"]}],"tip":"2격 명사는 수식하는 명사 뒤에 와요. 한국어의 '습기의 원인'과 순서가 반대라서 die Ursache der Feuchtigkeit는 뒤에서부터 읽으면 쉬워요."}],"vocab":[{"de":"die Mieterversammlung, -en","ko":"세입자 총회"},{"de":"die Hausverwaltung, -en","ko":"(건물) 관리사무소"},{"de":"der Aufzug, -¨e","ko":"엘리베이터"},{"de":"warten (eine Anlage)","ko":"(기계·설비를) 점검하다, 정비하다"},{"de":"aus|tauschen","ko":"교체하다"},{"de":"das Ersatzteil, -e","ko":"교체 부품"},{"de":"ein|bauen","ko":"설치하다"},{"de":"der Aushang, -¨e","ko":"게시물, 게시판 공지"},{"de":"der Schimmel (Sg.)","ko":"곰팡이"},{"de":"die Feuchtigkeit (Sg.)","ko":"습기"},{"de":"der Fachbetrieb, -e","ko":"전문 업체"},{"de":"der Gutachter, -","ko":"감정인, 전문 평가자"},{"de":"lagern","ko":"보관하다, 쌓아 두다"},{"de":"lüften","ko":"환기하다"},{"de":"umständlich","ko":"번거로운, 복잡한"},{"de":"die Enthaltung, -en","ko":"(투표의) 기권"}],"phrases":[{"de":"außer Betrieb sein","ko":"운행·작동이 멈춰 있다","ex":"Der Aufzug ist seit dem 20. Februar wegen eines defekten Motors außer Betrieb, und obwohl er erst im Oktober gewartet wurde, muss der Motor nun ausgetauscht werden.","exko":"엘리베이터는 모터 고장으로 2월 20일부터 운행이 멈춘 상태이며, 지난 10월에 점검을 받은 지 얼마 되지 않았는데도 이제 모터를 교체해야 합니다."},{"de":"darauf hin|weisen, dass …","ko":"~라는 점을 지적하다, 알리다","ex":"Frau Demir weist darauf hin, dass mehrere ältere Mieter ihre Wohnungen seit Wochen kaum verlassen","exko":"데미르 씨는 나이 든 세입자 여러 명이 몇 주째 거의 집 밖에 나가지 않는다고 지적합니다"},{"de":"sich bereit erklären, etwas zu tun","ko":"~하겠다고 나서다","ex":"drei Mieter erklären sich bereit, bis zur Reparatur für sie einzukaufen","exko":"세입자 세 명이 수리가 끝날 때까지 이분들 대신 장을 보겠다고 나섭니다"},{"de":"um Verständnis bitten","ko":"양해를 구하다","ex":"Herr Kaya bittet um Verständnis, weil lange kein Fachbetrieb verfügbar war.","exko":"카야 씨는 오랫동안 일을 맡을 수 있는 전문 업체가 없었다며 양해를 구합니다."},{"de":"etwas bekannt geben","ko":"~을 알리다, 공지하다","ex":"Ergebnis: Die Hausverwaltung gibt den Einbautermin per Aushang bekannt.","exko":"결과: 관리사무소가 설치 날짜를 게시판에 공지합니다."}],"words":357},{"id":"b1-14","level":"B1","no":14,"title":"Was Kunden sagen","titleKo":"손님들이 남긴 후기","type":"Online-Bewertungen","typeKo":"온라인 후기","intro":"보덴호의 자전거 대여점에 손님 세 명이 남긴 후기와 주인의 답글이에요.","focus":["관사 없는 형용사 어미","für의 여러 뜻","angeblich · offenbar · tatsächlich","명사 앞 비교급·최상급"],"paragraphs":[{"style":"meta","de":"Radverleih Seewind, Lindau","ko":"자전거 대여점 제빈트, 린다우"},{"label":"★★★★★ Lena K.","de":"Meine Freundin und ich haben uns für drei Tage zwei E-Bikes geliehen und waren rundum zufrieden. Freundliches Personal, gepflegte Räder und eine kurze, aber gründliche Einweisung – mehr braucht man nicht. Der junge Mitarbeiter hat uns sogar die schönste Strecke am Seeufer auf einer Radkarte eingezeichnet. Unterwegs haben wir in Bregenz und in einem kleinen Fischerdorf mit herrlichem Alpenblick Pause gemacht. Für uns der beste Verleih am ganzen See!","ko":"친구와 저는 사흘 동안 전기자전거 두 대를 빌렸는데, 모든 면에서 만족했어요. 친절한 직원, 잘 관리된 자전거, 짧지만 꼼꼼한 사용 설명까지, 더 바랄 게 없어요. 젊은 직원분은 호숫가에서 가장 아름다운 길을 자전거 지도에 그려 주기까지 했어요. 가는 길에 브레겐츠와, 알프스가 멋지게 보이는 작은 어촌 마을에서 쉬어 갔어요. 저희가 보기에는 호수 주변을 통틀어 최고의 대여점이에요!"},{"label":"★★☆☆☆ Thomas W.","de":"Online hatte ich ein neues Trekkingrad reserviert, bekommen habe ich aber ein älteres Rad mit quietschenden Bremsen. Der Mitarbeiter an der Theke war zwar freundlich, konnte mir aber kein anderes Rad geben, weil angeblich alle Räder vermietet waren. Nach zwanzig Kilometern hatte ich dann auch noch eine Reifenpanne. Da ich telefonisch niemanden erreicht habe, musste ich das Rad bis zum nächsten Bahnhof schieben. Für 25 Euro am Tag erwarte ich ein besseres Rad und bei einer Panne schnellere Hilfe. Zwei Sterne gibt es nur für die Freundlichkeit an der Theke.","ko":"온라인으로 새 트레킹 자전거를 예약했는데, 막상 받은 건 브레이크에서 끽끽 소리가 나는 오래된 자전거였어요. 카운터 직원은 친절하긴 했지만, 자전거가 전부 대여 중이라면서 다른 자전거를 주지 못했어요. 게다가 20킬로미터를 달린 뒤에는 타이어 펑크까지 났어요. 전화로 아무와도 연락이 닿지 않아서 가장 가까운 기차역까지 자전거를 밀고 가야 했어요. 하루에 25유로를 낸다면 더 좋은 자전거와, 고장이 났을 때 더 빠른 도움을 기대해요. 별 두 개는 카운터 직원이 친절했던 것에 대한 점수일 뿐이에요."},{"label":"★★★★☆ Sabine M.","de":"Wir waren mit unseren Kindern hier. Die Ausstattung ist gut, denn es gibt Kinderräder in verschiedenen Größen und Anhänger für kleinere Geschwister. Die Mietpreise sind fair, und Helme kosten nichts extra. Im Juli und August sind die Räder offenbar schnell ausgebucht, deshalb sollte man online oder am Vortag telefonisch reservieren. Ein kleiner Nachteil ist die Rückgabe bis 18 Uhr, denn für längere Tagestouren ist das etwas knapp. Insgesamt ein solider Verleih für Familien.","ko":"저희는 아이들과 함께 왔어요. 여러 크기의 어린이 자전거와 더 어린 동생들을 태울 트레일러가 있어서 장비가 잘 갖춰져 있어요. 대여료는 적당하고, 헬멧은 따로 돈을 내지 않아도 돼요. 7월과 8월에는 자전거 예약이 금방 차는 것 같으니, 온라인으로든 전날 전화로든 미리 예약하는 게 좋아요. 작은 단점은 오후 6시까지 반납해야 한다는 점인데, 하루 종일 타는 긴 코스에는 시간이 좀 빠듯해요. 전체적으로 가족에게 무난한 대여점이에요."},{"label":"Antwort von Markus Brenner, Inhaber","de":"Liebe Gäste, vielen Dank für Ihre Bewertungen! Über Lob freuen wir uns sehr, aber aus Kritik lernen wir am meisten.","ko":"손님 여러분, 후기를 남겨 주셔서 정말 감사해요! 칭찬을 들으면 무척 기쁘지만, 저희가 가장 많이 배우는 건 비판을 통해서예요."},{"de":"Lieber Herr W., es tut mir leid, dass Sie Ihr Rad schieben mussten. An diesem Tag war unser Telefon zwar ständig besetzt, aber das ist keine Entschuldigung. Seitdem klebt an jedem Rad eine Notfallnummer, unter der man tatsächlich jederzeit jemanden erreicht. Außerdem haben wir zehn neue Trekkingräder angeschafft. Als Entschädigung bekommen Sie beim nächsten Besuch einen Tag kostenlos oder ein E-Bike zum Preis eines normalen Rads – Sie haben die Wahl.","ko":"W 씨, 자전거를 밀고 가셔야 했다니 죄송해요. 그날 저희 전화가 계속 통화 중이었던 건 맞지만, 그게 변명이 될 수는 없어요. 그 뒤로 모든 자전거에 긴급 전화번호를 붙여 두었고, 이 번호로는 실제로 언제든 누군가와 통화할 수 있어요. 또 새 트레킹 자전거 열 대를 들여왔어요. 보상으로, 다음에 오시면 하루를 무료로 이용하시거나 일반 자전거 가격으로 전기자전거를 타실 수 있어요. 어느 쪽으로 할지는 직접 고르세요."},{"de":"Liebe Frau M., danke für Ihre Anregung zu den Rückgabezeiten: Ab kommendem Sommer ist die Rückgabe bis 20 Uhr möglich. Und liebe Lena, schöne Grüße von Jonas – er hat sich über Ihr Lob sehr gefreut!","ko":"M 씨, 반납 시간에 대해 의견을 주셔서 감사해요. 돌아오는 여름부터는 저녁 8시까지 반납하실 수 있어요. 그리고 레나 씨, 요나스가 안부를 전해요. 레나 씨의 칭찬에 정말 기뻐했어요!"}],"questions":[{"type":"rf","kind":"detail","q":"Lena und ihre Freundin wurden vor der Fahrt kurz, aber sorgfältig in die Räder eingewiesen.","answer":0,"evidence":"eine kurze, aber gründliche Einweisung","pairs":[["eine kurze, aber gründliche Einweisung","kurz, aber sorgfältig in die Räder eingewiesen"]],"explain":"레나는 '짧지만 꼼꼼한 사용 설명(eine kurze, aber gründliche Einweisung)'을 받았다고 해요. 명사 Einweisung을 동사 einweisen의 수동태로, gründlich를 sorgfältig로 바꿔 말했어요."},{"type":"mc","kind":"detail","q":"Was hat der junge Mitarbeiter für Lena und ihre Freundin getan?","options":["Er hat ihnen die beiden E-Bikes gleich für eine ganze Woche geliehen.","Er hat sie selbst nach Bregenz und in ein kleines Fischerdorf begleitet.","Er hat ihnen auf einem Plan markiert, wo man am See am schönsten fährt."],"answer":2,"evidence":"Der junge Mitarbeiter hat uns sogar die schönste Strecke am Seeufer auf einer Radkarte eingezeichnet.","pairs":[["auf einer Radkarte eingezeichnet","auf einem Plan markiert"],["die schönste Strecke am Seeufer","wo man am See am schönsten fährt"]],"explain":"젊은 직원은 호숫가에서 가장 아름다운 길을 자전거 지도에 그려 주었어요. 'auf einer Radkarte einzeichnen'을 'auf einem Plan markieren'으로 바꿔 말했어요. 두 사람은 자전거를 사흘 동안 빌렸어요. 또 브레겐츠와 어촌 마을에는 직원과 함께 간 것이 아니라 두 사람끼리 들렀어요."},{"type":"rf","kind":"detail","q":"Thomas W. bekam an der Theke genau das neue Trekkingrad, das er online reserviert hatte.","answer":1,"evidence":"Online hatte ich ein neues Trekkingrad reserviert, bekommen habe ich aber ein älteres Rad mit quietschenden Bremsen.","pairs":[["bekommen habe ich aber ein älteres Rad","bekam an der Theke genau das neue Trekkingrad"]],"explain":"Thomas는 온라인으로 새 트레킹 자전거를 예약했지만, 실제로는 브레이크에서 소리가 나는 오래된 자전거를 받았어요. 'Theke', 'Trekkingrad', 'online reserviert'는 본문에 나오는 말이지만, 예약한 자전거를 받았다는 내용은 본문과 반대예요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Der Mitarbeiter an der Theke war zwar freundlich, konnte mir aber kein anderes Rad geben, weil angeblich alle Räder vermietet waren.“?","options":["Der Angestellte blieb höflich, doch nach seinen Worten war kein Ersatz frei.","Der Mitarbeiter an der Theke war unhöflich und gab ihm keines der freien Räder.","Der Mitarbeiter an der Theke war freundlich und gab ihm sofort ein anderes Rad."],"answer":0,"evidence":"Der Mitarbeiter an der Theke war zwar freundlich, konnte mir aber kein anderes Rad geben, weil angeblich alle Räder vermietet waren.","pairs":[["war zwar freundlich","blieb höflich"],["weil angeblich alle Räder vermietet waren","nach seinen Worten war kein Ersatz frei"]],"explain":"'zwar … aber'는 '~하긴 했지만'이라는 뜻이에요. 직원은 친절했지만 다른 자전거를 주지 못했어요. 'freundlich'를 'höflich'로 바꿔 말했고, angeblich는 '그 사람 말로는'이라는 뜻이라서 'nach seinen Worten'으로 바꿔 말했어요. 직원은 불친절하지 않았고, 다른 자전거를 주지도 않았어요."},{"type":"mc","kind":"detail","q":"Was empfiehlt Sabine M. Gästen, die im Hochsommer kommen?","options":["Sie sollen nur online buchen, weil am Telefon sowieso niemand antwortet.","Sie sollen sich früh ein Rad sichern, im Netz oder per Anruf am Vortag.","Sie sollen eigene Helme mitbringen, weil diese im Verleih extra kosten."],"answer":1,"evidence":"Im Juli und August sind die Räder offenbar schnell ausgebucht, deshalb sollte man online oder am Vortag telefonisch reservieren.","pairs":[["online oder am Vortag telefonisch reservieren","im Netz oder per Anruf am Vortag"],["Im Juli und August","im Hochsommer"]],"explain":"사비네는 7월과 8월에는 자전거가 금방 다 예약되는 것 같으니 온라인이나 전날 전화로 예약하라고 권해요. 'reservieren'을 'sich ein Rad sichern'으로, 'online'을 'im Netz'로, 'telefonisch'를 'per Anruf'로 바꿔 말했어요. 전화로 아무도 받지 않았다는 사람은 Thomas이고, 헬멧은 따로 돈을 내지 않아요."},{"type":"mc","kind":"meaning","q":"Was bedeutet „etwas knapp“ im Text?","options":["Für Kinder sind die Räder auf langen Tagestouren eher zu klein.","Für Familien sind die Mietpreise bei langen Touren eher zu hoch.","Für längere Ausflüge reicht die Zeit bis zur Rückgabe kaum aus."],"answer":2,"evidence":"Ein kleiner Nachteil ist die Rückgabe bis 18 Uhr, denn für längere Tagestouren ist das etwas knapp.","pairs":[["etwas knapp","reicht die Zeit bis zur Rückgabe kaum aus"],["für längere Tagestouren","Für längere Ausflüge"]],"explain":"knapp은 '빠듯하다, 겨우 될 정도로 모자라다'는 뜻이에요. 오후 6시까지 자전거를 반납해야 해서 긴 코스를 타기에는 시간이 부족하다는 말이에요. 자전거 크기나 가격에 대한 말이 아니에요. 사비네는 가격이 적당하다고 했어요."},{"type":"mc","kind":"inference","q":"Wer ist Jonas wahrscheinlich?","options":["der Inhaber, der den Gästen auf ihre Bewertungen selbst geantwortet hat","der Angestellte, den Lena in ihrer Bewertung besonders erwähnt","ein Freund von Lena, mit dem sie die beiden E-Bikes geliehen hat"],"answer":1,"evidence":"Und liebe Lena, schöne Grüße von Jonas – er hat sich über Ihr Lob sehr gefreut!","pairs":[["er hat sich über Ihr Lob sehr gefreut","den Lena in ihrer Bewertung besonders erwähnt"],["Der junge Mitarbeiter","der Angestellte"]],"explain":"레나가 후기에서 따로 이야기한 사람은 길을 지도에 그려 준 젊은 직원이에요. 주인은 요나스가 레나의 칭찬에 기뻐했다고 전하니, 요나스는 그 직원일 가능성이 높아요. 답글을 쓰는 주인은 마르쿠스 브레너이고, 레나는 남성 친구(Freund)가 아니라 여성 친구(Freundin)와 함께 자전거를 빌렸어요."},{"type":"mc","kind":"intent","q":"Wie geht der Inhaber in seiner Antwort mit den Bewertungen um?","options":["Er nimmt die Kritik ernst und nennt ganz konkrete Verbesserungen.","Er weist die Kritik zurück und lobt vor allem seinen Mitarbeiter.","Er bedankt sich, bietet aber nur Familien eine Entschädigung an."],"answer":0,"evidence":"Seitdem klebt an jedem Rad eine Notfallnummer","pairs":[["aus Kritik lernen wir am meisten","Er nimmt die Kritik ernst"],["Notfallnummer","konkrete Verbesserungen"],["Ab kommendem Sommer ist die Rückgabe bis 20 Uhr möglich","konkrete Verbesserungen"]],"explain":"주인은 비판에서 가장 많이 배운다고 하고, 긴급 전화번호, 새 트레킹 자전거, 저녁 8시까지의 반납처럼 구체적으로 바꾼 점을 말해요. 비판을 부정하지 않았고(das ist keine Entschuldigung), 보상은 가족이 아니라 Thomas에게 제안했어요."}],"grammar":[{"title":"관사 없이 쓰는 형용사의 어미","term":"Adjektivdeklination ohne Artikel (starke Deklination)","explain":"명사 앞에 관사가 없으면 형용사가 관사 대신 격을 보여 줘요. 그래서 형용사에 정관사와 비슷한 어미가 붙어요. 남성 1격은 -er(Lieber Herr W.), 중성 1·4격은 -es(Freundliches Personal), 여성과 복수 1·4격은 -e(gepflegte Räder, schnellere Hilfe), 남성·중성 3격은 -em(mit herrlichem Alpenblick, ab kommendem Sommer), 복수 3격은 -en(in verschiedenen Größen)이에요. 후기나 광고처럼 짧게 쓰는 글에서 관사 없는 명사구가 자주 나와요.","pattern":"형용사 + 명사 (관사 없음): -er / -es / -e / -em / -en","examples":[{"de":"Ab kommendem Sommer ist die Rückgabe bis 20 Uhr möglich.","ko":"돌아오는 여름부터는 저녁 8시까지 반납하실 수 있어요.","mark":["Ab kommendem Sommer"],"parts":[["Ab kommendem Sommer","부사어(시간)"],["ist","동사"],["die Rückgabe","주어"],["bis 20 Uhr","부사어(시간)"],["möglich.","보어"]]},{"de":"Freundliches Personal, gepflegte Räder und eine kurze, aber gründliche Einweisung – mehr braucht man nicht.","ko":"친절한 직원, 잘 관리된 자전거, 짧지만 꼼꼼한 사용 설명까지, 더 바랄 게 없어요.","mark":["Freundliches Personal","gepflegte Räder"]},{"de":"Unterwegs haben wir in Bregenz und in einem kleinen Fischerdorf mit herrlichem Alpenblick Pause gemacht.","ko":"가는 길에 브레겐츠와, 알프스가 멋지게 보이는 작은 어촌 마을에서 쉬어 갔어요.","mark":["mit herrlichem Alpenblick"]}],"tip":"두 번째 예문의 'eine kurze, aber gründliche Einweisung'은 부정관사 eine가 있어서 형용사가 -e로만 끝나요. 관사가 있고 없음에 따라 어미가 달라지는 것을 비교해 보세요."},{"title":"für + 4격의 여러 가지 뜻","term":"Die Präposition für: Preis, Urteil, Grund, Zweck","explain":"für는 4격과 함께 쓰고 뜻이 여러 가지예요. 값을 말할 때(für 25 Euro = 25유로를 내고), 누구의 판단인지 말할 때(für uns = 우리가 보기에), 무엇에 대한 대가나 이유인지 말할 때(für die Freundlichkeit = 친절함 때문에), 무엇을 하기에 그런지 말할 때(für längere Tagestouren = 긴 하루 코스를 타기에는) 써요. 감사 표현 vielen Dank für …의 für도 '~에 대해'라는 이유의 뜻이에요.","pattern":"für + 4격: 값 · 판단하는 사람 · 이유와 대가 · 목적","examples":[{"de":"Für 25 Euro am Tag erwarte ich ein besseres Rad und bei einer Panne schnellere Hilfe.","ko":"하루에 25유로를 낸다면 더 좋은 자전거와, 고장이 났을 때 더 빠른 도움을 기대해요.","mark":["Für 25 Euro am Tag"],"parts":[["Für 25 Euro am Tag","부사어"],["erwarte","동사"],["ich","주어"],["ein besseres Rad","4격 목적어"],["und","접속사"],["bei einer Panne","부사어"],["schnellere Hilfe.","4격 목적어"]]},{"de":"Zwei Sterne gibt es nur für die Freundlichkeit an der Theke.","ko":"별 두 개는 카운터 직원이 친절했던 것에 대한 점수일 뿐이에요.","mark":["für die Freundlichkeit an der Theke"]},{"de":"Für uns der beste Verleih am ganzen See!","ko":"저희가 보기에는 호수 주변을 통틀어 최고의 대여점이에요!","mark":["Für uns"]},{"de":"Ein kleiner Nachteil ist die Rückgabe bis 18 Uhr, denn für längere Tagestouren ist das etwas knapp.","ko":"작은 단점은 오후 6시까지 반납해야 한다는 점인데, 하루 종일 타는 긴 코스에는 시간이 좀 빠듯해요.","mark":["für längere Tagestouren"]}],"tip":"für 뒤에는 4격이 와요(für uns, für die Freundlichkeit). 같은 말이라도 문맥에 따라 '값', '판단', '이유', '목적' 가운데 어느 뜻인지 생각하며 읽어 보세요."},{"title":"출처와 확신을 나타내는 부사 angeblich · offenbar · tatsächlich","term":"Modalwörter: angeblich, offenbar, tatsächlich","explain":"angeblich는 '남이 그렇다고 말하지만 확인되지 않은'이라는 뜻이에요. 말하는 사람이 그 말을 다 믿지 않는다는 느낌이 들어요. offenbar는 '보이는 사실로 판단하면 분명히 그런 것 같다'는 뜻이에요. tatsächlich는 '실제로, 정말로'라는 뜻으로, 말이나 약속이 사실과 같다는 것을 강조해요. 이런 부사는 문장 내용에 대한 말하는 사람의 판단을 나타내고, 보통 동사 뒤 중간 영역에 와요.","pattern":"주어 + 동사 + angeblich / offenbar / tatsächlich + …","examples":[{"de":"Im Juli und August sind die Räder offenbar schnell ausgebucht, deshalb sollte man online oder am Vortag telefonisch reservieren.","ko":"7월과 8월에는 자전거 예약이 금방 차는 것 같으니, 온라인으로든 전날 전화로든 미리 예약하는 게 좋아요.","mark":["offenbar"],"parts":[["Im Juli und August","부사어(시간)"],["sind","동사"],["die Räder","주어"],["offenbar","부사어"],["schnell","부사어(방법)"],["ausgebucht,","보어"],["deshalb","접속부사"],["sollte","동사"],["man","주어"],["online oder am Vortag telefonisch","부사어(방법)"],["reservieren.","동사(끝)"]]},{"de":"Der Mitarbeiter an der Theke war zwar freundlich, konnte mir aber kein anderes Rad geben, weil angeblich alle Räder vermietet waren.","ko":"카운터 직원은 친절하긴 했지만, 자전거가 전부 대여 중이라면서 다른 자전거를 주지 못했어요.","mark":["angeblich"]},{"de":"Seitdem klebt an jedem Rad eine Notfallnummer, unter der man tatsächlich jederzeit jemanden erreicht.","ko":"그 뒤로 모든 자전거에 긴급 전화번호를 붙여 두었고, 이 번호로는 실제로 언제든 누군가와 통화할 수 있어요.","mark":["tatsächlich"]}],"tip":"'weil angeblich alle Räder vermietet waren'은 직원이 그렇게 말했지만 Thomas는 그 말을 확신하지 않는다는 뜻이에요. angeblich가 없으면 모든 자전거가 대여 중이었다는 것이 사실로 들려요."},{"title":"명사 앞에 쓰는 비교급과 최상급","term":"Komparativ und Superlativ als Attribut","explain":"비교급(älter, besser, schneller)과 최상급(schönst-, best-)을 명사 앞에 쓰면 보통 형용사처럼 어미가 붙어요. 비교급은 -er 뒤에 어미가 붙어 ein älteres Rad, schnellere Hilfe처럼 되고, 최상급은 보통 정관사와 함께 die schönste Strecke, der beste Verleih처럼 써요. 'ein älteres Rad'은 다른 것과 직접 비교한다기보다 '비교적 오래된 자전거'라는 뜻이에요.","pattern":"ein + 비교급-er + 어미 + 명사  ·  der/die/das + 최상급-(e)st + 어미 + 명사","examples":[{"de":"Der junge Mitarbeiter hat uns sogar die schönste Strecke am Seeufer auf einer Radkarte eingezeichnet.","ko":"젊은 직원분은 호숫가에서 가장 아름다운 길을 자전거 지도에 그려 주기까지 했어요.","mark":["die schönste Strecke"],"parts":[["Der junge Mitarbeiter","주어"],["hat","동사"],["uns","3격 목적어"],["sogar","기타"],["die schönste Strecke am Seeufer","4격 목적어"],["auf einer Radkarte","부사어(장소)"],["eingezeichnet.","동사(끝)"]]},{"de":"Online hatte ich ein neues Trekkingrad reserviert, bekommen habe ich aber ein älteres Rad mit quietschenden Bremsen.","ko":"온라인으로 새 트레킹 자전거를 예약했는데, 막상 받은 건 브레이크에서 끽끽 소리가 나는 오래된 자전거였어요.","mark":["ein älteres Rad"]},{"de":"Für 25 Euro am Tag erwarte ich ein besseres Rad und bei einer Panne schnellere Hilfe.","ko":"하루에 25유로를 낸다면 더 좋은 자전거와, 고장이 났을 때 더 빠른 도움을 기대해요.","mark":["ein besseres Rad","schnellere Hilfe"]}],"tip":"gut의 비교급과 최상급은 불규칙해요(gut – besser – am besten). 명사 앞에서는 ein besseres Rad, der beste Verleih처럼 써요."}],"vocab":[{"de":"der Verleih, -e","ko":"대여점"},{"de":"sich (Dat.) etwas leihen (leiht, lieh, hat geliehen)","ko":"(남에게서) 빌리다"},{"de":"gepflegt","ko":"잘 관리된"},{"de":"die Einweisung, -en","ko":"(사용법) 설명, 안내"},{"de":"ein|zeichnen (zeichnet ein, zeichnete ein, hat eingezeichnet)","ko":"(지도 등에) 그려 넣다"},{"de":"die Theke, -n","ko":"카운터, 계산대"},{"de":"angeblich","ko":"(남의 말로는) ~라고 하는, 소문으로는"},{"de":"vermieten","ko":"빌려주다, 대여하다"},{"de":"die Reifenpanne, -n","ko":"타이어 펑크"},{"de":"schieben (schiebt, schob, hat geschoben)","ko":"밀다, 밀고 가다"},{"de":"ausgebucht","ko":"예약이 다 찬"},{"de":"knapp","ko":"빠듯한, 부족한"},{"de":"besetzt","ko":"(전화가) 통화 중인"},{"de":"an|schaffen (schafft an, schaffte an, hat angeschafft)","ko":"(물건을) 장만하다, 들여놓다"},{"de":"die Entschädigung, -en","ko":"보상"},{"de":"die Anregung, -en","ko":"제안, 의견"}],"phrases":[{"de":"rundum zufrieden sein","ko":"모든 면에서 만족하다","ex":"Meine Freundin und ich haben uns für drei Tage zwei E-Bikes geliehen und waren rundum zufrieden.","exko":"친구와 저는 사흘 동안 전기자전거 두 대를 빌렸는데, 모든 면에서 만족했어요."},{"de":"Pause machen","ko":"쉬다, 휴식하다","ex":"Unterwegs haben wir in Bregenz und in einem kleinen Fischerdorf mit herrlichem Alpenblick Pause gemacht.","exko":"가는 길에 브레겐츠와, 알프스가 멋지게 보이는 작은 어촌 마을에서 쉬어 갔어요."},{"de":"nichts extra kosten","ko":"따로 돈이 들지 않다","ex":"Die Mietpreise sind fair, und Helme kosten nichts extra.","exko":"대여료는 적당하고, 헬멧은 따로 돈을 내지 않아도 돼요."},{"de":"Es tut mir leid, dass …","ko":"~해서 죄송해요, 유감이에요","ex":"es tut mir leid, dass Sie Ihr Rad schieben mussten","exko":"자전거를 밀고 가셔야 했다니 죄송해요"},{"de":"die Wahl haben","ko":"고를 수 있다, 선택권이 있다","ex":"Sie haben die Wahl.","exko":"어느 쪽으로 할지는 직접 고르세요."}],"words":359},{"id":"b1-15","level":"B1","no":15,"title":"Audioguide: Die Speicherstadt","titleKo":"오디오 가이드: 슈파이허슈타트","type":"Audioguide","typeKo":"오디오 가이드 원고","intro":"함부르크의 옛 창고 지구를 걸으며 듣는 오디오 가이드 원고예요.","focus":["수동태 과거형","damals · früher · bis heute","dessen · deren","관계절 wo"],"paragraphs":[{"style":"h","de":"Station 1 · Am Fleet","ko":"1번 지점 · 플레트에서"},{"de":"Herzlich willkommen in der Speicherstadt! Sie stehen jetzt auf einer Brücke über einem Fleet – so heißen hier die Kanäle. Links von Ihnen erheben sich hohe Backsteingebäude, die mit ihren Türmchen wie kleine Burgen aussehen. Gebaut wurden sie nicht für Menschen, sondern für Waren; deshalb nennt man sie Speicher, also Lagerhäuser.","ko":"슈파이허슈타트에 오신 것을 환영해요! 여러분은 지금 플레트 위의 다리에 서 계세요. 이곳에서는 운하를 플레트라고 불러요. 왼쪽에는 작은 탑이 달린 높은 벽돌 건물들이 솟아 있는데, 마치 작은 성처럼 보여요. 하지만 이 건물들은 사람이 아니라 물건을 위해 지어졌어요. 그래서 이런 건물을 슈파이허, 곧 창고라고 불러요."},{"style":"h","de":"Station 2 · Ein Viertel verschwindet","ko":"2번 지점 · 사라진 동네"},{"de":"Bevor die Speicherstadt entstand, lebten hier Tausende Menschen in engen Fachwerkhäusern. Warum mussten sie ihre Wohnungen verlassen? Hamburg hatte 1881 zugestimmt, Teil des deutschen Zollgebiets zu werden; die Kaufleute brauchten deshalb einen Freihafen, wo sie Waren zollfrei einlagern konnten. Ab 1883 wurde das alte Wohnviertel abgerissen, und Abschnitt für Abschnitt wurden die neuen Speicher errichtet.","ko":"슈파이허슈타트가 생기기 전에는 이곳의 좁은 목조 골조 주택에 수천 명이 살았어요. 이 사람들은 왜 집을 떠나야 했을까요? 함부르크는 1881년에 독일 관세 구역에 들어가기로 동의했어요. 그래서 상인들에게는 관세 없이 물건을 보관할 수 있는 자유항이 필요했어요. 1883년부터 옛 주택가가 철거되었고, 새 창고들이 구역별로 차례차례 세워졌어요."},{"style":"h","de":"Station 3 · Häuser auf Holz","ko":"3번 지점 · 나무 위에 선 건물"},{"de":"Warum versinken so schwere Gebäude nicht im sumpfigen Untergrund? Die Antwort finden Sie dort, wo niemand hinschaut, nämlich tief unter Ihren Füßen. Bevor die Mauern hochgezogen wurden, rammten Arbeiter unzählige Pfähle aus Eichenholz in die Erde, auf denen die Speicher bis heute stehen. Solange das Holz nass bleibt, fault es nicht.","ko":"이렇게 무거운 건물이 왜 늪처럼 무른 땅속으로 가라앉지 않을까요? 답은 아무도 눈여겨보지 않는 곳, 바로 여러분의 발아래 깊은 곳에 있어요. 벽을 쌓아 올리기 전에 일꾼들이 셀 수 없이 많은 참나무 말뚝을 땅에 박았고, 창고들은 지금까지도 그 말뚝 위에 서 있어요. 나무는 젖어 있는 동안에는 썩지 않아요."},{"style":"h","de":"Station 4 · Kaffee, Tee und Teppiche","ko":"4번 지점 · 커피, 차, 양탄자"},{"de":"Unter den Dächern sehen Sie Seilwinden, mit denen Säcke und Kisten aus den Booten in die oberen Stockwerke gezogen wurden. Nachdem ein Frachtschiff im Hafen angekommen war, brachten flache Lastkähne die Ladung durch die Fleete bis vor die Speicher. Gelagert wurden damals vor allem Kaffee, Tee, Gewürze und Teppiche.","ko":"지붕 아래에 밧줄 윈치가 보이는데, 이 윈치로 자루와 상자를 배에서 위층으로 끌어 올렸어요. 화물선이 항구에 도착하고 나면, 바닥이 평평한 짐배들이 화물을 싣고 플레트를 지나 창고 앞까지 날랐어요. 당시 이곳에는 주로 커피, 차, 향신료, 양탄자가 보관되었어요."},{"de":"Eine wichtige Rolle spielten dabei die Quartiersleute, deren Aufgabe die Prüfung und fachgerechte Lagerung der Waren war. Ein Kaufmann, dessen Kaffee hier lag, musste sich deshalb auf ihre Erfahrung verlassen können. Erst nachdem die Quartiersleute die Qualität kontrolliert hatten, wurde die Ware weiterverkauft.","ko":"이때 중요한 역할을 한 사람들이 크바르티어스로이테, 곧 창고 관리인이었어요. 이들은 물건을 검사하고 알맞게 보관하는 일을 맡았어요. 그래서 커피를 이곳에 맡겨 둔 상인은 이들의 경험을 믿을 수 있어야 했어요. 창고 관리인들이 품질을 확인하고 나서야 물건은 다시 팔려 나갔어요."},{"style":"h","de":"Station 5 · Ein Welterbe aus Backstein","ko":"5번 지점 · 벽돌로 지은 세계유산"},{"de":"Zum Schluss führt Sie unser Rundgang ins nahe Kontorhausviertel, wo Reedereien und Handelsfirmen ab den 1920er-Jahren große Bürohäuser bauen ließen. Am bekanntesten ist das Chilehaus, dessen spitze Ecke an den Bug eines Schiffes erinnert. Seit 2015 gehören die beiden Viertel, deren Geschichte eng mit dem Hafen verbunden ist, gemeinsam zum UNESCO-Welterbe.","ko":"마지막으로 이번 투어는 가까운 콘토어하우스 지구로 이어져요. 그곳에는 1920년대부터 해운 회사와 무역 회사들이 큰 사무용 건물을 세웠어요. 가장 유명한 건물은 칠레하우스로, 뾰족한 모서리가 배의 뱃머리를 떠올리게 해요. 역사가 항구와 깊이 연결된 이 두 지구는 2015년부터 함께 유네스코 세계유산에 올라 있어요."},{"de":"Nehmen Sie sich Zeit für einen Spaziergang durch die Speicherstadt, wo früher schwere Säcke geschleppt wurden und heute Museen und Cafés auf Sie warten. Vielen Dank, dass Sie mit uns unterwegs waren!","ko":"예전에는 무거운 자루를 나르던 곳이고, 오늘날에는 박물관과 카페가 여러분을 기다리는 슈파이허슈타트를 시간을 내어 천천히 산책해 보세요. 저희와 함께해 주셔서 감사해요!"}],"questions":[{"type":"rf","kind":"detail","q":"Die Backsteingebäude der Speicherstadt wurden zuerst als Wohnungen für Menschen gebaut.","answer":1,"evidence":"Gebaut wurden sie nicht für Menschen, sondern für Waren","pairs":[["nicht für Menschen, sondern für Waren","als Wohnungen für Menschen gebaut"]],"explain":"가이드는 이 건물들이 사람이 아니라 물건을 위해 지어졌다고 해요. 그래서 이름도 창고(Speicher, Lagerhäuser)예요. 'Backsteingebäude', 'Menschen', 'gebaut'는 본문에 나오는 말이지만, 사람을 위해 지었다는 내용은 본문과 반대예요."},{"type":"mc","kind":"detail","q":"Was erfährt man über die Menschen, die früher an diesem Ort lebten?","options":["Sie zogen nach dem Bau selbst in die fertigen Speicher ein.","Sie mussten ihr Zuhause für das neue Lagerviertel aufgeben.","Sie kamen erst nach 1883 als Arbeiter in das alte Viertel."],"answer":1,"evidence":"Warum mussten sie ihre Wohnungen verlassen?","pairs":[["ihre Wohnungen verlassen","ihr Zuhause für das neue Lagerviertel aufgeben"]],"explain":"슈파이허슈타트가 생기기 전 이곳에는 수천 명이 살았고, 이 사람들은 집을 떠나야 했어요. 1883년부터 옛 주택가가 철거되고 창고가 들어섰어요. 'Wohnungen verlassen'을 'ihr Zuhause aufgeben'으로 바꿔 말했어요. 이 사람들이 창고에 들어가 살았다거나 1883년 뒤에 왔다는 말은 본문과 맞지 않아요."},{"type":"mc","kind":"detail","q":"Wozu brauchten die Kaufleute den Freihafen?","options":["um ihre Waren dort vor dem Verkauf zu verzollen","um Hamburg weiterhin außerhalb des Zollgebiets zu halten","um Güter dort aufzubewahren, ohne Abgaben zu zahlen"],"answer":2,"evidence":"einen Freihafen, wo sie Waren zollfrei einlagern konnten","pairs":[["Waren zollfrei einlagern","Güter dort aufzubewahren, ohne Abgaben zu zahlen"]],"explain":"함부르크가 독일 관세 구역에 들어가기로 하자, 상인들은 관세 없이 물건을 보관할 수 있는 자유항이 필요했어요. 'Waren zollfrei einlagern'을 'Güter aufbewahren, ohne Abgaben zu zahlen'으로 바꿔 말했어요. 함부르크는 관세 구역에 들어가기로 동의했으니 밖에 두려는 것이 아니었고, 관세를 내려던 것도 아니에요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Solange das Holz nass bleibt, fault es nicht.“?","options":["Das Eichenholz hält nur dann, wenn es nicht austrocknet.","Nässe schadet den Pfählen, deshalb hält man sie trocken.","Die nassen Pfähle werden immer wieder durch neue ersetzt."],"answer":0,"evidence":"Solange das Holz nass bleibt, fault es nicht.","pairs":[["Solange das Holz nass bleibt","wenn es nicht austrocknet"],["fault es nicht","hält"]],"explain":"solange는 '~하는 동안에는'이라는 뜻이에요. 나무가 젖어 있는 동안에는 썩지 않으니, 마르지 않아야 오래간다는 뜻이에요. 물기가 말뚝을 망가뜨린다는 것은 반대 내용이고, 말뚝을 새것으로 바꾼다는 말은 없어요. 창고는 지금도 같은 말뚝 위에 서 있어요."},{"type":"rf","kind":"detail","q":"Die Güter kamen vom Schiff auf dem Wasserweg bis zu den Lagerhäusern.","answer":0,"evidence":"Nachdem ein Frachtschiff im Hafen angekommen war, brachten flache Lastkähne die Ladung durch die Fleete bis vor die Speicher.","pairs":[["brachten flache Lastkähne die Ladung durch die Fleete","auf dem Wasserweg"],["bis vor die Speicher","bis zu den Lagerhäusern"],["die Ladung","Die Güter"]],"explain":"화물선이 항구에 도착하면, 바닥이 평평한 짐배(Lastkähne)가 화물을 싣고 운하(Fleete)를 지나 창고 앞까지 날랐어요. 그러니 화물은 물길로 창고에 도착했어요. 'die Ladung'을 'die Güter'로, 'durch die Fleete'를 'auf dem Wasserweg'로, 'bis vor die Speicher'를 'bis zu den Lagerhäusern'으로 바꿔 말했어요."},{"type":"mc","kind":"meaning","q":"Was bedeutet „Quartiersleute“ im Text?","options":["Bewohner, die vor dem Bau im alten Quartier lebten","Händler, die ihren Kaffee in den Speichern anboten","Fachleute, die die gelagerten Güter kontrollierten"],"answer":2,"evidence":"Eine wichtige Rolle spielten dabei die Quartiersleute, deren Aufgabe die Prüfung und fachgerechte Lagerung der Waren war.","pairs":[["deren Aufgabe die Prüfung und fachgerechte Lagerung der Waren war","Fachleute, die die gelagerten Güter kontrollierten"]],"explain":"Quartiersleute는 물건을 검사하고 알맞게 보관하는 일을 맡은 창고 관리인이에요. 'Quartier'라는 낱말 때문에 옛 동네 주민으로 생각하기 쉽지만, 본문은 이들의 일을 '물건 검사와 보관'이라고 설명해요. 커피를 맡긴 사람은 상인(Kaufmann)이에요."},{"type":"mc","kind":"inference","q":"Was kann man über Kaufleute und Quartiersleute schließen?","options":["Die Händler überließen ihre Güter anderen und mussten ihnen trauen.","Die Händler kontrollierten ihre Ware lieber selbst ohne fremde Hilfe.","Die Quartiersleute hatten mit dem Kaffee der Händler nichts zu tun."],"answer":0,"evidence":"Ein Kaufmann, dessen Kaffee hier lag, musste sich deshalb auf ihre Erfahrung verlassen können.","pairs":[["musste sich deshalb auf ihre Erfahrung verlassen können","mussten ihnen trauen"],["dessen Kaffee hier lag","überließen ihre Güter anderen"]],"explain":"상인의 커피는 창고에 있었고, 검사와 보관은 창고 관리인이 맡았어요. 그래서 상인은 관리인의 경험을 믿을 수 있어야 했어요. 'sich verlassen auf'를 'trauen'으로 바꿔 말했어요. 상인이 직접 검사한 것이 아니고, 관리인은 바로 그 커피의 품질을 확인했어요."},{"type":"mc","kind":"detail","q":"Was gilt seit 2015?","options":["Nur die Speicherstadt ist Welterbe, nicht das Kontorhausviertel.","Zwei benachbarte Viertel tragen nun zusammen den Titel Welterbe.","Das Chilehaus ist als einziges Gebäude des Viertels ein Welterbe."],"answer":1,"evidence":"Seit 2015 gehören die beiden Viertel, deren Geschichte eng mit dem Hafen verbunden ist, gemeinsam zum UNESCO-Welterbe.","pairs":[["die beiden Viertel","Zwei benachbarte Viertel"],["gemeinsam zum UNESCO-Welterbe","tragen nun zusammen den Titel Welterbe"]],"explain":"2015년부터 슈파이허슈타트와 가까운 콘토어하우스 지구가 함께(gemeinsam) 유네스코 세계유산이에요. 'die beiden Viertel'을 'zwei benachbarte Viertel'로, 'gemeinsam'을 'zusammen'으로 바꿔 말했어요. 칠레하우스는 그 지구에서 가장 유명한 건물일 뿐, 혼자 세계유산인 것이 아니에요."}],"grammar":[{"title":"수동태 과거형","term":"Passiv Präteritum","explain":"wurde/wurden + 과거분사는 과거에 일어난 일을 수동태로 말할 때 써요. 누가 했는지보다 무엇이 일어났는지가 중요할 때 쓰기 때문에 역사를 설명하는 글에서 자주 나와요. 주어가 복수이면 wurden을 써요. 과거분사를 문장 맨 앞으로 보내 강조할 수도 있어요(Gebaut wurden sie …, Gelagert wurden …).","pattern":"주어 + wurde/wurden + … + 과거분사(끝)  ·  과거분사 + wurde/wurden + 주어 …","examples":[{"de":"Ab 1883 wurde das alte Wohnviertel abgerissen, und Abschnitt für Abschnitt wurden die neuen Speicher errichtet.","ko":"1883년부터 옛 주택가가 철거되었고, 새 창고들이 구역별로 차례차례 세워졌어요.","mark":["wurde","abgerissen","wurden","errichtet"],"parts":[["Ab 1883","부사어(시간)"],["wurde","동사"],["das alte Wohnviertel","주어"],["abgerissen,","동사(끝)"],["und","접속사"],["Abschnitt für Abschnitt","부사어(방법)"],["wurden","동사"],["die neuen Speicher","주어"],["errichtet.","동사(끝)"]]},{"de":"Gebaut wurden sie nicht für Menschen, sondern für Waren; deshalb nennt man sie Speicher, also Lagerhäuser.","ko":"하지만 이 건물들은 사람이 아니라 물건을 위해 지어졌어요. 그래서 이런 건물을 슈파이허, 곧 창고라고 불러요.","mark":["Gebaut wurden"]},{"de":"Unter den Dächern sehen Sie Seilwinden, mit denen Säcke und Kisten aus den Booten in die oberen Stockwerke gezogen wurden.","ko":"지붕 아래에 밧줄 윈치가 보이는데, 이 윈치로 자루와 상자를 배에서 위층으로 끌어 올렸어요.","mark":["gezogen wurden"]}],"tip":"관계절 안에서는 wurde/wurden이 맨 끝에 와요(…, mit denen Säcke und Kisten … gezogen wurden). 수동태를 만드는 werden과 '~이 되다'라는 뜻의 werden(Teil des deutschen Zollgebiets zu werden)을 구별하세요."},{"title":"damals · früher · heute · bis heute","term":"Temporaladverbien: damals, früher, heute, bis heute","explain":"damals는 앞에서 말한 과거의 한 시기, 곧 '그때, 당시'를 가리켜요. früher는 지금과 비교한 '예전에'라는 뜻이라서 heute와 짝을 이뤄 자주 써요(früher …, heute …). bis heute는 과거에 시작된 일이 지금까지 이어진다는 뜻이에요. 지금도 계속되는 상태를 말할 때는 동사를 현재 시제로 써요(… auf denen die Speicher bis heute stehen). 역사 안내문에서는 이런 부사로 과거와 현재를 구별해요.","pattern":"damals + 과거 시제  ·  früher … , heute …  ·  bis heute + 지금도 이어지는 상태(현재 시제)","examples":[{"de":"Bevor die Mauern hochgezogen wurden, rammten Arbeiter unzählige Pfähle aus Eichenholz in die Erde, auf denen die Speicher bis heute stehen.","ko":"벽을 쌓아 올리기 전에 일꾼들이 셀 수 없이 많은 참나무 말뚝을 땅에 박았고, 창고들은 지금까지도 그 말뚝 위에 서 있어요.","mark":["bis heute stehen"],"parts":[["Bevor die Mauern hochgezogen wurden,","종속절"],["rammten","동사"],["Arbeiter","주어"],["unzählige Pfähle aus Eichenholz","4격 목적어"],["in die Erde,","부사어(장소)"],["auf denen die Speicher bis heute stehen.","관계절"]]},{"de":"Gelagert wurden damals vor allem Kaffee, Tee, Gewürze und Teppiche.","ko":"당시 이곳에는 주로 커피, 차, 향신료, 양탄자가 보관되었어요.","mark":["damals"]},{"de":"Nehmen Sie sich Zeit für einen Spaziergang durch die Speicherstadt, wo früher schwere Säcke geschleppt wurden und heute Museen und Cafés auf Sie warten.","ko":"예전에는 무거운 자루를 나르던 곳이고, 오늘날에는 박물관과 카페가 여러분을 기다리는 슈파이허슈타트를 시간을 내어 천천히 산책해 보세요.","mark":["früher","heute"]}],"tip":"damals는 '그 시기'를 이미 알고 있을 때 써요. 이 글에서는 앞에서 설명한 창고 시대를 가리켜요. 그냥 '옛날에'라고 할 때는 früher가 더 자연스러워요."},{"title":"관계대명사 2격: dessen · deren","term":"Relativpronomen im Genitiv (dessen, deren)","explain":"관계절에서 '그 사람의 ~, 그것의 ~'를 말할 때 2격 관계대명사를 써요. 앞의 명사가 남성·중성이면 dessen, 여성이나 복수이면 deren이에요. dessen/deren 바로 뒤의 명사에는 관사를 쓰지 않아요(dessen Kaffee, deren Geschichte). 관계절의 동사는 끝에 와요.","pattern":"남성·중성 명사, dessen + 명사 … 동사(끝)  ·  여성·복수 명사, deren + 명사 … 동사(끝)","examples":[{"de":"Ein Kaufmann, dessen Kaffee hier lag, musste sich deshalb auf ihre Erfahrung verlassen können.","ko":"그래서 커피를 이곳에 맡겨 둔 상인은 이들의 경험을 믿을 수 있어야 했어요.","mark":["dessen Kaffee"],"parts":[["Ein Kaufmann,","주어"],["dessen Kaffee hier lag,","관계절"],["musste","동사"],["sich","재귀대명사"],["deshalb","접속부사"],["auf ihre Erfahrung","전치사 목적어"],["verlassen können.","동사(끝)"]]},{"de":"Am bekanntesten ist das Chilehaus, dessen spitze Ecke an den Bug eines Schiffes erinnert.","ko":"가장 유명한 건물은 칠레하우스로, 뾰족한 모서리가 배의 뱃머리를 떠올리게 해요.","mark":["dessen spitze Ecke"]},{"de":"Eine wichtige Rolle spielten dabei die Quartiersleute, deren Aufgabe die Prüfung und fachgerechte Lagerung der Waren war.","ko":"이때 중요한 역할을 한 사람들이 크바르티어스로이테, 곧 창고 관리인이었어요. 이들은 물건을 검사하고 알맞게 보관하는 일을 맡았어요.","mark":["deren Aufgabe"]},{"de":"Seit 2015 gehören die beiden Viertel, deren Geschichte eng mit dem Hafen verbunden ist, gemeinsam zum UNESCO-Welterbe.","ko":"역사가 항구와 깊이 연결된 이 두 지구는 2015년부터 함께 유네스코 세계유산에 올라 있어요.","mark":["deren Geschichte"]}],"tip":"dessen/deren의 성과 수는 뒤의 명사가 아니라 앞의 명사에 맞춰요. 'das Chilehaus, dessen Ecke'에서 Ecke는 여성이지만 앞의 Chilehaus가 중성이라서 dessen이에요."},{"title":"장소를 나타내는 관계절: wo","term":"Relativsatz mit wo","explain":"장소를 나타내는 명사나 dort, da 뒤에서는 'in dem, in der' 대신 wo로 관계절을 시작할 수 있어요. wo 관계절은 '~하는 곳'이라는 뜻이고, 동사는 끝에 와요. 지명이나 장소 이름(die Speicherstadt, das Kontorhausviertel) 뒤에서도 자주 써요.","pattern":"장소 명사 / dort, + wo + … + 동사(끝)","examples":[{"de":"Die Antwort finden Sie dort, wo niemand hinschaut, nämlich tief unter Ihren Füßen.","ko":"답은 아무도 눈여겨보지 않는 곳, 바로 여러분의 발아래 깊은 곳에 있어요.","mark":["dort, wo"],"parts":[["Die Antwort","4격 목적어"],["finden","동사"],["Sie","주어"],["dort,","부사어(장소)"],["wo niemand hinschaut,","관계절"],["nämlich tief unter Ihren Füßen.","부사어(장소)"]]},{"de":"Hamburg hatte 1881 zugestimmt, Teil des deutschen Zollgebiets zu werden; die Kaufleute brauchten deshalb einen Freihafen, wo sie Waren zollfrei einlagern konnten.","ko":"함부르크는 1881년에 독일 관세 구역에 들어가기로 동의했어요. 그래서 상인들에게는 관세 없이 물건을 보관할 수 있는 자유항이 필요했어요.","mark":["einen Freihafen, wo"]},{"de":"Zum Schluss führt Sie unser Rundgang ins nahe Kontorhausviertel, wo Reedereien und Handelsfirmen ab den 1920er-Jahren große Bürohäuser bauen ließen.","ko":"마지막으로 이번 투어는 가까운 콘토어하우스 지구로 이어져요. 그곳에는 1920년대부터 해운 회사와 무역 회사들이 큰 사무용 건물을 세웠어요.","mark":["Kontorhausviertel, wo"]}],"tip":"wo 대신 전치사 + 관계대명사를 써도 돼요(einen Freihafen, in dem …). 글에서는 시간을 나타내는 명사 뒤에 wo보다 als나 전치사 + 관계대명사(an dem, in dem)를 쓰는 것이 좋아요."}],"vocab":[{"de":"der Speicher, -","ko":"창고"},{"de":"das Fleet, -e","ko":"(함부르크의) 운하"},{"de":"der Backstein, -e","ko":"벽돌"},{"de":"zu|stimmen + Dat.","ko":"동의하다"},{"de":"der Zoll, -¨e","ko":"관세"},{"de":"der Freihafen, -¨","ko":"자유항(관세 없이 물건을 둘 수 있는 항구 구역)"},{"de":"ab|reißen (reißt ab, riss ab, hat abgerissen)","ko":"(건물을) 철거하다"},{"de":"errichten","ko":"세우다, 짓다"},{"de":"versinken (versank, ist versunken)","ko":"가라앉다"},{"de":"sumpfig","ko":"늪 같은, 질척한"},{"de":"der Pfahl, -¨e","ko":"말뚝"},{"de":"faulen (hat/ist gefault)","ko":"썩다"},{"de":"die Seilwinde, -n","ko":"밧줄 윈치(짐을 끌어 올리는 장치)"},{"de":"der Lastkahn, -¨e","ko":"짐배, 바지선"},{"de":"sich verlassen auf + Akk. (verlässt sich, verließ sich, hat sich verlassen)","ko":"~을 믿다, ~에 의지하다"},{"de":"die Reederei, -en","ko":"해운 회사"}],"phrases":[{"de":"Teil einer Sache (Gen.) werden","ko":"~의 일부가 되다","ex":"Hamburg hatte 1881 zugestimmt, Teil des deutschen Zollgebiets zu werden","exko":"함부르크는 1881년에 독일 관세 구역에 들어가기로 동의했어요"},{"de":"Abschnitt für Abschnitt","ko":"구역별로 차례차례","ex":"Ab 1883 wurde das alte Wohnviertel abgerissen, und Abschnitt für Abschnitt wurden die neuen Speicher errichtet.","exko":"1883년부터 옛 주택가가 철거되었고, 새 창고들이 구역별로 차례차례 세워졌어요."},{"de":"eine wichtige Rolle spielen","ko":"중요한 역할을 하다","ex":"Eine wichtige Rolle spielten dabei die Quartiersleute, deren Aufgabe die Prüfung und fachgerechte Lagerung der Waren war.","exko":"이때 중요한 역할을 한 사람들이 창고 관리인이었어요. 이들은 물건을 검사하고 알맞게 보관하는 일을 맡았어요."},{"de":"an etwas (Akk.) erinnern","ko":"~을 떠올리게 하다","ex":"Am bekanntesten ist das Chilehaus, dessen spitze Ecke an den Bug eines Schiffes erinnert.","exko":"가장 유명한 건물은 칠레하우스로, 뾰족한 모서리가 배의 뱃머리를 떠올리게 해요."},{"de":"sich (Dat.) Zeit nehmen für + Akk.","ko":"~에 시간을 내다","ex":"Nehmen Sie sich Zeit für einen Spaziergang durch die Speicherstadt","exko":"시간을 내어 슈파이허슈타트를 천천히 산책해 보세요"}],"words":357},{"id":"b1-16","level":"B1","no":16,"title":"Rede zum Schulabschluss","titleKo":"졸업식 학생 대표 연설","type":"Rede","typeKo":"연설문","intro":"레알슐레 졸업식에서 학생 대표가 6년의 학교생활을 돌아보는 연설이에요.","focus":["화법조동사 완료형","동사 + 전치사","재귀대명사 3격·4격","강조 불변화사"],"paragraphs":[{"style":"meta","de":"Ronja Feldhaus, Schülersprecherin der Realschule am Lindenpark","ko":"린덴파크 레알슐레 학생 대표 로냐 펠트하우스"},{"style":"meta","de":"Sehr geehrte Frau Ostendorf, liebe Lehrerinnen und Lehrer, liebe Eltern, liebe Mitschülerinnen und Mitschüler,","ko":"존경하는 오스텐도르프 선생님, 선생님 여러분, 부모님 여러분, 그리고 학우 여러분,"},{"de":"als wir vor sechs Jahren zum ersten Mal in dieser Aula saßen, waren wir zehn oder elf. Ehrlich gesagt hätte ich mir damals nicht vorstellen können, dass ausgerechnet ich heute am Rednerpult stehen würde. Als Fünftklässlerin war ich nämlich so schüchtern, dass ich mich nicht einmal getraut habe, im Sekretariat nach dem Weg zum Musikraum zu fragen.","ko":"6년 전 처음으로 이 강당에 앉아 있었을 때 저희는 열 살이나 열한 살이었습니다. 솔직히 말씀드리면, 그때의 저는 다름 아닌 제가 오늘 이 연단에 서게 되리라고는 상상도 하지 못했을 것입니다. 5학년 때 저는 수줍음이 너무 많아서 행정실에 가서 음악실 가는 길을 물어볼 용기조차 내지 못했기 때문입니다."},{"de":"Sechs Jahre lang haben wir um halb sieben aufstehen müssen, obwohl wir lieber im Bett geblieben wären. Nach schlechten Noten fehlte uns manchmal die Motivation, weiterzumachen, besonders in der achten Klasse, als sich die Klassenarbeiten stapelten. Gerade damals lernten wir, einander zu helfen: Wer eine Hausaufgabe nicht verstanden hatte, fand in der Pause immer jemanden, der sie ihm geduldig erklärte.","ko":"저희는 6년 동안, 차라리 침대에 그대로 있고 싶었는데도 아침 6시 반에 일어나야 했습니다. 나쁜 점수를 받고 나면 계속해 나갈 의욕이 없을 때도 있었는데, 시험이 줄줄이 쌓였던 8학년 때는 특히 그랬습니다. 바로 그때 저희는 서로 돕는 법을 배웠습니다. 숙제를 이해하지 못한 사람은 쉬는 시간에 그것을 차근차근 설명해 주는 친구를 언제나 찾을 수 있었습니다."},{"de":"Zunächst möchte ich mich bei unseren Lehrerinnen und Lehrern bedanken – dafür, dass sie mehr Geduld mit uns hatten, als wir verdient haben. Besonders bedanken möchte ich mich bei Herrn Pohlmann, der uns vier Jahre lang als Klassenlehrer begleitet hat. Ohne seine Übungsstunden in der Mittagspause hätten einige von uns die Matheprüfung wohl nicht bestehen können – ich übrigens auch nicht.","ko":"먼저 선생님들께, 저희에게 과분할 만큼 큰 인내심을 보여 주신 데 대해 감사드리고 싶습니다. 특히 4년 동안 담임 선생님으로서 저희와 함께해 주신 폴만 선생님께 감사드리고 싶습니다. 선생님께서 점심시간에 열어 주신 연습 시간이 없었다면 저희 중 몇몇은 아마 수학 시험에 합격하지 못했을 것입니다. 덧붙이자면 저도 마찬가지였을 것입니다."},{"de":"Liebe Eltern, auch bei Ihnen möchten wir uns bedanken. Sie haben uns frühmorgens geweckt, Pausenbrote geschmiert und alle Elternbriefe unterschrieben – sogar die, die wir erst am letzten Tag zerknittert aus der Schultasche gezogen haben. Vor allem aber haben Sie an uns geglaubt, wenn wir selbst an uns gezweifelt haben.","ko":"부모님 여러분, 여러분께도 감사드리고 싶습니다. 여러분은 이른 아침마다 저희를 깨워 주셨고, 쉬는 시간에 먹을 빵을 싸 주셨고, 가정통신문에 빠짐없이 서명해 주셨습니다. 저희가 마지막 날에야 구겨진 채로 책가방에서 꺼낸 통신문까지 말입니다. 무엇보다도 여러분은 저희가 스스로를 믿지 못할 때에도 저희를 믿어 주셨습니다."},{"de":"Nach den Sommerferien trennen sich unsere Wege: Einige beginnen eine Ausbildung, andere wechseln aufs Gymnasium. Zum ersten Mal entscheiden wir selbst, wie es weitergeht, und tragen damit auch die Verantwortung. Ich würde gern behaupten, dass mir das keine Angst macht. Aber das wäre gelogen. Sicher ist nur, dass ich mich darauf freue, meine Ausbildung zur Tischlerin zu beginnen.","ko":"여름 방학이 끝나면 저희는 각자의 길을 가게 됩니다. 몇몇은 직업 교육을 시작하고, 다른 친구들은 김나지움으로 옮겨 갑니다. 저희는 처음으로 앞으로 어떻게 할지 스스로 결정하고, 그에 따른 책임도 지게 됩니다. 저는 그것이 두렵지 않다고 말하고 싶습니다. 하지만 그렇게 말한다면 거짓말일 것입니다. 확실한 것은 제가 목수 직업 교육을 시작할 날을 기다리고 있다는 사실 하나뿐입니다."},{"de":"Heute verabschieden wir uns von unserer Realschule, aber hoffentlich nicht voneinander. Deshalb hätte ich einen Vorschlag: Treffen wir uns in fünf Jahren wieder in dieser Aula, um zu erfahren, was aus jedem von uns geworden ist!","ko":"오늘 저희는 이 레알슐레와 작별합니다. 하지만 서로와는 작별하지 않기를 바랍니다. 그래서 한 가지 제안이 있습니다. 5년 뒤에 이 강당에서 다시 만나, 저희 각자가 어떤 사람이 되었는지 알아보면 어떨까요?"},{"de":"Liebe Mitschülerinnen und Mitschüler, danke, dass ihr diese sechs Jahre zu etwas Besonderem gemacht habt. Und jetzt lasst uns feiern!","ko":"학우 여러분, 이 6년을 특별한 시간으로 만들어 주어서 고맙습니다. 자, 이제 다 함께 즐길 시간입니다!"}],"questions":[{"type":"rf","kind":"detail","q":"In ihrem ersten Jahr an der Schule hatte Ronja nicht den Mut, im Schulbüro eine Frage zu stellen.","answer":0,"evidence":"dass ich mich nicht einmal getraut habe, im Sekretariat nach dem Weg zum Musikraum zu fragen","pairs":[["nicht einmal getraut","nicht den Mut"],["im Sekretariat","im Schulbüro"],["Als Fünftklässlerin","In ihrem ersten Jahr an der Schule"]],"explain":"로냐는 5학년 때 행정실(Sekretariat)에 음악실 가는 길을 물어볼 용기조차 내지 못했다고 해요. 6년 전 열 살이나 열한 살에 이 학교에 들어왔으니 5학년이 이 학교에서 보낸 첫해예요. 문제에서는 sich nicht trauen을 nicht den Mut haben으로, Sekretariat를 Schulbüro로 바꿔 말했어요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Ehrlich gesagt hätte ich mir damals nicht vorstellen können, dass ausgerechnet ich heute am Rednerpult stehen würde.“?","options":["Als Kind hätte sie nie gedacht, dass sie eines Tages vor Publikum spricht.","Schon in der fünften Klasse wollte sie unbedingt einmal am Rednerpult stehen.","Heute kann sie sich kaum vorstellen, dass sie früher so schüchtern war."],"answer":0,"evidence":"Ehrlich gesagt hätte ich mir damals nicht vorstellen können, dass ausgerechnet ich heute am Rednerpult stehen würde.","pairs":[["hätte ich mir damals nicht vorstellen können","Als Kind hätte sie nie gedacht"],["heute am Rednerpult stehen","vor Publikum spricht"]],"explain":"'그때의 저는 다름 아닌 제가 오늘 연단에 서리라고는 상상하지 못했을 것'이라는 뜻이에요. 그러니까 어렸을 때는 자기가 언젠가 사람들 앞에서 말하게 될 줄 몰랐다는 보기가 맞아요. 5학년 때부터 연단에 서고 싶었다는 것은 반대 내용이에요. 수줍음이 많았던 과거를 지금 믿기 어렵다는 것은 '상상하지 못한 시점'을 과거에서 현재로 뒤바꾼 내용이에요."},{"type":"mc","kind":"detail","q":"Was berichtet Ronja über die achte Klasse?","options":["Damals fand man in der Pause kaum jemanden, der bei den Aufgaben half.","Damals mussten alle zum ersten Mal schon um halb sieben aufstehen.","Damals mussten sie in kurzer Zeit ungewöhnlich viele Tests schreiben."],"answer":2,"evidence":"besonders in der achten Klasse, als sich die Klassenarbeiten stapelten","pairs":[["als sich die Klassenarbeiten stapelten","in kurzer Zeit ungewöhnlich viele Tests schreiben"],["fand in der Pause immer jemanden","fand man in der Pause kaum jemanden"],["Sechs Jahre lang","zum ersten Mal"]],"explain":"8학년 때는 Klassenarbeiten(학교 필기시험)이 쌓였다(sich stapeln)고 해요. 짧은 기간에 시험을 아주 많이 봐야 했다는 뜻이에요. 바로 그때 서로 돕는 법을 배웠고 쉬는 시간에는 늘 설명해 줄 친구가 있었으니, 도와줄 사람이 거의 없었다는 보기는 틀려요. 6시 반에 일어나는 일은 6년 내내 해야 했으니 8학년 때 처음 시작된 일도 아니에요."},{"type":"mc","kind":"inference","q":"Was kann man aus Ronjas Dank an Herrn Pohlmann schließen?","options":["Er hat ihre Klasse alle sechs Jahre lang als Klassenlehrer geführt.","Ohne seine Hilfe wäre vermutlich auch Ronja in Mathe durchgefallen.","Seine Übungsstunden fanden immer am Nachmittag nach dem Unterricht statt."],"answer":1,"evidence":"Ohne seine Übungsstunden in der Mittagspause hätten einige von uns die Matheprüfung wohl nicht bestehen können – ich übrigens auch nicht.","pairs":[["ich übrigens auch nicht","wäre vermutlich auch Ronja in Mathe durchgefallen"],["vier Jahre lang","alle sechs Jahre lang"],["in der Mittagspause","am Nachmittag nach dem Unterricht"]],"explain":"로냐는 폴만 선생님의 연습 시간이 없었다면 몇몇은 수학 시험에 합격하지 못했을 거라고 말한 뒤 '참고로 저도요(ich übrigens auch nicht)'라고 덧붙여요. 로냐 자신도 그 도움 덕분에 합격했다는 뜻이에요. 폴만 선생님이 담임을 맡은 기간은 6년이 아니라 4년이고, 연습 시간은 오후가 아니라 점심시간(Mittagspause)에 있었어요."},{"type":"rf","kind":"detail","q":"Die Eltern haben nur die Elternbriefe unterschrieben, die rechtzeitig aus der Schultasche gezogen wurden.","answer":1,"evidence":"alle Elternbriefe unterschrieben – sogar die, die wir erst am letzten Tag zerknittert aus der Schultasche gezogen haben","pairs":[["alle Elternbriefe unterschrieben – sogar die","nur die Elternbriefe unterschrieben"],["erst am letzten Tag","rechtzeitig"]],"explain":"로냐는 부모님이 가정통신문에 모두 서명해 주셨고, 마지막 날에야 구겨진 채로 꺼낸 통신문까지(sogar die) 서명해 주셨다고 말해요. 그러니까 제때 꺼낸 통신문에만 서명했다는 말은 틀려요."},{"type":"mc","kind":"meaning","q":"Was meint Ronja mit „und tragen damit auch die Verantwortung“?","options":["Die Eltern bestimmen weiterhin, wie es nach der Schule weitergeht.","Die Lehrer sind auch nach dem Abschluss noch für alle zuständig.","Wer nun selbst wählt, muss auch mit den Folgen seiner Wahl leben."],"answer":2,"evidence":"Zum ersten Mal entscheiden wir selbst, wie es weitergeht, und tragen damit auch die Verantwortung.","pairs":[["entscheiden wir selbst","Wer nun selbst wählt"],["die Verantwortung","mit den Folgen seiner Wahl leben"]],"explain":"로냐는 졸업생들이 처음으로 앞으로의 길을 스스로 정하고, 그래서(damit) 그 책임도 진다고 말해요. 스스로 고른 사람은 그 결과도 받아들여야 한다는 뜻이에요. 부모님이 계속 정한다거나 선생님이 계속 책임진다는 보기는 '우리가 스스로 결정한다'는 앞부분과 맞지 않아요."},{"type":"mc","kind":"inference","q":"Wie fühlt sich Ronja wahrscheinlich, wenn sie an die Zeit nach der Schule denkt?","options":["Sie hat gar keine Angst, weil ihre Ausbildung schon sicher ist.","Sie blickt mit Vorfreude nach vorn, ist aber auch etwas nervös.","Sie wäre eigentlich lieber wie andere aufs Gymnasium gewechselt."],"answer":1,"evidence":"Ich würde gern behaupten, dass mir das keine Angst macht. Aber das wäre gelogen.","pairs":[["Aber das wäre gelogen.","ist aber auch etwas nervös"],["dass ich mich darauf freue","mit Vorfreude"]],"explain":"로냐는 두렵지 않다고 말하면 거짓말일 거라고 해요. 조금은 불안하다는 뜻이에요. 동시에 목수 직업 교육을 시작할 날을 기다린다고 하니까, 설레면서도 조금 긴장된다고 추론할 수 있어요. 전혀 두렵지 않다는 보기는 로냐가 직접 '거짓말'이라고 한 내용이에요. 직업 교육을 기대한다고 했으니 김나지움에 가지 않은 것을 아쉬워한다는 보기도 틀려요."},{"type":"mc","kind":"gist","q":"Worum geht es in Ronjas Rede vor allem?","options":["um Erinnerungen an die Schulzeit, um Dank und um Pläne für später","um Kritik an den vielen Klassenarbeiten und am frühen Aufstehen","um den Abschied von Herrn Pohlmann, der die Realschule bald verlässt"],"answer":0,"evidence":"Heute verabschieden wir uns von unserer Realschule, aber hoffentlich nicht voneinander.","pairs":[["als wir vor sechs Jahren zum ersten Mal in dieser Aula saßen","Erinnerungen an die Schulzeit"],["Zunächst möchte ich mich bei unseren Lehrerinnen und Lehrern bedanken","um Dank"],["Sicher ist nur, dass ich mich darauf freue, meine Ausbildung zur Tischlerin zu beginnen.","Pläne für später"]],"explain":"로냐는 6년 전 입학했을 때를 돌아보고, 선생님과 부모님께 감사하고, 졸업 뒤의 계획을 이야기해요. 시험이 많았던 일과 일찍 일어나야 했던 일은 비판이 아니라 추억으로 말해요. 학교를 떠나는 사람은 폴만 선생님이 아니라 졸업생들이에요."}],"grammar":[{"title":"화법조동사의 현재완료와 접속법 2식 과거 – 동사원형 두 개","term":"Modalverben im Perfekt und im Konjunktiv II der Vergangenheit (Ersatzinfinitiv)","explain":"화법조동사를 다른 동사와 함께 현재완료로 쓰면 과거분사 gemusst, gekonnt 대신 동사원형 müssen, können을 써요. 그래서 문장 끝에 동사원형이 두 개 나란히 와요(aufstehen müssen). 완료형은 haben으로 만들어요. aufstehen은 혼자 쓰면 sein으로 완료형을 만들지만(ich bin aufgestanden), 화법조동사와 함께 쓰면 haben을 써요. 접속법 2식 과거도 같은 방식이에요. hätte + … + 동사원형 + 화법조동사 원형으로, 과거에 실제로는 일어나지 않은 가능성을 말해요.","pattern":"haben / hätte + … + 동사원형 + 화법조동사 원형(끝)","examples":[{"de":"Sechs Jahre lang haben wir um halb sieben aufstehen müssen, obwohl wir lieber im Bett geblieben wären.","ko":"저희는 6년 동안, 차라리 침대에 그대로 있고 싶었는데도 아침 6시 반에 일어나야 했습니다.","mark":["haben","aufstehen müssen"],"parts":[["Sechs Jahre lang","부사어(시간)"],["haben","동사"],["wir","주어"],["um halb sieben","부사어(시간)"],["aufstehen müssen,","동사(끝)"],["obwohl wir lieber im Bett geblieben wären.","종속절"]]},{"de":"Ohne seine Übungsstunden in der Mittagspause hätten einige von uns die Matheprüfung wohl nicht bestehen können – ich übrigens auch nicht.","ko":"선생님께서 점심시간에 열어 주신 연습 시간이 없었다면 저희 중 몇몇은 아마 수학 시험에 합격하지 못했을 것입니다. 덧붙이자면 저도 마찬가지였을 것입니다.","mark":["hätten","bestehen können"],"parts":[["Ohne seine Übungsstunden in der Mittagspause","부사어"],["hätten","동사"],["einige von uns","주어"],["die Matheprüfung","4격 목적어"],["wohl","기타"],["nicht","부정어"],["bestehen können","동사(끝)"],["– ich übrigens auch nicht.","기타"]]}],"tip":"부문장에서는 haben이 동사원형 두 개 앞으로 와요: …, dass wir um halb sieben haben aufstehen müssen. 과거형을 쓰면 더 간단하게 말할 수 있어요: Wir mussten um halb sieben aufstehen."},{"title":"전치사와 함께 쓰는 동사 – 전치사와 격을 함께 외우기","term":"Verben mit Präpositionalobjekt (sich bedanken bei … für …, sich verabschieden von, glauben an, zweifeln an)","explain":"어떤 동사는 정해진 전치사와 함께 써요. 전치사마다 3격이나 4격이 정해져 있고, an처럼 두 격을 다 쓰는 전치사는 동사에 따라 격이 달라져요. 그래서 동사, 전치사, 격을 한 덩어리로 외우는 것이 좋아요. sich bedanken은 감사하는 사람 앞에 bei + 3격을, 감사하는 이유 앞에 für + 4격을 써요. sich verabschieden von은 3격, glauben an은 4격, zweifeln an은 3격과 함께 써요.","pattern":"sich bedanken bei + 3격 (für + 4격) · sich verabschieden von + 3격 · glauben an + 4격 · zweifeln an + 3격","examples":[{"de":"Heute verabschieden wir uns von unserer Realschule, aber hoffentlich nicht voneinander.","ko":"오늘 저희는 이 레알슐레와 작별합니다. 하지만 서로와는 작별하지 않기를 바랍니다.","mark":["verabschieden","von unserer Realschule","voneinander"],"parts":[["Heute","부사어(시간)"],["verabschieden","동사"],["wir","주어"],["uns","재귀대명사"],["von unserer Realschule,","전치사 목적어"],["aber hoffentlich nicht voneinander.","기타"]]},{"de":"Vor allem aber haben Sie an uns geglaubt, wenn wir selbst an uns gezweifelt haben.","ko":"무엇보다도 여러분은 저희가 스스로를 믿지 못할 때에도 저희를 믿어 주셨습니다.","mark":["an uns geglaubt","an uns gezweifelt"],"parts":[["Vor allem","부사어"],["aber","접속부사"],["haben","동사"],["Sie","주어"],["an uns","전치사 목적어"],["geglaubt,","동사(끝)"],["wenn wir selbst an uns gezweifelt haben.","종속절"]]},{"de":"Besonders bedanken möchte ich mich bei Herrn Pohlmann, der uns vier Jahre lang als Klassenlehrer begleitet hat.","ko":"특히 4년 동안 담임 선생님으로서 저희와 함께해 주신 폴만 선생님께 감사드리고 싶습니다.","mark":["bedanken","bei Herrn Pohlmann"]}],"tip":"glauben an과 zweifeln an은 같은 an을 쓰지만 격이 달라요: Ich glaube an den Erfolg. / Ich zweifle am Erfolg. 전치사 뒤에 명사 대신 dass 절이 오면 da(r)- + 전치사를 앞에 둬요: Zunächst möchte ich mich … bedanken – dafür, dass sie mehr Geduld mit uns hatten, …"},{"title":"재귀대명사 4격과 3격 – mich와 mir","term":"Reflexivpronomen im Akkusativ und im Dativ","explain":"재귀대명사는 주어와 같은 사람을 가리켜요. 재귀대명사 말고 다른 4격 목적어가 없으면 보통 4격(mich, dich)을 써요: Ich traue mich nicht. 문장에 4격 목적어가 따로 있으면 재귀대명사는 3격(mir, dir)이 돼요: Ich stelle mir etwas vor. 본문의 두 번째 예문에서는 dass 절이 4격 목적어 역할을 해요. 3격과 4격의 모양이 다른 것은 ich와 du뿐이에요(mich/mir, dich/dir). 나머지는 모양이 같아요(sich, uns, euch).","pattern":"sich (4격): ich → mich, du → dich · sich (3격) + 4격 목적어: ich → mir, du → dir","examples":[{"de":"Als Fünftklässlerin war ich nämlich so schüchtern, dass ich mich nicht einmal getraut habe, im Sekretariat nach dem Weg zum Musikraum zu fragen.","ko":"5학년 때 저는 수줍음이 너무 많아서 행정실에 가서 음악실 가는 길을 물어볼 용기조차 내지 못했기 때문입니다.","mark":["mich","getraut"],"parts":[["Als Fünftklässlerin","부사어(시간)"],["war","동사"],["ich","주어"],["nämlich","기타"],["so schüchtern,","보어"],["dass ich mich nicht einmal getraut habe, im Sekretariat nach dem Weg zum Musikraum zu fragen.","종속절"]]},{"de":"Ehrlich gesagt hätte ich mir damals nicht vorstellen können, dass ausgerechnet ich heute am Rednerpult stehen würde.","ko":"솔직히 말씀드리면, 그때의 저는 다름 아닌 제가 오늘 이 연단에 서게 되리라고는 상상도 하지 못했을 것입니다.","mark":["mir","vorstellen"],"parts":[["Ehrlich gesagt","기타"],["hätte","동사"],["ich","주어"],["mir","재귀대명사"],["damals","부사어(시간)"],["nicht","부정어"],["vorstellen können,","동사(끝)"],["dass ausgerechnet ich heute am Rednerpult stehen würde.","종속절"]]}],"tip":"sich vorstellen은 격에 따라 뜻이 달라요. Ich stelle mich vor.는 '제 소개를 해요', Ich stelle mir das vor.는 '그것을 상상해요'라는 뜻이에요."},{"title":"강조하는 말 – ausgerechnet · gerade · sogar","term":"Fokuspartikeln: ausgerechnet, gerade, sogar","explain":"이 말들은 보통 바로 뒤에 오는 말에 힘을 줘요. ausgerechnet는 '하필이면, 다름 아닌'이라는 뜻으로, 그렇게 될 줄 몰랐던 사람이나 일을 가리켜요. 본문의 ausgerechnet ich는 수줍음이 많던 자기가 연설을 하게 되어 놀랍다는 뜻이에요. gerade는 '바로 그 ~'라는 뜻으로, 다른 때나 다른 사람이 아니라 바로 그때, 그 사람이라는 점을 강조해요. 본문의 Gerade damals는 힘들었던 8학년 때 오히려 서로 돕는 법을 배웠다는 뜻이에요. sogar는 '~까지도, 심지어'라는 뜻으로, 예상하기 어려운 경우까지 덧붙여요.","pattern":"ausgerechnet · gerade · sogar + 강조할 말","examples":[{"de":"Gerade damals lernten wir, einander zu helfen","ko":"바로 그때 저희는 서로 돕는 법을 배웠습니다","mark":["Gerade damals"],"parts":[["Gerade damals","부사어(시간)"],["lernten","동사"],["wir,","주어"],["einander zu helfen","zu 부정사구"]]},{"de":"Sie haben uns frühmorgens geweckt, Pausenbrote geschmiert und alle Elternbriefe unterschrieben – sogar die, die wir erst am letzten Tag zerknittert aus der Schultasche gezogen haben.","ko":"여러분은 이른 아침마다 저희를 깨워 주셨고, 쉬는 시간에 먹을 빵을 싸 주셨고, 가정통신문에 빠짐없이 서명해 주셨습니다. 저희가 마지막 날에야 구겨진 채로 책가방에서 꺼낸 통신문까지 말입니다.","mark":["sogar die"]},{"de":"dass ausgerechnet ich heute am Rednerpult stehen würde","ko":"다름 아닌 제가 오늘 연단에 서게 되리라는 것","mark":["ausgerechnet ich"]}],"tip":"sogar에 해당하는 부정 표현은 nicht einmal(~조차 ~않다)이에요: dass ich mich nicht einmal getraut habe, … zu fragen. gerade는 '방금'이라는 시간 부사로도 써요: Ich bin gerade angekommen."}],"vocab":[{"de":"die Schülersprecherin, -nen","ko":"학생 대표(여자)"},{"de":"die Aula, Aulen","ko":"(학교) 강당"},{"de":"das Rednerpult, -e","ko":"연단, 연설대"},{"de":"schüchtern","ko":"수줍어하는, 내성적인"},{"de":"sich (Akk.) trauen + zu + Inf.","ko":"용기를 내어 ~하다"},{"de":"das Sekretariat, -e","ko":"(학교) 행정실, 사무실"},{"de":"die Klassenarbeit, -en","ko":"(수업 시간에 보는) 학교 필기시험"},{"de":"sich stapeln","ko":"(일·서류 등이) 쌓이다"},{"de":"geduldig","ko":"참을성 있게, 차근차근"},{"de":"begleiten","ko":"곁에서 함께하다, 이끌어 주다"},{"de":"bestehen (bestand, hat bestanden)","ko":"(시험에) 합격하다"},{"de":"der Elternbrief, -e","ko":"가정통신문"},{"de":"zerknittert","ko":"구겨진"},{"de":"zweifeln an + Dat.","ko":"~을 의심하다, 믿지 못하다"},{"de":"die Verantwortung (Sg.)","ko":"책임"},{"de":"sich verabschieden von + Dat.","ko":"~와 작별하다"}],"phrases":[{"de":"ehrlich gesagt","ko":"솔직히 말하면","ex":"Ehrlich gesagt hätte ich mir damals nicht vorstellen können, dass ausgerechnet ich heute am Rednerpult stehen würde.","exko":"솔직히 말씀드리면, 그때의 저는 다름 아닌 제가 오늘 이 연단에 서게 되리라고는 상상도 하지 못했을 것입니다."},{"de":"Geduld mit jemandem haben","ko":"~에게 참을성 있게 대하다","ex":"Zunächst möchte ich mich bei unseren Lehrerinnen und Lehrern bedanken – dafür, dass sie mehr Geduld mit uns hatten, als wir verdient haben.","exko":"먼저 선생님들께, 저희에게 과분할 만큼 큰 인내심을 보여 주신 데 대해 감사드리고 싶습니다."},{"de":"an jemanden glauben","ko":"~을 믿어 주다","ex":"Vor allem aber haben Sie an uns geglaubt, wenn wir selbst an uns gezweifelt haben.","exko":"무엇보다도 여러분은 저희가 스스로를 믿지 못할 때에도 저희를 믿어 주셨습니다."},{"de":"Die Wege trennen sich.","ko":"각자 다른 길을 가게 되다","ex":"Nach den Sommerferien trennen sich unsere Wege: Einige beginnen eine Ausbildung, andere wechseln aufs Gymnasium.","exko":"여름 방학이 끝나면 저희는 각자의 길을 가게 됩니다. 몇몇은 직업 교육을 시작하고, 다른 친구들은 김나지움으로 옮겨 갑니다."},{"de":"aus jemandem wird etwas","ko":"~가 (어떤 사람으로) 되다, 자라다","ex":"Treffen wir uns in fünf Jahren wieder in dieser Aula, um zu erfahren, was aus jedem von uns geworden ist!","exko":"5년 뒤에 이 강당에서 다시 만나, 저희 각자가 어떤 사람이 되었는지 알아보면 어떨까요?"}],"words":360},{"id":"b1-17","level":"B1","no":17,"title":"Vom Altpapier zur Zeitung","titleKo":"폐지가 신문 용지가 되기까지","type":"Prozessbeschreibung im Kundenmagazin","typeKo":"고객 잡지의 과정 설명글","intro":"수거한 폐지가 새 신문 용지가 되기까지의 과정을 설명하는 글이에요.","focus":["수동태 현재완료","zum + 동사원형","nachdem · während","werden의 쓰임"],"paragraphs":[{"de":"Alle zwei Wochen leeren unsere Fahrzeuge Ihre blaue Papiertonne. Doch was passiert mit dem Papier, nachdem es abgeholt worden ist? Um das herauszufinden, haben wir die Papierfabrik Haslinger besucht, die aus Altpapier neues Zeitungspapier herstellt.","ko":"2주마다 저희 차량이 여러분의 파란 종이 수거함을 비워요. 그런데 수거된 종이는 그 뒤에 어떻게 될까요? 이것을 알아보려고 저희는 폐지로 새 신문 용지를 만드는 하슬링거 제지 공장을 찾아갔어요."},{"style":"h","de":"Erst sortieren, dann pressen","ko":"먼저 분류하고, 그다음 압축해요"},{"de":"Zunächst bringen wir das Papier in eine Sortieranlage, wo Zeitungen, Prospekte und Kartons über Förderbänder laufen. Von Hand und mit Maschinen wird die braune Pappe aussortiert, die sich nicht für die Herstellung von Zeitungspapier eignet. Außerdem entfernt man Fremdstoffe wie Plastikfolien oder Getränkedosen. Zum Verladen wird das Papier anschließend zu Ballen gepresst, die rund 500 Kilo wiegen.","ko":"먼저 저희는 이 종이를 선별 시설로 가져가요. 그곳에서는 신문, 광고 전단, 상자가 컨베이어 벨트 위를 지나가요. 갈색 판지는 신문 용지를 만드는 데 알맞지 않아서 손과 기계로 골라내요. 또 비닐이나 음료 캔 같은 이물질도 없애요. 그다음 차에 싣기 위해 종이를 뭉치로 압축하는데, 뭉치 하나의 무게는 약 500킬로그램이에요."},{"style":"h","de":"Ein Bad für alte Zeitungen","ko":"헌 신문을 물에 풀어요"},{"de":"Wenn ein Lastwagen in der Papierfabrik ankommt, ist seine Ladung also bereits sortiert und gepresst worden. Zum Auflösen werden die Ballen in einen riesigen Behälter mit warmem Wasser gegeben, wo das Papier unter ständigem Rühren in einzelne Fasern zerfällt und ein grauer Faserbrei entsteht.","ko":"그러니까 트럭이 제지 공장에 도착할 때 실려 있는 종이는 이미 분류되고 압축된 상태예요. 종이를 풀기 위해 뭉치를 따뜻한 물이 담긴 거대한 통에 넣어요. 그 안에서 계속 저어 주면 종이가 낱낱의 섬유로 풀어지면서 회색 섬유 죽이 생겨요."},{"de":"Nachdem Büroklammern, Klebereste und Sand Schritt für Schritt herausgefiltert worden sind, bleibt noch die Druckfarbe übrig. Zum Entfernen der Farbe gibt man eine seifenartige Flüssigkeit hinzu und bläst gleichzeitig Luft hinein. Die Farbteilchen bleiben an den Luftblasen hängen und steigen nach oben, wo sie als grauer Schaum abgeschöpft werden.","ko":"클립, 접착제 찌꺼기, 모래를 한 단계씩 걸러 낸 뒤에도 인쇄 잉크는 아직 남아 있어요. 잉크를 없애기 위해 비누 같은 액체를 넣고 동시에 공기를 불어 넣어요. 잉크 입자는 공기 방울에 달라붙어 위로 떠오르고, 그곳에서 회색 거품 상태로 걷어 내요."},{"style":"h","de":"Aus Brei wird Papier","ko":"죽이 종이가 돼요"},{"de":"Die nächste Station ist die Papiermaschine, die ungefähr so lang ist wie ein Fußballfeld. Der Faserbrei besteht hier zu 99 Prozent aus Wasser und wird auf ein großes Sieb gespritzt. Während das Wasser abläuft, verbinden sich die Fasern zu einer dünnen Schicht, der Papierbahn. Diese wird zwischen Walzen gepresst und läuft zum Trocknen über heiße Zylinder, bis kaum noch Feuchtigkeit in ihr steckt. Schließlich wird das fertige Papier auf riesige Rollen gewickelt und an die Druckereien der Tageszeitungen geliefert.","ko":"다음 단계는 제지기예요. 제지기는 길이가 대략 축구장만 해요. 이 단계에서 섬유 죽은 99퍼센트가 물이고, 큰 망 위에 뿌려져요. 물이 빠지는 동안 섬유가 서로 엉겨 얇은 층, 즉 종이 띠가 돼요. 이 종이 띠는 롤러 사이에서 눌린 다음, 물기가 거의 남지 않을 때까지 마르도록 뜨거운 실린더 위를 지나가요. 마지막으로 완성된 종이는 거대한 롤에 감겨 일간 신문 인쇄소로 보내져요."},{"de":"„Ohne frische Fasern aus Holz funktioniert dieser Kreislauf allerdings nicht“, erklärt Produktionsleiterin Henrike Oberdorf. „Bei jeder Wiederverwertung werden die Fasern nämlich kürzer. Wenn sie zu oft recycelt worden sind, halten sie nicht mehr zusammen, und die Qualität des Papiers sinkt.“","ko":"“하지만 나무에서 얻은 새 섬유가 없으면 이 순환은 이루어지지 않아요”라고 생산 책임자 헨리케 오버도르프 씨가 설명해요. “재활용할 때마다 섬유가 짧아지거든요. 너무 여러 번 재활용되면 섬유가 더 이상 서로 붙어 있지 못하고, 종이의 품질이 떨어져요.”"},{"de":"Und was können Sie tun? In die blaue Tonne gehören nur Papier, Pappe und Kartons. Benutzte Taschentücher, Backpapier und Kassenzettel werfen Sie bitte in den Restmüll. Und dieses Magazin? Sobald Sie es gelesen haben, ist es in der blauen Papiertonne genau richtig.","ko":"그럼 여러분은 무엇을 할 수 있을까요? 파란 수거함에는 종이, 판지, 상자만 넣어야 해요. 사용한 휴지, 유산지, 영수증은 일반 쓰레기로 버려 주세요. 그럼 이 잡지는요? 다 읽으신 뒤에는 파란 종이 수거함이 바로 제자리예요."}],"questions":[{"type":"rf","kind":"detail","q":"Die Papierfabrik Haslinger leert die blauen Tonnen alle zwei Wochen mit eigenen Fahrzeugen.","answer":1,"evidence":"Alle zwei Wochen leeren unsere Fahrzeuge Ihre blaue Papiertonne.","pairs":[["Alle zwei Wochen leeren unsere Fahrzeuge Ihre blaue Papiertonne","leert die blauen Tonnen alle zwei Wochen mit eigenen Fahrzeugen"],["haben wir die Papierfabrik Haslinger besucht","Die Papierfabrik Haslinger"]],"explain":"2주마다 파란 수거함을 비우는 것은 이 잡지를 내는 회사의 차량(unsere Fahrzeuge)이에요. 이 회사는 하슬링거 제지 공장을 찾아가서(besucht) 취재했고, 모은 종이를 먼저 선별 시설로 가져가는 것도 이 회사(wir)예요. 그러니까 제지 공장이 자기 차량으로 수거함을 비운다는 말은 틀려요."},{"type":"mc","kind":"detail","q":"Welche Aussage über die Sortieranlage stimmt?","options":["Dort wird die Druckfarbe mit Seife von den Fasern gelöst.","Dort wird die braune Pappe zu Zeitungspapier verarbeitet.","Dort holt man Verpackungen aus Plastik und Metall heraus."],"answer":2,"evidence":"Außerdem entfernt man Fremdstoffe wie Plastikfolien oder Getränkedosen.","pairs":[["Fremdstoffe wie Plastikfolien oder Getränkedosen","Verpackungen aus Plastik und Metall"],["die braune Pappe aussortiert, die sich nicht für die Herstellung von Zeitungspapier eignet","die braune Pappe zu Zeitungspapier verarbeitet"]],"explain":"선별 시설에서는 비닐이나 음료 캔 같은 이물질(Fremdstoffe)을 없애요. 정답은 이것을 '플라스틱과 금속으로 된 포장재를 꺼낸다'로 바꿔 말했어요. 갈색 판지는 신문 용지에 알맞지 않아서 골라내는 것이지 신문 용지로 만드는 것이 아니에요. 잉크를 없애는 일은 제지 공장에서 해요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Wenn ein Lastwagen in der Papierfabrik ankommt, ist seine Ladung also bereits sortiert und gepresst worden.“?","options":["Die Ladung wurde schon vor der Fahrt zur Fabrik getrennt und verdichtet.","Erst nach der Ankunft in der Fabrik wird die Ladung sortiert und dann gepresst.","In der Fabrik presst man das Papier, nachdem der Fahrer es dort sortiert hat."],"answer":0,"evidence":"Wenn ein Lastwagen in der Papierfabrik ankommt, ist seine Ladung also bereits sortiert und gepresst worden.","pairs":[["bereits sortiert und gepresst worden","schon vor der Fahrt zur Fabrik getrennt und verdichtet"],["Wenn ein Lastwagen in der Papierfabrik ankommt","vor der Fahrt zur Fabrik"]],"explain":"ist … worden은 수동태 현재완료예요. 트럭이 공장에 도착하는 시점에 분류와 압축은 이미 끝나 있다는 뜻이에요. 정답은 sortiert를 getrennt로, gepresst를 verdichtet로 바꿔 말했어요. 공장에 도착한 뒤에 분류하거나 압축한다는 두 보기는 bereits(이미)의 뜻과 맞지 않아요."},{"type":"rf","kind":"detail","q":"Bevor die Farbe an die Reihe kommt, sind kleinere Fremdkörper schon herausgeholt worden.","answer":0,"evidence":"Nachdem Büroklammern, Klebereste und Sand Schritt für Schritt herausgefiltert worden sind, bleibt noch die Druckfarbe übrig.","pairs":[["Nachdem","Bevor"],["Büroklammern, Klebereste und Sand","kleinere Fremdkörper"],["herausgefiltert worden sind","herausgeholt worden"]],"explain":"클립, 접착제 찌꺼기, 모래를 걸러 낸 뒤에도(Nachdem …) 인쇄 잉크가 남아 있다고 해요. 그러니까 잉크를 없애는 단계보다 작은 이물질을 꺼내는 단계가 먼저예요. 문제에서는 'A를 한 뒤에(nachdem) B'를 'B 전에(bevor) A'로 바꿔 말했어요. 일의 순서는 같아요."},{"type":"mc","kind":"meaning","q":"Was bedeutet „abgeschöpft“ im Text?","options":["durch ein feines Sieb gedrückt","von der Oberfläche abgenommen","zurück unter die Fasern gemischt"],"answer":1,"evidence":"Die Farbteilchen bleiben an den Luftblasen hängen und steigen nach oben, wo sie als grauer Schaum abgeschöpft werden.","pairs":[["steigen nach oben","von der Oberfläche"],["abgeschöpft","abgenommen"]],"explain":"abschöpfen은 액체 위에 뜬 것을 걷어 내는 거예요. 잉크 입자는 공기 방울에 붙어 위로 떠오르고(steigen nach oben), 위에 생긴 회색 거품을 걷어 내요. 체로 누르거나 다시 섞는 것이 아니에요."},{"type":"mc","kind":"detail","q":"Was geschieht mit der Papierbahn direkt nach dem Pressen zwischen den Walzen?","options":["Sie wird auf große Rollen gewickelt und zu den Druckereien gebracht.","Man gibt eine seifenartige Flüssigkeit dazu, damit sich die Farbe löst.","Sie wird über erhitzte Trommeln geführt, bis sie beinahe trocken ist."],"answer":2,"evidence":"Diese wird zwischen Walzen gepresst und läuft zum Trocknen über heiße Zylinder, bis kaum noch Feuchtigkeit in ihr steckt.","pairs":[["heiße Zylinder","erhitzte Trommeln"],["bis kaum noch Feuchtigkeit in ihr steckt","bis sie beinahe trocken ist"],["Schließlich wird das fertige Papier auf riesige Rollen gewickelt","Sie wird auf große Rollen gewickelt"]],"explain":"종이 띠는 롤러 사이에서 눌린 다음 뜨거운 실린더(heiße Zylinder) 위를 지나며, 물기가 거의 없어질 때까지 말라요. 정답은 Zylinder를 Trommeln으로, kaum noch Feuchtigkeit를 beinahe trocken으로 바꿔 말했어요. 롤에 감아 인쇄소로 보내는 일은 마지막(Schließlich) 단계이고, 비누 같은 액체를 넣는 일은 제지기에 오기 전 단계예요."},{"type":"mc","kind":"inference","q":"Was folgt aus der Erklärung von Frau Oberdorf?","options":["Dieselben Rohstoffe kann man nicht endlos zu neuem Papier verarbeiten.","Fasern aus Altpapier kann man immer nur ein einziges Mal wiederverwenden.","Je öfter man die Fasern recycelt, desto stabiler wird das neue Papier."],"answer":0,"evidence":"Wenn sie zu oft recycelt worden sind, halten sie nicht mehr zusammen, und die Qualität des Papiers sinkt.","pairs":[["Wenn sie zu oft recycelt worden sind, halten sie nicht mehr zusammen","nicht endlos zu neuem Papier verarbeiten"],["zu oft recycelt","nur ein einziges Mal"],["die Qualität des Papiers sinkt","desto stabiler wird das neue Papier"]],"explain":"오버도르프 씨는 섬유가 재활용할 때마다 짧아지고, 너무 여러 번 재활용되면 서로 붙어 있지 못한다고 해요. 그래서 같은 섬유로 끝없이 새 종이를 만들 수는 없고, 나무에서 얻은 새 섬유가 필요해요. '너무 여러 번(zu oft)'이라고 했으니 한 번만 쓸 수 있다는 보기는 틀리고, 품질이 떨어진다(sinkt)고 했으니 더 튼튼해진다는 보기도 틀려요."},{"type":"mc","kind":"intent","q":"Was will der letzte Abschnitt bei den Leserinnen und Lesern erreichen?","options":["Sie sollen alte Zeitungen lieber selbst zur Papierfabrik bringen.","Sie sollen beim Wegwerfen darauf achten, was ins Altpapier darf.","Sie sollen auch Backpapier und Kassenzettel in die Tonne werfen."],"answer":1,"evidence":"In die blaue Tonne gehören nur Papier, Pappe und Kartons.","pairs":[["In die blaue Tonne gehören nur Papier, Pappe und Kartons.","darauf achten, was ins Altpapier darf"],["werfen Sie bitte in den Restmüll","in die Tonne werfen"]],"explain":"마지막 단락은 파란 수거함에 무엇을 넣고 무엇을 일반 쓰레기로 버려야 하는지 알려 줘요. 즉 종이 쓰레기를 잘 나눠서 버려 달라는 부탁이에요. 유산지와 영수증은 일반 쓰레기(Restmüll)로 버려야 하고, 다 읽은 잡지는 파란 수거함에 넣으면 돼요. 공장에 직접 가져가라는 말은 없어요."}],"grammar":[{"title":"수동태 현재완료 – ist … worden","term":"Passiv Perfekt","explain":"수동태 현재완료는 sein + 과거분사 + worden으로 만들어요. werden의 과거분사는 원래 geworden이지만, 수동태에서는 ge-가 없는 worden을 써요. 주절에서는 sein이 두 번째 자리에 오고, 과거분사 + worden이 문장 끝에 와요. 부문장에서는 과거분사 + worden + sein 순서로 모두 끝에 와요. 어떤 시점에 한 과정이 이미 끝나 있다는 것을 말할 때 써요.","pattern":"주절: sein + … + 과거분사 + worden / 부문장: … + 과거분사 + worden + sein","examples":[{"de":"Wenn ein Lastwagen in der Papierfabrik ankommt, ist seine Ladung also bereits sortiert und gepresst worden.","ko":"그러니까 트럭이 제지 공장에 도착할 때 실려 있는 종이는 이미 분류되고 압축된 상태예요.","mark":["ist","sortiert und gepresst worden"],"parts":[["Wenn ein Lastwagen in der Papierfabrik ankommt,","종속절"],["ist","동사"],["seine Ladung","주어"],["also","기타"],["bereits","부사어(시간)"],["sortiert und gepresst worden.","동사(끝)"]]},{"de":"Wenn sie zu oft recycelt worden sind, halten sie nicht mehr zusammen, und die Qualität des Papiers sinkt.","ko":"너무 여러 번 재활용되면 섬유가 더 이상 서로 붙어 있지 못하고, 종이의 품질이 떨어져요.","mark":["recycelt worden sind"],"parts":[["Wenn sie zu oft recycelt worden sind,","종속절"],["halten","동사"],["sie","주어"],["nicht mehr","부정어"],["zusammen,","동사(끝)"],["und die Qualität des Papiers sinkt.","기타"]]},{"de":"Doch was passiert mit dem Papier, nachdem es abgeholt worden ist?","ko":"그런데 수거된 종이는 그 뒤에 어떻게 될까요?","mark":["abgeholt worden ist"]}],"tip":"worden과 geworden을 구별하세요. 소제목 „Aus Brei wird Papier“처럼 werden이 '~이 되다'라는 뜻이면 현재완료는 ist … geworden이에요(Aus Brei ist Papier geworden). worden은 수동태의 완료형에서만 써요."},{"title":"zum + 명사화된 동사원형 – 목적을 짧게 말하기","term":"zum + nominalisierter Infinitiv","explain":"동사원형의 첫 글자를 대문자로 쓰면 중성 명사가 돼요(trocknen → das Trocknen). 여기에 zum(zu + dem)을 붙이면 '~하기 위해, ~하는 데'라는 목적을 나타내요. um … zu 부정사구보다 짧아서 설명문과 사용 설명서에 자주 나와요. 목적어가 있으면 2격으로 뒤에 붙여요(zum Entfernen der Farbe).","pattern":"zum + 명사화된 동사원형 (+ 2격)","examples":[{"de":"Zum Verladen wird das Papier anschließend zu Ballen gepresst, die rund 500 Kilo wiegen.","ko":"그다음 차에 싣기 위해 종이를 뭉치로 압축하는데, 뭉치 하나의 무게는 약 500킬로그램이에요.","mark":["Zum Verladen"],"parts":[["Zum Verladen","부사어"],["wird","동사"],["das Papier","주어"],["anschließend","부사어(시간)"],["zu Ballen","부사어(방법)"],["gepresst,","동사(끝)"],["die rund 500 Kilo wiegen.","관계절"]]},{"de":"Zum Entfernen der Farbe gibt man eine seifenartige Flüssigkeit hinzu und bläst gleichzeitig Luft hinein.","ko":"잉크를 없애기 위해 비누 같은 액체를 넣고 동시에 공기를 불어 넣어요.","mark":["Zum Entfernen der Farbe"],"parts":[["Zum Entfernen der Farbe","부사어"],["gibt","동사"],["man","주어"],["eine seifenartige Flüssigkeit","4격 목적어"],["hinzu","동사(끝)"],["und bläst gleichzeitig Luft hinein.","기타"]]},{"de":"Diese wird zwischen Walzen gepresst und läuft zum Trocknen über heiße Zylinder, bis kaum noch Feuchtigkeit in ihr steckt.","ko":"이 종이 띠는 롤러 사이에서 눌린 다음, 물기가 거의 남지 않을 때까지 마르도록 뜨거운 실린더 위를 지나가요.","mark":["zum Trocknen"]}],"tip":"um … zu로 바꿔 쓸 수도 있어요: Um die Farbe zu entfernen, gibt man … hinzu. beim + 동사원형은 목적이 아니라 '~할 때'라는 뜻이에요: beim Trocknen(말리는 동안)."},{"title":"nachdem과 während – 먼저 끝난 일과 동시에 일어나는 일","term":"Temporalsätze mit nachdem und während","explain":"nachdem은 '~한 뒤에'라는 뜻으로, nachdem 절의 일이 주절의 일보다 먼저 끝나요. 그래서 주절이 현재형이면 nachdem 절은 현재완료로, 주절이 과거형이면 과거완료로 써요. während는 '~하는 동안'이라는 뜻으로, 두 가지 일이 같은 시간에 일어나요. 그래서 두 절의 시제가 같아요. 둘 다 부문장을 이끌기 때문에 동사가 부문장 끝에 와요.","pattern":"Nachdem + … + 과거분사 + sein/haben, 주절(현재) · Während + … + 동사, 주절","examples":[{"de":"Nachdem Büroklammern, Klebereste und Sand Schritt für Schritt herausgefiltert worden sind, bleibt noch die Druckfarbe übrig.","ko":"클립, 접착제 찌꺼기, 모래를 한 단계씩 걸러 낸 뒤에도 인쇄 잉크는 아직 남아 있어요.","mark":["Nachdem","herausgefiltert worden sind"],"parts":[["Nachdem Büroklammern, Klebereste und Sand Schritt für Schritt herausgefiltert worden sind,","종속절"],["bleibt","동사"],["noch","기타"],["die Druckfarbe","주어"],["übrig.","동사(끝)"]]},{"de":"Während das Wasser abläuft, verbinden sich die Fasern zu einer dünnen Schicht, der Papierbahn.","ko":"물이 빠지는 동안 섬유가 서로 엉겨 얇은 층, 즉 종이 띠가 돼요.","mark":["Während","abläuft"],"parts":[["Während das Wasser abläuft,","종속절"],["verbinden","동사"],["sich","재귀대명사"],["die Fasern","주어"],["zu einer dünnen Schicht, der Papierbahn.","전치사 목적어"]]}],"tip":"부문장이 문장 맨 앞에 오면 주절의 동사가 바로 뒤에 와요(…, bleibt noch …). während는 2격 전치사로도 써요: während der Fahrt(가는 동안)."},{"title":"werden의 쓰임 – '~이 되다'와 수동태","term":"werden als Vollverb und im Passiv","explain":"werden은 혼자 쓰면 '~이 되다'라는 뜻이에요. 형용사와 함께 쓰면 상태가 바뀌는 것을 말하고(kürzer werden), aus + 3격과 함께 쓰면 무엇이 무엇으로 바뀌는지 말해요(Aus Brei wird Papier). 문장 끝에 과거분사가 있으면 수동태예요(wird … gewickelt). 그래서 werden이 보이면 문장 끝에 형용사나 명사가 있는지, 과거분사가 있는지 먼저 확인하세요.","pattern":"werden + 형용사 · aus + 3격 + werden + 1격 / werden + … + 과거분사(끝)","examples":[{"de":"Bei jeder Wiederverwertung werden die Fasern nämlich kürzer.","ko":"재활용할 때마다 섬유가 짧아지거든요.","mark":["werden","kürzer"],"parts":[["Bei jeder Wiederverwertung","부사어(시간)"],["werden","동사"],["die Fasern","주어"],["nämlich","기타"],["kürzer.","보어"]]},{"de":"Schließlich wird das fertige Papier auf riesige Rollen gewickelt und an die Druckereien der Tageszeitungen geliefert.","ko":"마지막으로 완성된 종이는 거대한 롤에 감겨 일간 신문 인쇄소로 보내져요.","mark":["wird","gewickelt","geliefert"],"parts":[["Schließlich","부사어(시간)"],["wird","동사"],["das fertige Papier","주어"],["auf riesige Rollen","부사어(장소)"],["gewickelt","동사(끝)"],["und an die Druckereien der Tageszeitungen geliefert.","기타"]]},{"de":"Aus Brei wird Papier","ko":"죽이 종이가 돼요","mark":["Aus Brei wird Papier"]}],"tip":"werden + 동사원형(끝)은 미래나 계획을 나타내요: Wir werden die Fabrik besuchen. werden의 모양(werde, wird, wurde …)만 보고는 구별할 수 없으니 문장 끝을 보세요."}],"vocab":[{"de":"das Altpapier (Sg.)","ko":"폐지"},{"de":"die Tonne, -n","ko":"(쓰레기) 수거함"},{"de":"die Sortieranlage, -n","ko":"선별 시설"},{"de":"das Förderband, -¨er","ko":"컨베이어 벨트"},{"de":"die Pappe, -n","ko":"판지, 마분지"},{"de":"der Fremdstoff, -e","ko":"이물질 (섞이면 안 되는 물질)"},{"de":"der Ballen, -","ko":"(압축한) 뭉치, 더미"},{"de":"die Faser, -n","ko":"섬유"},{"de":"der Brei, -e","ko":"죽, 죽처럼 걸쭉한 것"},{"de":"zerfallen (zerfällt, zerfiel, ist zerfallen)","ko":"분해되다, 낱낱으로 흩어지다"},{"de":"die Druckfarbe, -n","ko":"인쇄 잉크"},{"de":"ab|schöpfen","ko":"(위에 뜬 것을) 걷어 내다"},{"de":"das Sieb, -e","ko":"체, 망"},{"de":"die Feuchtigkeit (Sg.)","ko":"습기, 물기"},{"de":"die Wiederverwertung (Sg.)","ko":"재활용"},{"de":"der Restmüll (Sg.)","ko":"일반 쓰레기"}],"phrases":[{"de":"alle zwei Wochen","ko":"2주마다","ex":"Alle zwei Wochen leeren unsere Fahrzeuge Ihre blaue Papiertonne.","exko":"2주마다 저희 차량이 여러분의 파란 종이 수거함을 비워요."},{"de":"sich für etwas (Akk.) eignen","ko":"~에 알맞다, ~에 쓰기 좋다","ex":"Von Hand und mit Maschinen wird die braune Pappe aussortiert, die sich nicht für die Herstellung von Zeitungspapier eignet.","exko":"갈색 판지는 신문 용지를 만드는 데 알맞지 않아서 손과 기계로 골라내요."},{"de":"an + Dat. hängen bleiben","ko":"~에 달라붙다, 걸리다","ex":"Die Farbteilchen bleiben an den Luftblasen hängen und steigen nach oben, wo sie als grauer Schaum abgeschöpft werden.","exko":"잉크 입자는 공기 방울에 달라붙어 위로 떠오르고, 그곳에서 회색 거품 상태로 걷어 내요."},{"de":"zu … Prozent aus + Dat. bestehen","ko":"~퍼센트가 ~로 이루어져 있다","ex":"Der Faserbrei besteht hier zu 99 Prozent aus Wasser und wird auf ein großes Sieb gespritzt.","exko":"이 단계에서 섬유 죽은 99퍼센트가 물이고, 큰 망 위에 뿌려져요."},{"de":"(irgendwo) genau richtig sein","ko":"(어떤 곳이) 딱 알맞은 자리이다","ex":"Sobald Sie es gelesen haben, ist es in der blauen Papiertonne genau richtig.","exko":"다 읽으신 뒤에는 파란 종이 수거함이 바로 제자리예요."}],"words":359},{"id":"b1-18","level":"B1","no":18,"title":"Mein Navi und ich","titleKo":"내비게이션과 나","type":"Kolumne","typeKo":"지역 신문 칼럼","intro":"내비게이션 없이는 운전하기 어려워진 사람이 쓴 유머 칼럼이에요.","focus":["형용사 + 전치사","auch wenn","과거형과 현재완료","einer · keiner · welche"],"paragraphs":[{"style":"meta","de":"Die Samstagskolumne von Volker Imhoff","ko":"폴커 임호프의 토요 칼럼"},{"de":"„In 300 Metern rechts abbiegen.“ Diese Anweisung höre ich inzwischen häufiger als „Guten Morgen“, denn seit drei Jahren fahre ich kaum noch einen Meter ohne mein Navi. Ich muss zugeben, dass ich von dem Ding ziemlich abhängig geworden bin. Während meine Frau einen kompletten Stadtplan im Kopf hat, habe ich offenbar keinen.","ko":"“300미터 앞에서 우회전하세요.” 저는 요즘 이 지시를 ‘안녕하세요’보다 더 자주 들어요. 3년 전부터 내비게이션 없이는 1미터도 거의 운전하지 않거든요. 솔직히 저는 이 기계에 꽤 의존하게 되었다는 걸 인정할 수밖에 없어요. 제 아내의 머릿속에는 시내 지도가 통째로 들어 있는데, 제 머릿속에는 아무래도 그런 지도가 없나 봐요."},{"de":"Dabei war das früher vollkommen anders, denn mit 19 bin ich mit einer zerfledderten Straßenkarte quer durch Frankreich gefahren, und darauf bin ich bis heute stolz. Inzwischen finde ich ohne die freundliche Frauenstimme nicht einmal mehr den Baumarkt im Nachbarort, obwohl ich dort seit Jahren regelmäßig einkaufe. Ich frage mich manchmal, woran das liegt, und habe eine Vermutung: Wer nie selbst nach dem Weg suchen muss, verlernt irgendwann, wie das funktioniert.","ko":"사실 예전에는 완전히 달랐어요. 열아홉 살 때 저는 너덜너덜한 도로 지도 한 장을 들고 프랑스를 가로질러 운전했고, 그 일이 지금도 자랑스러워요. 그런데 이제는 그 친절한 여자 목소리가 없으면 옆 동네에 있는 대형 철물점조차 찾지 못해요. 몇 년째 꾸준히 물건을 사러 가는 곳인데도요. 저는 가끔 왜 그런지 생각해 보는데, 짐작 가는 것이 하나 있어요. 스스로 길을 찾을 필요가 없는 사람은 언젠가 그 방법을 잊어버린다는 거예요."},{"de":"Perfekt ist mein Navi übrigens überhaupt nicht. Als ich im letzten Sommer zu einer Hochzeit unterwegs war, wollte es mich über einen Feldweg schicken, der kaum breiter als mein Kleinwagen war. Ein Landwirt, der mit seinem Traktor vorbeikam, lachte und erzählte, dass vor einer Stunde schon ein Autofahrer aus Hamburg an derselben Stelle gestanden hatte.","ko":"그렇다고 제 내비게이션이 완벽한 건 전혀 아니에요. 지난여름 결혼식에 가던 길에, 내비게이션은 제 소형차 폭과 별 차이가 없는 농로로 저를 보내려고 했어요. 트랙터를 타고 지나가던 농부 한 분은 웃으면서, 한 시간 전에도 함부르크에서 온 운전자가 바로 그 자리에 서 있었다고 이야기해 주었어요."},{"de":"Und worüber ärgere ich mich am meisten? Ausgerechnet über die Geduld der Frauenstimme, die nie böse auf mich ist, auch wenn ich zum fünften Mal in die falsche Richtung abbiege. „Die Route wird neu berechnet“, kommentiert sie lediglich, ganz ohne Vorwurf. Meine Frau ist da weniger geduldig.","ko":"그럼 제가 가장 화가 나는 건 뭘까요? 하필이면 그 여자 목소리의 인내심이에요. 제가 다섯 번째로 엉뚱한 방향으로 꺾어도 그 목소리는 저한테 절대 화를 내지 않아요. 나무라는 기색 하나 없이 “경로를 다시 계산합니다”라고 한마디 할 뿐이에요. 제 아내는 그럴 때 그렇게 참아 주지 않아요."},{"de":"Gibt es eigentlich noch Menschen, die ohne Navi zurechtkommen? Ja, es gibt welche. Mein Vater zum Beispiel ist 81, besitzt keins und hat nie eins gewollt, weil er mit seinem dicken Autoatlas aus den Neunzigerjahren völlig zufrieden ist. Neulich habe ich ihn zum neuen Ärztehaus am Stadtrand gefahren. Ich hatte die Adresse gerade in mein Navi eingegeben, als er plötzlich sagte: „Mach das aus – an der zweiten Ampel links und dann immer geradeaus bis zur Kirche.“ Wir kamen zu meiner Überraschung fünf Minuten früher an, als das Navi vorausgesagt hatte.","ko":"그런데 요즘도 내비게이션 없이 잘 다니는 사람이 있을까요? 네, 있어요. 예를 들어 제 아버지는 여든한 살인데, 내비게이션이 없고 한 번도 갖고 싶어 하신 적이 없어요. 90년대에 나온 두꺼운 도로 지도책 하나로 아주 만족하시거든요. 얼마 전에 저는 아버지를 차에 모시고 시 외곽에 새로 생긴 병원 건물에 갔어요. 제가 막 내비게이션에 주소를 입력했을 때 아버지가 갑자기 말씀하셨어요. “그거 꺼요. 두 번째 신호등에서 좌회전하고, 그다음엔 교회까지 쭉 직진해요.” 놀랍게도 우리는 내비게이션이 예상한 것보다 5분 일찍 도착했어요."},{"de":"Seitdem trainiere ich und fahre wöchentlich ohne Navi zum Baumarkt im Nachbarort. Angekommen bin ich immer, und mein Vater ist stolz auf mich, auch wenn ich unterwegs oft Umwege mache. Das Navi liegt ausgeschaltet im Handschuhfach – für alle Fälle.","ko":"그 뒤로 저는 훈련하고 있어요. 매주 내비게이션 없이 옆 동네 대형 철물점까지 운전해요. 목적지에는 늘 도착했고, 가는 길에 자주 돌아가기는 해도 아버지는 저를 자랑스러워하세요. 내비게이션은 꺼진 채로 글로브박스 안에 있어요. 혹시 모를 때를 대비해서요."}],"questions":[{"type":"rf","kind":"detail","q":"Sein Navi schaltet der Autor nur ein, wenn er in einer fremden Gegend unterwegs ist.","answer":1,"evidence":"denn seit drei Jahren fahre ich kaum noch einen Meter ohne mein Navi","pairs":[["kaum noch einen Meter ohne mein Navi","nur ein, wenn er in einer fremden Gegend unterwegs ist"],["nicht einmal mehr den Baumarkt im Nachbarort","in einer fremden Gegend"]],"explain":"글쓴이는 3년 전부터 내비게이션 없이는 1미터도 거의 운전하지 않는다고 해요. 늘 가는 옆 동네 철물점도 내비게이션 없이는 찾지 못해요. 그러니까 낯선 곳에 갈 때만 켠다는 말은 틀려요."},{"type":"mc","kind":"detail","q":"Was sagt der Autor über seine Reise mit 19?","options":["Mit der alten Karte hat er damals viel zu viel Zeit verloren.","Er hält diese Reise noch heute für eine echte Leistung.","Er schämt sich, weil er damals ohne Navi durch Frankreich fuhr."],"answer":1,"evidence":"denn mit 19 bin ich mit einer zerfledderten Straßenkarte quer durch Frankreich gefahren, und darauf bin ich bis heute stolz","pairs":[["darauf bin ich bis heute stolz","Er hält diese Reise noch heute für eine echte Leistung."]],"explain":"darauf는 낡은 지도 한 장으로 프랑스를 가로지른 일을 가리키고, 그 일이 지금도 자랑스럽다(stolz)고 해요. 그래서 '지금도 그 여행을 대단한 일로 여긴다'가 맞아요. 부끄러워한다는 말은 stolz와 반대이고, 시간을 많이 잃었다는 이야기는 하지 않아요."},{"type":"mc","kind":"meaning","q":"Was bedeutet „verlernt“ im Text?","options":["verliert eine Fähigkeit, die man vorher besaß","lernt etwas nie richtig, weil es niemand erklärt","hat keine Lust mehr, selbst den Weg zu suchen"],"answer":0,"evidence":"Wer nie selbst nach dem Weg suchen muss, verlernt irgendwann, wie das funktioniert.","pairs":[["verlernt","verliert eine Fähigkeit, die man vorher besaß"],["Dabei war das früher vollkommen anders","die man vorher besaß"]],"explain":"verlernen은 예전에 할 줄 알던 것을 더는 못 하게 되는 거예요. 글쓴이는 젊을 때 지도만 보고 프랑스를 가로질렀지만, 지금은 길을 찾지 못해요. 처음부터 제대로 배우지 못했다는 뜻도, 길을 찾고 싶은 마음이 없다는 뜻도 아니에요."},{"type":"rf","kind":"inference","q":"Schon vor dem Autor war an diesem Tag ein anderer Autofahrer auf dem schmalen Weg gelandet.","answer":0,"evidence":"dass vor einer Stunde schon ein Autofahrer aus Hamburg an derselben Stelle gestanden hatte","pairs":[["vor einer Stunde schon ein Autofahrer aus Hamburg","Schon vor dem Autor"],["an derselben Stelle gestanden hatte","auf dem schmalen Weg gelandet"],["der kaum breiter als mein Kleinwagen war","schmalen Weg"]],"explain":"농부는 한 시간 전에도 함부르크에서 온 운전자가 바로 그 자리에 서 있었다고 말해요. 차 폭만 한 좁은 농로에 그날 글쓴이보다 먼저 들어선 사람이 있었다는 뜻이에요. 그래서 맞는 말이에요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Meine Frau ist da weniger geduldig.“?","options":["Seine Frau bleibt in solchen Momenten noch ruhiger als die Frauenstimme.","Seine Frau ist genauso geduldig wie die Stimme, die ihm den Weg zeigt.","Wenn er sich verfährt, verliert seine Frau ziemlich schnell die Nerven."],"answer":2,"evidence":"Meine Frau ist da weniger geduldig.","pairs":[["weniger geduldig","verliert seine Frau ziemlich schnell die Nerven"],["in die falsche Richtung abbiege","Wenn er sich verfährt"]],"explain":"da는 '그럴 때', 즉 글쓴이가 길을 잘못 들 때를 가리켜요. 그럴 때 아내는 내비게이션 목소리보다 참을성이 적다(weniger geduldig)는 뜻이에요. 정답은 이것을 '금방 신경질을 낸다(die Nerven verlieren)'로 바꿔 말했어요. 목소리보다 더 차분하다거나 목소리만큼 참을성이 있다는 보기는 weniger의 뜻과 반대예요."},{"type":"mc","kind":"detail","q":"Was erfährt man über den Vater des Autors?","options":["Für ihn reicht ein altes Buch voller Straßenkarten völlig aus.","Er besitzt ein Navi, benutzt es aber nur auf langen Fahrten.","Er wünscht sich schon lange ein Navi, findet es aber zu teuer."],"answer":0,"evidence":"weil er mit seinem dicken Autoatlas aus den Neunzigerjahren völlig zufrieden ist","pairs":[["mit seinem dicken Autoatlas aus den Neunzigerjahren völlig zufrieden","Für ihn reicht ein altes Buch voller Straßenkarten völlig aus."],["besitzt keins","Er besitzt ein Navi"],["hat nie eins gewollt","Er wünscht sich schon lange ein Navi"]],"explain":"아버지는 90년대에 나온 두꺼운 도로 지도책(Autoatlas)에 아주 만족한다고 해요. 정답은 이것을 '오래된 지도책 하나면 충분하다'로 바꿔 말했어요. 아버지는 내비게이션이 없고(besitzt keins) 한 번도 갖고 싶어 한 적이 없으니(hat nie eins gewollt) 나머지 두 보기는 틀려요."},{"type":"mc","kind":"inference","q":"Was zeigt die Fahrt zum Ärztehaus wahrscheinlich?","options":["Das Navi hat den Vater auf einen kürzeren Weg zur Kirche geführt.","Der Vater wollte unbedingt wissen, welche Route das Navi berechnet.","In der eigenen Stadt kennt der Vater schnellere Wege als das Gerät."],"answer":2,"evidence":"Wir kamen zu meiner Überraschung fünf Minuten früher an, als das Navi vorausgesagt hatte.","pairs":[["fünf Minuten früher an, als das Navi vorausgesagt hatte","schnellere Wege als das Gerät"],["Mach das aus","Der Vater wollte unbedingt wissen, welche Route das Navi berechnet."]],"explain":"아버지는 내비게이션을 끄라고(Mach das aus) 하고 자기가 아는 길을 알려 줘요. 그 길로 갔더니 내비게이션이 예상한 시간보다 5분 일찍 도착했어요. 아버지가 동네 길을 기계보다 더 잘 안다는 뜻이에요. 아버지는 내비게이션을 끄게 했으니 경로를 알고 싶어 했다거나 내비게이션이 지름길로 안내했다는 보기는 틀려요."},{"type":"mc","kind":"intent","q":"Was will der Autor mit dem Hinweis auf das Handschuhfach sagen?","options":["Er hat das Navi für immer weggelegt und will es nie mehr benutzen.","Er übt jetzt ohne Navi, möchte es im Notfall aber gern dabeihaben.","Er nimmt das Navi nur noch mit, wenn sein Vater im Auto sitzt."],"answer":1,"evidence":"Das Navi liegt ausgeschaltet im Handschuhfach – für alle Fälle.","pairs":[["für alle Fälle","im Notfall"],["Seitdem trainiere ich","Er übt jetzt ohne Navi"]],"explain":"글쓴이는 매주 내비게이션 없이 운전하는 연습을 해요. 하지만 내비게이션을 버린 것이 아니라 꺼서 글로브박스에 넣어 두었어요. für alle Fälle(혹시 모를 때를 대비해서)라는 말에서, 필요할 때는 다시 쓰려고 차에 두었다는 것을 알 수 있어요. 아버지가 탈 때만 가져간다는 말은 없어요."}],"grammar":[{"title":"전치사와 함께 쓰는 형용사","term":"Adjektive mit Präpositionen","explain":"어떤 형용사는 정해진 전치사와 함께 써요. 전치사 뒤의 격도 정해져 있어서 형용사, 전치사, 격을 한 덩어리로 외우는 것이 좋아요: abhängig von + 3격(~에 의존하는), stolz auf + 4격(~을 자랑스러워하는), böse auf + 4격(~에게 화가 난), zufrieden mit + 3격(~에 만족하는). 전치사구는 형용사 앞에 오기도 하고(mit seinem Autoatlas zufrieden), 뒤에 오기도 해요(stolz auf mich). 전치사 뒤에 오는 내용을 앞에서 이미 말했다면 da(r)- + 전치사로 받아요: darauf bin ich stolz.","pattern":"sein / werden + 형용사 + 전치사 + 명사 / 전치사 + 명사 + 형용사 + sein","examples":[{"de":"Angekommen bin ich immer, und mein Vater ist stolz auf mich, auch wenn ich unterwegs oft Umwege mache.","ko":"목적지에는 늘 도착했고, 가는 길에 자주 돌아가기는 해도 아버지는 저를 자랑스러워하세요.","mark":["stolz auf mich"],"parts":[["Angekommen","동사(끝)"],["bin","동사"],["ich","주어"],["immer,","부사어(빈도)"],["und","접속사"],["mein Vater","주어"],["ist","동사"],["stolz","보어"],["auf mich,","전치사 목적어"],["auch wenn ich unterwegs oft Umwege mache.","종속절"]]},{"de":"Ich muss zugeben, dass ich von dem Ding ziemlich abhängig geworden bin.","ko":"솔직히 저는 이 기계에 꽤 의존하게 되었다는 걸 인정할 수밖에 없어요.","mark":["von dem Ding","abhängig"],"parts":[["Ich","주어"],["muss","동사"],["zugeben,","동사(끝)"],["dass ich von dem Ding ziemlich abhängig geworden bin.","종속절"]]},{"de":"Mein Vater zum Beispiel ist 81, besitzt keins und hat nie eins gewollt, weil er mit seinem dicken Autoatlas aus den Neunzigerjahren völlig zufrieden ist.","ko":"예를 들어 제 아버지는 여든한 살인데, 내비게이션이 없고 한 번도 갖고 싶어 하신 적이 없어요. 90년대에 나온 두꺼운 도로 지도책 하나로 아주 만족하시거든요.","mark":["mit seinem dicken Autoatlas","zufrieden"]}],"tip":"형용사 + 전치사도 wo(r)- + 전치사로 물어요: Worauf ist er bis heute stolz? – Auf seine Reise durch Frankreich. 사람에 대해 물을 때는 전치사 + 의문사를 써요: Auf wen ist die Stimme nie böse? – Auf den Autor."},{"title":"auch wenn – 그래도 결과가 달라지지 않을 때","term":"Konzessivsatz mit auch wenn","explain":"auch wenn은 '~하더라도, ~해도'라는 뜻이에요. auch wenn 절의 일이 일어나도 주절의 결과는 달라지지 않아요. 부문장이라서 auch wenn 절의 동사는 끝에 와요. 본문처럼 주절 뒤에 올 때가 많지만, 주절 앞에 올 수도 있어요. 그러면 주절은 동사로 시작해요: Auch wenn ich falsch abbiege, bleibt die Stimme freundlich.","pattern":"주절, auch wenn + … + 동사(끝) / Auch wenn + … + 동사(끝), 동사 + 주어 …","examples":[{"de":"Ausgerechnet über die Geduld der Frauenstimme, die nie böse auf mich ist, auch wenn ich zum fünften Mal in die falsche Richtung abbiege.","ko":"하필이면 그 여자 목소리의 인내심이에요. 제가 다섯 번째로 엉뚱한 방향으로 꺾어도 그 목소리는 저한테 절대 화를 내지 않아요.","mark":["auch wenn","abbiege"],"parts":[["Ausgerechnet über die Geduld der Frauenstimme,","기타"],["die nie böse auf mich ist,","관계절"],["auch wenn ich zum fünften Mal in die falsche Richtung abbiege.","종속절"]]},{"de":"Angekommen bin ich immer, und mein Vater ist stolz auf mich, auch wenn ich unterwegs oft Umwege mache.","ko":"목적지에는 늘 도착했고, 가는 길에 자주 돌아가기는 해도 아버지는 저를 자랑스러워하세요.","mark":["auch wenn ich unterwegs oft Umwege mache"]}],"tip":"obwohl은 이미 사실인 일에 써요: …, obwohl ich dort seit Jahren regelmäßig einkaufe. auch wenn은 사실에도 쓰고, 앞으로 일어날 수 있는 일에도 써요: Ich fahre morgen ohne Navi, auch wenn es regnet."},{"title":"과거형과 현재완료 – 이야기 속 두 과거 시제","term":"Präteritum und Perfekt im Erzählen","explain":"칼럼처럼 말하듯 쓴 글에서는 과거형과 현재완료가 함께 나와요. sein, haben, 화법조동사는 과거형(war, hatte, wollte)을 자주 쓰고, 다른 동사는 말할 때처럼 현재완료(bin … gefahren, habe … gefahren)를 자주 써요. 한 장면을 차례로 그릴 때는 다른 동사도 과거형(lachte, erzählte, kamen … an)으로 써요. 그보다 더 앞선 일은 과거완료(hatte … eingegeben, vorausgesagt hatte)로 써요.","pattern":"과거형: war, hatte, wollte, kamen … / 현재완료: haben · sein + … + 과거분사(끝)","examples":[{"de":"Neulich habe ich ihn zum neuen Ärztehaus am Stadtrand gefahren.","ko":"얼마 전에 저는 아버지를 차에 모시고 시 외곽에 새로 생긴 병원 건물에 갔어요.","mark":["habe","gefahren"],"parts":[["Neulich","부사어(시간)"],["habe","동사"],["ich","주어"],["ihn","4격 목적어"],["zum neuen Ärztehaus am Stadtrand","부사어(장소)"],["gefahren.","동사(끝)"]]},{"de":"Dabei war das früher vollkommen anders, denn mit 19 bin ich mit einer zerfledderten Straßenkarte quer durch Frankreich gefahren, und darauf bin ich bis heute stolz.","ko":"사실 예전에는 완전히 달랐어요. 열아홉 살 때 저는 너덜너덜한 도로 지도 한 장을 들고 프랑스를 가로질러 운전했고, 그 일이 지금도 자랑스러워요.","mark":["war","bin","gefahren"]},{"de":"Wir kamen zu meiner Überraschung fünf Minuten früher an, als das Navi vorausgesagt hatte.","ko":"놀랍게도 우리는 내비게이션이 예상한 것보다 5분 일찍 도착했어요.","mark":["kamen","an","vorausgesagt hatte"]}],"tip":"fahren은 혼자 어디로 갈 때 sein으로 완료형을 만들어요(ich bin … gefahren). 누군가를 차로 태워다 줄 때는 4격 목적어가 있어서 haben을 써요(ich habe ihn … gefahren)."},{"title":"부정대명사 einer · keiner · welche – 명사를 되풀이하지 않고 받기","term":"Indefinitpronomen als Ersatz für ein Nomen: einer, keiner, welche","explain":"앞에 나온 명사를 다시 쓰지 않을 때 einer, keiner, welche 같은 부정대명사를 써요. 모양은 가리키는 명사의 성과 격에 따라 달라져요: einen Stadtplan → keinen, ein Navi → eins / keins. 복수 명사를 '그런 사람들, 그런 것들'로 받을 때는 welche를 써요: Gibt es noch Menschen …? – Ja, es gibt welche.","pattern":"남성 einer / einen · 중성 eins · 여성 eine · 복수 welche (부정: keiner, keinen, keins, keine)","examples":[{"de":"Während meine Frau einen kompletten Stadtplan im Kopf hat, habe ich offenbar keinen.","ko":"제 아내의 머릿속에는 시내 지도가 통째로 들어 있는데, 제 머릿속에는 아무래도 그런 지도가 없나 봐요.","mark":["einen kompletten Stadtplan","keinen"],"parts":[["Während meine Frau einen kompletten Stadtplan im Kopf hat,","종속절"],["habe","동사"],["ich","주어"],["offenbar","기타"],["keinen.","4격 목적어"]]},{"de":"Ja, es gibt welche.","ko":"네, 있어요.","mark":["welche"]},{"de":"besitzt keins und hat nie eins gewollt","ko":"내비게이션이 없고 한 번도 갖고 싶어 하신 적이 없어요","mark":["keins","eins"]}],"tip":"남성은 1격 einer / keiner, 4격 einen / keinen이에요. 중성은 1격과 4격 모두 eins / keins예요. 사람을 막연히 가리킬 때는 jemand(누군가), niemand(아무도)를 써요."}],"vocab":[{"de":"das Navi, -s","ko":"내비게이션"},{"de":"ab|biegen (biegt ab, bog ab, ist abgebogen)","ko":"(방향을 바꿔) 꺾어 들다"},{"de":"abhängig von + Dat.","ko":"~에 의존하는"},{"de":"zu|geben (gibt zu, gab zu, hat zugegeben)","ko":"(잘못이나 약점을) 인정하다"},{"de":"die Straßenkarte, -n","ko":"도로 지도"},{"de":"stolz auf + Akk.","ko":"~을 자랑스러워하는"},{"de":"der Baumarkt, -¨e","ko":"대형 철물점, 건축 자재 마트"},{"de":"verlernen","ko":"(할 줄 알던 것을) 잊어버리다"},{"de":"die Vermutung, -en","ko":"짐작, 추측"},{"de":"der Feldweg, -e","ko":"들길, 농로"},{"de":"böse auf + Akk.","ko":"~에게 화가 난"},{"de":"der Vorwurf, -¨e","ko":"비난, 나무람"},{"de":"zurecht|kommen (kommt zurecht, kam zurecht, ist zurechtgekommen)","ko":"잘 해내다, 불편 없이 지내다"},{"de":"zufrieden mit + Dat.","ko":"~에 만족하는"},{"de":"voraus|sagen","ko":"미리 말하다, 예측하다"},{"de":"das Handschuhfach, -¨er","ko":"(자동차) 글로브박스, 조수석 앞 수납함"}],"phrases":[{"de":"nicht einmal (mehr)","ko":"~조차 (더는) ~않다","ex":"Inzwischen finde ich ohne die freundliche Frauenstimme nicht einmal mehr den Baumarkt im Nachbarort, obwohl ich dort seit Jahren regelmäßig einkaufe.","exko":"그런데 이제는 그 친절한 여자 목소리가 없으면, 몇 년째 꾸준히 물건을 사러 가는 옆 동네 대형 철물점조차 찾지 못해요."},{"de":"an etwas (Dat.) liegen","ko":"~ 때문이다, ~에 원인이 있다","ex":"Ich frage mich manchmal, woran das liegt, und habe eine Vermutung: Wer nie selbst nach dem Weg suchen muss, verlernt irgendwann, wie das funktioniert.","exko":"저는 가끔 왜 그런지 생각해 보는데, 짐작 가는 것이 하나 있어요. 스스로 길을 찾을 필요가 없는 사람은 언젠가 그 방법을 잊어버린다는 거예요."},{"de":"zum … Mal","ko":"~번째로","ex":"Ausgerechnet über die Geduld der Frauenstimme, die nie böse auf mich ist, auch wenn ich zum fünften Mal in die falsche Richtung abbiege.","exko":"하필이면 그 여자 목소리의 인내심이에요. 제가 다섯 번째로 엉뚱한 방향으로 꺾어도 그 목소리는 저한테 절대 화를 내지 않아요."},{"de":"zu meiner Überraschung","ko":"놀랍게도","ex":"Wir kamen zu meiner Überraschung fünf Minuten früher an, als das Navi vorausgesagt hatte.","exko":"놀랍게도 우리는 내비게이션이 예상한 것보다 5분 일찍 도착했어요."},{"de":"für alle Fälle","ko":"혹시 모를 때를 대비해서","ex":"Das Navi liegt ausgeschaltet im Handschuhfach – für alle Fälle.","exko":"내비게이션은 꺼진 채로 글로브박스 안에 있어요. 혹시 모를 때를 대비해서요."}],"words":359},{"id":"b1-19","level":"B1","no":19,"title":"Elternbrief: Klassenfahrt nach Weimar","titleKo":"가정통신문: 바이마르 수학여행","type":"Elternbrief","typeKo":"가정통신문","intro":"담임 선생님이 학부모에게 바이마르 수학여행 계획을 알리는 편지예요.","focus":["werden + 동사원형","2격 지배 전치사","dass 절","목적어 순서"],"paragraphs":[{"style":"meta","de":"Betreff: Klassenfahrt der 8c nach Weimar","ko":"제목: 8c반 바이마르 수학여행"},{"style":"meta","de":"Liebe Eltern der Klasse 8c,","ko":"8c반 학부모님께"},{"de":"wie beim Elternabend im September angekündigt, wird unsere Klasse eine Klassenfahrt nach Weimar machen. Die Fahrt wird vom 19. bis zum 23. April 2027 stattfinden; die Begleitung der Kinder übernehmen mein Kollege Herr Brückner und ich.","ko":"9월 학부모 모임에서 미리 말씀드린 대로, 저희 반은 바이마르로 수학여행을 갈 예정입니다. 여행은 2027년 4월 19일부터 23일까지 진행될 것이며, 아이들의 인솔은 제 동료인 브뤼크너 선생님과 제가 맡습니다."},{"de":"Weimar ist eine kleine Stadt mit großer Geschichte: Goethe und Schiller haben hier gelebt und gearbeitet, und 1919 erfolgte in Weimar die Gründung des Bauhauses. Am Dienstag steht die Besichtigung von Goethes Wohnhaus auf dem Programm, am Mittwoch folgt ein Besuch im Bauhaus-Museum. Dort wird die Klasse in einem Workshop eigene Entwürfe anfertigen, an denen wir nach der Fahrt im Kunstunterricht weiterarbeiten werden. Den Donnerstag werden die Kinder mit einer Stadtrallye in kleinen Gruppen verbringen.","ko":"바이마르는 작지만 역사가 깊은 도시입니다. 괴테와 실러가 이곳에서 살며 활동했고, 1919년에는 바이마르에서 바우하우스가 설립되었습니다. 화요일에는 괴테가 살던 집을 견학하는 일정이 있고, 수요일에는 바우하우스 박물관을 방문합니다. 그곳에서 학생들은 워크숍에 참여해 직접 디자인 시안을 만들 예정이며, 여행이 끝난 뒤에는 미술 시간에 이 시안으로 작업을 이어 갈 것입니다. 목요일에는 아이들이 작은 모둠으로 나뉘어 시내 탐방 미션을 하며 하루를 보낼 것입니다."},{"de":"Übernachten werden wir in einer Jugendherberge, die etwas außerhalb des Stadtzentrums liegt; bis zur Altstadt sind es zu Fuß etwa 15 Minuten. Pro Person kostet die Fahrt 265 Euro. Darin sind die Bahnfahrt, die Übernachtungen mit Vollpension und alle Eintrittsgelder enthalten, nicht jedoch das Taschengeld. Bitte überweisen Sie den Betrag innerhalb der nächsten vier Wochen auf das Konto der Schule.","ko":"저희는 시내 중심가에서 조금 벗어난 곳에 있는 유스호스텔에서 묵을 예정이며, 구시가지까지는 걸어서 15분 정도 걸립니다. 여행 비용은 1인당 265유로입니다. 여기에는 기차 요금, 세 끼 식사를 포함한 숙박, 모든 입장료가 포함되어 있지만 용돈은 포함되어 있지 않습니다. 이 금액은 앞으로 4주 안에 학교 계좌로 이체해 주시기 바랍니다."},{"de":"Uns ist wichtig, dass kein Kind aus finanziellen Gründen zu Hause bleiben muss. Familien, für die der Betrag eine Belastung darstellt, können deshalb beim Förderverein finanzielle Unterstützung beantragen. Für eine persönliche Beratung steht Ihnen Frau Thiele im Sekretariat gern zur Verfügung.","ko":"어떤 아이도 경제적인 이유로 집에 남아 있는 일이 없도록 하는 것이 저희에게는 중요합니다. 그래서 이 금액이 부담되는 가정은 학교 후원회에 경제적 지원을 신청할 수 있습니다. 개별 상담이 필요하시면 행정실의 틸레 씨가 기꺼이 도와드립니다."},{"de":"Während des gesamten Aufenthalts gilt unsere Schulordnung. Handys dürfen die Kinder mitnehmen; während der Führungen und nach 22 Uhr bleiben die Geräte jedoch ausgeschaltet. Außerhalb der Programmzeiten dürfen die Kinder die Altstadt in Gruppen von mindestens drei Personen erkunden, allerdings nur nach vorheriger Abmeldung bei uns. Von allen erwarten wir, dass sie Rücksicht auf die anderen Gäste der Herberge nehmen.","ko":"여행 기간 내내 저희 학교의 교칙이 적용됩니다. 아이들은 휴대전화를 가져가도 되지만, 안내 투어 중과 밤 10시 이후에는 전원을 꺼 두어야 합니다. 정해진 일정 이외의 시간에는 아이들이 3명 이상 모둠으로 구시가지를 둘러볼 수 있습니다. 다만 미리 저희에게 알린 뒤에만 나갈 수 있습니다. 저희는 모든 아이가 유스호스텔의 다른 투숙객을 배려해 주기를 기대합니다."},{"de":"Nimmt Ihr Kind regelmäßig Medikamente ein oder hat es eine Allergie, geben Sie uns bitte auf dem beiliegenden Formular Bescheid. Diese Informationen werden selbstverständlich vertraulich behandelt. Wir wären Ihnen dankbar, wenn Sie Ihrem Kind das ausgefüllte Formular bis spätestens 27. November mitgeben könnten. Während der Fahrt sind wir über das Klassenhandy jederzeit für Sie erreichbar.","ko":"자녀가 정기적으로 약을 먹거나 알레르기가 있으면 동봉한 양식에 적어 알려 주십시오. 이 정보는 당연히 비밀로 다루어집니다. 작성하신 양식을 늦어도 11월 27일까지 자녀 편에 보내 주시면 감사하겠습니다. 여행 중에는 학급 휴대전화로 언제든지 저희와 연락하실 수 있습니다."},{"de":"Wir freuen uns auf eine erlebnisreiche Woche mit Ihren Kindern.","ko":"저희는 자녀분들과 함께할 알찬 한 주를 기대하고 있습니다."},{"style":"meta","de":"Mit freundlichen Grüßen\nKerstin Haberland\n(Klassenlehrerin der 8c)","ko":"안부를 전하며\n케르스틴 하버란트 드림\n(8c반 담임 교사)"}],"questions":[{"type":"rf","kind":"detail","q":"Die Klassenlehrerin wird die Gruppe auf der Reise nicht allein betreuen.","answer":0,"evidence":"die Begleitung der Kinder übernehmen mein Kollege Herr Brückner und ich","pairs":[["die Begleitung der Kinder übernehmen mein Kollege Herr Brückner und ich","nicht allein betreuen"]],"explain":"담임 선생님은 동료인 브뤼크너 선생님과 함께 아이들의 인솔(Begleitung)을 맡는다고 해요. 그러니까 혼자 아이들을 돌보는 것이 아니에요. 문제에서는 die Begleitung übernehmen을 betreuen으로, mein Kollege … und ich를 nicht allein으로 바꿔 말했어요."},{"type":"mc","kind":"detail","q":"Was wird die Klasse im Bauhaus-Museum machen?","options":["Sie zeigt dort Entwürfe, die sie vorher im Kunstunterricht gemacht hat.","Sie besichtigt dort das Haus, in dem Goethe früher gelebt und gearbeitet hat.","Sie beginnt dort eine Arbeit, die nach der Reise in der Schule weitergeht."],"answer":2,"evidence":"Dort wird die Klasse in einem Workshop eigene Entwürfe anfertigen, an denen wir nach der Fahrt im Kunstunterricht weiterarbeiten werden.","pairs":[["eigene Entwürfe anfertigen","beginnt dort eine Arbeit"],["an denen wir nach der Fahrt im Kunstunterricht weiterarbeiten werden","die nach der Reise in der Schule weitergeht"],["Am Dienstag steht die Besichtigung von Goethes Wohnhaus auf dem Programm","Sie besichtigt dort das Haus, in dem Goethe früher gelebt und gearbeitet hat."]],"explain":"학생들은 바우하우스 박물관의 워크숍에서 직접 디자인 시안(Entwürfe)을 만들고, 여행이 끝난 뒤 미술 시간에 이어서 작업해요. 정답은 이것을 '거기서 작업을 시작하고 여행 뒤에 학교에서 계속한다'로 바꿔 말했어요. 미술 시간에 미리 만든 것을 보여 준다는 보기는 순서가 반대이고, 괴테의 집 견학은 화요일 일정이에요."},{"type":"mc","kind":"meaning","q":"Was bedeutet „etwas außerhalb des Stadtzentrums“ im Text?","options":["nicht im Zentrum, aber nur einen kurzen Fußweg davon entfernt","direkt in der Altstadt, ganz in der Nähe der wichtigen Museen","so weit von Weimar entfernt, dass man immer einen Bus braucht"],"answer":0,"evidence":"Übernachten werden wir in einer Jugendherberge, die etwas außerhalb des Stadtzentrums liegt; bis zur Altstadt sind es zu Fuß etwa 15 Minuten.","pairs":[["etwas außerhalb des Stadtzentrums","nicht im Zentrum"],["bis zur Altstadt sind es zu Fuß etwa 15 Minuten","nur einen kurzen Fußweg davon entfernt"]],"explain":"etwas außerhalb는 '조금 벗어난'이라는 뜻이에요. 유스호스텔은 시내 중심가 안에 있지는 않지만, 구시가지까지 걸어서 15분 정도라서 멀지 않아요. 구시가지 한가운데에 있다는 보기도, 버스가 늘 필요할 만큼 멀다는 보기도 틀려요."},{"type":"rf","kind":"detail","q":"Mit den 265 Euro ist auch das Geld für eigene Einkäufe in Weimar schon bezahlt.","answer":1,"evidence":"nicht jedoch das Taschengeld","pairs":[["nicht jedoch das Taschengeld","auch das Geld für eigene Einkäufe"]],"explain":"265유로에는 기차 요금, 세 끼 식사를 포함한 숙박, 입장료가 들어 있지만 용돈(Taschengeld)은 빠져 있어요(nicht jedoch). 그러니까 개인적으로 쓸 돈은 따로 챙겨야 해요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Uns ist wichtig, dass kein Kind aus finanziellen Gründen zu Hause bleiben muss.“?","options":["Die Schule übernimmt für jede Familie die vollen Kosten der Fahrt.","Eine Teilnahme an der Reise soll für niemanden am Geld scheitern.","Wer den Betrag nicht bezahlen kann, muss leider zu Hause bleiben."],"answer":1,"evidence":"Uns ist wichtig, dass kein Kind aus finanziellen Gründen zu Hause bleiben muss.","pairs":[["kein Kind aus finanziellen Gründen zu Hause bleiben muss","soll für niemanden am Geld scheitern"]],"explain":"이 문장은 형편이 어려워도 모든 아이가 여행에 함께 갈 수 있어야 한다는 뜻이에요. 그래서 바로 뒤에서 부담이 되는 가정은 후원회에 경제적 지원을 신청할 수 있다고 말해요. 학교가 모든 가정의 비용을 다 낸다는 말은 없고, 돈을 내지 못하면 집에 있어야 한다는 보기는 이 문장과 정반대예요."},{"type":"mc","kind":"detail","q":"Was gilt für die freie Zeit außerhalb des Programms?","options":["Auch dann müssen alle Kinder in der Nähe der Lehrkräfte bleiben.","Jedes Kind darf allein in die Altstadt, wenn es um 22 Uhr zurück ist.","Zu dritt oder mehr dürfen sie ohne Lehrer los, wenn sie sich melden."],"answer":2,"evidence":"Außerhalb der Programmzeiten dürfen die Kinder die Altstadt in Gruppen von mindestens drei Personen erkunden, allerdings nur nach vorheriger Abmeldung bei uns.","pairs":[["in Gruppen von mindestens drei Personen","Zu dritt oder mehr"],["nach vorheriger Abmeldung bei uns","wenn sie sich melden"],["nach 22 Uhr bleiben die Geräte jedoch ausgeschaltet","wenn es um 22 Uhr zurück ist"]],"explain":"정해진 일정 이외의 시간에는 3명 이상 모둠으로 구시가지를 둘러볼 수 있지만, 미리 선생님께 알려야(nach vorheriger Abmeldung) 해요. 정답은 이것을 zu dritt oder mehr, wenn sie sich melden으로 바꿔 말했어요. 혼자 다니는 것은 허락되지 않고, 밤 10시는 휴대전화를 꺼 두는 시간이에요."},{"type":"mc","kind":"intent","q":"Warum erwähnt die Lehrerin Goethe, Schiller und das Bauhaus?","options":["Sie will zeigen, warum sich gerade Weimar als Reiseziel lohnt.","Sie will zeigen, dass Weimar eine sehr große und moderne Stadt ist.","Sie will erklären, warum der Workshop schon vor der Fahrt beginnt."],"answer":0,"evidence":"Weimar ist eine kleine Stadt mit großer Geschichte","pairs":[["eine kleine Stadt mit großer Geschichte","warum sich gerade Weimar als Reiseziel lohnt"],["eine kleine Stadt","eine sehr große und moderne Stadt"]],"explain":"선생님은 괴테와 실러, 바우하우스를 들어 바이마르가 '작지만 역사가 깊은 도시'라는 것을 보여 줘요. 이 도시가 왜 수학여행지로 좋은지 설명하려는 거예요. 바이마르는 작은 도시라고 했으니 크고 현대적인 도시라는 보기는 틀리고, 워크숍 작업은 여행이 끝난 뒤에 이어 가요."},{"type":"mc","kind":"gist","q":"Was ist das Hauptziel dieses Briefes?","options":["Die Eltern sollen gemeinsam über das Ziel der Klassenfahrt abstimmen.","Die Familien sollen alles über Programm, Kosten und Regeln erfahren.","Eltern, die als Begleitung mitfahren möchten, sollen sich bald melden."],"answer":1,"evidence":"Pro Person kostet die Fahrt 265 Euro.","pairs":[["Am Dienstag steht die Besichtigung von Goethes Wohnhaus auf dem Programm","Programm"],["Pro Person kostet die Fahrt 265 Euro.","Kosten"],["Während des gesamten Aufenthalts gilt unsere Schulordnung.","Regeln"]],"explain":"편지에는 일정, 숙소와 비용, 지원 방법, 여행 중의 규칙, 건강 정보 양식이 차례로 나와요. 가정에서 알아야 할 내용을 모두 알리는 편지예요. 여행지를 함께 정하자거나 부모님 중에서 인솔자를 찾는다는 내용은 없어요."}],"grammar":[{"title":"미래형 – 계획을 정식으로 알리기","term":"Futur I (werden + Infinitiv)","explain":"werden + 동사원형(끝)은 앞으로 할 일을 나타내요. 독일어에서는 시간 표현이 있으면 현재형으로도 미래를 자주 말해요(Am Mittwoch folgt ein Besuch …). 이 편지처럼 앞으로의 계획을 분명하게 알릴 때는 미래형도 써요. werden은 주어에 맞춰 변하고 두 번째 자리에 오며, 동사원형은 문장 끝에 와요. 부문장에서는 werden이 맨 끝으로 가요(…, an denen wir … weiterarbeiten werden).","pattern":"주어 + werden + … + 동사원형(끝) / 부문장: … + 동사원형 + werden","examples":[{"de":"Den Donnerstag werden die Kinder mit einer Stadtrallye in kleinen Gruppen verbringen.","ko":"목요일에는 아이들이 작은 모둠으로 나뉘어 시내 탐방 미션을 하며 하루를 보낼 것입니다.","mark":["werden","verbringen"],"parts":[["Den Donnerstag","4격 목적어"],["werden","동사"],["die Kinder","주어"],["mit einer Stadtrallye","부사어(방법)"],["in kleinen Gruppen","부사어(방법)"],["verbringen.","동사(끝)"]]},{"de":"Dort wird die Klasse in einem Workshop eigene Entwürfe anfertigen, an denen wir nach der Fahrt im Kunstunterricht weiterarbeiten werden.","ko":"그곳에서 학생들은 워크숍에 참여해 직접 디자인 시안을 만들 예정이며, 여행이 끝난 뒤에는 미술 시간에 이 시안으로 작업을 이어 갈 것입니다.","mark":["wird","anfertigen","weiterarbeiten werden"]},{"de":"Übernachten werden wir in einer Jugendherberge, die etwas außerhalb des Stadtzentrums liegt; bis zur Altstadt sind es zu Fuß etwa 15 Minuten.","ko":"저희는 시내 중심가에서 조금 벗어난 곳에 있는 유스호스텔에서 묵을 예정이며, 구시가지까지는 걸어서 15분 정도 걸립니다.","mark":["Übernachten werden wir"]}],"tip":"세 번째 예문은 동사원형 Übernachten을 문장 맨 앞에 두어 '묵는 일'을 먼저 꺼내고, 어디에서 묵는지를 뒤에서 알려 줘요. werden + 과거분사는 수동태예요(Diese Informationen werden … behandelt). 문장 끝에 동사원형이 있는지 과거분사가 있는지 보면 구별할 수 있어요."},{"title":"2격 지배 전치사 – während · innerhalb · außerhalb","term":"Präpositionen mit Genitiv","explain":"während(~ 동안), innerhalb(~ 안에, ~ 이내에), außerhalb(~ 밖에, ~ 이외에)는 2격과 함께 써요. 시간에도 장소에도 쓸 수 있어요: innerhalb der nächsten vier Wochen(앞으로 4주 안에), außerhalb des Stadtzentrums(시내 중심가 밖에). 남성·중성 명사의 2격에서는 관사가 des가 되고 명사에 -s나 -es가 붙어요(des Aufenthalts, des Stadtzentrums).","pattern":"während · innerhalb · außerhalb + 2격 (des / der + 명사)","examples":[{"de":"Während des gesamten Aufenthalts gilt unsere Schulordnung.","ko":"여행 기간 내내 저희 학교의 교칙이 적용됩니다.","mark":["Während des gesamten Aufenthalts"],"parts":[["Während des gesamten Aufenthalts","부사어(시간)"],["gilt","동사"],["unsere Schulordnung.","주어"]]},{"de":"Außerhalb der Programmzeiten dürfen die Kinder die Altstadt in Gruppen von mindestens drei Personen erkunden, allerdings nur nach vorheriger Abmeldung bei uns.","ko":"정해진 일정 이외의 시간에는 아이들이 3명 이상 모둠으로 구시가지를 둘러볼 수 있습니다. 다만 미리 저희에게 알린 뒤에만 나갈 수 있습니다.","mark":["Außerhalb der Programmzeiten"]},{"de":"Bitte überweisen Sie den Betrag innerhalb der nächsten vier Wochen auf das Konto der Schule.","ko":"이 금액은 앞으로 4주 안에 학교 계좌로 이체해 주시기 바랍니다.","mark":["innerhalb der nächsten vier Wochen"]}],"tip":"관사 없이 쓰면 2격이 드러나지 않아서 innerhalb von + 3격을 써요(innerhalb von vier Wochen). 말할 때는 während dem처럼 3격을 쓰는 사람도 있지만, 편지 같은 글에서는 2격을 써요."},{"title":"중요한 점과 기대를 말하는 dass 절","term":"dass-Sätze nach Ausdrücken der Wichtigkeit und Erwartung (Uns ist wichtig, dass … / Wir erwarten, dass …)","explain":"무엇이 중요한지, 무엇을 기대하는지 말할 때 그 내용을 dass 절로 이어요. Uns ist wichtig, dass …는 '우리에게는 ~이 중요하다'라는 뜻이고, 이때 dass 절이 문장의 주어 역할을 해요. Wir erwarten (von allen), dass …에서는 dass 절이 4격 목적어 역할을 해요. dass 절은 부문장이라서 동사가 끝에 와요. 학교가 바라는 점을 정중하면서도 분명하게 알릴 때 자주 써요.","pattern":"3격 + ist wichtig, dass … + 동사(끝) / erwarten (von + 3격), dass … + 동사(끝)","examples":[{"de":"Uns ist wichtig, dass kein Kind aus finanziellen Gründen zu Hause bleiben muss.","ko":"어떤 아이도 경제적인 이유로 집에 남아 있는 일이 없도록 하는 것이 저희에게는 중요합니다.","mark":["Uns ist wichtig, dass","muss"],"parts":[["Uns","3격 목적어"],["ist","동사"],["wichtig,","보어"],["dass kein Kind aus finanziellen Gründen zu Hause bleiben muss.","종속절"]]},{"de":"Von allen erwarten wir, dass sie Rücksicht auf die anderen Gäste der Herberge nehmen.","ko":"저희는 모든 아이가 유스호스텔의 다른 투숙객을 배려해 주기를 기대합니다.","mark":["erwarten wir, dass","nehmen"],"parts":[["Von allen","전치사 목적어"],["erwarten","동사"],["wir,","주어"],["dass sie Rücksicht auf die anderen Gäste der Herberge nehmen.","종속절"]]}],"tip":"같은 내용을 명사로 줄여 말할 수도 있어요: Wir erwarten von allen Rücksicht auf die anderen Gäste. dass 절은 문장 앞에 올 수도 있어요: Dass kein Kind zu Hause bleiben muss, ist uns wichtig."},{"title":"3격과 4격 목적어의 순서","term":"Stellung von Dativ- und Akkusativobjekt im Mittelfeld","explain":"한 문장에 3격 목적어와 4격 목적어가 함께 있을 때, 둘 다 명사이면 보통 3격이 4격 앞에 와요: Ihrem Kind (3격) das ausgefüllte Formular (4격). 대명사는 명사보다 앞으로 가는 경향이 있어서, 3격 대명사가 주어 명사보다 먼저 오기도 해요: steht Ihnen Frau Thiele … zur Verfügung. 3격과 4격이 모두 대명사이면 4격이 먼저 와요: Geben Sie es ihm mit.","pattern":"명사 + 명사: 3격 → 4격 · 대명사 + 대명사: 4격 → 3격 · 대명사는 명사보다 앞","examples":[{"de":"wenn Sie Ihrem Kind das ausgefüllte Formular bis spätestens 27. November mitgeben könnten","ko":"작성하신 양식을 늦어도 11월 27일까지 자녀 편에 보내 주시면","mark":["Ihrem Kind","das ausgefüllte Formular"],"parts":[["wenn","접속사"],["Sie","주어"],["Ihrem Kind","3격 목적어"],["das ausgefüllte Formular","4격 목적어"],["bis spätestens 27. November","부사어(시간)"],["mitgeben könnten","동사(끝)"]]},{"de":"Für eine persönliche Beratung steht Ihnen Frau Thiele im Sekretariat gern zur Verfügung.","ko":"개별 상담이 필요하시면 행정실의 틸레 씨가 기꺼이 도와드립니다.","mark":["Ihnen","Frau Thiele"],"parts":[["Für eine persönliche Beratung","부사어"],["steht","동사"],["Ihnen","3격 목적어"],["Frau Thiele","주어"],["im Sekretariat","부사어(장소)"],["gern","부사어(방법)"],["zur Verfügung.","동사(끝)"]]}],"tip":"4격을 강조하고 싶을 때는 문장 맨 앞에 둘 수 있어요: Das ausgefüllte Formular geben Sie Ihrem Kind bitte mit. 본문의 Wir wären Ihnen dankbar, wenn …은 접속법 2식으로 공손하게 부탁하는 표현이에요."}],"vocab":[{"de":"die Klassenfahrt, -en","ko":"수학여행"},{"de":"der Elternabend, -e","ko":"학부모 모임"},{"de":"an|kündigen","ko":"미리 알리다, 예고하다"},{"de":"statt|finden (findet statt, fand statt, hat stattgefunden)","ko":"열리다, 진행되다"},{"de":"die Begleitung (Sg.)","ko":"인솔, 동행"},{"de":"die Besichtigung, -en","ko":"견학, 관람"},{"de":"der Entwurf, -¨e","ko":"(디자인) 시안, 초안"},{"de":"an|fertigen","ko":"만들다, 제작하다"},{"de":"die Jugendherberge, -n","ko":"유스호스텔"},{"de":"die Vollpension (Sg.)","ko":"세 끼 식사가 포함된 숙박"},{"de":"das Taschengeld (Sg.)","ko":"용돈"},{"de":"überweisen (überweist, überwies, hat überwiesen)","ko":"(계좌로) 이체하다"},{"de":"die Belastung, -en","ko":"부담"},{"de":"der Förderverein, -e","ko":"(학교) 후원회"},{"de":"erkunden","ko":"둘러보다, 탐방하다"},{"de":"die Abmeldung, -en","ko":"(나가거나 빠진다고) 알림, 신고"}],"phrases":[{"de":"auf dem Programm stehen","ko":"일정에 들어 있다","ex":"Am Dienstag steht die Besichtigung von Goethes Wohnhaus auf dem Programm, am Mittwoch folgt ein Besuch im Bauhaus-Museum.","exko":"화요일에는 괴테가 살던 집을 견학하는 일정이 있고, 수요일에는 바우하우스 박물관을 방문합니다."},{"de":"eine Belastung darstellen","ko":"부담이 되다","ex":"Familien, für die der Betrag eine Belastung darstellt, können deshalb beim Förderverein finanzielle Unterstützung beantragen.","exko":"그래서 이 금액이 부담되는 가정은 학교 후원회에 경제적 지원을 신청할 수 있습니다."},{"de":"jemandem zur Verfügung stehen","ko":"~을 도울 수 있게 준비되어 있다","ex":"Für eine persönliche Beratung steht Ihnen Frau Thiele im Sekretariat gern zur Verfügung.","exko":"개별 상담이 필요하시면 행정실의 틸레 씨가 기꺼이 도와드립니다."},{"de":"Rücksicht nehmen auf + Akk.","ko":"~을 배려하다","ex":"Von allen erwarten wir, dass sie Rücksicht auf die anderen Gäste der Herberge nehmen.","exko":"저희는 모든 아이가 유스호스텔의 다른 투숙객을 배려해 주기를 기대합니다."},{"de":"jemandem Bescheid geben","ko":"~에게 알려 주다","ex":"Nimmt Ihr Kind regelmäßig Medikamente ein oder hat es eine Allergie, geben Sie uns bitte auf dem beiliegenden Formular Bescheid.","exko":"자녀가 정기적으로 약을 먹거나 알레르기가 있으면 동봉한 양식에 적어 알려 주십시오."}],"words":356},{"id":"b1-20","level":"B1","no":20,"title":"Ausbildung abbrechen – ja oder nein?","titleKo":"직업 교육을 그만둬야 할까요?","type":"Forumsdiskussion","typeKo":"온라인 게시판 토론","intro":"직업 교육을 그만둘지 고민하는 청년의 글과 답글들을 읽어요.","focus":["solange","nicht brauchen … zu","sehen · hören + 동사원형","bevor"],"paragraphs":[{"label":"jonas06","de":"Moin zusammen, ich mache seit acht Monaten eine Ausbildung zum Bankkaufmann und bin total frustriert. Jeden Montagmorgen sehe ich meine Kollegen mit müden Gesichtern in die Filiale schlurfen und frage mich, ob ich die nächsten vierzig Jahre so absitzen will. Die Bearbeitung von Kreditanträgen langweilt mich, und die Berufsschule finde ich öde. Eigentlich arbeite ich lieber mit Holz und habe schon als Kind in der Werkstatt meines Großvaters Regale und Hocker gezimmert. Meine Eltern drängen mich aber durchzuhalten, sonst finde ich später niemals einen sicheren Arbeitsplatz. Was würdet ihr in meiner Situation tun?","ko":"안녕하세요, 여러분. 저는 여덟 달째 은행원 직업 교육을 받고 있는데 정말 답답해요. 월요일 아침마다 동료들이 피곤한 얼굴로 지점에 터덜터덜 들어오는 걸 보면서, 앞으로 40년을 정말 이렇게 시간만 때우며 보내고 싶은지 생각해요. 대출 신청서를 처리하는 일은 지루하고, 직업 학교도 따분해요. 사실 저는 나무로 뭔가를 만드는 일이 더 좋아서, 어릴 때 할아버지 작업장에서 선반이랑 스툴을 직접 만들기도 했어요. 그런데 부모님은 끝까지 버티라고 재촉하세요. 그러지 않으면 나중에 안정된 일자리를 절대 못 구한다면서요. 여러분이 제 상황이라면 어떻게 하시겠어요?"},{"label":"mira.k","de":"Mir ging es vor sechs Jahren genauso: Ich hatte eine Ausbildung zur Hotelfachfrau angefangen und mich durch Spätschichten an der Rezeption gequält. Nach dem ersten Lehrjahr habe ich abgebrochen und eine Lehre als Tischlerin begonnen, und heute liebe ich meine Arbeit als Gesellin. Ein Ausbildungsabbruch ist also kein Weltuntergang, und du brauchst dich nicht zu schämen, wenn ein Beruf nicht zu dir passt. Schmeiß aber nicht einfach hin, ohne einen Plan zu haben! Ich hatte nämlich schon einen neuen Ausbildungsplatz in der Tasche, bevor ich gekündigt habe.","ko":"저도 6년 전에 똑같았어요. 호텔리어 직업 교육을 시작했는데, 프런트의 늦은 교대 근무를 견디느라 괴로웠어요. 첫 1년을 마치고 그만둔 뒤 목공 견습을 시작했고, 지금은 숙련공으로 하는 제 일을 무척 좋아해요. 그러니까 직업 교육을 그만두는 게 세상이 끝나는 일은 아니에요. 어떤 직업이 자기와 맞지 않는다고 해서 부끄러워할 필요는 없어요. 하지만 계획도 없이 그냥 때려치우지는 마세요! 저는 그만두기 전에 이미 새 교육 자리를 구해 두었거든요."},{"label":"Kemal Polat (Ausbildungsberater)","de":"Solange du noch nicht weißt, was du stattdessen machen willst, solltest du deinen Ausbildungsvertrag nicht kündigen. Nach der Probezeit beträgt die Kündigungsfrist vier Wochen. Sprich zunächst mit deinem Ausbilder, denn vielleicht kannst du innerhalb der Bank in eine andere Abteilung wechseln. Außerdem brauchst du das Problem nicht allein zu lösen: Die Ausbildungsberater der Kammern beraten dich kostenlos, auch beim Wechsel in einen anderen Beruf. Noch ein Tipp: Bevor du dich entscheidest, mach in deinen Urlaubstagen ein Schnupperpraktikum in einer Tischlerei. Dort siehst du die Gesellen an der Hobelbank arbeiten und merkst schnell, ob dir das Handwerk liegt.","ko":"그 대신 무엇을 하고 싶은지 아직 모르는 동안에는 직업 교육 계약을 해지하지 않는 게 좋아요. 수습 기간이 끝난 뒤에는 해지 예고 기간이 4주예요. 먼저 교육 담당자와 이야기해 보세요. 어쩌면 은행 안에서 다른 부서로 옮길 수 있을지도 몰라요. 게다가 이 문제를 혼자 해결할 필요도 없어요. 상공회의소나 수공업회의소의 직업 교육 상담사들이 무료로 상담해 줘요. 다른 직업으로 바꿀 때도요. 그리고 하나 더 조언하자면, 결정하기 전에 휴가 기간에 목공소에서 체험 실습을 해 보세요. 그곳에서 숙련공들이 대패질 작업대에서 일하는 모습을 보면, 수공업 일이 자신에게 맞는지 금방 알 수 있어요."},{"label":"jonas06","de":"Danke für eure Tipps! Gestern habe ich mit meinem Ausbilder gesprochen, obwohl ich vor seiner Reaktion Bammel hatte. Er war überhaupt nicht sauer, sondern hat mir geduldig zugehört und von seinem Berufswechsel erzählt. Ich höre ihn noch sagen: „Lieber jetzt ehrlich als in drei Jahren unglücklich.“ Im Mai mache ich ein zweiwöchiges Praktikum in einer Tischlerei; bis dahin bleibe ich in der Filiale. Danach treffe ich meine Entscheidung.","ko":"다들 조언해 줘서 고마워요! 어제 교육 담당자와 이야기했어요. 어떤 반응을 보일지 조마조마했지만요. 그런데 그분은 전혀 화를 내지 않고, 제 이야기를 차분히 들어 주면서 자신이 직업을 바꾼 이야기도 해 주었어요. “3년 뒤에 불행한 것보다 지금 솔직한 게 나아요.”라고 하던 목소리가 아직도 귀에 생생해요. 5월에 목공소에서 2주짜리 실습을 해요. 그때까지는 지점에서 계속 일할 거예요. 그다음에 결정을 내릴 거예요."}],"questions":[{"type":"mc","kind":"gist","q":"Worum geht es in Jonas’ erstem Beitrag?","options":["Er fragt sich, ob er seine kaufmännische Lehre zu Ende bringen soll.","Er sucht in seiner Bank eine bessere Stelle in einer anderen Abteilung.","Er beschwert sich über Kollegen, die montags immer zu spät kommen."],"answer":0,"evidence":"frage mich, ob ich die nächsten vierzig Jahre so absitzen will","pairs":[["frage mich, ob ich die nächsten vierzig Jahre so absitzen will","Er fragt sich, ob er seine kaufmännische Lehre zu Ende bringen soll."],["in eine andere Abteilung wechseln","eine bessere Stelle in einer anderen Abteilung"]],"explain":"요나스는 은행원 직업 교육이 답답하고, 앞으로 40년을 이렇게 보내야 하나 고민한다고 해요. 부모님은 버티라고 하시니 다른 사람들의 생각을 묻는 글이에요. 그러니까 중심 내용은 '이 교육을 끝까지 계속할지 고민한다'예요. 다른 부서로 옮기는 이야기는 상담사 폴라트 씨의 조언이고, 동료들이 늦게 온다는 말은 없어요."},{"type":"rf","kind":"detail","q":"In der Berufsschule fühlt sich Jonas wohler als in der Filiale.","answer":1,"evidence":"und die Berufsschule finde ich öde","pairs":[["die Berufsschule finde ich öde","In der Berufsschule fühlt sich Jonas wohler"]],"explain":"요나스는 대출 신청서 처리도 지루하고 직업 학교(Berufsschule)도 따분하다(öde)고 해요. 직업 학교가 지점보다 더 편하다는 말은 본문과 맞지 않아요."},{"type":"mc","kind":"detail","q":"Was befürchten Jonas’ Eltern?","options":["Dass er in der Werkstatt seines Großvaters arbeiten möchte.","Dass er mit Kreditanträgen auf Dauer zu wenig Geld verdienen wird.","Dass ihm ohne Abschluss später eine feste Stelle fehlen könnte."],"answer":2,"evidence":"sonst finde ich später niemals einen sicheren Arbeitsplatz","pairs":[["sonst finde ich später niemals einen sicheren Arbeitsplatz","ohne Abschluss später eine feste Stelle fehlen könnte"]],"explain":"부모님은 요나스가 끝까지 버티지 않으면(sonst) 나중에 안정된 일자리를 구하지 못할 거라고 걱정해요. 정답은 이것을 '교육을 마치지 않으면 나중에 일자리가 없을 수 있다'로 바꿔 말했어요. 할아버지 작업장은 요나스의 어린 시절 이야기이고, 돈을 적게 번다는 걱정은 본문에 없어요."},{"type":"rf","kind":"detail","q":"Mira hat ihre Lehre im Hotel nicht abgeschlossen.","answer":0,"evidence":"Nach dem ersten Lehrjahr habe ich abgebrochen","pairs":[["Nach dem ersten Lehrjahr habe ich abgebrochen","nicht abgeschlossen"],["Ausbildung zur Hotelfachfrau","Lehre im Hotel"]],"explain":"미라는 호텔리어 직업 교육을 시작했다가 첫 1년을 마치고 그만두었다(abgebrochen)고 해요. 그러니까 호텔 일을 배우는 과정을 끝까지 마치지 않은 것이 맞아요."},{"type":"mc","kind":"meaning","q":"Was meint Mira mit „du brauchst dich nicht zu schämen“?","options":["Du solltest dich bei deinem Ausbilder für alles entschuldigen.","Einen unpassenden Beruf aufzugeben, ist nichts Peinliches.","Du musst keine Angst vor der Reaktion deiner Eltern haben."],"answer":1,"evidence":"Ein Ausbildungsabbruch ist also kein Weltuntergang, und du brauchst dich nicht zu schämen, wenn ein Beruf nicht zu dir passt.","pairs":[["du brauchst dich nicht zu schämen","ist nichts Peinliches"],["wenn ein Beruf nicht zu dir passt","Einen unpassenden Beruf aufzugeben"]],"explain":"sich schämen은 '부끄러워하다'이고, nicht brauchen … zu는 '~할 필요가 없다'예요. 맞지 않는 직업을 그만두는 것은 부끄러운(peinlich) 일이 아니라는 뜻이에요. 사과하라는 말도, 부모님의 반응을 두려워하지 말라는 말도 아니에요."},{"type":"mc","kind":"detail","q":"Was soll Jonas nach Herrn Polats Rat als Erstes tun?","options":["Sofort einen Ausbildungsvertrag mit einer Tischlerei abschließen.","Ein Gespräch mit dem Verantwortlichen für seine Lehre führen.","Kündigen und dann in aller Ruhe ein Schnupperpraktikum suchen."],"answer":1,"evidence":"Sprich zunächst mit deinem Ausbilder","pairs":[["Sprich zunächst mit deinem Ausbilder","Ein Gespräch mit dem Verantwortlichen für seine Lehre führen."],["solltest du deinen Ausbildungsvertrag nicht kündigen","Kündigen und dann in aller Ruhe ein Schnupperpraktikum suchen."]],"explain":"폴라트 씨는 먼저(zunächst) 교육 담당자(Ausbilder)와 이야기해 보라고 해요. 정답은 Ausbilder를 '그의 직업 교육을 책임지는 사람'으로 바꿔 말했어요. 다른 계획이 없는 동안에는 계약을 해지하지 말라고 했으니 먼저 그만두라는 보기는 틀리고, 목공소와 바로 계약하라는 말도 없어요."},{"type":"mc","kind":"intent","q":"Warum empfiehlt Herr Polat ein Praktikum?","options":["Jonas soll testen, ob er sich in dem neuen Beruf wohlfühlt.","Jonas bekommt so später leichter einen sicheren Arbeitsplatz.","Jonas kann in seinen Urlaubstagen etwas Geld verdienen."],"answer":0,"evidence":"Dort siehst du die Gesellen an der Hobelbank arbeiten und merkst schnell, ob dir das Handwerk liegt.","pairs":[["merkst schnell, ob dir das Handwerk liegt","testen, ob er sich in dem neuen Beruf wohlfühlt"]],"explain":"폴라트 씨는 목공소에서 숙련공들이 일하는 모습을 보면 수공업 일이 자신에게 맞는지(liegt) 금방 알 수 있다고 해요. 결정하기 전에 새 직업을 직접 경험해 보라는 거예요. 안정된 일자리는 부모님의 걱정이고, 돈을 번다는 이야기는 없어요."},{"type":"rf","kind":"detail","q":"Jonas hat seinen Ausbildungsvertrag schon gekündigt, bevor er ins Praktikum geht.","answer":1,"evidence":"bis dahin bleibe ich in der Filiale","pairs":[["bis dahin bleibe ich in der Filiale","schon gekündigt"]],"explain":"요나스는 5월에 목공소에서 실습을 하고, 그때까지(bis dahin)는 은행 지점에서 계속 일한다고 해요. 결정은 실습이 끝난 뒤에 내려요. 그러니까 실습 전에 이미 계약을 해지했다는 말은 틀려요."}],"grammar":[{"title":"solange – ~하는 동안에는, ~하는 한","term":"Konjunktion solange","explain":"solange는 어떤 상태가 이어지는 동안에만 주절의 내용이 해당된다는 것을 말하는 종속접속사예요. 그래서 '~하는 한'이라는 조건의 뜻도 생겨요. 본문에서 폴라트 씨는 '다른 계획이 없는 동안에는 그만두지 말라'고 해요. 그 상태가 끝나면, 즉 하고 싶은 일을 알게 되면 상황이 달라질 수 있다는 뜻이에요. 부문장이라서 동사는 절 끝에 오고, solange 절이 앞에 오면 주절은 동사로 시작해요.","pattern":"Solange + … + 동사(끝), 동사 + 주어 …","examples":[{"de":"Solange du noch nicht weißt, was du stattdessen machen willst, solltest du deinen Ausbildungsvertrag nicht kündigen.","ko":"그 대신 무엇을 하고 싶은지 아직 모르는 동안에는 직업 교육 계약을 해지하지 않는 게 좋아요.","mark":["Solange","weißt"],"parts":[["Solange du noch nicht weißt, was du stattdessen machen willst,","종속절"],["solltest","동사"],["du","주어"],["deinen Ausbildungsvertrag","4격 목적어"],["nicht","부정어"],["kündigen.","동사(끝)"]]}],"tip":"solange … nicht는 '~하지 않는 한', '~할 때까지는'으로 옮기면 자연스러워요. während도 '~하는 동안'이지만, 두 일이 같은 때에 일어난다는 것만 말하고 조건의 뜻은 없어요."},{"title":"nicht brauchen … zu – 필요 없음을 말하기","term":"nicht brauchen + zu + Infinitiv","explain":"brauchen을 nicht와 zu 부정사와 함께 쓰면 '~할 필요가 없다'는 뜻이 돼요. nicht müssen과 뜻이 같지만, 동사원형 앞에 zu를 넣어요. 이 뜻의 brauchen은 보통 nicht, kein, nur 같은 말과 함께 써요. 재귀동사를 쓰면 재귀대명사는 zu + 동사원형 옆이 아니라 nicht 앞에 와요(du brauchst dich nicht zu schämen).","pattern":"brauchen(두 번째 자리) + … + nicht + … + zu + 동사원형(끝)","examples":[{"de":"Außerdem brauchst du das Problem nicht allein zu lösen:","ko":"게다가 이 문제를 혼자 해결할 필요도 없어요.","mark":["brauchst","nicht","zu lösen"],"parts":[["Außerdem","접속부사"],["brauchst","동사"],["du","주어"],["das Problem","4격 목적어"],["nicht","부정어"],["allein","부사어(방법)"],["zu lösen:","동사(끝)"]]},{"de":"Ein Ausbildungsabbruch ist also kein Weltuntergang, und du brauchst dich nicht zu schämen, wenn ein Beruf nicht zu dir passt.","ko":"그러니까 직업 교육을 그만두는 게 세상이 끝나는 일은 아니에요. 어떤 직업이 자기와 맞지 않는다고 해서 부끄러워할 필요는 없어요.","mark":["brauchst dich nicht zu schämen"]}],"tip":"nicht dürfen과 헷갈리지 마세요. Du brauchst nicht zu kündigen.은 '그만둘 필요가 없다', Du darfst nicht kündigen.은 '그만두면 안 된다'예요. 말할 때는 zu를 빼는 사람도 많아요."},{"title":"sehen · hören + 동사원형 – 보고 들은 장면","term":"Wahrnehmungsverben mit Infinitiv","explain":"sehen과 hören은 zu 없이 다른 동사원형과 함께 써서 '누가 무엇을 하는 것을 보다/듣다'라는 뜻을 나타내요. 보거나 듣는 사람은 주어예요. 눈에 보이거나 소리가 들리는 사람, 즉 행동하는 사람은 4격 목적어이고, 그 사람이 하는 행동은 동사원형으로 문장 끝에 와요.","pattern":"sehen / hören + 4격(행동하는 사람) + … + 동사원형(끝)","examples":[{"de":"Dort siehst du die Gesellen an der Hobelbank arbeiten und merkst schnell, ob dir das Handwerk liegt.","ko":"그곳에서 숙련공들이 대패질 작업대에서 일하는 모습을 보면, 수공업 일이 자신에게 맞는지 금방 알 수 있어요.","mark":["siehst","die Gesellen","arbeiten"],"parts":[["Dort","부사어(장소)"],["siehst","동사"],["du","주어"],["die Gesellen","4격 목적어"],["an der Hobelbank","부사어(장소)"],["arbeiten","동사(끝)"],["und merkst schnell, ob dir das Handwerk liegt.","기타"]]},{"de":"Jeden Montagmorgen sehe ich meine Kollegen mit müden Gesichtern in die Filiale schlurfen und frage mich, ob ich die nächsten vierzig Jahre so absitzen will.","ko":"월요일 아침마다 동료들이 피곤한 얼굴로 지점에 터덜터덜 들어오는 걸 보면서, 앞으로 40년을 정말 이렇게 시간만 때우며 보내고 싶은지 생각해요.","mark":["sehe","meine Kollegen","schlurfen"]},{"de":"Ich höre ihn noch sagen:","ko":"그분 목소리가 아직도 귀에 생생해요.","mark":["höre ihn","sagen"]}],"tip":"현재완료에서는 과거분사 대신 동사원형을 쓰는 경우가 많아요: Ich habe ihn kommen sehen."},{"title":"bevor – ~하기 전에","term":"Temporalsatz mit bevor","explain":"bevor는 '~하기 전에'라는 뜻의 종속접속사예요. 주절의 일이 bevor 절의 일보다 먼저 일어나요. 그래서 먼저 해 둘 일이나 먼저 끝나 있던 일을 말할 때 써요. 부문장이라서 동사가 끝에 오고, bevor 절이 앞에 오면 주절은 동사로 시작해요(Bevor du dich entscheidest, mach …).","pattern":"주절, bevor + … + 동사(끝) / Bevor + … + 동사(끝), 동사 + …","examples":[{"de":"Ich hatte nämlich schon einen neuen Ausbildungsplatz in der Tasche, bevor ich gekündigt habe.","ko":"저는 그만두기 전에 이미 새 교육 자리를 구해 두었거든요.","mark":["bevor ich gekündigt habe"],"parts":[["Ich","주어"],["hatte","동사"],["nämlich","기타"],["schon","부사어(시간)"],["einen neuen Ausbildungsplatz","4격 목적어"],["in der Tasche,","부사어(장소)"],["bevor ich gekündigt habe.","종속절"]]},{"de":"Bevor du dich entscheidest, mach in deinen Urlaubstagen ein Schnupperpraktikum in einer Tischlerei.","ko":"결정하기 전에 휴가 기간에 목공소에서 체험 실습을 해 보세요.","mark":["Bevor","entscheidest","mach"]}],"tip":"bevor와 vor를 헷갈리지 마세요. vor는 전치사라서 뒤에 명사가 와요(vor der Entscheidung). 반대 순서, 즉 '~한 뒤에'는 nachdem으로 말해요."}],"vocab":[{"de":"die Ausbildung, -en","ko":"직업 교육"},{"de":"der Bankkaufmann, -leute","ko":"은행원 (직업 교육을 마친 은행 사무직)"},{"de":"die Filiale, -n","ko":"(은행의) 지점"},{"de":"die Berufsschule, -n","ko":"직업 학교 (직업 교육 중에 다니는 학교)"},{"de":"durch|halten (hält durch, hielt durch, hat durchgehalten)","ko":"끝까지 버티다"},{"de":"sich (Akk.) quälen","ko":"괴로워하다, 힘겹게 견디다"},{"de":"ab|brechen (bricht ab, brach ab, hat abgebrochen)","ko":"(교육 등을) 중간에 그만두다"},{"de":"die Lehre, -n","ko":"견습, 직업 교육"},{"de":"die Gesellin, -nen","ko":"(수공업의) 숙련공(여자)"},{"de":"sich (Akk.) schämen","ko":"부끄러워하다"},{"de":"hin|schmeißen (schmiss hin, hat hingeschmissen) (ugs.)","ko":"(일을) 때려치우다"},{"de":"kündigen","ko":"(계약을) 해지하다, 그만두다"},{"de":"die Probezeit, -en","ko":"수습 기간"},{"de":"der Ausbilder, -","ko":"교육 담당자 (직업 교육을 맡은 사람)"},{"de":"die Kammer, -n","ko":"(상공회의소·수공업회의소 같은) 회의소"},{"de":"das Praktikum, Praktika","ko":"실습, 인턴십"}],"phrases":[{"de":"eine Ausbildung zum/zur … machen","ko":"~ 직업 교육을 받다","ex":"Moin zusammen, ich mache seit acht Monaten eine Ausbildung zum Bankkaufmann und bin total frustriert.","exko":"안녕하세요, 여러분. 저는 여덟 달째 은행원 직업 교육을 받고 있는데 정말 답답해요."},{"de":"jemandem geht es genauso","ko":"~도 마찬가지이다, ~도 똑같은 처지였다","ex":"Mir ging es vor sechs Jahren genauso: Ich hatte eine Ausbildung zur Hotelfachfrau angefangen und mich durch Spätschichten an der Rezeption gequält.","exko":"저도 6년 전에 똑같았어요. 호텔리어 직업 교육을 시작했는데, 프런트의 늦은 교대 근무를 견디느라 괴로웠어요."},{"de":"etwas in der Tasche haben","ko":"~을 이미 확보해 두다","ex":"Ich hatte nämlich schon einen neuen Ausbildungsplatz in der Tasche, bevor ich gekündigt habe.","exko":"저는 그만두기 전에 이미 새 교육 자리를 구해 두었거든요."},{"de":"jemandem liegen","ko":"~에게 맞다, ~의 적성에 맞다","ex":"Dort siehst du die Gesellen an der Hobelbank arbeiten und merkst schnell, ob dir das Handwerk liegt.","exko":"그곳에서 숙련공들이 대패질 작업대에서 일하는 모습을 보면, 수공업 일이 자신에게 맞는지 금방 알 수 있어요."},{"de":"Lieber … als …","ko":"~보다 ~가 낫다","ex":"Ich höre ihn noch sagen: „Lieber jetzt ehrlich als in drei Jahren unglücklich.“","exko":"“3년 뒤에 불행한 것보다 지금 솔직한 게 나아요.”라고 하던 목소리가 아직도 귀에 생생해요."}],"words":345},{"id":"b1-21","level":"B1","no":21,"title":"Beschwerde über einen Sprachkurs","titleKo":"어학 강좌에 대한 항의","type":"Beschwerdebrief","typeKo":"항의 편지","intro":"수강한 영어 집중 강좌가 안내와 달라서 학원에 수강료 일부를 돌려 달라고 요구하는 편지예요.","focus":["da · nämlich","상태수동","darauf, dass","3격이 남는 수동태"],"paragraphs":[{"style":"meta","de":"An: Sprachschule Lingua Nord, Kundenservice","ko":"받는 사람: 링구아 노르트 어학원 고객 센터"},{"style":"meta","de":"Betreff: Beschwerde über den Intensivkurs „Englisch für den Beruf“ (3.–14. März)","ko":"제목: 집중 강좌 “직장인을 위한 영어”(3월 3일~14일)에 대한 항의"},{"style":"meta","de":"Sehr geehrte Damen und Herren,","ko":"담당자님께"},{"de":"vom 3. bis 14. März habe ich an Ihrer Sprachschule den Intensivkurs „Englisch für den Beruf“ besucht und dafür 480 Euro Kursgebühr bezahlt. Leider war ich mit dem Kurs sehr unzufrieden, da mehrere Leistungen nicht so erbracht wurden, wie sie auf Ihrer Internetseite und in der Anmeldebestätigung beschrieben sind.","ko":"저는 3월 3일부터 14일까지 귀 어학원에서 집중 강좌 “직장인을 위한 영어”를 수강했고, 수강료로 480유로를 냈습니다. 안타깝게도 저는 이 강좌에 매우 불만족스러웠습니다. 여러 서비스가 귀 학원 홈페이지와 등록 확인서에 설명된 대로 제공되지 않았기 때문입니다."},{"de":"Laut Ihrer Internetseite ist die Gruppengröße auf acht Personen begrenzt. Tatsächlich saßen wir zu fünfzehnt in einem kleinen Kursraum, sodass die meisten Teilnehmenden nur selten zu Wort kamen. Bereits am zweiten Kurstag habe ich im Sekretariat um eine Teilung der Gruppe gebeten. Obwohl mir eine schnelle Rückmeldung zugesagt wurde, habe ich bis heute keine erhalten.","ko":"귀 학원 홈페이지에 따르면 한 반의 인원은 여덟 명으로 제한되어 있습니다. 그런데 실제로는 열다섯 명이 작은 강의실에 앉아 있어서 수강생 대부분이 말할 기회를 거의 얻지 못했습니다. 저는 수업 둘째 날에 이미 사무실에 반을 나누어 달라고 요청했습니다. 빨리 답을 주겠다는 약속을 받았지만, 지금까지 아무 답도 받지 못했습니다."},{"de":"Außerdem wurde die Lehrkraft nach drei Kurstagen ausgetauscht. Die Vertretung war völlig unvorbereitet und wusste nicht einmal, welche Themen wir bereits behandelt hatten. Aus diesem Grund haben wir zwei Tage lang denselben Lernstoff wiederholt, was für alle Teilnehmenden verlorene Zeit war.","ko":"게다가 수업 사흘 만에 강사가 바뀌었습니다. 대신 온 강사는 전혀 준비가 되어 있지 않았고, 저희가 어떤 주제를 이미 다루었는지조차 몰랐습니다. 이런 이유로 저희는 이틀 동안 같은 학습 내용을 되풀이했고, 이것은 수강생 모두에게 시간 낭비였습니다."},{"de":"Auch beim Lehrbuch wurde die Vereinbarung nicht eingehalten. Laut Anmeldebestätigung ist es in der Kursgebühr enthalten, trotzdem musste ich es für 29 Euro selbst kaufen. Das Sprachlabor, das wir täglich eine Stunde nutzen sollten, war wegen einer technischen Störung die ganze erste Kurswoche geschlossen. Niemand konnte uns Auskunft darüber geben, wann es wieder geöffnet wird, und eine andere Übungsmöglichkeit wurde uns nicht angeboten.","ko":"교재에 관한 약속도 지켜지지 않았습니다. 등록 확인서에 따르면 교재는 수강료에 포함되어 있는데도, 저는 29유로를 내고 교재를 직접 사야 했습니다. 매일 한 시간씩 이용하기로 되어 있던 어학 실습실은 기술적인 고장 때문에 강좌 첫 주 내내 닫혀 있었습니다. 언제 다시 여는지 아무도 알려 주지 못했고, 다른 연습 방법도 제안받지 못했습니다."},{"de":"Den Kurs habe ich zur Vorbereitung auf eine neue Arbeitsstelle gebucht, die ich im April antrete. Dort brauche ich nämlich täglich Englisch. Ich habe mich darauf verlassen, dass die Angaben auf Ihrer Internetseite stimmen. Mein Ziel, sicherer Englisch zu sprechen, habe ich unter diesen Bedingungen jedoch nicht erreicht.","ko":"제가 이 강좌를 신청한 것은 4월에 일을 시작하는 새 직장을 준비하기 위해서였습니다. 그곳에서는 매일 영어를 써야 하기 때문입니다. 저는 귀 학원 홈페이지의 안내가 사실이라고 믿었습니다. 하지만 이런 조건에서는 영어를 더 자신 있게 말하겠다는 목표를 이루지 못했습니다."},{"de":"Da Ihre Sprachschule die vereinbarten Leistungen nur teilweise erbracht hat, bestehe ich darauf, dass Sie mir ein Drittel der Kursgebühr, also 160 Euro, sowie die 29 Euro für das Lehrbuch erstatten. Ich bitte um Überweisung des Gesamtbetrags auf mein Konto bis zum 4. April und um eine kurze Mitteilung, ob Sie mit dieser Regelung einverstanden sind. Andernfalls sehe ich mich gezwungen, die Verbraucherzentrale einzuschalten.","ko":"귀 학원이 약속한 서비스를 일부만 제공했으므로, 저는 수강료의 3분의 1인 160유로와 교재비 29유로를 환불해 주실 것을 분명히 요구합니다. 4월 4일까지 총액을 제 계좌로 송금해 주시고, 이렇게 처리하는 데 동의하시는지 짧게 알려 주시기 바랍니다. 그렇지 않으면 저는 소비자 센터에 이 일을 알리고 도움을 받을 수밖에 없습니다."},{"style":"meta","de":"Mit freundlichen Grüßen","ko":"안녕히 계십시오."},{"style":"meta","de":"Verena Stoll","ko":"페레나 슈톨"}],"questions":[{"type":"mc","kind":"gist","q":"Was möchte Frau Stoll mit ihrem Brief vor allem erreichen?","options":["Sie will einen Teil ihrer Kosten zurückbekommen.","Sie will den Kurs ohne weitere Kosten wiederholen.","Sie will die volle Kursgebühr zurückbekommen."],"answer":0,"evidence":"bestehe ich darauf, dass Sie mir ein Drittel der Kursgebühr, also 160 Euro, sowie die 29 Euro für das Lehrbuch erstatten","pairs":[["erstatten","zurückbekommen"],["ein Drittel der Kursgebühr","einen Teil ihrer Kosten"]],"explain":"슈톨 씨는 수강료의 3분의 1과 교재비를 돌려 달라고(erstatten) 요구해요. 이것을 einen Teil ihrer Kosten zurückbekommen(비용 일부를 돌려받다)으로 바꿔 말했어요. 수강료 전체 480유로를 돌려 달라는 것이 아니라 3분의 1(ein Drittel)인 160유로만 요구하고, 강좌를 다시 듣겠다는 말은 편지에 없어요."},{"type":"rf","kind":"detail","q":"Wegen des kleinen Kursraums wurde die Gruppe auf acht Personen begrenzt.","answer":1,"evidence":"Tatsächlich saßen wir zu fünfzehnt in einem kleinen Kursraum","pairs":[["ist die Gruppengröße auf acht Personen begrenzt","die Gruppe auf acht Personen begrenzt"],["zu fünfzehnt in einem kleinen Kursraum","Wegen des kleinen Kursraums"]],"explain":"여덟 명 제한은 홈페이지에 적힌 약속일 뿐이에요. 실제로는 열다섯 명(zu fünfzehnt)이 작은 강의실에 앉아 있었어요. 작은 강의실 때문에 인원을 여덟 명으로 줄였다는 말은 틀려요."},{"type":"mc","kind":"detail","q":"Wie reagierte die Schule auf Frau Stolls Bitte, die Gruppe zu teilen?","options":["Die Gruppe wurde kurz darauf in zwei Gruppen geteilt.","Man versprach ihr für die Gruppe einen größeren Raum.","Die versprochene Antwort ist bis heute ausgeblieben."],"answer":2,"evidence":"Obwohl mir eine schnelle Rückmeldung zugesagt wurde, habe ich bis heute keine erhalten.","pairs":[["zugesagt","versprochene"],["habe ich bis heute keine erhalten","ist bis heute ausgeblieben"]],"explain":"슈톨 씨는 빨리 답을 주겠다는 약속(zugesagt)을 받았지만 지금까지 답을 받지 못했어요. 이것을 '약속한 답이 오지 않았다(ausgeblieben)'로 바꿔 말했어요. 반은 나뉘지 않았고, 학원이 약속한 것도 더 큰 강의실이 아니라 빠른 답이었어요."},{"type":"mc","kind":"detail","q":"Warum hat die Gruppe zwei Tage lang denselben Stoff wiederholt?","options":["Die Teilnehmenden hatten die Themen noch nicht verstanden.","Die Vertretung kannte den bisherigen Kursverlauf nicht.","Die Vertretung wollte die Themen der ersten Tage vertiefen."],"answer":1,"evidence":"wusste nicht einmal, welche Themen wir bereits behandelt hatten","pairs":[["welche Themen wir bereits behandelt hatten","den bisherigen Kursverlauf"],["wusste nicht einmal","kannte"]],"explain":"대신 온 강사는 수강생들이 어떤 주제를 이미 다루었는지조차 몰랐어요. 그래서(Aus diesem Grund) 이틀 동안 같은 내용을 되풀이했어요. 이것을 '지금까지의 수업 진행(Kursverlauf)을 몰랐다'로 바꿔 말했어요. 수강생들이 이해하지 못했다는 말은 없어요. 대신 온 강사는 앞에서 다룬 주제를 몰랐으니 그 주제를 일부러 더 깊이 다루려 했다는 말도 틀려요."},{"type":"rf","kind":"detail","q":"Frau Stoll hat für ein Buch bezahlt, das eigentlich schon im Kurspreis inbegriffen war.","answer":0,"evidence":"Laut Anmeldebestätigung ist es in der Kursgebühr enthalten, trotzdem musste ich es für 29 Euro selbst kaufen.","pairs":[["in der Kursgebühr enthalten","im Kurspreis inbegriffen"],["für 29 Euro selbst kaufen","hat für ein Buch bezahlt"]],"explain":"등록 확인서에 따르면 교재는 수강료에 포함되어(enthalten) 있어요. 그런데도 슈톨 씨는 29유로를 내고 교재를 직접 샀어요. in der Kursgebühr enthalten을 im Kurspreis inbegriffen으로 바꿔 말했으니 맞는 말이에요."},{"type":"mc","kind":"paraphrase","q":"Was meint Frau Stoll mit dem Satz „Ich habe mich darauf verlassen, dass die Angaben auf Ihrer Internetseite stimmen“?","options":["Sie hat den Informationen der Schule vertraut.","Sie hatte schon vorher Zweifel an den Angaben.","Sie verlangt, dass die Internetseite korrigiert wird."],"answer":0,"evidence":"Ich habe mich darauf verlassen, dass die Angaben auf Ihrer Internetseite stimmen.","pairs":[["mich darauf verlassen","vertraut"],["die Angaben auf Ihrer Internetseite","den Informationen der Schule"]],"explain":"sich auf etwas verlassen은 '~을 믿다, ~에 기대다'라는 뜻이에요. 슈톨 씨는 홈페이지의 안내(Angaben)가 맞다고 믿고 강좌를 신청했어요. 처음부터 의심했다는 말은 반대 뜻이고, 홈페이지를 고쳐 달라는 요구는 편지에 없어요."},{"type":"mc","kind":"inference","q":"Welchen Betrag soll die Schule Frau Stoll insgesamt überweisen?","options":["160 €","480 €","189 €"],"answer":2,"evidence":"also 160 Euro, sowie die 29 Euro für das Lehrbuch erstatten","pairs":[["160 Euro, sowie die 29 Euro","189 €"]],"explain":"슈톨 씨는 수강료의 3분의 1인 160유로와 교재비 29유로를 돌려 달라고 하고, 이 총액(Gesamtbetrag)을 송금해 달라고 해요. 둘을 더하면 189유로예요. 160유로는 수강료 부분만이고, 480유로는 수강료 전체예요."},{"type":"mc","kind":"intent","q":"Warum erwähnt Frau Stoll am Ende die Verbraucherzentrale?","options":["Sie hat sich dort schon früher über den Intensivkurs beschwert.","Sie will die Schule unter Druck setzen, damit sie zahlt.","Sie möchte dort einen günstigeren Englischkurs finden."],"answer":1,"evidence":"Andernfalls sehe ich mich gezwungen, die Verbraucherzentrale einzuschalten.","pairs":[["Andernfalls sehe ich mich gezwungen","unter Druck setzen"]],"explain":"슈톨 씨는 학원이 요구를 받아들이지 않으면(Andernfalls) 소비자 센터에 이 일을 알릴(einschalten) 수밖에 없다고 해요. 소비자 센터를 언급해서 학원이 돈을 돌려주도록 압박하려는 거예요. 아직 소비자 센터에 항의한 것은 아니고, 그곳에서 새 강좌를 찾겠다는 말도 없어요."}],"grammar":[{"title":"이유를 말하는 da · nämlich · aus diesem Grund","term":"Kausale Verbindungen: da, nämlich, aus diesem Grund","explain":"da는 weil과 같은 뜻의 종속접속사로, 격식 있는 글에서 자주 써요. da절에서는 동사가 끝에 와요. da절이 문장 맨 앞에 오면 주절은 동사로 시작해요. nämlich는 접속사가 아니라 부사예요. 앞 문장의 이유를 덧붙이는 문장에서 동사 뒤 중간 자리에 놓아요. aus diesem Grund(이런 이유로)는 앞 문장의 내용을 원인으로 받아서 결과를 말해요. 문장 맨 앞에 자주 오고, 그러면 바로 뒤에 동사가 와요.","pattern":"…, da + 주어 … 동사(끝) · Da …, 동사 + 주어 … · 주어 + 동사 + nämlich … · Aus diesem Grund + 동사 + 주어 …","examples":[{"de":"Dort brauche ich nämlich täglich Englisch.","ko":"그곳에서는 매일 영어를 써야 하기 때문입니다.","mark":["nämlich"],"parts":[["Dort","부사어(장소)"],["brauche","동사"],["ich","주어"],["nämlich","부사어"],["täglich","부사어(빈도)"],["Englisch.","4격 목적어"]]},{"de":"Aus diesem Grund haben wir zwei Tage lang denselben Lernstoff wiederholt, was für alle Teilnehmenden verlorene Zeit war.","ko":"이런 이유로 저희는 이틀 동안 같은 학습 내용을 되풀이했고, 이것은 수강생 모두에게 시간 낭비였습니다.","mark":["Aus diesem Grund"],"parts":[["Aus diesem Grund","부사어(이유)"],["haben","동사"],["wir","주어"],["zwei Tage lang","부사어(시간)"],["denselben Lernstoff","4격 목적어"],["wiederholt,","동사(끝)"],["was für alle Teilnehmenden verlorene Zeit war.","관계절"]]},{"de":"Leider war ich mit dem Kurs sehr unzufrieden, da mehrere Leistungen nicht so erbracht wurden, wie sie auf Ihrer Internetseite und in der Anmeldebestätigung beschrieben sind.","ko":"안타깝게도 저는 이 강좌에 매우 불만족스러웠습니다. 여러 서비스가 귀 학원 홈페이지와 등록 확인서에 설명된 대로 제공되지 않았기 때문입니다.","mark":["da","erbracht wurden"]}],"tip":"nämlich는 문장 맨 앞에 올 수 없어요. Nämlich brauche ich …는 틀리고 Ich brauche nämlich …가 맞아요. nämlich 문장은 이유를 덧붙이는 문장이라서 앞 문장 뒤에 와요."},{"title":"상태수동: 이미 그렇게 되어 있는 상태","term":"Zustandspassiv (sein + Partizip II)","explain":"sein + 과거분사는 어떤 동작이 끝난 뒤에 남은 상태를 나타내요. 동작 자체를 말하는 수동태는 werden + 과거분사예요. Die Lehrkraft wurde ausgetauscht.는 강사를 바꾸는 동작이고, Das Sprachlabor war geschlossen.은 실습실이 닫혀 있던 상태예요. 지금의 상태는 ist/sind로, 과거의 상태는 war/waren으로 말해요.","pattern":"sein(변화형) + … + 과거분사(문장 끝) ↔ werden(변화형) + … + 과거분사(문장 끝)","examples":[{"de":"Laut Ihrer Internetseite ist die Gruppengröße auf acht Personen begrenzt.","ko":"귀 학원 홈페이지에 따르면 한 반의 인원은 여덟 명으로 제한되어 있습니다.","mark":["ist","begrenzt"],"parts":[["Laut Ihrer Internetseite","부사어"],["ist","동사"],["die Gruppengröße","주어"],["auf acht Personen","전치사 목적어"],["begrenzt.","동사(끝)"]]},{"de":"Das Sprachlabor, das wir täglich eine Stunde nutzen sollten, war wegen einer technischen Störung die ganze erste Kurswoche geschlossen.","ko":"매일 한 시간씩 이용하기로 되어 있던 어학 실습실은 기술적인 고장 때문에 강좌 첫 주 내내 닫혀 있었습니다.","mark":["war","geschlossen"]},{"de":"Außerdem wurde die Lehrkraft nach drei Kurstagen ausgetauscht.","ko":"게다가 수업 사흘 만에 강사가 바뀌었습니다.","mark":["wurde","ausgetauscht"]}],"tip":"한국어의 '~되어 있다'에 가까워요. 동작을 말하는 werden + 과거분사와 상태를 말하는 sein + 과거분사를 구별하세요."},{"title":"뒤에 오는 dass절을 미리 가리키는 darauf","term":"Präpositionaladverb als Korrelat: sich darauf verlassen, dass … / darauf bestehen, dass …","explain":"sich verlassen auf + 4격(~을 믿다), bestehen auf + 3격(~을 끝까지 요구하다)처럼 전치사와 함께 쓰는 동사 뒤에 명사 대신 문장이 올 때가 있어요. 이때 주절에 da(r) + 전치사, 곧 darauf를 먼저 쓰고 그 내용을 dass절로 이어요. darauf는 뒤에 오는 dass절의 내용을 가리켜요. dass절에서는 동사가 끝에 와요.","pattern":"주어 + 동사 + (재귀대명사) + darauf …, dass + 주어 … 동사(끝)","examples":[{"de":"Ich habe mich darauf verlassen, dass die Angaben auf Ihrer Internetseite stimmen.","ko":"저는 귀 학원 홈페이지의 안내가 사실이라고 믿었습니다.","mark":["darauf","dass"],"parts":[["Ich","주어"],["habe","동사"],["mich","재귀대명사"],["darauf","전치사 목적어"],["verlassen,","동사(끝)"],["dass die Angaben auf Ihrer Internetseite stimmen.","종속절"]]},{"de":"Da Ihre Sprachschule die vereinbarten Leistungen nur teilweise erbracht hat, bestehe ich darauf, dass Sie mir ein Drittel der Kursgebühr, also 160 Euro, sowie die 29 Euro für das Lehrbuch erstatten.","ko":"귀 학원이 약속한 서비스를 일부만 제공했으므로, 저는 수강료의 3분의 1인 160유로와 교재비 29유로를 환불해 주실 것을 분명히 요구합니다.","mark":["bestehe ich darauf","dass","erstatten"]}],"tip":"sich verlassen auf와 bestehen auf에서는 darauf를 빼면 틀려요. Ich habe mich verlassen, dass …가 아니라 Ich habe mich darauf verlassen, dass …라고 해요."},{"title":"3격이 남는 수동태: mir wurde … zugesagt","term":"Passiv mit Dativobjekt (mir wurde … zugesagt, uns wurde … angeboten)","explain":"zusagen(약속하다), anbieten(제안하다)처럼 3격과 4격을 함께 쓰는 동사를 수동태로 바꾸면 4격 목적어가 1격 주어가 되고, 3격은 그대로 3격으로 남아요. Man sagte mir eine Rückmeldung zu.는 수동태로 Mir wurde eine Rückmeldung zugesagt.가 돼요. werden의 형태는 1격 주어(eine Rückmeldung)에 맞춰요. 누가 약속했는지는 말하지 않아도 돼요.","pattern":"(접속사) + 3격 + 1격 주어 + 과거분사 + wurde · 1격 주어 + wurde + 3격 + … + 과거분사(끝)","examples":[{"de":"Obwohl mir eine schnelle Rückmeldung zugesagt wurde, habe ich bis heute keine erhalten.","ko":"빨리 답을 주겠다는 약속을 받았지만, 지금까지 아무 답도 받지 못했습니다.","mark":["mir","zugesagt wurde"],"parts":[["Obwohl","접속사"],["mir","3격 목적어"],["eine schnelle Rückmeldung","주어"],["zugesagt wurde,","동사(끝)"],["habe ich bis heute keine erhalten.","기타"]]},{"de":"Niemand konnte uns Auskunft darüber geben, wann es wieder geöffnet wird, und eine andere Übungsmöglichkeit wurde uns nicht angeboten.","ko":"언제 다시 여는지 아무도 알려 주지 못했고, 다른 연습 방법도 제안받지 못했습니다.","mark":["eine andere Übungsmöglichkeit","wurde uns","angeboten"],"parts":[["Niemand konnte uns Auskunft darüber geben, wann es wieder geöffnet wird,","기타"],["und","접속사"],["eine andere Übungsmöglichkeit","주어"],["wurde","동사"],["uns","3격 목적어"],["nicht","부정어"],["angeboten.","동사(끝)"]]}],"tip":"3격은 수동태의 주어가 되지 않아요. Ich wurde eine Rückmeldung zugesagt.는 틀리고 Mir wurde eine Rückmeldung zugesagt.가 맞아요."}],"vocab":[{"de":"unzufrieden (mit + Dat.)","ko":"불만족스러운"},{"de":"die Kursgebühr, -en","ko":"수강료"},{"de":"die Leistung, -en","ko":"(약속한) 서비스, 제공 내용"},{"de":"erbringen (erbringt, erbrachte, hat erbracht)","ko":"(서비스를) 제공하다, 이행하다"},{"de":"die Anmeldebestätigung, -en","ko":"등록 확인서"},{"de":"begrenzen auf + Akk.","ko":"~으로 제한하다"},{"de":"die Rückmeldung, -en","ko":"답변, 회신"},{"de":"zu|sagen + Dat. + Akk.","ko":"(~에게 ~을) 약속하다"},{"de":"die Lehrkraft, -¨e","ko":"강사, 교사"},{"de":"aus|tauschen","ko":"바꾸다, 교체하다"},{"de":"die Vertretung, -en","ko":"대신 온 사람, 대리 강사"},{"de":"unvorbereitet","ko":"준비가 안 된"},{"de":"die Störung, -en","ko":"고장, 장애"},{"de":"die Auskunft, -¨e","ko":"안내, 정보"},{"de":"erstatten","ko":"환불하다, 돌려주다"},{"de":"die Verbraucherzentrale, -n","ko":"소비자 센터"}],"phrases":[{"de":"zu Wort kommen","ko":"말할 기회를 얻다","ex":"Tatsächlich saßen wir zu fünfzehnt in einem kleinen Kursraum, sodass die meisten Teilnehmenden nur selten zu Wort kamen.","exko":"그런데 실제로는 열다섯 명이 작은 강의실에 앉아 있어서 수강생 대부분이 말할 기회를 거의 얻지 못했습니다."},{"de":"in etwas (Dat.) enthalten sein","ko":"~에 포함되어 있다","ex":"Laut Anmeldebestätigung ist es in der Kursgebühr enthalten, trotzdem musste ich es für 29 Euro selbst kaufen.","exko":"등록 확인서에 따르면 교재는 수강료에 포함되어 있는데도, 저는 29유로를 내고 교재를 직접 사야 했습니다."},{"de":"eine Vereinbarung ein|halten","ko":"약속(합의)을 지키다","ex":"Auch beim Lehrbuch wurde die Vereinbarung nicht eingehalten.","exko":"교재에 관한 약속도 지켜지지 않았습니다."},{"de":"eine Stelle an|treten","ko":"새 일자리에서 일을 시작하다","ex":"Den Kurs habe ich zur Vorbereitung auf eine neue Arbeitsstelle gebucht, die ich im April antrete.","exko":"제가 이 강좌를 신청한 것은 4월에 일을 시작하는 새 직장을 준비하기 위해서였습니다."},{"de":"sich gezwungen sehen, … zu …","ko":"~할 수밖에 없다","ex":"Andernfalls sehe ich mich gezwungen, die Verbraucherzentrale einzuschalten.","exko":"그렇지 않으면 저는 소비자 센터에 이 일을 알리고 도움을 받을 수밖에 없습니다."}],"words":347},{"id":"b1-22","level":"B1","no":22,"title":"Welcher Laptop passt zu mir?","titleKo":"어떤 노트북이 저한테 맞을까요?","type":"Beratungsgespräch","typeKo":"구매 상담 대화","intro":"대학생이 전자 제품 매장에서 점원과 상담하며 노트북을 고르는 대화예요.","focus":["화법 불변화사","als · wie 비교절","derselbe · dieselbe · dasselbe","alles, was · das, was"],"paragraphs":[{"label":"Verkäufer","de":"Guten Tag! Kann ich Ihnen weiterhelfen? Was für ein Gerät suchen Sie denn?","ko":"안녕하세요! 도와드릴까요? 어떤 기기를 찾으세요?"},{"label":"Kundin","de":"Ich brauche einen Laptop für mein Studium, denn der alte Rechner meines Bruders, den ich bisher benutzt habe, ist inzwischen viel zu langsam und stürzt ständig ab. Ich arbeite vor allem an Hausarbeiten und Präsentationen und nehme regelmäßig an Videokonferenzen teil. Mein Budget liegt eigentlich bei höchstens 700 Euro.","ko":"대학 공부에 쓸 노트북이 필요해요. 지금까지는 오빠가 쓰던 낡은 컴퓨터를 썼는데, 이제 너무 느리고 자꾸 멈춰 버리거든요. 저는 주로 과제 리포트와 발표 자료를 만들고, 화상 회의에도 자주 참여해요. 사실 예산은 많아야 700유로예요."},{"label":"Verkäufer","de":"Dann schauen Sie sich doch mal diese beiden Modelle an. Das linke ist mit 599 Euro günstiger und hat einen größeren Bildschirm mit hoher Auflösung, das rechte ist kompakter, kostet aber 749 Euro. Beide haben übrigens dieselbe Tastatur, denselben Arbeitsspeicher und dieselben Anschlüsse.","ko":"그럼 이 두 모델을 한번 보세요. 왼쪽 것은 599유로로 더 싸고 화면이 더 크고 해상도도 높아요. 오른쪽 것은 더 작지만 749유로예요. 참고로 둘 다 자판, 메모리, 연결 단자가 똑같아요."},{"label":"Kundin","de":"Oh, das kleinere ist ja viel leichter, als ich dachte! Aber warum ist es denn trotz des kleineren Bildschirms so viel teurer?","ko":"어, 작은 것이 생각했던 것보다 훨씬 가볍네요! 그런데 화면이 더 작은데도 왜 이렇게 훨씬 비싼가요?"},{"label":"Verkäufer","de":"Das kleinere wiegt nur 1,2 Kilogramm, und seine Akkulaufzeit beträgt ungefähr zwölf Stunden. Das größere ist dagegen beinahe ein Kilogramm schwerer und muss bereits nach sechs Stunden an die Steckdose. Die Rechenleistung ist allerdings identisch, denn in beiden steckt derselbe Prozessor.","ko":"작은 것은 무게가 1.2킬로그램밖에 안 되고, 배터리 사용 시간이 열두 시간쯤 돼요. 반면에 큰 것은 거의 1킬로그램 더 무겁고, 여섯 시간만 지나면 콘센트에 꽂아야 해요. 그래도 성능은 똑같아요. 둘 다 같은 프로세서가 들어 있거든요."},{"label":"Kundin","de":"Ich bin täglich mit dem Fahrrad unterwegs und arbeite oft stundenlang in der Universitätsbibliothek, wo es kaum freie Steckdosen gibt. Deshalb ist mir das Gewicht wichtiger als die Bildschirmgröße. Darf ich mal tippen? Die Tastatur fühlt sich angenehmer an, als sie aussieht. Aber 749 Euro sind deutlich mehr, als ich eingeplant habe.","ko":"저는 매일 자전거로 다니고, 대학 도서관에서 몇 시간씩 작업할 때가 많은데 그곳에는 빈 콘센트가 거의 없어요. 그래서 저한테는 화면 크기보다 무게가 더 중요해요. 한번 쳐 봐도 될까요? 자판이 보기보다 느낌이 좋네요. 하지만 749유로는 제가 잡아 둔 예산보다 꽤 많아요."},{"label":"Verkäufer","de":"Haben Sie eigentlich einen Studierendenausweis dabei? Damit bekommen Sie zehn Prozent Ermäßigung, und das Notebook kostet dann nur noch ungefähr 674 Euro.","ko":"혹시 학생증 가지고 계세요? 학생증이 있으면 10퍼센트 할인을 받을 수 있어서 이 노트북은 674유로쯤밖에 안 해요."},{"label":"Kundin","de":"Ja, den habe ich glücklicherweise dabei, und dann ist es ja nicht so teuer, wie ich befürchtet habe! Gibt es sonst noch etwas, was ich vor dem Kauf unbedingt beachten sollte?","ko":"네, 다행히 가지고 있어요. 그러면 걱정했던 것만큼 비싸지는 않네요! 사기 전에 꼭 알아 두어야 할 것이 또 있나요?"},{"label":"Verkäufer","de":"Sie bekommen eine zweijährige Herstellergarantie, und für 89 Euro können Sie eine Zusatzversicherung abschließen, die auch dann zahlt, wenn Ihnen das Notebook herunterfällt. Das ist alles, was ich Ihnen noch empfehlen würde.","ko":"2년짜리 제조사 보증이 붙고, 89유로를 내면 추가 보험에도 들 수 있어요. 이 보험은 노트북을 떨어뜨렸을 때도 보상해 줘요. 제가 더 권해 드릴 것은 이게 전부예요."},{"label":"Kundin","de":"Nein, danke, auf die Zusatzversicherung verzichte ich lieber, aber das, was Sie über die Akkulaufzeit erzählt haben, hat mich überzeugt. Ich nehme das kleinere – vielen Dank für die ausführliche Beratung!","ko":"아니요, 괜찮아요. 추가 보험은 들지 않을게요. 하지만 배터리 사용 시간에 대해 말씀해 주신 것을 듣고 마음을 정했어요. 작은 것으로 할게요. 자세히 설명해 주셔서 감사해요!"},{"label":"Verkäufer","de":"Gern, dann hole ich Ihnen mal dasselbe Modell originalverpackt aus unserem Lager.","ko":"네, 그럼 창고에서 같은 모델로 포장을 뜯지 않은 새 상품을 가져다 드릴게요."}],"questions":[{"type":"rf","kind":"detail","q":"Bisher hat die Kundin den Computer eines Familienmitglieds benutzt.","answer":0,"evidence":"der alte Rechner meines Bruders, den ich bisher benutzt habe","pairs":[["Rechner meines Bruders","Computer eines Familienmitglieds"]],"explain":"손님은 지금까지 오빠가 쓰던 낡은 컴퓨터를 썼어요. Rechner meines Bruders(오빠의 컴퓨터)를 Computer eines Familienmitglieds(가족 한 사람의 컴퓨터)로 바꿔 말했으니 맞는 말이에요."},{"type":"mc","kind":"detail","q":"Was erfährt die Kundin über die beiden Modelle?","options":["Das kleinere hat weniger Anschlüsse als das größere.","Das kleinere arbeitet genauso schnell wie das größere.","Das größere hat mehr Arbeitsspeicher als das kleinere."],"answer":1,"evidence":"Die Rechenleistung ist allerdings identisch, denn in beiden steckt derselbe Prozessor.","pairs":[["Die Rechenleistung ist allerdings identisch","arbeitet genauso schnell"]],"explain":"점원은 두 모델에 같은 프로세서가 들어 있어서 성능(Rechenleistung)이 똑같다(identisch)고 해요. 이것을 '작은 것도 큰 것만큼 빠르게 작동한다(genauso schnell)'로 바꿔 말했어요. 점원은 연결 단자(Anschlüsse)와 메모리(Arbeitsspeicher)도 두 모델이 똑같다고 했으니, 작은 것의 단자가 더 적다거나 큰 것의 메모리가 더 많다는 말은 틀려요."},{"type":"mc","kind":"detail","q":"Warum kostet das kleinere Modell mehr?","options":["Es ist leichter, und sein Akku hält länger.","Es hat einen schnelleren Prozessor als das linke.","Es hat eine angenehmere Tastatur als das große."],"answer":0,"evidence":"Das kleinere wiegt nur 1,2 Kilogramm, und seine Akkulaufzeit beträgt ungefähr zwölf Stunden.","pairs":[["wiegt nur 1,2 Kilogramm","leichter"],["seine Akkulaufzeit beträgt ungefähr zwölf Stunden","sein Akku hält länger"]],"explain":"손님이 왜 더 비싼지 묻자 점원은 작은 모델이 1.2킬로그램밖에 안 되고 배터리가 열두 시간쯤 간다고 대답해요. 더 가볍고 배터리가 더 오래간다는 뜻이에요. 프로세서와 자판은 두 모델이 똑같아요."},{"type":"rf","kind":"detail","q":"Ein großer Bildschirm ist der Kundin wichtiger als ein geringes Gewicht.","answer":1,"evidence":"Deshalb ist mir das Gewicht wichtiger als die Bildschirmgröße.","pairs":[["das Gewicht wichtiger als die Bildschirmgröße","Ein großer Bildschirm ist der Kundin wichtiger"]],"explain":"손님은 화면 크기보다 무게가 더 중요하다고 해요. 문제의 문장은 둘의 순서를 뒤바꿨어요."},{"type":"mc","kind":"paraphrase","q":"Was meint die Kundin mit dem Satz „dann ist es ja nicht so teuer, wie ich befürchtet habe“?","options":["Sie hatte mit einem niedrigeren Preis gerechnet.","Sie findet das Notebook immer noch zu teuer.","Sie hatte mit einem höheren Preis gerechnet."],"answer":2,"evidence":"dann ist es ja nicht so teuer, wie ich befürchtet habe","pairs":[["nicht so teuer, wie ich befürchtet habe","mit einem höheren Preis gerechnet"]],"explain":"nicht so teuer, wie ich befürchtet habe는 '걱정했던 것만큼 비싸지 않다'는 뜻이에요. 손님은 더 비쌀 거라고 걱정했는데, 학생 할인을 받으면 674유로쯤이 되는 거예요. 그래서 더 높은 가격을 예상했다는 말이 맞아요. 더 싼 값을 예상했다는 말과 지금도 너무 비싸다고 생각한다는 말은 반대예요."},{"type":"mc","kind":"inference","q":"Wie viel bezahlt die Kundin am Ende ungefähr?","options":["674 €","749 €","763 €"],"answer":0,"evidence":"Nein, danke, auf die Zusatzversicherung verzichte ich lieber","pairs":[["nur noch ungefähr 674 Euro","674 €"]],"explain":"학생 할인을 받으면 작은 노트북은 674유로쯤이에요. 손님은 89유로짜리 추가 보험을 들지 않기로 했으니까(verzichte) 값이 더 올라가지 않아요. 749유로는 할인 전 가격이고, 763유로는 보험까지 더한 가격이에요."},{"type":"mc","kind":"inference","q":"Warum ist eine lange Akkulaufzeit für die Kundin besonders wichtig?","options":["Bei ihr zu Hause gibt es keine freie Steckdose.","Sie kann den Akku in der Bibliothek selten laden.","In der Bibliothek ist das Laden von Geräten verboten."],"answer":1,"evidence":"wo es kaum freie Steckdosen gibt","pairs":[["kaum freie Steckdosen","selten laden"]],"explain":"손님은 대학 도서관에서 몇 시간씩 작업하는데 그곳에는 빈 콘센트가 거의 없다고 해요. 그래서 충전하지 않고 오래 쓸 수 있는 배터리가 중요해요. 콘센트가 부족한 곳은 집이 아니라 도서관이고, 충전이 금지되어 있다는 말은 없어요."},{"type":"mc","kind":"detail","q":"Was macht der Verkäufer am Schluss?","options":["Er verpackt das Gerät, das sie getestet hat.","Er bestellt dasselbe Modell beim Hersteller.","Er bringt ihr ein unbenutztes Exemplar."],"answer":2,"evidence":"dann hole ich Ihnen mal dasselbe Modell originalverpackt aus unserem Lager","pairs":[["dasselbe Modell originalverpackt","ein unbenutztes Exemplar"]],"explain":"점원은 창고에서 같은 모델을 원래 포장 그대로(originalverpackt) 가져오겠다고 해요. 아직 아무도 쓰지 않은 새 상품이라는 뜻이에요. 손님이 쳐 본 기기를 포장해 주는 것이 아니고, 제조사에 주문하는 것도 아니에요."}],"grammar":[{"title":"화법 불변화사 doch · mal · ja · denn · eigentlich","term":"Modalpartikeln","explain":"화법 불변화사는 말하는 사람의 태도를 담는 짧은 말이에요. 문장의 내용은 거의 바꾸지 않고 말투를 부드럽게 하거나 느낌을 더해요. 질문의 denn은 관심을 담고, 권유의 doch mal은 제안을 부드럽게 해요. 평서문의 ja는 이 대화에서처럼 놀람을 나타내거나 상대도 아는 사실을 가리키고, 질문의 eigentlich는 '그런데 혹시'처럼 화제를 살짝 바꿀 때 써요. 보통 강세 없이 문장 가운데에 와요.","pattern":"동사 + (주어) + 불변화사 + …","examples":[{"de":"Was für ein Gerät suchen Sie denn?","ko":"어떤 기기를 찾으세요?","mark":["denn"],"parts":[["Was für ein Gerät","4격 목적어"],["suchen","동사"],["Sie","주어"],["denn?","기타"]]},{"de":"Dann schauen Sie sich doch mal diese beiden Modelle an.","ko":"그럼 이 두 모델을 한번 보세요.","mark":["doch mal"],"parts":[["Dann","부사어"],["schauen","동사"],["Sie","주어"],["sich","재귀대명사"],["doch mal","기타"],["diese beiden Modelle","4격 목적어"],["an.","동사(끝)"]]},{"de":"Oh, das kleinere ist ja viel leichter, als ich dachte!","ko":"어, 작은 것이 생각했던 것보다 훨씬 가볍네요!","mark":["ja"]},{"de":"Haben Sie eigentlich einen Studierendenausweis dabei?","ko":"혹시 학생증 가지고 계세요?","mark":["eigentlich"]}],"tip":"화법 불변화사로 쓸 때는 문장 맨 앞(1번 자리)에 오지 않아요. Doch schauen Sie …가 아니라 Schauen Sie doch …라고 해요."},{"title":"als · wie가 이끄는 비교절","term":"Vergleichssätze mit als / wie + Nebensatz","explain":"비교급 뒤에서는 als를, (nicht) so + 형용사 뒤에서는 wie를 써요. 비교하는 대상이 문장일 때 als나 wie 뒤는 종속절이 되어 동사가 끝에 와요. 종속절 앞에는 쉼표를 찍어요. 비교 대상이 명사 하나일 때는 종속절이 아니라서 쉼표 없이 써요(wichtiger als die Bildschirmgröße).","pattern":"비교급 + , als + 주어 … 동사(끝) · (nicht) so + 형용사 + , wie + 주어 … 동사(끝)","examples":[{"de":"Aber 749 Euro sind deutlich mehr, als ich eingeplant habe.","ko":"하지만 749유로는 제가 잡아 둔 예산보다 꽤 많아요.","mark":["mehr, als","eingeplant habe"],"parts":[["Aber","접속사"],["749 Euro","주어"],["sind","동사"],["deutlich mehr,","보어"],["als ich eingeplant habe.","종속절"]]},{"de":"Die Tastatur fühlt sich angenehmer an, als sie aussieht.","ko":"자판이 보기보다 느낌이 좋네요.","mark":["angenehmer","als sie aussieht"]},{"de":"Ja, den habe ich glücklicherweise dabei, und dann ist es ja nicht so teuer, wie ich befürchtet habe!","ko":"네, 다행히 가지고 있어요. 그러면 걱정했던 것만큼 비싸지는 않네요!","mark":["nicht so teuer, wie","befürchtet habe"]}],"tip":"nicht so … wie는 '~만큼 ~하지 않다'라는 뜻이에요. nicht so teuer, wie ich befürchtet habe는 걱정했던 것보다 덜 비싸다는 뜻이에요."},{"title":"derselbe · dieselbe · dasselbe: 똑같은 그것","term":"Demonstrativpronomen derselbe, dieselbe, dasselbe","explain":"derselbe는 '똑같은 바로 그 ~'라는 뜻이에요. 앞부분 der-/die-/das-는 정관사처럼, 뒷부분 -selbe는 정관사 뒤의 형용사처럼 변하고, 한 단어로 붙여 써요. 남성 4격은 denselben(denselben Arbeitsspeicher), 복수는 dieselben(dieselben Anschlüsse)이에요.","pattern":"derselbe Prozessor · dieselbe Tastatur · dasselbe Modell · denselben Arbeitsspeicher(4격) · dieselben Anschlüsse(복수)","examples":[{"de":"Beide haben übrigens dieselbe Tastatur, denselben Arbeitsspeicher und dieselben Anschlüsse.","ko":"참고로 둘 다 자판, 메모리, 연결 단자가 똑같아요.","mark":["dieselbe","denselben","dieselben"],"parts":[["Beide","주어"],["haben","동사"],["übrigens","부사어"],["dieselbe Tastatur, denselben Arbeitsspeicher und dieselben Anschlüsse.","4격 목적어"]]},{"de":"Die Rechenleistung ist allerdings identisch, denn in beiden steckt derselbe Prozessor.","ko":"그래도 성능은 똑같아요. 둘 다 같은 프로세서가 들어 있거든요.","mark":["derselbe"]},{"de":"Gern, dann hole ich Ihnen mal dasselbe Modell originalverpackt aus unserem Lager.","ko":"네, 그럼 창고에서 같은 모델로 포장을 뜯지 않은 새 상품을 가져다 드릴게요.","mark":["dasselbe"]}],"tip":"엄밀히 말하면 derselbe는 바로 그 하나가 같다는 뜻이고, der gleiche는 종류가 같은 다른 물건을 가리켜요. 이 대화의 dieselbe Tastatur, derselbe Prozessor처럼 같은 모델을 말할 때는 일상에서 derselbe도 많이 써요."},{"title":"alles, was · etwas, was · das, was","term":"Relativsätze mit was (nach alles, etwas, nichts, das)","explain":"alles, etwas, nichts, das처럼 정해지지 않은 것이나 어떤 내용 전체를 가리키는 말 뒤에서는 관계대명사로 was를 써요. was가 이끄는 관계절에서도 동사는 끝에 와요. das, was …는 '~한 것'이라는 뜻이고, 이 덩어리가 주절의 주어나 목적어가 돼요.","pattern":"alles / etwas / nichts / das + , was + … 동사(끝)","examples":[{"de":"Das ist alles, was ich Ihnen noch empfehlen würde.","ko":"제가 더 권해 드릴 것은 이게 전부예요.","mark":["alles, was"],"parts":[["Das","주어"],["ist","동사"],["alles,","보어"],["was ich Ihnen noch empfehlen würde.","관계절"]]},{"de":"Gibt es sonst noch etwas, was ich vor dem Kauf unbedingt beachten sollte?","ko":"사기 전에 꼭 알아 두어야 할 것이 또 있나요?","mark":["etwas, was"]},{"de":"Nein, danke, auf die Zusatzversicherung verzichte ich lieber, aber das, was Sie über die Akkulaufzeit erzählt haben, hat mich überzeugt.","ko":"아니요, 괜찮아요. 추가 보험은 들지 않을게요. 하지만 배터리 사용 시간에 대해 말씀해 주신 것을 듣고 마음을 정했어요.","mark":["das, was"]}],"tip":"명사 뒤에서는 was가 아니라 der·die·das를 써요. das Modell, das ich nehme가 맞고, das Modell, was ich nehme는 표준어에서 틀린 형태예요."}],"vocab":[{"de":"der Rechner, -","ko":"컴퓨터"},{"de":"ab|stürzen (ist abgestürzt)","ko":"(컴퓨터가) 멈추다, 다운되다"},{"de":"die Hausarbeit, -en","ko":"(대학의) 과제 리포트"},{"de":"das Budget, -s","ko":"예산"},{"de":"die Auflösung, -en","ko":"(화면의) 해상도"},{"de":"kompakt","ko":"작고 간편한"},{"de":"der Arbeitsspeicher, -","ko":"(컴퓨터의) 메모리"},{"de":"der Anschluss, -¨e","ko":"연결 단자"},{"de":"wiegen (wiegt, wog, hat gewogen)","ko":"무게가 ~이다"},{"de":"die Akkulaufzeit, -en","ko":"배터리 사용 시간"},{"de":"die Rechenleistung, -en","ko":"(컴퓨터의) 성능"},{"de":"identisch","ko":"똑같은"},{"de":"ein|planen","ko":"(예산·계획에) 넣어 두다"},{"de":"die Ermäßigung, -en","ko":"할인"},{"de":"befürchten","ko":"걱정하다, 염려하다"},{"de":"verzichten auf + Akk.","ko":"~을 하지 않기로 하다, ~ 없이 지내다"}],"phrases":[{"de":"vor allem","ko":"주로, 무엇보다","ex":"Ich arbeite vor allem an Hausarbeiten und Präsentationen und nehme regelmäßig an Videokonferenzen teil.","exko":"저는 주로 과제 리포트와 발표 자료를 만들고, 화상 회의에도 자주 참여해요."},{"de":"sich etwas an|schauen","ko":"~을 살펴보다","ex":"Dann schauen Sie sich doch mal diese beiden Modelle an.","exko":"그럼 이 두 모델을 한번 보세요."},{"de":"an die Steckdose müssen","ko":"(기기를) 충전해야 하다","ex":"Das größere ist dagegen beinahe ein Kilogramm schwerer und muss bereits nach sechs Stunden an die Steckdose.","exko":"반면에 큰 것은 거의 1킬로그램 더 무겁고, 여섯 시간만 지나면 콘센트에 꽂아야 해요."},{"de":"unterwegs sein","ko":"이동 중이다, 돌아다니다","ex":"Ich bin täglich mit dem Fahrrad unterwegs und arbeite oft stundenlang in der Universitätsbibliothek, wo es kaum freie Steckdosen gibt.","exko":"저는 매일 자전거로 다니고, 대학 도서관에서 몇 시간씩 작업할 때가 많은데 그곳에는 빈 콘센트가 거의 없어요."},{"de":"eine Versicherung ab|schließen","ko":"보험에 들다","ex":"Sie bekommen eine zweijährige Herstellergarantie, und für 89 Euro können Sie eine Zusatzversicherung abschließen, die auch dann zahlt, wenn Ihnen das Notebook herunterfällt.","exko":"2년짜리 제조사 보증이 붙고, 89유로를 내면 추가 보험에도 들 수 있어요. 이 보험은 노트북을 떨어뜨렸을 때도 보상해 줘요."}],"words":348},{"id":"b1-23","level":"B1","no":23,"title":"Wer kocht heute noch selbst?","titleKo":"요즘 누가 직접 요리할까요?","type":"Text zu einer Infografik","typeKo":"설문 그래프 설명글","intro":"한 도시 주민 1,000명에게 집에서 얼마나 자주 요리하는지 물은 설문 결과를 정리한 글이에요.","focus":["비율 표현","대조 표현","형용사의 명사화","steigen · sinken"],"paragraphs":[{"de":"Wie oft steht in Marlenburg noch jemand am Herd? Das wollte unser Magazin wissen und hat im Frühjahr 1.000 Einwohnerinnen und Einwohner nach ihren Kochgewohnheiten befragt. Die Infografik auf dieser Seite zeigt die wichtigsten Ergebnisse der Umfrage.","ko":"마를렌부르크에서는 아직 얼마나 자주 직접 요리를 할까요? 본지는 이것이 궁금해서 올봄에 주민 1,000명에게 요리 습관을 물었습니다. 이 면의 인포그래픽은 설문의 가장 중요한 결과를 보여 줍니다."},{"de":"Nur noch 38 Prozent der Befragten bereiten jeden Tag selbst eine Mahlzeit zu. Vor zehn Jahren war es bei einer vergleichbaren Befragung noch gut die Hälfte, nämlich 51 Prozent. Der Anteil derjenigen, die täglich kochen, ist also um 13 Prozentpunkte gesunken. Rund ein Drittel kocht mehrmals pro Woche, während 28 Prozent selten oder nie am Herd stehen. Zusammengenommen sind das fast zwei Drittel, die nicht mehr täglich kochen.","ko":"응답자 가운데 매일 직접 식사를 준비하는 사람은 이제 38퍼센트뿐입니다. 10년 전 비슷한 조사에서는 절반이 조금 넘는 51퍼센트였습니다. 그러니까 매일 요리하는 사람의 비율이 13퍼센트포인트 줄어든 것입니다. 약 3분의 1은 일주일에 여러 번 요리하는 반면, 28퍼센트는 요리하는 일이 드물거나 전혀 없습니다. 이 둘을 합치면 매일 요리하지는 않는 사람이 거의 3분의 2에 이릅니다."},{"de":"Besonders groß ist der Unterschied zwischen den Generationen. Bei den über 60-Jährigen bereitet mehr als die Hälfte täglich eine warme Mahlzeit zu. Bei den 18- bis 29-Jährigen ist es dagegen nur jeder Fünfte. Während die Älteren das Kochen meist als festen Bestandteil ihres Alltags sehen, fehlt den Jüngeren dafür nach eigenen Angaben oft die Zeit.","ko":"세대 사이의 차이가 특히 큽니다. 60세가 넘은 사람들은 절반 이상이 매일 따뜻한 식사를 준비합니다. 반면 18세에서 29세 사이에서는 다섯 명 중 한 명뿐입니다. 나이 든 사람들은 요리를 대개 일상의 당연한 일부로 여기지만, 젊은 사람들은 본인들 말로는 요리할 시간이 없는 경우가 많습니다."},{"de":"Warum bleibt die Küche kalt? Zwei Drittel der Berufstätigen geben an, dass sie nach Feierabend zu müde zum Kochen sind. Jeder dritte Alleinlebende ist zudem der Meinung, dass sich der Aufwand für eine einzige Person nicht lohnt. Gleichzeitig gewinnen Lieferdienste an Bedeutung: Der Anteil der Menschen, die sich mindestens einmal pro Woche Mahlzeiten nach Hause liefern lassen, ist innerhalb eines Jahrzehnts von 9 auf 27 Prozent gestiegen.","ko":"왜 부엌에서 요리를 하지 않을까요? 직장인의 3분의 2는 퇴근하고 나면 요리하기에는 너무 피곤하다고 답합니다. 혼자 사는 사람 세 명 중 한 명은 또 한 사람만을 위해 그런 수고를 들일 만하지 않다고 생각합니다. 동시에 배달 서비스가 점점 더 중요해지고 있습니다. 일주일에 한 번 이상 음식을 집으로 배달시키는 사람의 비율은 10년 사이에 9퍼센트에서 27퍼센트로 늘었습니다."},{"de":"Eine Zahl hat die Redaktion allerdings überrascht: Im Vergleich zu den Älteren kochen die Jüngeren zwar seltener, aber deutlich häufiger in Gesellschaft. 45 Prozent der unter 30-Jährigen treffen sich am Wochenende im Freundeskreis zum gemeinsamen Kochen, während es bei den über 60-Jährigen nur 12 Prozent sind.","ko":"그런데 편집부를 놀라게 한 숫자가 하나 있습니다. 젊은 사람들은 나이 든 사람들에 비해 요리를 덜 하지만, 다른 사람과 함께 요리하는 일은 훨씬 많습니다. 30세 미만의 45퍼센트는 주말에 친구들과 만나 함께 요리하는 반면, 60세가 넘은 사람들 가운데서는 12퍼센트뿐입니다."},{"de":"Die Ernährungsberaterin Carmen Ebert wundert diese Entwicklung nicht. „Für viele Jüngere ist Kochen keine tägliche Pflicht mehr, sondern ein geselliges Erlebnis“, sagt sie. „Wer unter der Woche keine Zeit hat, sollte am Sonntag gleich mehrere Portionen vorkochen. Das spart Geld und ist in der Regel gesünder als die meisten Fertiggerichte.“","ko":"영양 상담사 카르멘 에베르트는 이런 변화가 놀랍지 않다고 합니다. “많은 젊은이에게 요리는 이제 매일 해야 하는 의무가 아니라 사람들과 어울리는 즐거운 경험이에요.” 에베르트는 이렇게 말합니다. “평일에 시간이 없는 사람은 일요일에 한꺼번에 여러 끼니를 미리 만들어 두는 것이 좋아요. 돈도 아끼고, 대체로 대부분의 즉석식품보다 건강에도 좋아요.”"}],"questions":[{"type":"mc","kind":"gist","q":"Welche Entwicklung beschreibt der Artikel vor allem?","options":["Heute kochen mehr Menschen täglich als vor zehn Jahren.","Die Jüngeren kochen häufiger als die ältere Generation.","Für immer weniger Leute gehört Kochen zum Tagesablauf."],"answer":2,"evidence":"Nur noch 38 Prozent der Befragten bereiten jeden Tag selbst eine Mahlzeit zu.","pairs":[["Nur noch 38 Prozent","immer weniger Leute"],["jeden Tag selbst eine Mahlzeit zu","Kochen zum Tagesablauf"]],"explain":"매일 직접 요리하는 사람은 10년 전 51퍼센트에서 지금 38퍼센트로 줄었어요. 그래서 '요리가 하루 일과에 들어 있는 사람이 점점 줄고 있다'가 전체 내용을 가장 잘 나타내요. 매일 요리하는 사람이 늘었다는 말은 반대예요. 젊은 사람들은 나이 든 사람들보다 요리를 덜 하고, 함께 요리하는 일만 더 많아요."},{"type":"rf","kind":"detail","q":"Zehn Jahre zuvor hat noch etwas mehr als jeder Zweite jeden Tag gekocht.","answer":0,"evidence":"Vor zehn Jahren war es bei einer vergleichbaren Befragung noch gut die Hälfte, nämlich 51 Prozent.","pairs":[["gut die Hälfte","etwas mehr als jeder Zweite"],["Vor zehn Jahren","Zehn Jahre zuvor"]],"explain":"10년 전 비슷한 조사에서는 51퍼센트가 매일 요리했어요. gut die Hälfte는 '절반이 조금 넘는다'는 뜻이고, 이것을 '두 명 중 한 명보다 조금 많다(etwas mehr als jeder Zweite)'로 바꿔 말했으니 맞는 말이에요."},{"type":"mc","kind":"inference","q":"Wie groß ist der Anteil der Befragten, die selten oder nie kochen?","options":["knapp zwei Drittel","gut ein Viertel","rund ein Drittel"],"answer":1,"evidence":"während 28 Prozent selten oder nie am Herd stehen","pairs":[["28 Prozent","gut ein Viertel"]],"explain":"요리를 거의 하지 않거나 전혀 하지 않는 사람은 28퍼센트예요. 4분의 1은 25퍼센트니까 28퍼센트는 4분의 1이 조금 넘어요(gut ein Viertel). rund ein Drittel은 일주일에 여러 번 요리하는 사람이고, 거의 3분의 2는 매일 요리하지 않는 사람 전체예요."},{"type":"mc","kind":"detail","q":"Was unterscheidet die über 60-Jährigen von den 18- bis 29-Jährigen?","options":["Bei ihnen kocht die Mehrheit jeden Tag warm.","Bei ihnen kocht nur einer von fünf täglich.","Ihnen fehlt für das Kochen meistens die Zeit."],"answer":0,"evidence":"Bei den über 60-Jährigen bereitet mehr als die Hälfte täglich eine warme Mahlzeit zu.","pairs":[["mehr als die Hälfte","die Mehrheit"],["täglich eine warme Mahlzeit","jeden Tag warm"]],"explain":"60세가 넘은 사람들은 절반 이상이 매일 따뜻한 식사를 준비해요. mehr als die Hälfte(절반 이상)를 die Mehrheit(다수)로 바꿔 말했어요. 다섯 명 중 한 명만 매일 요리하고 시간이 부족하다고 말하는 쪽은 젊은 사람들이에요."},{"type":"rf","kind":"detail","q":"Viele Berufstätige haben abends keine Energie mehr zum Kochen.","answer":0,"evidence":"Zwei Drittel der Berufstätigen geben an, dass sie nach Feierabend zu müde zum Kochen sind.","pairs":[["nach Feierabend zu müde","abends keine Energie mehr"]],"explain":"직장인의 3분의 2는 퇴근하고 나면(nach Feierabend) 요리하기에는 너무 피곤하다고 답해요. 이것을 '저녁에 요리할 기운이 없다'로 바꿔 말했으니 맞는 말이에요."},{"type":"mc","kind":"meaning","q":"Was bedeutet die Frage „Warum bleibt die Küche kalt?“ im Text?","options":["Warum heizen so viele Leute ihre Küche nicht?","Warum essen so viele Leute lieber kalte Speisen?","Warum wird in vielen Haushalten nicht gekocht?"],"answer":2,"evidence":"Warum bleibt die Küche kalt?","pairs":[["die Küche kalt","nicht gekocht"]],"explain":"불을 쓰지 않으면 부엌이 차가워요. 그래서 die Küche bleibt kalt는 '집에서 요리를 하지 않는다'는 뜻이에요. 바로 뒤에 너무 피곤하다, 혼자라서 수고할 만하지 않다처럼 요리하지 않는 이유가 이어져요. 난방이나 찬 음식을 말하는 것이 아니에요."},{"type":"mc","kind":"inference","q":"Was hat sich bei den Essenslieferungen verändert?","options":["Dreimal so viele Leute lassen sich wöchentlich beliefern.","Etwa neun Prozent bestellen heute seltener als früher.","Jeder Zweite lässt sich inzwischen jede Woche Essen bringen."],"answer":0,"evidence":"ist innerhalb eines Jahrzehnts von 9 auf 27 Prozent gestiegen","pairs":[["von 9 auf 27 Prozent gestiegen","Dreimal so viele Leute"]],"explain":"일주일에 한 번 이상 음식을 배달시키는 사람의 비율이 10년 사이에 9퍼센트에서 27퍼센트로 늘었어요. 27은 9의 세 배예요. 두 명 중 한 명이면 50퍼센트라서 맞지 않고, 9퍼센트는 예전의 비율이에요."},{"type":"mc","kind":"detail","q":"Was rät Carmen Ebert Menschen mit wenig Zeit?","options":["Sie sollen öfter gesündere Fertiggerichte kaufen.","Sie sollen an ihrem freien Tag auf Vorrat kochen.","Sie sollen sich sonntags Essen liefern lassen."],"answer":1,"evidence":"Wer unter der Woche keine Zeit hat, sollte am Sonntag gleich mehrere Portionen vorkochen.","pairs":[["am Sonntag gleich mehrere Portionen vorkochen","an ihrem freien Tag auf Vorrat kochen"]],"explain":"에베르트는 평일에 시간이 없으면 일요일에 여러 끼니를 미리 만들어 두라고 권해요. 평일에 바쁜 사람에게 일요일(am Sonntag)은 쉬는 날이에요. 그래서 an ihrem freien Tag로 바꿔 말했고, mehrere Portionen vorkochen(여러 끼니를 미리 만들다)은 auf Vorrat kochen(넉넉히 만들어 두다)으로 바꿔 말했어요. 에베르트는 직접 만든 음식이 대부분의 즉석식품보다 건강에 좋다고 하고, 배달을 권하지는 않아요."}],"grammar":[{"title":"비율 표현","term":"Anteile angeben (die Hälfte, ein Drittel, jeder Fünfte)","explain":"비율은 퍼센트 말고도 분수나 jeder + 서수로 말할 수 있어요. die Hälfte는 절반, ein Drittel은 3분의 1, zwei Drittel은 3분의 2, ein Viertel은 4분의 1, jeder Fünfte는 다섯 명 중 한 명이에요. 앞에 gut(조금 넘게), knapp·fast(조금 못 되게), rund(약)를 붙여 어림수를 말해요. 누구의 비율인지는 뒤에 2격으로 써요(zwei Drittel der Berufstätigen).","pattern":"(gut / knapp / fast / rund) + die Hälfte / ein Drittel / zwei Drittel + 2격 · jeder + 서수","examples":[{"de":"Zwei Drittel der Berufstätigen geben an, dass sie nach Feierabend zu müde zum Kochen sind.","ko":"직장인의 3분의 2는 퇴근하고 나면 요리하기에는 너무 피곤하다고 답합니다.","mark":["Zwei Drittel der Berufstätigen"],"parts":[["Zwei Drittel der Berufstätigen","주어"],["geben","동사"],["an,","동사(끝)"],["dass sie nach Feierabend zu müde zum Kochen sind.","종속절"]]},{"de":"Vor zehn Jahren war es bei einer vergleichbaren Befragung noch gut die Hälfte, nämlich 51 Prozent.","ko":"10년 전 비슷한 조사에서는 절반이 조금 넘는 51퍼센트였습니다.","mark":["gut die Hälfte"]},{"de":"Zusammengenommen sind das fast zwei Drittel, die nicht mehr täglich kochen.","ko":"이 둘을 합치면 매일 요리하지는 않는 사람이 거의 3분의 2에 이릅니다.","mark":["fast zwei Drittel"]},{"de":"Jeder dritte Alleinlebende ist zudem der Meinung, dass sich der Aufwand für eine einzige Person nicht lohnt.","ko":"혼자 사는 사람 세 명 중 한 명은 또 한 사람만을 위해 그런 수고를 들일 만하지 않다고 생각합니다.","mark":["Jeder dritte"]}],"tip":"ein Drittel이 주어이면 동사는 단수를 써요(Rund ein Drittel kocht …). zwei Drittel이 주어일 때는 보통 복수 동사를 써요(Zwei Drittel … geben an)."},{"title":"대조 표현","term":"Gegensätze ausdrücken: während, dagegen, im Vergleich zu","explain":"두 집단이나 두 사실의 차이를 말할 때 쓰는 표현이에요. während는 '~하는 반면'이라는 뜻의 종속접속사라서 동사가 절의 끝에 와요. dagegen(반면에)은 접속부사라서 문장 맨 앞에 올 수도 있고, 이 글처럼 동사 뒤 중간 자리에 올 수도 있어요. im Vergleich zu + 3격은 '~과 비교하면'이라는 뜻이에요.","pattern":"Während + 주어 … 동사(끝), 동사 + 주어 … · …, während + 주어 … 동사(끝) · 동사 + … dagegen … · Im Vergleich zu + 3격 …","examples":[{"de":"Während die Älteren das Kochen meist als festen Bestandteil ihres Alltags sehen, fehlt den Jüngeren dafür nach eigenen Angaben oft die Zeit.","ko":"나이 든 사람들은 요리를 대개 일상의 당연한 일부로 여기지만, 젊은 사람들은 본인들 말로는 요리할 시간이 없는 경우가 많습니다.","mark":["Während","sehen"],"parts":[["Während die Älteren das Kochen meist als festen Bestandteil ihres Alltags sehen,","종속절"],["fehlt","동사"],["den Jüngeren","3격 목적어"],["dafür","부사어"],["nach eigenen Angaben","부사어"],["oft","부사어(빈도)"],["die Zeit.","주어"]]},{"de":"Rund ein Drittel kocht mehrmals pro Woche, während 28 Prozent selten oder nie am Herd stehen.","ko":"약 3분의 1은 일주일에 여러 번 요리하는 반면, 28퍼센트는 요리하는 일이 드물거나 전혀 없습니다.","mark":["während","stehen"]},{"de":"Bei den 18- bis 29-Jährigen ist es dagegen nur jeder Fünfte.","ko":"반면 18세에서 29세 사이에서는 다섯 명 중 한 명뿐입니다.","mark":["dagegen"]},{"de":"Im Vergleich zu den Älteren kochen die Jüngeren zwar seltener, aber deutlich häufiger in Gesellschaft.","ko":"젊은 사람들은 나이 든 사람들에 비해 요리를 덜 하지만, 다른 사람과 함께 요리하는 일은 훨씬 많습니다.","mark":["Im Vergleich zu den Älteren"]}],"tip":"während는 '~하는 동안'이라는 시간의 뜻으로도 써요. 두 사실을 맞세울 때는 '~하는 반면'이라는 뜻이에요."},{"title":"형용사·분사의 명사화","term":"Nominalisierte Adjektive und Partizipien (die Befragten, die Jüngeren)","explain":"형용사나 분사를 대문자로 쓰면 명사가 되고, 사람을 가리킬 때는 '~한 사람'이라는 뜻이에요. 하지만 어미는 형용사처럼 변해요. die Befragten(응답자들), die Berufstätigen(직장인들), die Älteren·die Jüngeren(나이가 더 많은 사람들·더 젊은 사람들), die über 60-Jährigen(60세가 넘은 사람들)이 그 예예요. 관사가 없으면 어미가 달라져요(viele Jüngere). jeder 뒤에서는 정관사 뒤와 같은 어미를 써요(jeder dritte Alleinlebende).","pattern":"der/die + 형용사·분사(대문자) + 형용사 어미 · viele + 형용사(대문자) + -e","examples":[{"de":"Nur noch 38 Prozent der Befragten bereiten jeden Tag selbst eine Mahlzeit zu.","ko":"응답자 가운데 매일 직접 식사를 준비하는 사람은 이제 38퍼센트뿐입니다.","mark":["der Befragten"],"parts":[["Nur noch 38 Prozent der Befragten","주어"],["bereiten","동사"],["jeden Tag","부사어(빈도)"],["selbst","부사어(방법)"],["eine Mahlzeit","4격 목적어"],["zu.","동사(끝)"]]},{"de":"Bei den über 60-Jährigen bereitet mehr als die Hälfte täglich eine warme Mahlzeit zu.","ko":"60세가 넘은 사람들은 절반 이상이 매일 따뜻한 식사를 준비합니다.","mark":["den über 60-Jährigen"]},{"de":"„Für viele Jüngere ist Kochen keine tägliche Pflicht mehr, sondern ein geselliges Erlebnis“, sagt sie.","ko":"“많은 젊은이에게 요리는 이제 매일 해야 하는 의무가 아니라 사람들과 어울리는 즐거운 경험이에요.” 에베르트는 이렇게 말합니다.","mark":["viele Jüngere"]}],"tip":"응답자 한 명은 der Befragte 또는 ein Befragter, 여러 명은 die Befragten 또는 viele Befragte예요."},{"title":"steigen · sinken: 변화를 나타내는 동사","term":"Veränderungen beschreiben: steigen / sinken + um / von … auf","explain":"수치가 늘면 steigen, 줄면 sinken을 써요. 둘 다 현재완료를 sein과 만들어요(ist gestiegen, ist gesunken). um은 변한 폭을, von … auf …는 처음 값과 나중 값을 나타내요. 퍼센트끼리의 차이는 Prozentpunkte(퍼센트포인트)로 말해요. 51퍼센트가 38퍼센트가 되면 13퍼센트포인트 줄어든 거예요.","pattern":"steigen/sinken + um + 변화 폭 · von + 처음 값 + auf + 나중 값","examples":[{"de":"Der Anteil derjenigen, die täglich kochen, ist also um 13 Prozentpunkte gesunken.","ko":"그러니까 매일 요리하는 사람의 비율이 13퍼센트포인트 줄어든 것입니다.","mark":["um 13 Prozentpunkte gesunken"],"parts":[["Der Anteil derjenigen, die täglich kochen,","주어"],["ist","동사"],["also","접속부사"],["um 13 Prozentpunkte","부사어"],["gesunken.","동사(끝)"]]},{"de":"Der Anteil der Menschen, die sich mindestens einmal pro Woche Mahlzeiten nach Hause liefern lassen, ist innerhalb eines Jahrzehnts von 9 auf 27 Prozent gestiegen.","ko":"일주일에 한 번 이상 음식을 집으로 배달시키는 사람의 비율은 10년 사이에 9퍼센트에서 27퍼센트로 늘었습니다.","mark":["von 9 auf 27 Prozent gestiegen"]}],"tip":"steigen과 sinken은 4격 목적어를 받지 않아요. 무엇을 올리거나 내린다고 말할 때는 erhöhen, senken을 써요."}],"vocab":[{"de":"der Herd, -e","ko":"(가스·전기) 레인지"},{"de":"befragen","ko":"(설문으로) 묻다"},{"de":"die Kochgewohnheit, -en","ko":"요리 습관"},{"de":"die Befragung, -en","ko":"설문 조사"},{"de":"vergleichbar","ko":"비교할 만한, 비슷한"},{"de":"der Anteil, -e","ko":"비율, 몫"},{"de":"sinken (sinkt, sank, ist gesunken)","ko":"줄다, 내려가다"},{"de":"steigen (steigt, stieg, ist gestiegen)","ko":"늘다, 오르다"},{"de":"zu|bereiten","ko":"(음식을) 준비하다, 만들다"},{"de":"die Mahlzeit, -en","ko":"식사, 끼니"},{"de":"der Bestandteil, -e","ko":"구성 요소, 일부"},{"de":"berufstätig","ko":"직업이 있는, 일하는"},{"de":"der Feierabend, -e","ko":"퇴근 뒤의 시간"},{"de":"der Aufwand (Sg.)","ko":"수고, 들이는 노력"},{"de":"der Lieferdienst, -e","ko":"배달 서비스, 배달 업체"},{"de":"das Fertiggericht, -e","ko":"즉석식품"}],"phrases":[{"de":"am Herd stehen","ko":"요리하다","ex":"Wie oft steht in Marlenburg noch jemand am Herd?","exko":"마를렌부르크에서는 아직 얼마나 자주 직접 요리를 할까요?"},{"de":"nach eigenen Angaben","ko":"본인들 말로는, 스스로 밝힌 바로는","ex":"Während die Älteren das Kochen meist als festen Bestandteil ihres Alltags sehen, fehlt den Jüngeren dafür nach eigenen Angaben oft die Zeit.","exko":"나이 든 사람들은 요리를 대개 일상의 당연한 일부로 여기지만, 젊은 사람들은 본인들 말로는 요리할 시간이 없는 경우가 많습니다."},{"de":"an Bedeutung gewinnen","ko":"중요해지다, 비중이 커지다","ex":"Gleichzeitig gewinnen Lieferdienste an Bedeutung","exko":"동시에 배달 서비스가 점점 더 중요해지고 있습니다."},{"de":"im Vergleich zu + Dat.","ko":"~과 비교하면","ex":"Im Vergleich zu den Älteren kochen die Jüngeren zwar seltener, aber deutlich häufiger in Gesellschaft.","exko":"젊은 사람들은 나이 든 사람들에 비해 요리를 덜 하지만, 다른 사람과 함께 요리하는 일은 훨씬 많습니다."},{"de":"unter der Woche","ko":"평일에","ex":"Wer unter der Woche keine Zeit hat, sollte am Sonntag gleich mehrere Portionen vorkochen.","exko":"평일에 시간이 없는 사람은 일요일에 한꺼번에 여러 끼니를 미리 만들어 두는 것이 좋아요."}],"words":324},{"id":"b1-24","level":"B1","no":24,"title":"Unterwegs mit dem Bücherbus","titleKo":"이동 도서관 버스와 함께","type":"Reportage","typeKo":"르포","intro":"시골 마을을 돌아다니는 이동 도서관 버스의 하루를 따라가 본 글이에요.","focus":["entlang · gegenüber · um … herum","einander · miteinander","-ung · -heit · -keit · -schaft","간접의문문 ob절"],"paragraphs":[{"de":"Dienstagmorgen, kurz nach neun Uhr. Ein knallgelber Bus fährt langsam die Landstraße entlang, an Feldern und einem Windrad vorbei. Am Steuer sitzt Annegret Thoms, die Bibliothekarin und Busfahrerin zugleich ist, denn ihr Arbeitsplatz ist eine Bibliothek auf Rädern.","ko":"화요일 아침, 아홉 시가 조금 지났어요. 샛노란 버스 한 대가 밭과 풍력 발전기를 지나 지방 도로를 따라 천천히 달려요. 운전석에는 안네그레트 톰스가 앉아 있어요. 톰스는 사서이면서 동시에 버스 운전사예요. 일터가 바퀴 달린 도서관이기 때문이에요."},{"de":"Alle zwei Wochen fährt der Bücherbus dieselbe Strecke, auf der er in vier Tagen 14 Ortschaften erreicht. In den Regalen hinter der Bibliothekarin stehen rund 3.000 Bücher, Hörbücher und Gesellschaftsspiele. Wer etwas ausleihen möchte, braucht nur einen Leseausweis, den Thoms direkt im Bücherbus ausstellt, und die Nutzung ist kostenlos. Der erste Haltepunkt ist heute Kleinrode, wo der Bücherbus gegenüber der alten Dorfschule parkt, die seit Jahren leer steht.","ko":"이 이동 도서관 버스는 2주마다 같은 노선을 달리며 나흘 동안 마을 열네 곳을 돌아요. 사서 뒤의 책장에는 책과 오디오북, 보드게임이 약 3,000점 꽂혀 있어요. 무언가를 빌리고 싶은 사람은 톰스가 버스 안에서 바로 만들어 주는 회원증만 있으면 되고, 이용은 무료예요. 오늘 첫 정차지는 클라인로데예요. 버스는 그곳에서 몇 년째 비어 있는 옛 마을 학교 건너편에 서요."},{"de":"Sobald sich die Tür öffnet, steigt die neunjährige Finja ein, bringt drei Pferdebücher zurück und sucht sofort nach neuen Büchern. „Frau Thoms weiß immer, welche Bücher mir gefallen“, erzählt sie. Auch Herr Paulsen kommt jeden zweiten Dienstag zum Bücherbus. Der 78-Jährige leiht zwar regelmäßig Kriminalromane aus, eigentlich kommt er aber wegen der Gesellschaft. Um den kleinen Klapptisch am Eingang herum stehen bald fünf Nachbarn, die sich miteinander unterhalten.","ko":"문이 열리자마자 아홉 살 핀야가 올라타서 말에 관한 책 세 권을 돌려주고 곧바로 새 책을 찾아요. “톰스 선생님은 제가 어떤 책을 좋아하는지 늘 아세요.” 핀야의 말이에요. 파울젠 씨도 격주 화요일마다 이 버스에 와요. 일흔여덟 살인 파울젠 씨는 추리 소설을 꾸준히 빌리기는 하지만, 사실은 사람들과 어울리려고 와요. 입구에 있는 작은 접이식 탁자 둘레에는 금세 이웃 다섯 명이 서서 서로 이야기를 나눠요."},{"de":"„Früher hat man sich im Dorfladen getroffen“, erzählt Paulsen. „Seit der geschlossen ist, sehen wir uns fast nur noch hier.“ Die Bibliothekarin kennt solche Geschichten. Für viele Dorfbewohner ist der Bücherbus die einzige Gelegenheit, ohne Auto an neue Bücher zu kommen. Auch die Freundlichkeit, mit der Thoms jeden Besucher begrüßt, gehört für viele einfach dazu. Bestellungen nimmt sie am Telefon an und bringt die bestellten Bücher beim nächsten Besuch mit.","ko":"“예전에는 마을 가게에서 서로 만났어요.” 파울젠 씨가 말해요. “가게가 문을 닫은 뒤로는 거의 여기에서만 서로 얼굴을 봐요.” 사서 톰스에게 이런 이야기는 익숙해요. 많은 마을 사람에게 이 버스는 차 없이 새 책을 구할 수 있는 유일한 기회예요. 톰스가 찾아오는 사람 한 명 한 명에게 친절하게 인사하는 것도 많은 사람에게는 이 버스에서 빠질 수 없는 부분이에요. 톰스는 전화로 주문을 받아서 다음번에 올 때 주문한 책을 가져다줘요."},{"de":"Nach 45 Minuten schließt die Bibliothekarin die Tür und fährt weiter zum nächsten Haltepunkt in Hohenmoor. Ob der Bücherbus auch im nächsten Jahr noch fährt, ist allerdings unsicher, denn der Landkreis hat die Finanzierung nur bis Dezember zugesagt. Die Dorfbewohner sammeln deshalb Unterschriften zur Rettung des Bücherbusses. „Wir lernen hier viel voneinander“, sagt Thoms. „Diese Gemeinschaft darf nicht verloren gehen.“","ko":"45분 뒤에 톰스는 문을 닫고 다음 정차지인 호엔모어로 떠나요. 그런데 이 버스가 내년에도 다닐지는 확실하지 않아요. 군에서 12월까지만 예산을 대 주기로 약속했기 때문이에요. 그래서 마을 사람들은 버스를 지키려고 서명을 모으고 있어요. “우리는 여기에서 서로에게 많이 배워요.” 톰스의 말이에요. “이 공동체가 사라져서는 안 돼요.”"}],"questions":[{"type":"mc","kind":"meaning","q":"Was bedeutet „eine Bibliothek auf Rädern“ im Text?","options":["Die Medien werden in einem Fahrzeug verliehen.","Die Bibliothek steht in der alten Dorfschule.","Thoms fährt die Bücher zu einer großen Bibliothek."],"answer":0,"evidence":"denn ihr Arbeitsplatz ist eine Bibliothek auf Rädern","pairs":[["eine Bibliothek auf Rädern","in einem Fahrzeug verliehen"]],"explain":"auf Rädern는 '바퀴 달린'이라는 뜻이에요. 톰스의 도서관은 건물이 아니라 버스라서 책과 오디오북, 게임을 차 안에서 빌려줘요. 옛 마을 학교는 버스가 서는 곳의 건너편에 있는 빈 건물이고, 톰스가 책을 다른 도서관으로 실어 나르는 것도 아니에요."},{"type":"rf","kind":"detail","q":"Jedes Dorf auf der Strecke wird im Abstand von vierzehn Tagen angefahren.","answer":0,"evidence":"Alle zwei Wochen fährt der Bücherbus dieselbe Strecke","pairs":[["Alle zwei Wochen","im Abstand von vierzehn Tagen"]],"explain":"버스는 2주마다(Alle zwei Wochen) 같은 노선을 달려요. 2주는 14일이니까 노선에 있는 마을마다 14일 간격으로 버스가 와요."},{"type":"mc","kind":"detail","q":"Wo hält der Bücherbus in Kleinrode?","options":["auf dem Hof der alten Dorfschule","gegenüber einem leeren Gebäude","direkt neben dem alten Dorfladen"],"answer":1,"evidence":"wo der Bücherbus gegenüber der alten Dorfschule parkt, die seit Jahren leer steht","pairs":[["die seit Jahren leer steht","einem leeren Gebäude"],["gegenüber der alten Dorfschule","gegenüber einem leeren Gebäude"]],"explain":"버스는 몇 년째 비어 있는 옛 마을 학교 건너편(gegenüber)에 서요. '비어 있는 옛 학교'를 '빈 건물'로 바꿔 말했어요. 버스는 학교 마당이 아니라 건너편에 서고, 마을 가게가 어디 있는지는 글에 나오지 않아요."},{"type":"mc","kind":"inference","q":"Warum kommt Herr Paulsen vor allem zum Bücherbus?","options":["Er sammelt seit vielen Jahren Kriminalromane.","Ohne Auto kommt er sonst an keine neuen Bücher.","Er möchte Zeit mit anderen Menschen verbringen."],"answer":2,"evidence":"eigentlich kommt er aber wegen der Gesellschaft","pairs":[["wegen der Gesellschaft","Zeit mit anderen Menschen verbringen"]],"explain":"파울젠 씨는 추리 소설을 꾸준히 빌리기는 하지만(zwar), 사실은(eigentlich … aber) 사람들과 어울리려고 와요. Gesellschaft(함께 어울림)를 '다른 사람들과 시간을 보내다'로 바꿔 말했어요. 차 없이 새 책을 구할 기회가 이 버스뿐이라는 말은 많은 마을 사람에 대한 설명이고, 파울젠 씨가 오는 주된 이유는 아니에요. 파울젠 씨가 추리 소설을 모은다는 말도 없어요."},{"type":"rf","kind":"detail","q":"Die Dorfbewohner treffen sich auch heute noch regelmäßig im Dorfladen.","answer":1,"evidence":"Seit der geschlossen ist, sehen wir uns fast nur noch hier.","pairs":[["Seit der geschlossen ist","auch heute noch regelmäßig im Dorfladen"]],"explain":"파울젠 씨는 예전에는 마을 가게에서 만났지만, 가게가 문을 닫은 뒤로는 거의 버스에서만 서로 만난다고 해요. 가게에서 만난 것은 예전 일이라서 틀린 말이에요."},{"type":"mc","kind":"detail","q":"Wie bekommt man ein Buch, das gerade nicht im Bücherbus steht?","options":["Man ruft an und bekommt es, wenn der Bus wiederkommt.","Man fährt mit dem Auto zur großen Bibliothek in der Stadt.","Man schreibt den Titel auf eine Liste im Bücherbus."],"answer":0,"evidence":"Bestellungen nimmt sie am Telefon an und bringt die bestellten Bücher beim nächsten Besuch mit.","pairs":[["nimmt sie am Telefon an","Man ruft an"],["beim nächsten Besuch","wenn der Bus wiederkommt"]],"explain":"톰스는 전화로 주문을 받아서 다음번에 올 때 주문한 책을 가져다줘요. 그러니까 전화를 걸면 버스가 다시 올 때 책을 받을 수 있어요. 차를 타고 도시 도서관에 가거나 버스 안 목록에 적는다는 말은 없어요."},{"type":"mc","kind":"detail","q":"Warum ist die Zukunft des Bücherbusses unsicher?","options":["Die Bibliothekarin möchte zum Jahresende aufhören.","In den Ortschaften leihen zu wenige Leute etwas aus.","Das Geld dafür ist nur bis Jahresende gesichert."],"answer":2,"evidence":"denn der Landkreis hat die Finanzierung nur bis Dezember zugesagt","pairs":[["die Finanzierung nur bis Dezember zugesagt","Das Geld dafür ist nur bis Jahresende gesichert"]],"explain":"군(Landkreis)은 12월까지만 예산을 대 주기로 약속했어요. 그 뒤의 돈은 아직 정해지지 않아서 버스가 내년에도 다닐지 알 수 없어요. Finanzierung(재정 지원)을 Geld(돈)로, Dezember를 Jahresende(연말)로 바꿔 말했어요. 톰스가 그만둔다거나 빌리는 사람이 적다는 말은 글에 없어요."},{"type":"mc","kind":"intent","q":"Was will die Reportage vor allem zeigen?","options":["Für die Dörfer ist der Bus auch ein wichtiger Treffpunkt.","Auf dem Land lesen die Menschen mehr als in der Stadt.","Kinder leihen heute lieber Gesellschaftsspiele als Bücher aus."],"answer":0,"evidence":"Seit der geschlossen ist, sehen wir uns fast nur noch hier.","pairs":[["sehen wir uns fast nur noch hier","ein wichtiger Treffpunkt"]],"explain":"이 글은 책을 빌려주는 일뿐 아니라 사람들이 버스에서 만나 이야기를 나누는 모습을 보여 줘요. 마을 가게가 문을 닫은 뒤 버스가 만남의 장소(Treffpunkt)가 되었고, 톰스도 이 공동체가 사라지면 안 된다고 해요. 시골 사람이 도시 사람보다 책을 더 많이 읽는다거나 아이들이 게임을 더 좋아한다는 말은 없어요."}],"grammar":[{"title":"장소 전치사 entlang · gegenüber · um … herum","term":"Lokale Präpositionen: entlang, gegenüber, um … herum, an … vorbei","explain":"entlang은 '~을 따라'라는 뜻이고 보통 4격 명사 뒤에 와요(die Landstraße entlang). gegenüber는 '~의 맞은편에'라는 뜻이고 3격과 써요. um … herum은 '~의 둘레에'라는 뜻이고 um 뒤에 4격이 와요. an … vorbei는 '~을 지나서'라는 뜻이고 an 뒤에 3격이 와요.","pattern":"4격 + entlang · gegenüber + 3격 · um + 4격 + herum · an + 3격 + vorbei","examples":[{"de":"Ein knallgelber Bus fährt langsam die Landstraße entlang, an Feldern und einem Windrad vorbei.","ko":"샛노란 버스 한 대가 밭과 풍력 발전기를 지나 지방 도로를 따라 천천히 달려요.","mark":["die Landstraße entlang","an Feldern und einem Windrad vorbei"],"parts":[["Ein knallgelber Bus","주어"],["fährt","동사"],["langsam","부사어(방법)"],["die Landstraße entlang,","부사어(장소)"],["an Feldern und einem Windrad vorbei.","부사어(장소)"]]},{"de":"Der erste Haltepunkt ist heute Kleinrode, wo der Bücherbus gegenüber der alten Dorfschule parkt, die seit Jahren leer steht.","ko":"오늘 첫 정차지는 클라인로데예요. 버스는 그곳에서 몇 년째 비어 있는 옛 마을 학교 건너편에 서요.","mark":["gegenüber der alten Dorfschule"]},{"de":"Um den kleinen Klapptisch am Eingang herum stehen bald fünf Nachbarn, die sich miteinander unterhalten.","ko":"입구에 있는 작은 접이식 탁자 둘레에는 금세 이웃 다섯 명이 서서 서로 이야기를 나눠요.","mark":["Um den kleinen Klapptisch am Eingang herum"]}],"tip":"gegenüber는 명사 앞에 올 때가 많지만, 대명사와 쓰면 뒤에 와요(ihr gegenüber)."},{"title":"서로: einander · miteinander","term":"Reziprokpronomen einander (miteinander, voneinander)","explain":"einander는 '서로'라는 뜻이에요. 전치사와 함께 쓸 때는 전치사와 붙여서 한 단어로 써요. mit + einander는 miteinander(서로 함께), von + einander는 voneinander(서로에게서)가 돼요. 전치사 없이 쓰는 einander는 조금 격식 있는 말이라서, 일상 대화에서는 파울젠 씨처럼 재귀대명사 uns, euch, sich로 '서로'를 나타낼 때가 많아요(wir sehen uns = wir sehen einander).","pattern":"동사 + einander · 전치사 + einander(한 단어: miteinander, voneinander)","examples":[{"de":"„Wir lernen hier viel voneinander“, sagt Thoms.","ko":"“우리는 여기에서 서로에게 많이 배워요.” 톰스의 말이에요.","mark":["voneinander"],"parts":[["„Wir","주어"],["lernen","동사"],["hier","부사어(장소)"],["viel","4격 목적어"],["voneinander“,","전치사 목적어"],["sagt Thoms.","기타"]]},{"de":"Seit der geschlossen ist, sehen wir uns fast nur noch hier.","ko":"가게가 문을 닫은 뒤로는 거의 여기에서만 서로 얼굴을 봐요.","mark":["uns"]},{"de":"Um den kleinen Klapptisch am Eingang herum stehen bald fünf Nachbarn, die sich miteinander unterhalten.","ko":"입구에 있는 작은 접이식 탁자 둘레에는 금세 이웃 다섯 명이 서서 서로 이야기를 나눠요.","mark":["miteinander"]}],"tip":"voneinander, miteinander처럼 전치사와 붙인 형태는 띄어 쓰지 않아요."},{"title":"명사를 만드는 접미사 -ung · -heit · -keit · -schaft","term":"Wortbildung: Nomen auf -ung, -heit, -keit, -schaft","explain":"이 접미사로 끝나는 명사는 여성(die)이고, 복수는 -en을 붙여요. -ung은 동사에서 명사를 만들어요(bestellen → die Bestellung, finanzieren → die Finanzierung). -heit와 -keit는 주로 형용사에서 명사를 만들어요(freundlich → die Freundlichkeit). -schaft는 사람들의 모임이나 관계를 나타내는 명사를 자주 만들어요(die Gemeinschaft, die Gesellschaft).","pattern":"동사 어간 + -ung · 형용사 + -heit / -keit · -schaft → die …, 복수 -en","examples":[{"de":"Diese Gemeinschaft darf nicht verloren gehen.","ko":"이 공동체가 사라져서는 안 돼요.","mark":["Gemeinschaft"],"parts":[["Diese Gemeinschaft","주어"],["darf","동사"],["nicht","부정어"],["verloren gehen.","동사(끝)"]]},{"de":"Auch die Freundlichkeit, mit der Thoms jeden Besucher begrüßt, gehört für viele einfach dazu.","ko":"톰스가 찾아오는 사람 한 명 한 명에게 친절하게 인사하는 것도 많은 사람에게는 이 버스에서 빠질 수 없는 부분이에요.","mark":["Freundlichkeit"]},{"de":"Bestellungen nimmt sie am Telefon an und bringt die bestellten Bücher beim nächsten Besuch mit.","ko":"톰스는 전화로 주문을 받아서 다음번에 올 때 주문한 책을 가져다줘요.","mark":["Bestellungen"]},{"de":"Für viele Dorfbewohner ist der Bücherbus die einzige Gelegenheit, ohne Auto an neue Bücher zu kommen.","ko":"많은 마을 사람에게 이 버스는 차 없이 새 책을 구할 수 있는 유일한 기회예요.","mark":["Gelegenheit"]}],"tip":"-ung 명사는 동사의 뜻을 이어받을 때가 많아요. bestellen(주문하다) → die Bestellung(주문), nutzen(이용하다) → die Nutzung(이용)."},{"title":"간접의문문: 주어·목적어가 되는 ob절과 의문사절","term":"Indirekte Fragesätze als Subjekt und Objekt (Ob …, ist unsicher. / weiß, welche …)","explain":"질문을 다른 문장 안에 넣으면 간접의문문이 돼요. 예·아니요로 답하는 질문은 ob으로, 의문사가 있는 질문은 그 의문사(welche, wann, wie 등)로 시작하고 동사는 끝에 와요. 간접의문문은 문장의 목적어가 될 수도 있고(Frau Thoms weiß immer, welche Bücher mir gefallen), 주어가 될 수도 있어요. ob절이 주어로 맨 앞에 오면 쉼표 뒤에 주절의 동사(ist)가 바로 와요.","pattern":"Ob + 주어 … 동사(끝), ist + 형용사 … · 주어 + 동사 …, welche/wann/wie + … 동사(끝)","examples":[{"de":"Ob der Bücherbus auch im nächsten Jahr noch fährt, ist allerdings unsicher, denn der Landkreis hat die Finanzierung nur bis Dezember zugesagt.","ko":"그런데 이 버스가 내년에도 다닐지는 확실하지 않아요. 군에서 12월까지만 예산을 대 주기로 약속했기 때문이에요.","mark":["Ob","fährt","ist allerdings unsicher"],"parts":[["Ob der Bücherbus auch im nächsten Jahr noch fährt,","종속절"],["ist","동사"],["allerdings","부사어"],["unsicher,","보어"],["denn der Landkreis hat die Finanzierung nur bis Dezember zugesagt.","기타"]]},{"de":"„Frau Thoms weiß immer, welche Bücher mir gefallen“, erzählt sie.","ko":"“톰스 선생님은 제가 어떤 책을 좋아하는지 늘 아세요.” 핀야의 말이에요.","mark":["welche Bücher mir gefallen"]}],"tip":"Es ist unsicher, ob der Bus nächstes Jahr fährt.처럼 주어 자리에 es를 두고 ob절을 뒤로 보내도 같은 뜻이에요."}],"vocab":[{"de":"die Landstraße, -n","ko":"지방 도로"},{"de":"das Steuer, -","ko":"운전대"},{"de":"die Bibliothekarin, -nen","ko":"(여자) 사서"},{"de":"die Strecke, -n","ko":"구간, 노선"},{"de":"die Ortschaft, -en","ko":"마을, 동네"},{"de":"aus|leihen (leiht aus, lieh aus, hat ausgeliehen)","ko":"빌리다"},{"de":"der Leseausweis, -e","ko":"도서관 회원증"},{"de":"aus|stellen","ko":"(증명서를) 발급하다, 만들어 주다"},{"de":"der Haltepunkt, -e","ko":"정차 지점, 정차지"},{"de":"der Kriminalroman, -e","ko":"추리 소설"},{"de":"die Gesellschaft (Sg.)","ko":"함께 어울림, 함께 있는 사람들"},{"de":"der Klapptisch, -e","ko":"접이식 탁자"},{"de":"die Gelegenheit, -en","ko":"기회"},{"de":"der Landkreis, -e","ko":"군(郡), 지방 행정 구역"},{"de":"die Finanzierung, -en","ko":"재정 지원, 자금 마련"},{"de":"die Unterschrift, -en","ko":"서명"}],"phrases":[{"de":"leer stehen","ko":"(건물이) 비어 있다","ex":"Der erste Haltepunkt ist heute Kleinrode, wo der Bücherbus gegenüber der alten Dorfschule parkt, die seit Jahren leer steht.","exko":"오늘 첫 정차지는 클라인로데예요. 버스는 그곳에서 몇 년째 비어 있는 옛 마을 학교 건너편에 서요."},{"de":"an etwas (Akk.) kommen","ko":"~을 구하다, 손에 넣다","ex":"Für viele Dorfbewohner ist der Bücherbus die einzige Gelegenheit, ohne Auto an neue Bücher zu kommen.","exko":"많은 마을 사람에게 이 버스는 차 없이 새 책을 구할 수 있는 유일한 기회예요."},{"de":"einfach dazu|gehören","ko":"당연히 함께 있는 것이다, 빠질 수 없다","ex":"Auch die Freundlichkeit, mit der Thoms jeden Besucher begrüßt, gehört für viele einfach dazu.","exko":"톰스가 찾아오는 사람 한 명 한 명에게 친절하게 인사하는 것도 많은 사람에게는 이 버스에서 빠질 수 없는 부분이에요."},{"de":"Unterschriften sammeln","ko":"서명을 모으다","ex":"Die Dorfbewohner sammeln deshalb Unterschriften zur Rettung des Bücherbusses.","exko":"그래서 마을 사람들은 버스를 지키려고 서명을 모으고 있어요."},{"de":"verloren gehen","ko":"사라지다, 없어지다","ex":"Diese Gemeinschaft darf nicht verloren gehen.","exko":"이 공동체가 사라져서는 안 돼요."}],"words":305},{"id":"b1-25","level":"B1","no":25,"title":"Filmtipp: Ein Sommer am Kanal","titleKo":"영화 추천: 운하에서 보낸 여름","type":"Filmkritik","typeKo":"영화평","intro":"할아버지와 여름을 보내게 된 열여섯 살 소녀의 이야기를 다룬 영화를 소개하고 평가하는 글이에요.","focus":["es 표현","wer …, (der) …","형용사 접미사","현재형 줄거리 요약"],"paragraphs":[{"de":"Selten war ein Spielfilm über Langeweile so wenig langweilig. In „Ein Sommer am Kanal“ erzählt die Regisseurin Mara Lindqvist eine recht einfache Geschichte. Doch gerade wegen dieser Einfachheit lohnt es sich, genauer hinzusehen.","ko":"지루함을 다룬 영화가 이렇게 지루하지 않은 경우는 드물어요. 마라 린드크비스트 감독은 “운하에서 보낸 여름”에서 꽤 단순한 이야기를 들려줘요. 그런데 바로 이 단순함 때문에 이 영화는 더 자세히 들여다볼 만해요."},{"de":"Im Mittelpunkt der Handlung steht die sechzehnjährige Jette aus Hamburg. Weil ihre Mutter beruflich ins Ausland muss, soll Jette die Sommerferien bei ihrem Großvater Hinnerk verbringen. Der Großvater wohnt auf dem Land und restauriert seit Jahren ein altes Hausboot. Mit dem Hausboot ist er früher als Schiffer über die Kanäle geschippert, heute liegt es fest am Ufer. Anfangs findet Jette alles furchtbar. Auf dem Land gibt es keinen Handyempfang, keine Freunde und kaum ein Gespräch mit dem schweigsamen Großvater. Erst als Jette dem Großvater aus Langeweile beim Streichen des Hausboots hilft, beginnt zwischen den beiden eine vorsichtige Annäherung. Doch dann erfährt Jette von der Entscheidung des Großvaters, das Hausboot zu verkaufen. Es kommt zu einer heftigen Auseinandersetzung. Wie die Geschichte ausgeht, wird hier nicht verraten.","ko":"이야기의 중심에는 함부르크에 사는 열여섯 살 예테가 있어요. 어머니가 일 때문에 외국에 가야 해서, 예테는 여름 방학을 할아버지 힌너크의 집에서 보내야 해요. 할아버지는 시골에 살면서 몇 년째 낡은 하우스보트를 복원하고 있어요. 예전에는 뱃사람으로 이 하우스보트를 타고 운하를 누볐지만, 지금은 배가 물가에 묶여 있어요. 처음에 예테는 모든 것이 끔찍하다고 생각해요. 시골에서는 휴대폰도 안 터지고 친구도 없고, 말수 적은 할아버지와는 대화도 거의 없어요. 예테가 심심해서 할아버지의 하우스보트 페인트칠을 돕고 나서야 두 사람 사이가 조심스럽게 가까워지기 시작해요. 그런데 예테는 할아버지가 하우스보트를 팔기로 했다는 것을 알게 돼요. 그래서 두 사람은 크게 다퉈요. 이야기가 어떻게 끝나는지는 여기에서 밝히지 않을게요."},{"de":"Der jungen Hauptdarstellerin Luisa Körber gelingt es, mit wenigen Worten sehr viel zu zeigen. Auch der Darsteller des Großvaters zeigt eine überzeugende Leistung, denn man glaubt ihm jedes seiner wenigen Worte. Besonders eindrucksvoll sind die Szenen auf dem Kanal, in denen kaum etwas passiert. In diesen Szenen sorgt die ruhige Kameraführung für eine besondere Stimmung, und Filmmusik setzt die Regisseurin kaum ein. Allerdings ist der Mittelteil des Films einige Minuten zu lang geraten. Außerdem fehlt es den Nebenfiguren an Tiefe; die Nachbarin des Großvaters zum Beispiel bleibt recht blass.","ko":"젊은 주연 배우 루이자 쾨르버는 몇 마디 말로 아주 많은 것을 보여 주는 데 성공해요. 할아버지 역을 맡은 배우도 설득력 있는 연기를 보여 줘요. 몇 마디 안 되는 대사 하나하나가 진짜처럼 들리거든요. 거의 아무 일도 일어나지 않는 운하 위 장면들이 특히 인상적이에요. 이런 장면에서는 차분한 카메라 움직임이 특별한 분위기를 만들고, 감독은 영화 음악을 거의 쓰지 않아요. 다만 영화의 중간 부분은 몇 분쯤 지나치게 길어졌어요. 게다가 조연들은 깊이가 부족해요. 예를 들어 할아버지의 이웃 여자는 꽤 밋밋한 인물로 남아요."},{"de":"Wer schnelle Schnitte und laute Filmmusik erwartet, wird sich in den 98 Minuten kaum wohlfühlen. Wer aber Geduld mitbringt, der sieht einen äußerst warmherzigen Film über die Beziehung zwischen Enkelin und Großvater, die erst lernen müssen, miteinander zu sprechen. Es lohnt sich übrigens, bis nach dem Abspann sitzen zu bleiben.","ko":"빠른 장면 전환과 시끄러운 영화 음악을 기대하는 사람은 98분 동안 편하게 보기 어려울 거예요. 하지만 느긋하게 볼 준비가 된 사람은, 서로 말하는 법부터 배워야 하는 손녀와 할아버지의 관계를 그린 더없이 따뜻한 영화를 만나게 돼요. 참고로 끝 자막이 다 올라갈 때까지 앉아 있을 만해요."},{"style":"meta","de":"„Ein Sommer am Kanal“ von Mara Lindqvist, 98 Minuten, ab sofort in ausgewählten Kinos.","ko":"운하에서 보낸 여름. 마라 린드크비스트 감독. 98분. 지금 일부 극장에서 상영 중."}],"questions":[{"type":"mc","kind":"intent","q":"Wie beurteilt die Kritik den Film insgesamt?","options":["Sie findet ihn langweilig und zu einfach erzählt.","Sie empfiehlt ihn trotz einiger kleiner Schwächen.","Sie lobt vor allem die spannende, schnelle Handlung."],"answer":1,"evidence":"Doch gerade wegen dieser Einfachheit lohnt es sich, genauer hinzusehen.","pairs":[["lohnt es sich, genauer hinzusehen","Sie empfiehlt ihn"],["einige Minuten zu lang geraten","einiger kleiner Schwächen"]],"explain":"글쓴이는 배우들의 연기와 운하 위 장면들을 칭찬하고, 이 영화를 더 자세히 들여다볼 만하다고 해요. 다만 중간 부분이 조금 길고 조연이 밋밋하다는 약점도 말해요. 그래서 '작은 약점이 있지만 추천한다'가 맞아요. 지루하다는 말은 오히려 반대이고, 빠르고 긴장감 있는 줄거리를 칭찬하는 것도 아니에요."},{"type":"rf","kind":"detail","q":"Jette freut sich von Anfang an auf die Ferien bei ihrem Großvater.","answer":1,"evidence":"Anfangs findet Jette alles furchtbar.","pairs":[["Anfangs findet Jette alles furchtbar","freut sich von Anfang an"]],"explain":"예테는 처음에 모든 것이 끔찍하다고 생각해요(Anfangs … furchtbar). 처음부터 방학을 기대한다는 말은 글의 내용과 반대예요."},{"type":"mc","kind":"detail","q":"Wodurch kommen sich Jette und ihr Großvater näher?","options":["durch die gemeinsame Arbeit am Boot","durch einen Ausflug auf dem Kanal","durch den Verkauf des alten Hausboots"],"answer":0,"evidence":"Erst als Jette dem Großvater aus Langeweile beim Streichen des Hausboots hilft, beginnt zwischen den beiden eine vorsichtige Annäherung.","pairs":[["beim Streichen des Hausboots hilft","die gemeinsame Arbeit am Boot"],["eine vorsichtige Annäherung","kommen sich Jette und ihr Großvater näher"]],"explain":"예테가 심심해서 할아버지의 하우스보트 페인트칠을 도우면서 두 사람은 조심스럽게 가까워지기 시작해요(Annäherung). 페인트칠은 배를 손질하는 일의 일부예요. 배는 물가에 묶여 있어서 운하로 나가지 않고, 배를 팔려는 계획은 오히려 다툼을 일으켜요."},{"type":"mc","kind":"detail","q":"Warum streiten sich die beiden?","options":["Jette sucht heimlich einen Käufer für das Boot.","Der Großvater spricht viel zu wenig mit Jette.","Der Großvater will sich von dem Boot trennen."],"answer":2,"evidence":"Doch dann erfährt Jette von der Entscheidung des Großvaters, das Hausboot zu verkaufen.","pairs":[["das Hausboot zu verkaufen","will sich von dem Boot trennen"]],"explain":"예테는 할아버지가 하우스보트를 팔기로 했다는 것을 알게 되고, 그래서 두 사람이 크게 다퉈요. verkaufen(팔다)을 sich trennen von(~을 내놓다)으로 바꿔 말했어요. 배를 팔려는 사람은 예테가 아니라 할아버지예요. 할아버지가 말수가 적은 것은 사실이지만 다툼의 이유는 아니에요."},{"type":"rf","kind":"detail","q":"Der Ausgang der Geschichte bleibt in der Kritik offen.","answer":0,"evidence":"Wie die Geschichte ausgeht, wird hier nicht verraten.","pairs":[["wird hier nicht verraten","bleibt in der Kritik offen"]],"explain":"글쓴이는 이야기가 어떻게 끝나는지 밝히지 않겠다고 해요(wird hier nicht verraten). 그래서 이 글만으로는 결말을 알 수 없으니 맞는 말이에요."},{"type":"mc","kind":"paraphrase","q":"Was bedeutet der Satz „Der jungen Hauptdarstellerin Luisa Körber gelingt es, mit wenigen Worten sehr viel zu zeigen“?","options":["Sie hat im Film leider nur eine kleine Rolle.","Sie drückt vieles aus, obwohl sie kaum redet.","Sie spricht ihre wenigen Sätze besonders deutlich."],"answer":1,"evidence":"Der jungen Hauptdarstellerin Luisa Körber gelingt es, mit wenigen Worten sehr viel zu zeigen.","pairs":[["mit wenigen Worten","obwohl sie kaum redet"],["sehr viel zu zeigen","drückt vieles aus"]],"explain":"es gelingt ihr, … zu …는 '그 사람이 ~을 해낸다'는 뜻이에요. 대사는 적지만 많은 것을 표현해 낸다는 칭찬이에요. 쾨르버는 주연 배우라서 작은 역이 아니고, 발음이 또렷하다는 말도 아니에요."},{"type":"mc","kind":"detail","q":"Was kritisiert der Text an dem Film?","options":["Manche Figuren am Rand bleiben farblos.","Die Szenen auf dem Kanal dauern zu lange.","Die Filmmusik ist an vielen Stellen zu laut."],"answer":0,"evidence":"Außerdem fehlt es den Nebenfiguren an Tiefe","pairs":[["den Nebenfiguren an Tiefe","Manche Figuren am Rand"],["recht blass","farblos"]],"explain":"글쓴이는 조연들에게 깊이가 부족하다고 해요. Nebenfiguren(조연)을 Figuren am Rand(주변 인물)로, blass(밋밋한)를 farblos(색이 없는)로 바꿔 말했어요. 운하 위 장면은 특히 인상적이라고 했고, 너무 긴 것은 중간 부분이에요. 영화 음악은 거의 없어요."},{"type":"mc","kind":"inference","q":"Für wen eignet sich der Film laut Kritik vor allem?","options":["für Fans von schnellen Schnitten","für Freunde von lauter Filmmusik","für alle, die ruhige Filme mögen"],"answer":2,"evidence":"Wer aber Geduld mitbringt, der sieht einen äußerst warmherzigen Film","pairs":[["Wer aber Geduld mitbringt","für alle, die ruhige Filme mögen"]],"explain":"글쓴이는 빠른 장면 전환과 시끄러운 음악을 기대하는 사람은 편하게 보기 어렵고, 느긋하게 볼 준비가 된 사람(Wer … Geduld mitbringt)은 따뜻한 영화를 만난다고 해요. 그래서 조용하고 느린 영화를 좋아하는 사람에게 권한다는 것을 알 수 있어요."}],"grammar":[{"title":"es가 들어가는 표현","term":"Feste Ausdrücke mit es (es gelingt, es lohnt sich, es fehlt an, es kommt zu)","explain":"독일어에는 es를 주어로 쓰는 굳은 표현이 많아요. 이때 es는 앞에 나온 특정한 명사를 가리키지 않아요. es gelingt + 3격은 '~가 해내다', es lohnt sich는 '할 만하다', es fehlt + 3격 + an + 3격은 '~에게 ~이 부족하다', es kommt zu + 3격은 '~이 일어나다'라는 뜻이에요. 문장 앞에 다른 성분이 오면 es는 동사 바로 뒤로 가요(Außerdem fehlt es …).","pattern":"Es + 동사 … · 다른 성분 + 동사 + es + …","examples":[{"de":"Es kommt zu einer heftigen Auseinandersetzung.","ko":"그래서 두 사람은 크게 다퉈요.","mark":["Es kommt zu"],"parts":[["Es","주어"],["kommt","동사"],["zu einer heftigen Auseinandersetzung.","전치사 목적어"]]},{"de":"Außerdem fehlt es den Nebenfiguren an Tiefe; die Nachbarin des Großvaters zum Beispiel bleibt recht blass.","ko":"게다가 조연들은 깊이가 부족해요. 예를 들어 할아버지의 이웃 여자는 꽤 밋밋한 인물로 남아요.","mark":["fehlt es","an Tiefe"]},{"de":"Der jungen Hauptdarstellerin Luisa Körber gelingt es, mit wenigen Worten sehr viel zu zeigen.","ko":"젊은 주연 배우 루이자 쾨르버는 몇 마디 말로 아주 많은 것을 보여 주는 데 성공해요.","mark":["gelingt es"]},{"de":"Es lohnt sich übrigens, bis nach dem Abspann sitzen zu bleiben.","ko":"참고로 끝 자막이 다 올라갈 때까지 앉아 있을 만해요.","mark":["Es lohnt sich"]}],"tip":"es gelingt와 es lohnt sich 뒤에는 zu 부정사구가 자주 와요. 이때 es는 뒤에 오는 zu 부정사구의 내용을 미리 가리켜요(Es lohnt sich, … sitzen zu bleiben)."},{"title":"wer …, (der) …: ~하는 사람은","term":"Relativsatz mit wer (verallgemeinernd)","explain":"정해지지 않은 사람 전체를 가리켜 '~하는 사람은 누구나'라고 말할 때 wer로 시작하는 절을 써요. wer절에서는 동사가 끝에 와요. 뒤따르는 주절은 동사로 시작하고, 그 앞에 der를 넣어 주어를 다시 받을 수도 있어요.","pattern":"Wer + … 동사(끝), (der) + 동사 + …","examples":[{"de":"Wer aber Geduld mitbringt, der sieht einen äußerst warmherzigen Film über die Beziehung zwischen Enkelin und Großvater, die erst lernen müssen, miteinander zu sprechen.","ko":"하지만 느긋하게 볼 준비가 된 사람은, 서로 말하는 법부터 배워야 하는 손녀와 할아버지의 관계를 그린 더없이 따뜻한 영화를 만나게 돼요.","mark":["Wer","mitbringt","der sieht"],"parts":[["Wer aber Geduld mitbringt,","종속절"],["der","주어"],["sieht","동사"],["einen äußerst warmherzigen Film über die Beziehung zwischen Enkelin und Großvater,","4격 목적어"],["die erst lernen müssen, miteinander zu sprechen.","관계절"]]},{"de":"Wer schnelle Schnitte und laute Filmmusik erwartet, wird sich in den 98 Minuten kaum wohlfühlen.","ko":"빠른 장면 전환과 시끄러운 영화 음악을 기대하는 사람은 98분 동안 편하게 보기 어려울 거예요.","mark":["Wer","erwartet","wird"]}],"tip":"wer절과 주절에서 필요한 격이 다르면 다시 받는 말도 그 격으로 써요(Wer Geduld hat, dem gefällt der Film)."},{"title":"형용사를 만드는 접미사 -ig · -lich · -sam · -voll","term":"Wortbildung: Adjektive auf -ig, -lich, -sam, -voll (langweilig, beruflich, schweigsam, eindrucksvoll)","explain":"명사나 동사 뒤에 접미사를 붙이면 형용사가 돼요. -ig는 '그런 성질이 있는'(die Langeweile → langweilig), -lich는 '~과 관련된'(der Beruf → beruflich), -sam은 '그런 경향이 있는'(schweigen → schweigsam), -voll은 '~이 가득한'(der Eindruck → eindrucksvoll)이라는 뜻을 더해요. 명사 앞에서는 다른 형용사처럼 어미가 붙어요(mit dem schweigsamen Großvater).","pattern":"명사·동사 + -ig / -lich / -sam / -voll → 형용사","examples":[{"de":"Selten war ein Spielfilm über Langeweile so wenig langweilig.","ko":"지루함을 다룬 영화가 이렇게 지루하지 않은 경우는 드물어요.","mark":["Langeweile","langweilig"],"parts":[["Selten","부사어(빈도)"],["war","동사"],["ein Spielfilm über Langeweile","주어"],["so wenig","부사어(방법)"],["langweilig.","보어"]]},{"de":"Besonders eindrucksvoll sind die Szenen auf dem Kanal, in denen kaum etwas passiert.","ko":"거의 아무 일도 일어나지 않는 운하 위 장면들이 특히 인상적이에요.","mark":["eindrucksvoll"]},{"de":"Auf dem Land gibt es keinen Handyempfang, keine Freunde und kaum ein Gespräch mit dem schweigsamen Großvater.","ko":"시골에서는 휴대폰도 안 터지고 친구도 없고, 말수 적은 할아버지와는 대화도 거의 없어요.","mark":["schweigsamen"]},{"de":"Weil ihre Mutter beruflich ins Ausland muss, soll Jette die Sommerferien bei ihrem Großvater Hinnerk verbringen.","ko":"어머니가 일 때문에 외국에 가야 해서, 예테는 여름 방학을 할아버지 힌너크의 집에서 보내야 해요.","mark":["beruflich"]}],"tip":"-voll과 반대되는 뜻은 -los로 나타낼 때가 많아요(humorvoll ↔ humorlos, sinnvoll ↔ sinnlos)."},{"title":"현재형으로 줄거리 요약하기","term":"Inhaltsangabe im Präsens (Vorzeitiges im Perfekt)","explain":"영화나 책의 줄거리를 소개할 때는 과거형이 아니라 현재형을 써요. 이야기 속의 일은 언제 보아도 똑같이 일어나기 때문이에요. 줄거리보다 먼저 일어난 일은 현재완료로 말해요(ist … geschippert). 지금까지 이어지는 일은 seit + 현재형으로 말해요(restauriert seit Jahren).","pattern":"줄거리: 현재형 · 그보다 앞선 일: 현재완료 · 계속되는 일: seit + 현재형","examples":[{"de":"Doch dann erfährt Jette von der Entscheidung des Großvaters, das Hausboot zu verkaufen.","ko":"그런데 예테는 할아버지가 하우스보트를 팔기로 했다는 것을 알게 돼요.","mark":["erfährt"],"parts":[["Doch","접속사"],["dann","부사어(시간)"],["erfährt","동사"],["Jette","주어"],["von der Entscheidung des Großvaters, das Hausboot zu verkaufen.","전치사 목적어"]]},{"de":"Mit dem Hausboot ist er früher als Schiffer über die Kanäle geschippert, heute liegt es fest am Ufer.","ko":"예전에는 뱃사람으로 이 하우스보트를 타고 운하를 누볐지만, 지금은 배가 물가에 묶여 있어요.","mark":["ist","geschippert","liegt"]},{"de":"Der Großvater wohnt auf dem Land und restauriert seit Jahren ein altes Hausboot.","ko":"할아버지는 시골에 살면서 몇 년째 낡은 하우스보트를 복원하고 있어요.","mark":["restauriert seit Jahren"]}],"tip":"줄거리에서는 anfangs, erst als, doch dann 같은 말로 시간의 흐름을 보여 줘요."}],"vocab":[{"de":"die Langeweile (Sg.)","ko":"지루함, 심심함"},{"de":"die Regisseurin, -nen","ko":"(여자) 감독"},{"de":"die Handlung, -en","ko":"줄거리"},{"de":"das Hausboot, -e","ko":"하우스보트 (집처럼 꾸민 배)"},{"de":"restaurieren","ko":"복원하다, 손질하여 되살리다"},{"de":"der Schiffer, -","ko":"뱃사람"},{"de":"das Ufer, -","ko":"물가, 강가"},{"de":"schweigsam","ko":"말수가 적은"},{"de":"streichen (streicht, strich, hat gestrichen)","ko":"페인트칠하다"},{"de":"die Annäherung, -en","ko":"가까워짐, 다가감"},{"de":"die Auseinandersetzung, -en","ko":"다툼, 언쟁"},{"de":"verraten (verrät, verriet, hat verraten)","ko":"(비밀을) 밝히다, 누설하다"},{"de":"die Hauptdarstellerin, -nen","ko":"(여자) 주연 배우"},{"de":"die Kameraführung (Sg.)","ko":"카메라 움직임, 촬영 방식"},{"de":"die Nebenfigur, -en","ko":"조연, 주변 인물"},{"de":"warmherzig","ko":"마음이 따뜻한"}],"phrases":[{"de":"im Mittelpunkt stehen","ko":"중심에 있다","ex":"Im Mittelpunkt der Handlung steht die sechzehnjährige Jette aus Hamburg.","exko":"이야기의 중심에는 함부르크에 사는 열여섯 살 예테가 있어요."},{"de":"eine Leistung zeigen","ko":"실력(연기)을 보여 주다","ex":"Auch der Darsteller des Großvaters zeigt eine überzeugende Leistung, denn man glaubt ihm jedes seiner wenigen Worte.","exko":"할아버지 역을 맡은 배우도 설득력 있는 연기를 보여 줘요. 몇 마디 안 되는 대사 하나하나가 진짜처럼 들리거든요."},{"de":"für eine Stimmung sorgen","ko":"분위기를 만들다","ex":"In diesen Szenen sorgt die ruhige Kameraführung für eine besondere Stimmung, und Filmmusik setzt die Regisseurin kaum ein.","exko":"이런 장면에서는 차분한 카메라 움직임이 특별한 분위기를 만들고, 감독은 영화 음악을 거의 쓰지 않아요."},{"de":"zu lang geraten","ko":"(뜻하지 않게) 너무 길어지다","ex":"Allerdings ist der Mittelteil des Films einige Minuten zu lang geraten.","exko":"다만 영화의 중간 부분은 몇 분쯤 지나치게 길어졌어요."},{"de":"sich wohlfühlen","ko":"편안하게 느끼다","ex":"Wer schnelle Schnitte und laute Filmmusik erwartet, wird sich in den 98 Minuten kaum wohlfühlen.","exko":"빠른 장면 전환과 시끄러운 영화 음악을 기대하는 사람은 98분 동안 편하게 보기 어려울 거예요."}],"words":311}];
